// Phase 12 — Linux-compatible syscall implementations (T013–T026)
// ===========================================================================

// ---------------------------------------------------------------------------
// File descriptor table (P12-T013, T015)
// ---------------------------------------------------------------------------

/// Initial virtual address for the program break (heap).
///
/// Placed at 8 GiB — above typical ELF segments (which load at ~4 MiB) and
/// well below the user stack (at ~128 TiB).
const BRK_BASE: u64 = 0x0000_0002_0000_0000;

/// Initial virtual address for anonymous mmap allocations.
///
/// Placed at 128 GiB — above the brk heap region and below the stack.
/// Re-used by `kernel::pci::bar` for device-MMIO BAR mappings, so
/// visibility is `pub(crate)` to keep a single source of truth.
pub(crate) const ANON_MMAP_BASE: u64 = 0x0000_0020_0000_0000;

// Re-export FD types from process module (Phase 14 — per-process FD table).
use crate::process::{FdBackend, FdEntry, MAX_FDS};

/// Clone the FD entry at `fd` from the current process's FD table.
///
/// Returns `None` if no process is running or the FD slot is empty.
/// Uses the shared fd table when the process is part of a thread group
/// created with `CLONE_FILES`.
fn current_fd_entry(fd: usize) -> Option<FdEntry> {
    let pid = crate::process::current_pid();
    let table = crate::process::PROCESS_TABLE.lock();
    let proc = table.find(pid)?;
    proc.fd_get(fd)
}

/// Mutate the FD entry at `fd` in the current process's FD table.
/// Uses the shared fd table when the process is part of a thread group
/// created with `CLONE_FILES`.
fn with_current_fd_mut<F: FnOnce(&mut Option<FdEntry>)>(fd: usize, f: F) {
    let pid = crate::process::current_pid();
    let mut table = crate::process::PROCESS_TABLE.lock();
    if let Some(proc) = table.find_mut(pid) {
        if let Some(shared) = &proc.shared_fd_table {
            if fd < MAX_FDS {
                f(&mut shared.lock()[fd]);
            }
        } else if let Some(slot) = proc.fd_table.get_mut(fd) {
            f(slot);
        }
    }
}

/// Allocate the lowest available FD slot (starting from `min_fd`) in the
/// current process's FD table. Returns the FD number or `None` if full.
/// Uses the shared fd table when the process is part of a thread group
/// created with `CLONE_FILES`.
fn alloc_fd(min_fd: usize, entry: FdEntry) -> Option<usize> {
    let pid = crate::process::current_pid();
    let mut table = crate::process::PROCESS_TABLE.lock();
    let proc = table.find_mut(pid)?;
    proc.fd_alloc(min_fd, entry)
}

/// Returns whether the current CPU reports support for the RDRAND instruction
/// (CPUID.01H:ECX bit 30).
fn cpu_has_rdrand() -> bool {
    let ecx: u32;
    unsafe {
        core::arch::asm!(
            "push rbx",
            "mov eax, 1",
            "cpuid",
            "pop rbx",
            out("ecx") ecx,
            out("eax") _,
            out("edx") _,
        );
    }
    ecx & (1 << 30) != 0
}

/// Cached RDRAND support: 0 = unchecked, 1 = supported, 2 = unsupported.
static RDRAND_SUPPORT: core::sync::atomic::AtomicU8 = core::sync::atomic::AtomicU8::new(0);

/// Try to read a 64-bit value from the hardware RDRAND instruction.
/// Returns `Some(value)` if RDRAND is available and succeeded, `None` otherwise.
/// Caches the CPUID check so only the first call executes CPUID.
/// Retries up to 10 times on transient failure per Intel guidance.
fn rdrand64() -> Option<u64> {
    let cached = RDRAND_SUPPORT.load(core::sync::atomic::Ordering::Relaxed);
    let supported = if cached == 0 {
        let s = cpu_has_rdrand();
        RDRAND_SUPPORT.store(if s { 1 } else { 2 }, core::sync::atomic::Ordering::Relaxed);
        s
    } else {
        cached == 1
    };
    if !supported {
        return None;
    }
    for _ in 0..10 {
        let mut val: u64;
        let ok: u8;
        unsafe {
            core::arch::asm!(
                "rdrand {val}",
                "setc {ok}",
                val = out(reg) val,
                ok = out(reg_byte) ok,
            );
        }
        if ok != 0 {
            return Some(val);
        }
    }
    None
}

// ---------------------------------------------------------------------------
// A.2 — RDSEED support (Phase 86a Track A)
// ---------------------------------------------------------------------------

/// Returns whether the current CPU supports the RDSEED instruction
/// (CPUID leaf 07H, subleaf 0, EBX bit 18).
fn cpu_has_rdseed() -> bool {
    let ebx: u32;
    unsafe {
        // SAFETY: CPUID is a ring-0 read-only instruction; no side effects.
        // We push/pop rbx because it is a callee-saved register and `asm!`
        // would otherwise clobber it, which upsets the compiler's register
        // allocator on some targets.
        core::arch::asm!(
            "push rbx",
            "mov eax, 7",
            "xor ecx, ecx",
            "cpuid",
            "mov {ebx:e}, ebx",
            "pop rbx",
            ebx = out(reg) ebx,
            out("eax") _,
            out("ecx") _,
            out("edx") _,
        );
    }
    ebx & (1 << 18) != 0
}

/// Cached RDSEED support: 0 = unchecked, 1 = supported, 2 = unsupported.
static RDSEED_SUPPORT: core::sync::atomic::AtomicU8 = core::sync::atomic::AtomicU8::new(0);

/// Try to read a 64-bit full-entropy seed word via the RDSEED instruction.
///
/// Returns `Some(value)` if RDSEED is available and CF=1 (seed valid).
/// Performs a bounded PAUSE-retry on CF=0 (seed pool momentarily empty).
fn rdseed64() -> Option<u64> {
    let cached = RDSEED_SUPPORT.load(core::sync::atomic::Ordering::Relaxed);
    let supported = if cached == 0 {
        let s = cpu_has_rdseed();
        RDSEED_SUPPORT.store(if s { 1 } else { 2 }, core::sync::atomic::Ordering::Relaxed);
        s
    } else {
        cached == 1
    };
    if !supported {
        return None;
    }
    for _ in 0..10 {
        let mut val: u64;
        let ok: u8;
        unsafe {
            // SAFETY: RDSEED is a ring-0 / ring-3 safe instruction that reads
            // from the hardware TRNG.  CF=1 indicates a valid seed word.
            core::arch::asm!(
                "rdseed {val}",
                "setc {ok}",
                val = out(reg) val,
                ok = out(reg_byte) ok,
            );
        }
        if ok != 0 {
            return Some(val);
        }
        // RDSEED pool is momentarily empty; PAUSE before retry.
        core::hint::spin_loop();
    }
    None
}

/// Collect 32 bytes of seed material for the CSPRNG.
///
/// Source preference:
///   1. **RDSEED** × 4 (256 full-entropy bits, source tag `"rdseed"`)
///   2. **RDRAND** × 4 (credit 256 bits from hardware DRBG, source tag `"rdrand"`)
///   3. **TSC degraded** (credit 0 bits, source tag `"degraded"`)
///
/// In every case, extra TSC reads are XOR-mixed in as uncredited diffusion so
/// that even the degraded path provides non-repeating seeds across reboots on
/// the same hardware.
pub(crate) fn gather_seed_entropy() -> ([u8; 32], usize, &'static str) {
    let mut seed = [0u8; 32];

    // Helper: write a u64 into 8 bytes of the seed buffer at a given offset.
    #[inline(always)]
    fn put_u64(buf: &mut [u8; 32], offset: usize, val: u64) {
        buf[offset..offset + 8].copy_from_slice(&val.to_le_bytes());
    }

    // Extra TSC diffusion mixed into every path.
    let tsc0 = unsafe { core::arch::x86_64::_rdtsc() };

    // --- Try RDSEED first (full-entropy hardware TRNG) ---
    if let (Some(a), Some(b), Some(c), Some(d)) = (rdseed64(), rdseed64(), rdseed64(), rdseed64()) {
        put_u64(&mut seed, 0, a ^ tsc0);
        put_u64(&mut seed, 8, b);
        put_u64(&mut seed, 16, c);
        let tsc1 = unsafe { core::arch::x86_64::_rdtsc() };
        put_u64(&mut seed, 24, d ^ tsc1);
        return (seed, 256, "rdseed");
    }

    // --- Fall back to RDRAND (hardware CTR_DRBG output) ---
    if let (Some(a), Some(b), Some(c), Some(d)) = (rdrand64(), rdrand64(), rdrand64(), rdrand64()) {
        put_u64(&mut seed, 0, a ^ tsc0);
        put_u64(&mut seed, 8, b);
        put_u64(&mut seed, 16, c);
        let tsc1 = unsafe { core::arch::x86_64::_rdtsc() };
        put_u64(&mut seed, 24, d ^ tsc1);
        return (seed, 256, "rdrand");
    }

    // --- Degraded: TSC-only mixing (credited bits = 0) ---
    // Mix several TSC samples with a non-zero constant to ensure the seed is
    // never all-zeros (which would produce the degenerate all-zero ChaCha20 key
    // that, while still functional, is not a good starting point).
    let tsc1 = unsafe { core::arch::x86_64::_rdtsc() };
    let tsc2 = unsafe { core::arch::x86_64::_rdtsc() };
    let tsc3 = unsafe { core::arch::x86_64::_rdtsc() };
    put_u64(&mut seed, 0, tsc0 ^ 0xDEAD_BEEF_CAFE_BABE);
    put_u64(&mut seed, 8, tsc1 ^ 0x0123_4567_89AB_CDEF);
    put_u64(&mut seed, 16, tsc2 ^ 0xFEDC_BA98_7654_3210);
    put_u64(&mut seed, 24, tsc3 ^ 0xA5A5_A5A5_5A5A_5A5A);
    (seed, 0, "degraded")
}

/// Seed the CSPRNG early in kernel boot from the best available hardware source.
///
/// Called from `kernel_main_entry` after `mm::init` + `task::kstack::init` and
/// before `net::virtio_net::init` and `task::spawn(init_task, …)`.
///
/// On success the global DRBG transitions to `READY` (RDSEED/RDRAND path) or
/// remains in `EARLY` (degraded path). The degraded path does NOT deadlock —
/// `GRND_INSECURE` and the AT_RANDOM / TCP ISN fallbacks use `fill_insecure`.
pub(crate) fn seed_csprng_early() {
    let (seed, bits, source) = gather_seed_entropy();
    kernel_core::csprng::seed_global(&seed, bits);
    let state = if kernel_core::csprng::global_ready() {
        "READY"
    } else {
        "EARLY"
    };
    log::info!(
        "[csprng] seeded source={} credited_bits={} state={}",
        source,
        bits,
        state
    );
}

// ---------------------------------------------------------------------------
// Device-node fill helpers (/dev/zero, /dev/full)
// ---------------------------------------------------------------------------

fn copy_byte_pattern_to_user(buf_ptr: u64, count: usize, byte: u8) -> Result<(), ()> {
    let chunk = [byte; 256];
    let mut written = 0usize;
    while written < count {
        let len = (count - written).min(chunk.len());
        if UserSliceWo::new(buf_ptr + written as u64, chunk[..len].len())
            .and_then(|s| s.copy_from_kernel(&chunk[..len]))
            .is_err()
        {
            return Err(());
        }
        written += len;
    }
    Ok(())
}

fn block_on_pty_master_read(pty_id: u32) -> Result<(), u64> {
    let task_id = crate::task::scheduler::current_task_id().ok_or(NEG_EINTR)?;
    let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
    crate::pty::PTY_MASTER_WQ[pty_id as usize].register(task_id, &woken);
    let ready = {
        let table = crate::pty::PTY_TABLE.lock();
        match table.get(pty_id as usize).and_then(|slot| slot.as_ref()) {
            Some(pair) => !pair.s2m.is_empty() || (pair.slave_refcount == 0 && pair.slave_opened),
            None => true,
        }
    };
    if !ready {
        let _ = crate::task::scheduler::block_current_until(
            crate::task::TaskState::BlockedOnRecv,
            &woken,
            None,
        );
    }
    crate::pty::PTY_MASTER_WQ[pty_id as usize].deregister(task_id);
    Ok(())
}

fn block_on_pty_slave_read(pty_id: u32) -> Result<(), u64> {
    let task_id = crate::task::scheduler::current_task_id().ok_or(NEG_EINTR)?;
    let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
    crate::pty::PTY_SLAVE_WQ[pty_id as usize].register(task_id, &woken);
    let (ready, deadline_ticks) = {
        let table = crate::pty::PTY_TABLE.lock();
        match table.get(pty_id as usize).and_then(|slot| slot.as_ref()) {
            Some(pair) => {
                if pair.termios.is_canonical() {
                    let r = pair.edit_buf.as_slice().contains(&b'\n')
                        || pair.eof_pending
                        || pair.master_refcount == 0;
                    (r, None)
                } else {
                    // Phase 69a Track F.2: honour VMIN / VTIME when parking
                    // the read.  Three cases:
                    //  * VMIN > 0, VTIME == 0 — block indefinitely.
                    //  * VMIN == 0, VTIME > 0 — block to absolute deadline.
                    //  * VMIN > 0, VTIME > 0 — inter-byte timer (if armed).
                    let vmin = pair.termios.c_cc[kernel_core::tty::VMIN] as u64;
                    let vtime = pair.termios.c_cc[kernel_core::tty::VTIME] as u64;
                    let avail = pair.m2s.available() as u64;
                    let r = match (vmin, vtime) {
                        (0, 0) => true,
                        (0, _) => avail > 0,
                        (n, 0) => avail >= n,
                        (n, _) => avail >= n,
                    } || pair.master_refcount == 0;
                    let dl = pair.ldisc_deadline_ticks;
                    (r, dl)
                }
            }
            None => (true, None),
        }
    };
    if !ready {
        let _ = crate::task::scheduler::block_current_until(
            crate::task::TaskState::BlockedOnRecv,
            &woken,
            deadline_ticks,
        );
    }
    crate::pty::PTY_SLAVE_WQ[pty_id as usize].deregister(task_id);
    Ok(())
}

// ---------------------------------------------------------------------------
// T013: read(fd, buf, count)
// ---------------------------------------------------------------------------

/// Maximum bytes copied from the dmesg ring per `/proc/kmsg` read. Caps the
/// transient kernel staging buffer; callers loop to drain more.
const KMSG_READ_CHUNK: usize = 4096;

pub(super) fn sys_linux_read(fd: u64, buf_ptr: u64, count: u64) -> u64 {
    let fd = fd as usize;
    if fd >= MAX_FDS {
        return NEG_EBADF;
    }

    let entry = match current_fd_entry(fd) {
        Some(e) => e,
        None => return NEG_EBADF,
    };

    if !entry.readable {
        return NEG_EBADF;
    }

    match &entry.backend {
        FdBackend::EventFd { id } => {
            // Phase 86d Track D — eventfd read: an 8-byte counter, drained on
            // read. Go's eventfd is non-blocking (EAGAIN when empty); a blocking
            // eventfd parks on the object's wait queue until a write makes it
            // readable (mirrors the pipe read pattern).
            let id = *id;
            if (count as usize) < 8 {
                return NEG_EINVAL;
            }
            let nonblock = entry.nonblock;
            let task_id = match crate::task::scheduler::current_task_id() {
                Some(t) => t,
                None => return NEG_EINTR,
            };
            let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
            loop {
                woken.store(false, core::sync::atomic::Ordering::Release);
                if !crate::eventfd::eventfd_register_waiter(id, task_id, &woken) {
                    // The eventfd object was freed (last fd reference closed,
                    // possibly by a peer thread while we were blocked here).
                    // Return EOF rather than dead-block on a wait queue that no
                    // longer exists — mirrors a pipe reader seeing writer-close.
                    return 0;
                }
                if let Some(val) = crate::eventfd::eventfd_read(id) {
                    crate::eventfd::eventfd_deregister_waiter(id, task_id);
                    let bytes = val.to_ne_bytes();
                    if UserSliceWo::new(buf_ptr, bytes.len())
                        .and_then(|s| s.copy_from_kernel(&bytes))
                        .is_err()
                    {
                        return NEG_EFAULT;
                    }
                    return 8;
                }
                if nonblock {
                    crate::eventfd::eventfd_deregister_waiter(id, task_id);
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    crate::eventfd::eventfd_deregister_waiter(id, task_id);
                    return NEG_EINTR;
                }
                let _ = crate::task::scheduler::block_current_until(
                    crate::task::TaskState::BlockedOnRecv,
                    &woken,
                    None,
                );
                crate::eventfd::eventfd_deregister_waiter(id, task_id);
            }
        }
        FdBackend::TimerFd { id } => {
            // Phase 89 Track A.1 — timerfd read: an 8-byte u64 expiration count,
            // drained on read. A blocking read parks until the next expiry; the
            // wake is driven by the scheduler `wake_deadline` (clamped to the
            // timer's next-expiry tick — the IRQ-safe wake path) or by a
            // `timerfd_settime` re-arm. TFD_NONBLOCK returns EAGAIN when unfired.
            let id = *id;
            if (count as usize) < 8 {
                return NEG_EINVAL;
            }
            let nonblock = entry.nonblock;
            let task_id = match crate::task::scheduler::current_task_id() {
                Some(t) => t,
                None => return NEG_EINTR,
            };
            let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
            loop {
                woken.store(false, core::sync::atomic::Ordering::Release);
                if !crate::timerfd::timerfd_register_waiter(id, task_id, &woken) {
                    return 0; // object freed under us → EOF
                }
                if let Some(expirations) = crate::timerfd::timerfd_read(id) {
                    crate::timerfd::timerfd_deregister_waiter(id, task_id);
                    let bytes = expirations.to_ne_bytes();
                    if UserSliceWo::new(buf_ptr, bytes.len())
                        .and_then(|s| s.copy_from_kernel(&bytes))
                        .is_err()
                    {
                        return NEG_EFAULT;
                    }
                    return 8;
                }
                if nonblock {
                    crate::timerfd::timerfd_deregister_waiter(id, task_id);
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    crate::timerfd::timerfd_deregister_waiter(id, task_id);
                    return NEG_EINTR;
                }
                // Block until the next expiry (or indefinitely if disarmed,
                // woken by a later settime). Clamping the block deadline to the
                // timer's next tick lets the scheduler's IRQ-safe deadline
                // scanner wake us — `WaitQueue::wake_all` can't run from the ISR.
                let deadline = crate::timerfd::timerfd_next_expiry_tick(id);
                let _ = crate::task::scheduler::block_current_until(
                    crate::task::TaskState::BlockedOnRecv,
                    &woken,
                    deadline,
                );
                crate::timerfd::timerfd_deregister_waiter(id, task_id);
            }
        }
        FdBackend::Stdin | FdBackend::DeviceTTY { .. } => {
            // Read from kernel stdin buffer.
            let capped = (count as usize).min(4096);
            let nonblock = entry.nonblock;
            // Phase 57e Bug #12 — replace the busy-yield loop with a
            // proper waitqueue-based block.  The previous
            // `loop { has_data || yield_now() }` shape was the dominant
            // yield_now caller on real hardware (`m3os.log` 2026-05-07
            // showed 95% of all yield_now calls coming from this site,
            // pid 18 / login).  Under preempt-full each yield triggered
            // an eager-yield in `preempt_enable`'s zero-cross branch,
            // cascading the input pipeline through hundreds of
            // unnecessary context switches per blocked read.
            //
            // STDIN_WAITQUEUE is woken by `stdin::push_char` and
            // `stdin::signal_eof`; both run AFTER mutating the buffer
            // so `has_data()` is ground truth.  The `woken` atomic
            // closes the lost-wake window between the readiness scan
            // and the block: if a wake fires after `has_data() == false`
            // and before `block_current_until`, the wake sets `woken`
            // and `block_current_until`'s early-bail returns
            // `AlreadyTrue` without yielding.  `wake_all` drains the
            // waiter queue per call so we re-register every iteration.
            let task_id = match crate::task::scheduler::current_task_id() {
                Some(id) => id,
                None => return NEG_EINTR,
            };
            let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
            loop {
                // Reset and re-register before the readiness scan so any
                // wake during the scan / block window sets our flag.
                woken.store(false, core::sync::atomic::Ordering::Release);
                crate::stdin::STDIN_WAITQUEUE.register(task_id, &woken);

                if crate::stdin::has_data() {
                    crate::stdin::STDIN_WAITQUEUE.deregister(task_id);
                    let mut tmp = [0u8; 4096];
                    let n = crate::stdin::read(&mut tmp[..capped]);
                    if n > 0 {
                        if UserSliceWo::new(buf_ptr, tmp[..n].len())
                            .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                            .is_err()
                        {
                            break NEG_EFAULT;
                        }
                        break n as u64;
                    }
                    // n == 0 with has_data() true means the EOF flag was set
                    // (^D / VEOF on an empty line) and `read` just consumed it.
                    // A read() that hits EOF MUST return 0 to userspace — not
                    // loop and re-block — so the reader sees end-of-input. This is
                    // what lets `^D` exit the Python REPL (and any fgets/readline
                    // loop) over the serial / kernel console; without it the EOF
                    // is silently swallowed and the read re-blocks. The flag is
                    // one-shot, so the next read blocks again as normal.
                    break 0;
                }
                if nonblock {
                    crate::stdin::STDIN_WAITQUEUE.deregister(task_id);
                    break NEG_EAGAIN;
                }
                if has_pending_signal() {
                    crate::stdin::STDIN_WAITQUEUE.deregister(task_id);
                    break NEG_EINTR;
                }
                let _ = crate::task::scheduler::block_current_until(
                    crate::task::TaskState::BlockedOnRecv,
                    &woken,
                    None,
                );
                // wake_all drained our entry; deregister is idempotent
                // for safety in case wake_one was used.
                crate::stdin::STDIN_WAITQUEUE.deregister(task_id);
            }
        }
        FdBackend::Stdout => NEG_EBADF,
        FdBackend::Ramdisk {
            content_addr,
            content_len,
        } => {
            let remaining = content_len.saturating_sub(entry.offset);
            let to_read = (count as usize).min(remaining).min(64 * 1024);
            if to_read == 0 {
                return 0; // EOF
            }

            // SAFETY: content_addr is a static ramdisk pointer (lives forever).
            let src = unsafe {
                core::slice::from_raw_parts((*content_addr + entry.offset) as *const u8, to_read)
            };

            if UserSliceWo::new(buf_ptr, src.len())
                .and_then(|s| s.copy_from_kernel(src))
                .is_err()
            {
                return NEG_EFAULT;
            }

            with_current_fd_mut(fd, |slot| {
                if let Some(e) = slot {
                    e.offset += to_read;
                }
            });
            to_read as u64
        }
        FdBackend::Tmpfs { path } => {
            // Cap count at 64 KiB to match ramdisk path and prevent overflow.
            let capped_count = (count as usize).min(64 * 1024);
            let tmpfs = crate::fs::tmpfs::TMPFS.lock();
            let data = match tmpfs.read_file(path, entry.offset, capped_count) {
                Ok(d) => d,
                Err(crate::fs::tmpfs::TmpfsError::NotFound) => return NEG_ENOENT,
                Err(_) => return NEG_EBADF,
            };
            let to_read = data.len();
            if to_read == 0 {
                return 0; // EOF
            }

            if UserSliceWo::new(buf_ptr, data.len())
                .and_then(|s| s.copy_from_kernel(data))
                .is_err()
            {
                return NEG_EFAULT;
            }

            drop(tmpfs);
            with_current_fd_mut(fd, |slot| {
                if let Some(e) = slot {
                    e.offset += to_read;
                }
            });
            to_read as u64
        }
        FdBackend::Proc { path } => {
            // `/proc/kmsg` is a live, consuming kernel-log stream. `entry.offset`
            // holds an absolute byte-sequence cursor into the dmesg ring (NOT a
            // file offset); each read copies the bytes logged since the cursor
            // and advances it. When the reader is caught up, read returns 0
            // (no data right now) and `fd_poll_events` reports it not-readable,
            // so a poll() loop blocks for its timeout instead of spinning.
            // This replaces the old frozen-snapshot model, which both busy-spun
            // poll() loops (always-readable at EOF) and never delivered kernel
            // messages emitted after open().
            if path == "/proc/kmsg" {
                let cap = (count as usize).min(KMSG_READ_CHUNK);
                if cap == 0 {
                    return 0;
                }
                let cursor = entry.offset as u64;
                let mut tmp = alloc::vec![0u8; cap];
                let (n, new_cursor) = crate::serial::dmesg_read_from(cursor, &mut tmp);
                if n == 0 {
                    return 0;
                }
                if UserSliceWo::new(buf_ptr, n)
                    .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                    .is_err()
                {
                    return NEG_EFAULT;
                }
                with_current_fd_mut(fd, |slot| {
                    if let Some(e) = slot {
                        e.offset = new_cursor as usize;
                    }
                });
                return n as u64;
            }

            // All other procfs files regenerate their full content on each read.
            let generated = match crate::fs::procfs::read_file(path) {
                Some(data) => data,
                None => return NEG_ENOENT,
            };
            let data: &[u8] = &generated;
            let offset = entry.offset.min(data.len());
            let to_read = (count as usize).min(data.len().saturating_sub(offset));
            if to_read == 0 {
                return 0;
            }

            if UserSliceWo::new(buf_ptr, data[offset..offset + to_read].len())
                .and_then(|s| s.copy_from_kernel(&data[offset..offset + to_read]))
                .is_err()
            {
                return NEG_EFAULT;
            }

            with_current_fd_mut(fd, |slot| {
                if let Some(e) = slot {
                    e.offset += to_read;
                }
            });
            to_read as u64
        }
        FdBackend::Fat32Disk {
            start_cluster,
            file_size,
            ..
        } => {
            let capped_count = (count as usize).min(64 * 1024);
            let start_cluster = *start_cluster;
            let file_size = *file_size;
            let offset = entry.offset;

            if start_cluster < 2 || offset >= file_size as usize {
                return 0; // EOF or empty file
            }

            let vol = crate::fs::fat32::FAT32_VOLUME.lock();
            if let Some(vol) = vol.as_ref() {
                let mut read_buf = alloc::vec![0u8; capped_count];
                match vol.read_file(start_cluster, file_size, offset, &mut read_buf) {
                    Ok(0) => 0,
                    Ok(n) => {
                        if UserSliceWo::new(buf_ptr, read_buf[..n].len())
                            .and_then(|s| s.copy_from_kernel(&read_buf[..n]))
                            .is_err()
                        {
                            return NEG_EFAULT;
                        }

                        with_current_fd_mut(fd, |slot| {
                            if let Some(e) = slot {
                                e.offset += n;
                            }
                        });
                        n as u64
                    }
                    Err(_) => NEG_EIO,
                }
            } else {
                NEG_EIO
            }
        }
        FdBackend::PipeRead { pipe_id } => {
            let pipe_id = *pipe_id;
            let nonblock = entry.nonblock;
            let capped = (count as usize).min(4096);
            // Phase 61 Track F — blocking-pipe read uses
            // `PIPE_WAITQUEUES[pipe_id].sleep()` instead of the previous
            // `loop { pipe_read; yield_now }` polling. Mirrors the stdin
            // direct-read pattern earlier in this file (`STDIN_WAITQUEUE
            // .register / sleep / deregister`). `wake_pipe` is called from
            // both `pipe_write` (data available) and the close paths
            // (reader/writer EOF), so the sleep is always woken when the
            // condition that would let `pipe_read` return changes.
            let task_id = match crate::task::scheduler::current_task_id() {
                Some(id) => id,
                None => return NEG_EINTR,
            };
            let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
            loop {
                woken.store(false, core::sync::atomic::Ordering::Release);
                crate::pipe::pipe_register_waiter(pipe_id, task_id, &woken);

                let mut tmp = [0u8; 4096];
                match crate::pipe::pipe_read(pipe_id, &mut tmp[..capped]) {
                    Ok(0) => {
                        crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                        return 0; // EOF
                    }
                    Ok(n) => {
                        crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                        if UserSliceWo::new(buf_ptr, tmp[..n].len())
                            .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                            .is_err()
                        {
                            return NEG_EFAULT;
                        }
                        return n as u64;
                    }
                    Err(_would_block) => {
                        if nonblock {
                            crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                            return NEG_EAGAIN;
                        }
                        if has_pending_signal() {
                            crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                            return NEG_EINTR;
                        }
                        // Park until `wake_pipe(pipe_id)` fires from a
                        // matching `pipe_write` / close. The `woken` flag
                        // closes the lost-wake window between the readiness
                        // scan and the block (same discipline as stdin).
                        let _ = crate::task::scheduler::block_current_until(
                            crate::task::TaskState::BlockedOnRecv,
                            &woken,
                            None,
                        );
                        // wake_all drained our entry; deregister is
                        // idempotent for safety.
                        crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                    }
                }
            }
        }
        FdBackend::Ext2Disk {
            inode_num, path, ..
        } => {
            let capped_count = (count as usize).min(64 * 1024);
            let inode_num = *inode_num;
            let offset = entry.offset;
            let path = path.clone();

            // Phase 92a D.4: a file under a /mnt/usbN secondary mount reads from
            // that mount's own ext2 volume. The vfs_server authority owns only
            // the root device, so it is bypassed here (the volume-local inode
            // number was resolved against this same volume at open time).
            if let Some(read_res) = crate::fs::ext2::with_usb_mount(
                &path,
                |vol, _rel| -> Result<alloc::vec::Vec<u8>, u64> {
                    let inode = vol.read_inode(inode_num).map_err(|_| NEG_EIO)?;
                    let actual_size = inode.size as usize;
                    if offset >= actual_size {
                        return Ok(alloc::vec::Vec::new());
                    }
                    let mut read_buf = alloc::vec![0u8; capped_count];
                    let n = vol
                        .read_file_data(&inode, offset as u64, &mut read_buf)
                        .map_err(|_| NEG_EIO)?;
                    read_buf.truncate(n);
                    Ok(read_buf)
                },
            ) {
                return match read_res {
                    Ok(data) => {
                        if data.is_empty() {
                            return 0;
                        }
                        let n = data.len();
                        if UserSliceWo::new(buf_ptr, n)
                            .and_then(|s| s.copy_from_kernel(&data))
                            .is_err()
                        {
                            return NEG_EFAULT;
                        }
                        with_current_fd_mut(fd, |slot| {
                            if let Some(e) = slot {
                                e.offset += n;
                            }
                        });
                        n as u64
                    }
                    Err(e) => e,
                };
            }

            // Phase 88: when the vfs_server ext2 authority is registered, read
            // through it (VFS_PREAD by path) so a writer reading back its own
            // writable fd — or any reader after an out-of-band write — sees the
            // coherent vfs_server view, not a stale kernel block-cache snapshot.
            if vfs_write_routable() {
                let capped = capped_count.min(kernel_core::fs::vfs_protocol::VFS_MAX_PREAD);
                let ret = vfs_service_pread(&path, offset, buf_ptr, capped);
                if (ret as i64) >= 0 {
                    let n = ret as usize;
                    if n > 0 {
                        with_current_fd_mut(fd, |slot| {
                            if let Some(e) = slot {
                                e.offset += n;
                            }
                        });
                    }
                    return ret;
                }
                // Transport miss — fall through to the in-kernel engine.
            }

            let vol = crate::fs::ext2::EXT2_VOLUME.lock();
            if let Some(vol) = vol.as_ref() {
                match vol.read_inode(inode_num) {
                    Ok(inode) => {
                        let actual_size = inode.size as usize;
                        if offset >= actual_size {
                            return 0;
                        }
                        let mut read_buf = alloc::vec![0u8; capped_count];
                        match vol.read_file_data(&inode, offset as u64, &mut read_buf) {
                            Ok(0) => 0,
                            Ok(n) => {
                                if UserSliceWo::new(buf_ptr, read_buf[..n].len())
                                    .and_then(|s| s.copy_from_kernel(&read_buf[..n]))
                                    .is_err()
                                {
                                    return NEG_EFAULT;
                                }
                                with_current_fd_mut(fd, |slot| {
                                    if let Some(e) = slot {
                                        e.offset += n;
                                        if let FdBackend::Ext2Disk {
                                            file_size: ref mut fs,
                                            ..
                                        } = e.backend
                                        {
                                            *fs = inode.size;
                                        }
                                    }
                                });
                                n as u64
                            }
                            Err(_) => NEG_EIO,
                        }
                    }
                    Err(_) => NEG_EIO,
                }
            } else {
                NEG_EIO
            }
        }
        FdBackend::PipeWrite { .. } => NEG_EBADF,
        FdBackend::Dir { .. } => NEG_EISDIR,
        FdBackend::DevNull => 0, // EOF
        FdBackend::DevZero | FdBackend::DevFull => {
            // /dev/zero and /dev/full behave like infinite zero-filled files.
            if copy_byte_pattern_to_user(buf_ptr, count as usize, 0).is_err() {
                return NEG_EFAULT;
            }
            count
        }
        FdBackend::DevUrandom => {
            // Phase 86a: /dev/urandom and /dev/random serve the ChaCha20 CSPRNG
            // (the same DRBG that backs getrandom). They never block — before the
            // DRBG is READY (a degraded boot without RDSEED/RDRAND) they serve
            // insecure DRBG output, matching Linux /dev/urandom semantics. READY
            // is monotonic, so the readiness check below cannot race the fill.
            maybe_reseed_csprng();
            let insecure = !kernel_core::csprng::global_ready();
            if getrandom_fill_user(buf_ptr, count as usize, insecure).is_err() {
                return NEG_EFAULT;
            }
            count
        }
        FdBackend::PtyMaster { pty_id } => {
            if count == 0 {
                return 0;
            }
            // Master reads from s2m (slave-to-master) buffer.
            let pty_id = *pty_id;
            let nonblock = entry.nonblock;
            loop {
                {
                    let mut table = crate::pty::PTY_TABLE.lock();
                    if let Some(Some(pair)) = table.get_mut(pty_id as usize) {
                        if !pair.s2m.is_empty() {
                            let mut dst = [0u8; 4096];
                            let to_read = count.min(dst.len() as u64) as usize;
                            let n = pair.s2m.read(&mut dst[..to_read]);
                            drop(table);
                            // Reading from s2m frees space for slave writers.
                            crate::pty::wake_slave(pty_id);
                            if UserSliceWo::new(buf_ptr, dst[..n].len())
                                .and_then(|s| s.copy_from_kernel(&dst[..n]))
                                .is_err()
                            {
                                return NEG_EFAULT;
                            }
                            return n as u64;
                        }
                        if pair.slave_refcount == 0 && pair.slave_opened {
                            return 0; // EOF — slave closed
                        }
                    } else {
                        return 0; // PTY freed
                    }
                }
                if nonblock {
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    return NEG_EINTR;
                }
                if let Err(err) = block_on_pty_master_read(pty_id) {
                    return err;
                }
            }
        }
        FdBackend::PtySlave { pty_id } => {
            if count == 0 {
                return 0;
            }
            // Slave reads from m2s (master-to-slave) buffer via line discipline.
            let pty_id = *pty_id;
            let nonblock = entry.nonblock;
            loop {
                {
                    let mut table = crate::pty::PTY_TABLE.lock();
                    if let Some(Some(pair)) = table.get_mut(pty_id as usize) {
                        if pair.termios.is_canonical() {
                            // Canonical mode: check edit buffer for complete line.
                            let line = pair.edit_buf.as_slice();
                            let has_line = line.contains(&b'\n');
                            if has_line {
                                let eol = line.iter().position(|&b| b == b'\n').unwrap() + 1;
                                let to_copy = eol.min(count as usize).min(4096);
                                let mut dst = [0u8; 4096];
                                dst[..to_copy]
                                    .copy_from_slice(&pair.edit_buf.as_slice()[..to_copy]);
                                pair.edit_buf.drain(to_copy);
                                drop(table);
                                // Draining edit_buf frees space for master writers.
                                crate::pty::wake_master(pty_id);
                                if UserSliceWo::new(buf_ptr, dst[..to_copy].len())
                                    .and_then(|s| s.copy_from_kernel(&dst[..to_copy]))
                                    .is_err()
                                {
                                    return NEG_EFAULT;
                                }
                                return to_copy as u64;
                            }
                            // VEOF (^D) on empty line → return 0 (EOF).
                            if pair.eof_pending {
                                pair.eof_pending = false;
                                drop(table);
                                return 0;
                            }
                        } else {
                            // Phase 69a Track F: VMIN / VTIME timer.  Four
                            // POSIX cases drive whether we return now,
                            // block for more data, or wait for a deadline.
                            let vmin = pair.termios.c_cc[kernel_core::tty::VMIN] as u64;
                            let vtime = pair.termios.c_cc[kernel_core::tty::VTIME] as u64;
                            let avail = pair.m2s.available() as u64;
                            let now = crate::arch::x86_64::interrupts::tick_count();

                            // If a VTIME deadline was previously armed, see
                            // whether it has expired.
                            let deadline_expired =
                                pair.ldisc_deadline_ticks.map(|d| now >= d).unwrap_or(false);

                            // Decide whether the read should complete now.
                            let ready = match (vmin, vtime) {
                                (0, 0) => true, // poll
                                (0, _) => avail > 0 || deadline_expired,
                                (n, 0) => avail >= n,
                                (n, _) => avail >= n || (avail > 0 && deadline_expired),
                            };

                            if ready {
                                // Drain up to min(count, available, 4096).
                                let mut dst = [0u8; 4096];
                                let cap = count.min(dst.len() as u64);
                                let to_read = cap.min(avail) as usize;
                                let n = pair.m2s.read(&mut dst[..to_read]);
                                // Clear the inter-byte timer once we've
                                // satisfied the read; arm again when the
                                // next byte arrives.
                                pair.ldisc_deadline_ticks = None;
                                drop(table);
                                crate::pty::wake_master(pty_id);
                                if UserSliceWo::new(buf_ptr, dst[..n].len())
                                    .and_then(|s| s.copy_from_kernel(&dst[..n]))
                                    .is_err()
                                {
                                    return NEG_EFAULT;
                                }
                                return n as u64;
                            }

                            // Not ready yet: arm the inter-byte timer if
                            // VTIME is set and at least one byte has
                            // arrived; or arm the absolute timer if
                            // VMIN==0 && VTIME>0.
                            if vtime > 0
                                && pair.ldisc_deadline_ticks.is_none()
                                && ((vmin > 0 && avail > 0) || vmin == 0)
                            {
                                pair.ldisc_deadline_ticks = Some(now.saturating_add(vtime * 100));
                            }
                        }
                        if pair.master_refcount == 0 {
                            return 0; // EOF — master closed
                        }
                    } else {
                        return 0; // PTY freed
                    }
                }
                if nonblock {
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    return NEG_EINTR;
                }
                if let Err(err) = block_on_pty_slave_read(pty_id) {
                    return err;
                }
            }
        }
        FdBackend::Socket { .. } => {
            // Delegate to recvfrom with no addr
            sys_recvfrom_socket(fd as u64, buf_ptr, count, 0, 0, 0)
        }
        FdBackend::UnixSocket { handle } => {
            if count == 0 {
                return 0;
            }
            let handle = *handle;
            let nonblock = entry.nonblock;
            let capped = (count as usize).min(4096);
            let sock_type = crate::net::unix::with_unix_socket(handle, |s| s.socket_type);
            match sock_type {
                Some(crate::net::unix::UnixSocketType::Stream) => {
                    let mut tmp = alloc::vec![0u8; capped];
                    loop {
                        match crate::net::unix::unix_stream_read(handle, &mut tmp) {
                            Ok(0) => return 0,
                            Ok(n) => {
                                if UserSliceWo::new(buf_ptr, tmp[..n].len())
                                    .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                                    .is_err()
                                {
                                    return NEG_EFAULT;
                                }
                                // Phase 69d follow-up (PR #177 third-pass
                                // review fix): plain `read(2)` advances
                                // `stream_pos_consumed` past any SCM_RIGHTS
                                // entries riding with the consumed bytes,
                                // but the caller never asked for ancillary
                                // data — drain the now-ready entries and
                                // release their refs so the inflight fds
                                // do not leak.  Without this, a sender
                                // that uses sendmsg(SCM_RIGHTS) and a
                                // receiver that uses plain read(2) would
                                // permanently retain the inflight refs
                                // on the sender's fds.
                                let dropped = crate::net::unix::unix_stream_drain_ready_anc(
                                    handle,
                                    usize::MAX,
                                );
                                for inf in &dropped {
                                    release_inflight_anc_backend(&inf.backend);
                                }
                                return n as u64;
                            }
                            Err(-11) => {
                                // EAGAIN — no data yet, block or return.
                                if nonblock {
                                    return NEG_EAGAIN;
                                }
                                if has_pending_signal() {
                                    return NEG_EINTR;
                                }
                                crate::net::unix::UNIX_SOCKET_WAITQUEUES[handle].sleep();
                            }
                            Err(e) => return e as u64, // ENOTCONN, etc.
                        }
                    }
                }
                Some(crate::net::unix::UnixSocketType::Datagram) => {
                    let mut tmp = alloc::vec![0u8; capped];
                    loop {
                        match crate::net::unix::unix_dgram_recv(handle, &mut tmp) {
                            Ok((n, _sender)) => {
                                if UserSliceWo::new(buf_ptr, tmp[..n].len())
                                    .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                                    .is_err()
                                {
                                    return NEG_EFAULT;
                                }
                                return n as u64;
                            }
                            Err(-11) => {
                                if nonblock {
                                    return NEG_EAGAIN;
                                }
                                if has_pending_signal() {
                                    return NEG_EINTR;
                                }
                                crate::net::unix::UNIX_SOCKET_WAITQUEUES[handle].sleep();
                            }
                            Err(e) => return e as u64,
                        }
                    }
                }
                None => NEG_EBADF,
            }
        }
        FdBackend::Epoll { .. } => NEG_EBADF,
        // Phase 54: read from userspace VFS-service-backed fd.
        FdBackend::VfsService { service_handle, .. } => {
            let handle = *service_handle;
            let offset = entry.offset;
            let result = vfs_service_read(handle, offset, buf_ptr, count as usize);
            if result > 0 && result < 0x8000_0000_0000_0000 {
                let bytes = result as usize;
                with_current_fd_mut(fd, |slot| {
                    if let Some(e) = slot {
                        e.offset += bytes;
                    }
                });
            }
            result
        }
    }
}

/// Phase 85d — `pread64(fd, buf, count, offset)`: read `count` bytes from `fd` at
/// file `offset` into `buf` WITHOUT advancing the fd position. LLVM/clang reads
/// source files (and resource headers) this way — CPython uses sequential
/// `read`, which is why python worked in-OS and clang did not. Backed by
/// the ext2/tmpfs/fat32/ramdisk file backends (`kernel_read_fd_at`) AND the ring-3
/// `VfsService` files clang opens under `/usr` (`vfs_service_read` — also
/// offset-based). It reads at `offset` directly and NEVER mutates the fd
/// position, so it is correct under concurrent access (unlike a
/// seek/read/restore). A single non-VFS call is capped at 64 KiB (like `read`);
/// callers loop on short reads.
pub(super) fn sys_linux_pread64(fd: u64, buf_ptr: u64, count: u64, offset: u64) -> u64 {
    let fd_us = fd as usize;
    if fd_us >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_us) {
        Some(e) => e,
        None => return NEG_EBADF,
    };
    if !entry.readable {
        return NEG_EBADF;
    }
    match &entry.backend {
        // The ring-3 VFS read is already offset-based and copies straight to the
        // user buffer — no shared fd position to disturb.
        FdBackend::VfsService { service_handle, .. } => {
            vfs_service_read(*service_handle, offset as usize, buf_ptr, count as usize)
        }
        _ => {
            let to_read = (count as usize).min(64 * 1024);
            if to_read == 0 {
                return 0;
            }
            let pid = crate::process::current_pid();
            let mut kbuf = alloc::vec![0u8; to_read];
            match kernel_read_fd_at(pid, fd_us, offset as usize, &mut kbuf) {
                Ok(0) => 0,
                Ok(n) => match UserSliceWo::new(buf_ptr, n)
                    .and_then(|s| s.copy_from_kernel(&kbuf[..n]))
                {
                    Ok(()) => n as u64,
                    Err(_) => NEG_EFAULT,
                },
                Err(e) => e as u64,
            }
        }
    }
}

/// `pwrite64(fd, buf, count, offset)`: write at `offset` without touching the
/// fd's shared position.
///
/// Phase 88 Track G — now ATOMIC. The Phase 85d implementation seeked the fd to
/// `offset`, called the normal write path, then restored the saved position;
/// under `CLONE_FILES` fd-table sharing that briefly published a bogus position
/// (a concurrent `write`/`lseek` on the same fd could observe it), and it was
/// inconsistent with the already-positional `pread64`. The write is now routed
/// through `kernel_write_fd_at` (the write analog of `kernel_read_fd_at`), which
/// writes at the explicit offset and never reads or mutates `entry.offset` —
/// matching POSIX `pwrite(2)`. Non-seekable fds (pipe/socket/tty) report
/// `ESPIPE`, as POSIX requires.
pub(super) fn sys_linux_pwrite64(fd: u64, buf_ptr: u64, count: u64, offset: u64) -> u64 {
    let fd_us = fd as usize;
    if fd_us >= MAX_FDS {
        return NEG_EBADF;
    }
    let to_write = (count as usize).min(64 * 1024);
    if to_write == 0 {
        return 0;
    }
    let mut kbuf = alloc::vec![0u8; to_write];
    if UserSliceRo::new(buf_ptr, to_write)
        .and_then(|s| s.copy_to_kernel(&mut kbuf))
        .is_err()
    {
        return NEG_EFAULT;
    }
    let pid = crate::process::current_pid();
    match kernel_write_fd_at(pid, fd_us, offset as usize, &kbuf) {
        Ok(n) => n as u64,
        Err(e) => e as u64,
    }
}

/// Write a Linux `struct rlimit { rlim_cur, rlim_max }` (two `u64`) to `rlim_ptr`.
/// m3OS does not enforce per-process resource limits, so it reports an
/// effectively-unlimited value — except `RLIMIT_NOFILE`, bounded to the real
/// `MAX_FDS` ceiling so callers see a truthful descriptor cap.
fn write_rlimit(resource: u64, rlim_ptr: u64) -> u64 {
    if rlim_ptr == 0 {
        return NEG_EFAULT;
    }
    const RLIMIT_NOFILE: u64 = 7;
    const RLIM_INFINITY: u64 = u64::MAX;
    let (cur, max) = if resource == RLIMIT_NOFILE {
        (MAX_FDS as u64, MAX_FDS as u64)
    } else {
        (RLIM_INFINITY, RLIM_INFINITY)
    };
    let mut buf = [0u8; 16];
    buf[0..8].copy_from_slice(&cur.to_ne_bytes());
    buf[8..16].copy_from_slice(&max.to_ne_bytes());
    match UserSliceWo::new(rlim_ptr, 16).and_then(|s| s.copy_from_kernel(&buf)) {
        Ok(()) => 0,
        Err(_) => NEG_EFAULT,
    }
}

/// Phase 85d — `getrlimit(resource, rlim)`. clang/musl probe RLIMIT_STACK /
/// RLIMIT_NOFILE during startup; reporting generous limits is correct since m3OS
/// does not enforce them.
pub(super) fn sys_getrlimit(resource: u64, rlim_ptr: u64) -> u64 {
    write_rlimit(resource, rlim_ptr)
}

/// Phase 85d — `prlimit64(pid, resource, new_rlim, old_rlim)`. m3OS does not
/// enforce rlimits, so any `new_rlim` is accepted-and-ignored and, when
/// `old_rlim` is non-null, the same generous limits `getrlimit` reports are
/// written back. (musl routes get/setrlimit through prlimit64 on modern Linux.)
pub(super) fn sys_prlimit64(_pid: u64, resource: u64, _new_rlim: u64, old_rlim: u64) -> u64 {
    if old_rlim != 0 {
        let r = write_rlimit(resource, old_rlim);
        if (r as i64) < 0 {
            return r;
        }
    }
    0
}

// ---------------------------------------------------------------------------
// T014: write(fd, buf, count)
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_write(fd: u64, buf_ptr: u64, count: u64) -> u64 {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }

    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };

    if !entry.writable {
        return NEG_EBADF;
    }

    match &entry.backend {
        FdBackend::EventFd { id } => {
            // Phase 86d Track D — eventfd write: add an 8-byte value to the
            // counter and wake epoll/poll waiters (Go's netpollBreak wakeup).
            if (count as usize) < 8 {
                return NEG_EINVAL;
            }
            let mut bytes = [0u8; 8];
            if UserSliceRo::new(buf_ptr, bytes.len())
                .and_then(|s| s.copy_to_kernel(&mut bytes))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let val = u64::from_ne_bytes(bytes);
            match crate::eventfd::eventfd_write(*id, val) {
                Ok(()) => 8,
                Err(crate::eventfd::EventFdWriteErr::Invalid) => NEG_EINVAL,
                Err(crate::eventfd::EventFdWriteErr::WouldBlock) => NEG_EAGAIN,
                Err(crate::eventfd::EventFdWriteErr::BadFd) => NEG_EBADF,
            }
        }
        // Phase 89 Track A.1 — a timerfd is read-only; write(2) returns EINVAL.
        FdBackend::TimerFd { .. } => NEG_EINVAL,
        FdBackend::Stdout | FdBackend::DeviceTTY { .. } => {
            // stdout/stderr/tty go to serial + framebuffer console.
            let len = (count as usize).min(4096);
            let mut buf = [0u8; 4096];
            if UserSliceRo::new(buf_ptr, buf[..len].len())
                .and_then(|s| s.copy_to_kernel(&mut buf[..len]))
                .is_err()
            {
                return NEG_EFAULT;
            }
            // Phase 69a Track D.1: honour OPOST + ONLCR on the TTY write
            // path.  When OPOST is cleared, bytes pass through verbatim
            // (Phase 69's wire-protocol assumption); when OPOST + ONLCR are
            // set, outgoing `\n` is expanded to `\r\n`.
            let oflag = crate::tty::TTY0.lock().ldisc.termios.c_oflag;
            let opost = oflag & kernel_core::tty::OPOST != 0;
            let onlcr = oflag & kernel_core::tty::ONLCR != 0;
            if opost && onlcr {
                // Expand \n → \r\n on the framebuffer + serial paths.
                let mut tmp: [u8; 8192] = [0; 8192];
                let mut out = 0usize;
                for &b in &buf[..len] {
                    if b == b'\n' {
                        if out + 2 > tmp.len() {
                            break;
                        }
                        tmp[out] = b'\r';
                        tmp[out + 1] = b'\n';
                        out += 2;
                    } else {
                        if out + 1 > tmp.len() {
                            break;
                        }
                        tmp[out] = b;
                        out += 1;
                    }
                }
                if let Ok(s) = core::str::from_utf8(&tmp[..out]) {
                    crate::serial::_print(format_args!("{}", s));
                    crate::fb::write_str(s);
                }
            } else if let Ok(s) = core::str::from_utf8(&buf[..len]) {
                // OPOST off — verbatim pass-through.
                crate::serial::_print(format_args!("{}", s));
                crate::fb::write_str(s);
            }
            len as u64
        }
        FdBackend::Stdin => NEG_EBADF,
        FdBackend::Ramdisk { .. } => NEG_EBADF, // ramdisk is read-only
        FdBackend::Proc { .. } => NEG_EBADF,
        FdBackend::Tmpfs { path } => {
            let len = (count as usize).min(64 * 1024);
            let mut buf = [0u8; 4096];
            let mut written = 0usize;
            let mut offset = entry.offset;

            // Write in 4 KiB chunks to avoid huge stack buffers.
            while written < len {
                let chunk = (len - written).min(4096);
                let user_ptr = match buf_ptr.checked_add(written as u64) {
                    Some(p) => p,
                    None => {
                        if written == 0 {
                            return NEG_EFAULT;
                        }
                        break;
                    }
                };
                if UserSliceRo::new(user_ptr, buf[..chunk].len())
                    .and_then(|s| s.copy_to_kernel(&mut buf[..chunk]))
                    .is_err()
                {
                    if written == 0 {
                        return NEG_EFAULT;
                    }
                    break;
                }
                let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
                if let Err(e) = tmpfs.write_file(path, offset, &buf[..chunk]) {
                    if written == 0 {
                        return match e {
                            crate::fs::tmpfs::TmpfsError::NoSpace => NEG_ENOSPC,
                            crate::fs::tmpfs::TmpfsError::NotFound => NEG_EBADF,
                            _ => NEG_EINVAL,
                        };
                    }
                    break;
                }
                drop(tmpfs);
                written += chunk;
                offset += chunk;
            }

            with_current_fd_mut(fd_idx, |slot| {
                if let Some(e) = slot {
                    e.offset = offset;
                }
            });
            written as u64
        }
        FdBackend::Fat32Disk {
            path,
            start_cluster,
            file_size,
            dir_cluster,
        } => {
            let len = (count as usize).min(64 * 1024);
            let path = path.clone();
            let start_cluster = *start_cluster;
            let current_file_size = *file_size as usize;
            let dir_cluster = *dir_cluster;
            let offset = entry.offset;

            // Read user data in 4 KiB chunks.
            let mut data = alloc::vec![0u8; len];
            let mut copied = 0usize;
            while copied < len {
                let chunk = (len - copied).min(4096);
                let user_ptr = match buf_ptr.checked_add(copied as u64) {
                    Some(p) => p,
                    None => {
                        if copied == 0 {
                            return NEG_EFAULT;
                        }
                        break;
                    }
                };
                let mut tmp = [0u8; 4096];
                if UserSliceRo::new(user_ptr, tmp[..chunk].len())
                    .and_then(|s| s.copy_to_kernel(&mut tmp[..chunk]))
                    .is_err()
                {
                    if copied == 0 {
                        return NEG_EFAULT;
                    }
                    break;
                }
                data[copied..copied + chunk].copy_from_slice(&tmp[..chunk]);
                copied += chunk;
            }
            let data = &data[..copied];

            let mut vol = crate::fs::fat32::FAT32_VOLUME.lock();
            if let Some(vol) = vol.as_mut() {
                match vol.write_file(start_cluster, offset, data, current_file_size) {
                    Ok((new_start, new_size)) => {
                        // Extract filename from path for dir entry update.
                        let file_name = path.rsplit('/').next().unwrap_or(&path);
                        if vol
                            .update_dir_entry(dir_cluster, file_name, new_start, new_size as u32)
                            .is_err()
                        {
                            return NEG_EIO;
                        }

                        let new_offset = offset + copied;
                        with_current_fd_mut(fd_idx, |slot| {
                            if let Some(e) = slot {
                                e.offset = new_offset;
                                if let FdBackend::Fat32Disk {
                                    start_cluster: ref mut sc,
                                    file_size: ref mut fs,
                                    ..
                                } = e.backend
                                {
                                    *sc = new_start;
                                    *fs = new_size as u32;
                                }
                            }
                        });
                        copied as u64
                    }
                    Err(_) => NEG_EIO,
                }
            } else {
                NEG_EIO
            }
        }
        FdBackend::Ext2Disk {
            inode_num,
            file_size,
            path,
            ..
        } => {
            let len = (count as usize).min(64 * 1024);
            let inode_num = *inode_num;
            let _current_file_size = *file_size as usize;
            let offset = entry.offset;
            let path = path.clone();

            let mut data = alloc::vec![0u8; len];
            let mut copied = 0usize;
            while copied < len {
                let chunk = (len - copied).min(4096);
                let user_ptr = match buf_ptr.checked_add(copied as u64) {
                    Some(p) => p,
                    None => {
                        if copied == 0 {
                            return NEG_EFAULT;
                        }
                        break;
                    }
                };
                let mut tmp = [0u8; 4096];
                if UserSliceRo::new(user_ptr, tmp[..chunk].len())
                    .and_then(|s| s.copy_to_kernel(&mut tmp[..chunk]))
                    .is_err()
                {
                    if copied == 0 {
                        return NEG_EFAULT;
                    }
                    break;
                }
                data[copied..copied + chunk].copy_from_slice(&tmp[..chunk]);
                copied += chunk;
            }
            let data = &data[..copied];

            // Phase 92a D.4: a file under a /mnt/usbN secondary mount writes to
            // that mount's own ext2 volume directly. The vfs_server authority
            // owns only the root device, so it is bypassed; same-volume reads
            // stay coherent through the volume's write-through block cache.
            if let Some(write_res) = crate::fs::ext2::with_usb_mount_mut(
                &path,
                |vol, _rel| -> Result<(usize, u32), u64> {
                    let mut inode = vol.read_inode(inode_num).map_err(|_| NEG_EIO)?;
                    let now = current_unix_time();
                    inode.mtime = now;
                    inode.ctime = now;
                    let n = vol
                        .write_file_data(inode_num, &mut inode, offset as u64, data)
                        .map_err(|_| NEG_EIO)?;
                    Ok((n, inode.size))
                },
            ) {
                return match write_res {
                    Ok((n, new_size)) => {
                        let new_offset = offset + n;
                        with_current_fd_mut(fd_idx, |slot| {
                            if let Some(e) = slot {
                                e.offset = new_offset;
                                if let FdBackend::Ext2Disk {
                                    file_size: ref mut fs,
                                    ..
                                } = e.backend
                                {
                                    *fs = new_size;
                                }
                            }
                        });
                        n as u64
                    }
                    Err(e) => e,
                };
            }

            // Phase 88: route the write to the vfs_server ext2 authority when
            // it is registered, so a later read (this fd or any other process)
            // sees coherent bytes. Chunk to the reply-bulk cap; on transport
            // failure fall back to the in-kernel engine.
            if vfs_write_routable() {
                let mut total = 0usize;
                let mut cur_off = offset as u64;
                let mut last_size = *file_size;
                while total < data.len() {
                    match vfs_service_write(&path, cur_off, &data[total..]) {
                        Ok((0, _)) => break,
                        Ok((n, new_size)) => {
                            total += n;
                            cur_off += n as u64;
                            last_size = new_size;
                        }
                        Err(e) => {
                            if total == 0 {
                                return e;
                            }
                            break;
                        }
                    }
                }
                let new_offset = offset + total;
                with_current_fd_mut(fd_idx, |slot| {
                    if let Some(e) = slot {
                        e.offset = new_offset;
                        if let FdBackend::Ext2Disk {
                            file_size: ref mut fs,
                            ..
                        } = e.backend
                        {
                            *fs = last_size;
                        }
                    }
                });
                return total as u64;
            }

            let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
            if let Some(vol) = vol.as_mut() {
                match vol.read_inode(inode_num) {
                    Ok(mut inode) => {
                        // Phase 32: update mtime/ctime on write
                        let now = current_unix_time();
                        inode.mtime = now;
                        inode.ctime = now;
                        match vol.write_file_data(inode_num, &mut inode, offset as u64, data) {
                            Ok(n) => {
                                let new_offset = offset + n;
                                let new_size = inode.size;
                                with_current_fd_mut(fd_idx, |slot| {
                                    if let Some(e) = slot {
                                        e.offset = new_offset;
                                        if let FdBackend::Ext2Disk {
                                            file_size: ref mut fs,
                                            ..
                                        } = e.backend
                                        {
                                            *fs = new_size;
                                        }
                                    }
                                });
                                n as u64
                            }
                            Err(_) => NEG_EIO,
                        }
                    }
                    Err(_) => NEG_EIO,
                }
            } else {
                NEG_EIO
            }
        }
        FdBackend::PipeWrite { pipe_id } => {
            let pipe_id = *pipe_id;
            let nonblock = entry.nonblock;
            let len = (count as usize).min(4096);
            let mut buf = [0u8; 4096];
            if UserSliceRo::new(buf_ptr, buf[..len].len())
                .and_then(|s| s.copy_to_kernel(&mut buf[..len]))
                .is_err()
            {
                return NEG_EFAULT;
            }
            // Phase 61 Track F — blocking-pipe write uses
            // `PIPE_WAITQUEUES[pipe_id].sleep()` instead of the previous
            // `loop { pipe_write; yield_now }` polling. `wake_pipe` is
            // called from `pipe_read` after a successful read drains
            // capacity, so the sleep is always woken when the buffer
            // shrinks. EPIPE (`Err(false)`) returns immediately without
            // entering the wait queue — no sleep needed when the reader
            // is gone.
            let task_id = match crate::task::scheduler::current_task_id() {
                Some(id) => id,
                None => return NEG_EINTR,
            };
            let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
            loop {
                woken.store(false, core::sync::atomic::Ordering::Release);
                crate::pipe::pipe_register_waiter(pipe_id, task_id, &woken);

                match crate::pipe::pipe_write(pipe_id, &buf[..len]) {
                    Ok(n) => {
                        crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                        return n as u64;
                    }
                    Err(false) => {
                        // Reader closed — EPIPE.
                        crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                        const NEG_EPIPE: u64 = (-32_i64) as u64;
                        return NEG_EPIPE;
                    }
                    Err(true) => {
                        if nonblock {
                            crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                            return NEG_EAGAIN;
                        }
                        if has_pending_signal() {
                            crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                            return NEG_EINTR;
                        }
                        // Park until `wake_pipe(pipe_id)` fires from a
                        // matching `pipe_read` (data drained → space
                        // available) or close.
                        let _ = crate::task::scheduler::block_current_until(
                            crate::task::TaskState::BlockedOnSend,
                            &woken,
                            None,
                        );
                        crate::pipe::pipe_deregister_waiter(pipe_id, task_id);
                    }
                }
            }
        }
        FdBackend::PipeRead { .. } => NEG_EBADF,
        FdBackend::Dir { .. } => NEG_EBADF,
        FdBackend::DevNull | FdBackend::DevZero | FdBackend::DevUrandom => count, // silently discard
        FdBackend::DevFull => NEG_ENOSPC, // no space left on device
        FdBackend::PtyMaster { pty_id } => {
            // Master writes to m2s (master-to-slave) buffer.
            // Apply line discipline on the slave side (input processing).
            let pty_id = *pty_id;
            let mut src_data = alloc::vec![0u8; count.min(4096) as usize];
            if UserSliceRo::new(buf_ptr, src_data.len())
                .and_then(|s| s.copy_to_kernel(&mut src_data))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let mut table = crate::pty::PTY_TABLE.lock();
            if let Some(Some(pair)) = table.get_mut(pty_id as usize) {
                if pair.slave_refcount == 0 && !pair.locked {
                    drop(table);
                    return NEG_EIO;
                }
                let is_canonical = pair.termios.is_canonical();
                let is_echo = pair.termios.is_echo();
                let is_isig = pair.termios.is_isig();
                let iexten = pair.termios.c_lflag & kernel_core::tty::IEXTEN != 0;
                let echoe = pair.termios.c_lflag & kernel_core::tty::ECHOE != 0;
                let echok = pair.termios.c_lflag & kernel_core::tty::ECHOK != 0;
                let echonl = pair.termios.c_lflag & kernel_core::tty::ECHONL != 0;
                let icrnl = pair.termios.c_iflag & kernel_core::tty::ICRNL != 0;
                let inlcr = pair.termios.c_iflag & kernel_core::tty::INLCR != 0;
                let igncr = pair.termios.c_iflag & kernel_core::tty::IGNCR != 0;
                let ixon = pair.termios.c_iflag & kernel_core::tty::IXON != 0;
                let vintr = pair.termios.c_cc[kernel_core::tty::VINTR];
                let vquit = pair.termios.c_cc[kernel_core::tty::VQUIT];
                let vsusp = pair.termios.c_cc[kernel_core::tty::VSUSP];
                let verase = pair.termios.c_cc[kernel_core::tty::VERASE];
                let vkill = pair.termios.c_cc[kernel_core::tty::VKILL];
                let vwerase = pair.termios.c_cc[kernel_core::tty::VWERASE];
                let veof = pair.termios.c_cc[kernel_core::tty::VEOF];
                let vstart = pair.termios.c_cc[kernel_core::tty::VSTART];
                let vstop = pair.termios.c_cc[kernel_core::tty::VSTOP];
                let vlnext = pair.termios.c_cc[kernel_core::tty::VLNEXT];
                let vdiscard = pair.termios.c_cc[kernel_core::tty::VDISCARD];
                let fg_pgid = pair.slave_fg_pgid;

                let mut written = 0usize;
                let mut lnext_pending = false;
                for &byte in &src_data {
                    // Phase 69a Track E.3: VLNEXT — deliver next byte literally.
                    if lnext_pending {
                        lnext_pending = false;
                        let pair = match table.get_mut(pty_id as usize).and_then(|s| s.as_mut()) {
                            Some(p) => p,
                            None => return written as u64,
                        };
                        if is_canonical {
                            if !pair.edit_buf.push(byte) {
                                break;
                            }
                        } else if pair.m2s.write(&[byte]) == 0 {
                            break;
                        }
                        if is_echo {
                            pair.s2m.write(&[byte]);
                        }
                        written += 1;
                        continue;
                    }

                    // Input flag transformations.
                    let mut b = byte;
                    if b == b'\r' {
                        if igncr {
                            written += 1;
                            continue;
                        }
                        if icrnl {
                            b = b'\n';
                        }
                    } else if b == b'\n' && inlcr {
                        b = b'\r';
                    }

                    // Phase 69a Track C: IXON flow control (XOFF/XON).
                    if ixon {
                        if b == vstop {
                            let pair = match table.get_mut(pty_id as usize).and_then(|s| s.as_mut())
                            {
                                Some(p) => p,
                                None => return written as u64,
                            };
                            pair.ldisc_output_suspended = true;
                            written += 1;
                            continue;
                        }
                        if b == vstart {
                            let pair = match table.get_mut(pty_id as usize).and_then(|s| s.as_mut())
                            {
                                Some(p) => p,
                                None => return written as u64,
                            };
                            pair.ldisc_output_suspended = false;
                            written += 1;
                            continue;
                        }
                    }

                    // Phase 69a Track E.3: IEXTEN/VLNEXT/VDISCARD.
                    if iexten {
                        if vlnext != 0 && b == vlnext {
                            lnext_pending = true;
                            written += 1;
                            continue;
                        }
                        if vdiscard != 0 && b == vdiscard {
                            // VDISCARD toggles output discard; treated as a
                            // consume-only byte for now (kernel side never
                            // actually drops s2m bytes — symmetric to a no-op
                            // toggle so userspace can round-trip the byte).
                            written += 1;
                            continue;
                        }
                    }

                    // Signal generation (ISIG).
                    if is_isig {
                        if b == vintr {
                            if fg_pgid != 0 {
                                drop(table);
                                crate::process::send_signal_to_group(
                                    fg_pgid,
                                    crate::process::SIGINT,
                                );
                                table = crate::pty::PTY_TABLE.lock();
                            }
                            written += 1;
                            continue;
                        }
                        if b == vquit {
                            if fg_pgid != 0 {
                                drop(table);
                                crate::process::send_signal_to_group(
                                    fg_pgid,
                                    crate::process::SIGQUIT,
                                );
                                table = crate::pty::PTY_TABLE.lock();
                            }
                            written += 1;
                            continue;
                        }
                        if b == vsusp {
                            if fg_pgid != 0 {
                                drop(table);
                                crate::process::send_signal_to_group(
                                    fg_pgid,
                                    crate::process::SIGTSTP,
                                );
                                table = crate::pty::PTY_TABLE.lock();
                            }
                            written += 1;
                            continue;
                        }
                    }

                    // Re-acquire pair reference after potential drop/reacquire.
                    let pair = match table.get_mut(pty_id as usize).and_then(|s| s.as_mut()) {
                        Some(p) => p,
                        None => return written as u64,
                    };

                    if is_canonical {
                        // Canonical mode: buffer in edit_buf.
                        if b == verase {
                            if pair.edit_buf.erase_char().is_some() && is_echo && echoe {
                                pair.s2m.write(b"\x08 \x08");
                            }
                        } else if b == vkill {
                            let n = pair.edit_buf.kill_line();
                            if is_echo {
                                if echok {
                                    pair.s2m.write(b"\n");
                                } else {
                                    for _ in 0..n {
                                        pair.s2m.write(b"\x08 \x08");
                                    }
                                }
                            }
                        } else if b == vwerase {
                            let n = pair.edit_buf.word_erase();
                            if is_echo {
                                for _ in 0..n {
                                    pair.s2m.write(b"\x08 \x08");
                                }
                            }
                        } else if b == veof {
                            // ^D: if edit buffer has content, flush as a line.
                            // If empty, signal EOF to the reader.
                            if !pair.edit_buf.is_empty() {
                                if !pair.edit_buf.push(b'\n') {
                                    // Edit buffer full — stop without counting this byte.
                                    break;
                                }
                            } else {
                                pair.eof_pending = true;
                            }
                            // Don't echo ^D.
                        } else {
                            if !pair.edit_buf.push(b) {
                                // Edit buffer full — stop without counting this byte.
                                break;
                            }
                            if is_echo {
                                if b == b'\n' || echonl || b >= 0x20 {
                                    pair.s2m.write(&[b]);
                                } else {
                                    // Echo control chars as ^X.
                                    pair.s2m.write(&[b'^', b + 0x40]);
                                }
                            }
                        }
                    } else {
                        // Raw mode: write directly to m2s.
                        if pair.m2s.write(&[b]) == 0 {
                            break; // buffer full
                        }
                        if is_echo {
                            pair.s2m.write(&[b]);
                        }
                    }
                    written += 1;
                }
                drop(table);
                // Wake slave waiters (data written to m2s / edit_buf).
                crate::pty::wake_slave(pty_id);
                // Wake master waiters (echo may have written to s2m).
                crate::pty::wake_master(pty_id);
                written as u64
            } else {
                NEG_EIO
            }
        }
        FdBackend::PtySlave { pty_id } => {
            // Slave writes to s2m (slave-to-master) buffer.
            // Apply output processing (OPOST).
            let pty_id = *pty_id;
            let mut src_data = alloc::vec![0u8; count.min(4096) as usize];
            if UserSliceRo::new(buf_ptr, src_data.len())
                .and_then(|s| s.copy_to_kernel(&mut src_data))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let mut table = crate::pty::PTY_TABLE.lock();
            if let Some(Some(pair)) = table.get_mut(pty_id as usize) {
                if pair.master_refcount == 0 {
                    return NEG_EIO;
                }
                let opost = pair.termios.c_oflag & kernel_core::tty::OPOST != 0;
                let onlcr = pair.termios.c_oflag & kernel_core::tty::ONLCR != 0;
                let mut written = 0usize;
                for &b in &src_data {
                    if opost && onlcr && b == b'\n' {
                        // Ensure atomic CR+LF: need at least 2 bytes of space.
                        if pair.s2m.space() < 2 {
                            break;
                        }
                        pair.s2m.write(b"\r");
                        pair.s2m.write(b"\n");
                    } else if pair.s2m.write(&[b]) == 0 {
                        break;
                    }
                    written += 1;
                }
                drop(table);
                // Wake master waiters (data written to s2m).
                crate::pty::wake_master(pty_id);
                written as u64
            } else {
                NEG_EIO
            }
        }
        FdBackend::Socket { .. } => {
            // Delegate to sendto with no addr
            sys_sendto(fd, buf_ptr, count, 0, 0, 0)
        }
        FdBackend::UnixSocket { handle } => {
            let handle = *handle;
            let nonblock = entry.nonblock;
            let capped = (count as usize).min(4096);
            let mut data = alloc::vec![0u8; capped];
            if UserSliceRo::new(buf_ptr, data.len())
                .and_then(|s| s.copy_to_kernel(&mut data))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let sock_type = crate::net::unix::with_unix_socket(handle, |s| s.socket_type);
            match sock_type {
                Some(crate::net::unix::UnixSocketType::Stream) => loop {
                    match crate::net::unix::unix_stream_write(handle, &data) {
                        Ok(n) => return n as u64,
                        Err(-11) => {
                            // EAGAIN — buffer full, block or return.
                            if nonblock {
                                return NEG_EAGAIN;
                            }
                            if has_pending_signal() {
                                return NEG_EINTR;
                            }
                            crate::net::unix::UNIX_SOCKET_WAITQUEUES[handle].sleep();
                        }
                        Err(e) => return e as u64, // EPIPE, ENOTCONN, etc.
                    }
                },
                Some(crate::net::unix::UnixSocketType::Datagram) => {
                    // For connected datagram sockets, send to peer
                    let peer = crate::net::unix::with_unix_socket(handle, |s| s.peer).flatten();
                    let sender_path =
                        crate::net::unix::with_unix_socket(handle, |s| s.path.clone()).flatten();
                    match peer {
                        Some(target) => loop {
                            match crate::net::unix::unix_dgram_send(
                                sender_path.clone(),
                                target,
                                &data,
                            ) {
                                Ok(n) => {
                                    crate::net::unix::wake_unix_socket(target);
                                    return n as u64;
                                }
                                Err(-11) => {
                                    if nonblock {
                                        return NEG_EAGAIN;
                                    }
                                    if has_pending_signal() {
                                        return NEG_EINTR;
                                    }
                                    crate::net::unix::UNIX_SOCKET_WAITQUEUES[target].sleep();
                                }
                                Err(e) => return e as u64,
                            }
                        },
                        None => NEG_ENOTCONN,
                    }
                }
                None => NEG_EBADF,
            }
        }
        FdBackend::Epoll { .. } => NEG_EBADF,
        FdBackend::VfsService { .. } => NEG_EBADF, // read-only; writes rejected
    }
}

// ---------------------------------------------------------------------------
// T015: open(path, flags) / openat delegates here
// ---------------------------------------------------------------------------

/// Read a null-terminated C string from userspace into `buf`.
///
/// Copies one byte at a time to handle page boundaries gracefully.
/// Returns the UTF-8 string on success, or `None` if the pointer is invalid,
/// the string exceeds `buf.len()`, or the bytes are not valid UTF-8.
fn read_user_cstr<const N: usize>(ptr: u64, buf: &mut [u8; N]) -> Option<&str> {
    if ptr == 0 {
        return None;
    }
    let mut len = 0usize;
    while len < buf.len() {
        let mut b = [0u8; 1];
        let addr = ptr.checked_add(len as u64)?;
        if UserSliceRo::new(addr, b.len())
            .and_then(|s| s.copy_to_kernel(&mut b))
            .is_err()
        {
            return None;
        }
        if b[0] == 0 {
            break;
        }
        buf[len] = b[0];
        len += 1;
    }
    if len >= buf.len() {
        return None; // no NUL terminator found within buffer
    }
    if len == 0 {
        return Some("");
    }
    core::str::from_utf8(&buf[..len]).ok()
}

/// Linux open flags.
const O_CREAT: u64 = 0o100;
const O_TRUNC: u64 = 0o1000;
const O_APPEND: u64 = 0o2000;
const O_DIRECTORY: u64 = 0o200000;
#[allow(dead_code)]
const O_NOFOLLOW: u64 = 0o400000;
/// `O_NONBLOCK` (0x800). When set on the FD via `open()` the kernel must
/// translate would-block conditions into `-EAGAIN` rather than parking.
const O_NONBLOCK: u64 = 0o4000;
/// `O_CLOEXEC` (0x80000). Atomically marks the new FD as close-on-exec,
/// closing the open/fcntl race window.
const O_CLOEXEC: u64 = 0o2000000;

/// `AT_FDCWD` sentinel: resolve relative paths against the process's cwd.
pub(super) const AT_FDCWD: u64 = (-100_i64) as u64;
pub(super) const AT_SYMLINK_NOFOLLOW: u64 = 0x100;
const AT_SYMLINK_FOLLOW: u64 = 0x400;

/// Check if a resolved absolute path is a directory across all filesystems.
fn is_directory(path: &str) -> bool {
    if path == "/" {
        return true;
    }
    if crate::fs::procfs::is_dir(path) {
        return true;
    }
    if let Some(rel) = tmpfs_relative_path(path) {
        if rel.is_empty() {
            return true; // /tmp itself
        }
        let tmpfs = crate::fs::tmpfs::TMPFS.lock();
        return tmpfs.stat(rel).map(|s| s.is_dir).unwrap_or(false);
    }
    // Check ramdisk first (overlays /bin, /sbin).
    if let Some(node) = crate::fs::ramdisk::ramdisk_lookup(path) {
        return node.is_dir();
    }
    // ext2 root filesystem.
    if crate::fs::ext2::is_mounted()
        && let Some(rel) = ext2_root_path(path)
    {
        let vol = crate::fs::ext2::EXT2_VOLUME.lock();
        if let Some(vol) = vol.as_ref() {
            return vol.is_dir(rel);
        }
    }
    // Legacy: /data paths for FAT32 fallback.
    if let Some(rel) = fat32_relative_path(path) {
        if rel.is_empty() {
            return data_is_mounted();
        }
        if crate::fs::fat32::is_mounted() {
            let vol = crate::fs::fat32::FAT32_VOLUME.lock();
            if let Some(vol) = vol.as_ref() {
                return vol.lookup(rel).map(|e| e.is_dir()).unwrap_or(false);
            }
        }
    }
    false
}

/// Phase 31: Read a file's entire contents from disk filesystems (ext2, FAT32, tmpfs).
///
/// Used by `sys_execve` to load binaries from persistent storage instead of
/// only the ramdisk. Returns `Ok(contents)` on success or `Err(neg_errno)` on
/// failure (e.g. `NEG_ENOENT` if not found, `NEG_E2BIG` if too large).
const NEG_E2BIG: u64 = (-7_i64) as u64;

/// Engine-unification Phase B: whether an `execve` binary read for `path` should
/// be served by the ring-3 `vfs_server` rather than the in-kernel ext2 loader.
///
/// The early-boot window — `vfs_server` not yet registered, or the `vfs_server`
/// binary loading *itself* — returns `false` so `init` and `vfs_server` are
/// brought up from the FS by the in-kernel loader (`vfs_write_routable` already
/// folds in the `is_current_exec_path("/bin/vfs_server")` guard). Only ext2-root
/// binaries route; ramdisk (`/bin/sh`, …) and `/data` (fat32) keep their own
/// loaders. Once routed, the read holds no `EXT2_VOLUME` lock and observes any
/// write-back-deferred bytes — the Phase C precondition for the exec path.
fn exec_should_route(path: &str) -> bool {
    vfs_write_routable()
        && !path.starts_with("/data/")
        && crate::fs::ramdisk::ramdisk_lookup(path).is_none()
        && ext2_root_path(path).is_some()
}

/// Open `path` read-only through `vfs_server` for a kernel-side exec read,
/// returning the raw service handle (no fd allocation). The `VFS_OPEN` reply
/// carries a stat-header bulk the exec loader does not need; it is drained so it
/// cannot bleed into the first `VFS_READ`. Close with [`vfs_service_close`].
fn vfs_exec_open(path: &str) -> Result<u64, u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_OPEN;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_ENOENT)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let mut msg = Message::new(VFS_OPEN);
    msg.data[0] = 0; // O_RDONLY — the server rejects anything else
    msg.data[1] = path.len() as u64;
    scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(path.as_bytes()));
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    // Drain the (unused) stat-header bulk the open reply delivers.
    let _ = scheduler::take_bulk_data(task_id);
    Ok(reply.data[0] & 0xFFFF_FFFF)
}

/// Read the whole of an already-stat'd ext2 binary (`size` bytes) through
/// `vfs_server` into a fresh kernel buffer (engine-unification Phase B, static
/// exec path). Opens a read-only handle, drains it with the kernel `VFS_READ`
/// client (which caps each round-trip at `VFS_MAX_PREAD`), and always closes the
/// handle. No `EXT2_VOLUME` lock is held across the transfer.
fn vfs_exec_read_bytes(path: &str, size: usize) -> Result<alloc::vec::Vec<u8>, u64> {
    let handle = vfs_exec_open(path)?;
    let mut buf = alloc::vec![0u8; size];
    let mut read = 0usize;
    let result = loop {
        if read >= size {
            break Ok(());
        }
        match vfs_service_read_kernel(handle, read, &mut buf[read..]) {
            Ok(0) => break Ok(()), // short file / EOF
            Ok(n) => read += n,
            Err(e) => break Err(e as u64),
        }
    };
    vfs_service_close(handle);
    result?;
    buf.truncate(read);
    Ok(buf)
}

pub(crate) fn read_file_from_disk(path: &str) -> Result<alloc::vec::Vec<u8>, u64> {
    /// Maximum executable size we can safely materialize in one reclaimable
    /// kernel heap allocation with the current page-backed large-allocation path.
    const MAX_EXEC_SIZE: usize = crate::mm::heap::max_page_backed_allocation_bytes();

    // Engine-unification Phase B: post-boot, read an ext2-resident binary through
    // the `vfs_server` authority — no `EXT2_VOLUME` lock held across the read,
    // and a write-back-deferred binary is visible. The `vfs_service_stat_path`
    // (cached) gives the size up front so a too-large binary returns E2BIG to the
    // streaming path exactly as the in-kernel branch does. Any vfs miss (stat
    // fails, not a regular file, read error) falls through to the in-kernel ext2
    // path below — which also covers the boot window, where `exec_should_route`
    // is false and `init`/`vfs_server` load via the in-kernel loader.
    if exec_should_route(path)
        && let Ok(st) = vfs_service_stat_path(path)
        && st.kind == kernel_core::fs::vfs_protocol::VFS_NODE_FILE
    {
        let size = st.size as usize;
        if size > MAX_EXEC_SIZE {
            log::warn!("[exec] file too large ({size} bytes > {MAX_EXEC_SIZE} limit): {path}");
            return Err(NEG_E2BIG);
        }
        if size > 0
            && let Ok(buf) = vfs_exec_read_bytes(path, size)
        {
            return Ok(buf);
        }
    }

    // Try ext2 root filesystem first (most likely location for compiled binaries).
    // Skip /data/ paths — those are routed to FAT32 by other syscalls.
    if crate::fs::ext2::is_mounted() && !path.starts_with("/data/") {
        let vol = crate::fs::ext2::EXT2_VOLUME.lock();
        if let Some(vol) = vol.as_ref() {
            let rel = path.trim_start_matches('/');
            if let Ok(inode_num) = vol.resolve_path(rel)
                && let Ok(inode) = vol.read_inode(inode_num)
            {
                let size = inode.size as usize;
                if size > MAX_EXEC_SIZE {
                    log::warn!(
                        "[exec] file too large ({} bytes > {} limit): {}",
                        size,
                        MAX_EXEC_SIZE,
                        path
                    );
                    return Err(NEG_E2BIG);
                }
                if size > 0 {
                    let mut buf = alloc::vec![0u8; size];
                    if let Ok(n) = vol.read_file_data(&inode, 0, &mut buf) {
                        buf.truncate(n);
                        return Ok(buf);
                    }
                }
            }
        }
    }

    // Try tmpfs (/tmp).
    if let Some(rel) = tmpfs_relative_path(path)
        && !rel.is_empty()
    {
        let tmpfs = crate::fs::tmpfs::TMPFS.lock();
        if let Ok(stat) = tmpfs.stat(rel) {
            if stat.size > MAX_EXEC_SIZE {
                log::warn!(
                    "[exec] file too large ({} bytes > {} limit): {}",
                    stat.size,
                    MAX_EXEC_SIZE,
                    path
                );
                return Err(NEG_E2BIG);
            }
            if let Ok(data) = tmpfs.read_file(rel, 0, stat.size)
                && !data.is_empty()
            {
                return Ok(data.to_vec());
            }
        }
    }

    // Try FAT32 (/data mount).
    let fat_rel = if let Some(stripped) = path.strip_prefix("/data/") {
        Some(stripped)
    } else if path.starts_with("/usr/") {
        Some(path.trim_start_matches('/'))
    } else {
        None
    };
    if let Some(rel) = fat_rel {
        let vol = crate::fs::fat32::FAT32_VOLUME.lock();
        if let Some(vol) = vol.as_ref()
            && let Ok(entry) = vol.lookup(rel)
            && !entry.is_dir()
        {
            let size = entry.file_size as usize;
            if size > MAX_EXEC_SIZE {
                log::warn!(
                    "[exec] file too large ({} bytes > {} limit): {}",
                    size,
                    MAX_EXEC_SIZE,
                    path
                );
                return Err(NEG_E2BIG);
            }
            if size > 0 {
                let cluster = entry.start_cluster();
                let mut buf = alloc::vec![0u8; size];
                if let Ok(n) = vol.read_file(cluster, entry.file_size, 0, &mut buf)
                    && n == size
                {
                    return Ok(buf);
                }
            }
        }
    }

    Err(NEG_ENOENT)
}

/// Phase 85d — ceiling for a binary loaded via the streaming exec path. The
/// streamed loader needs only a small windowed buffer, so this is generous (the
/// ~65 MiB static clang fits with room to spare); above it `execve` returns
/// E2BIG. Guards against a malformed/huge file driving unbounded segment reads.
const LARGE_EXEC_MAX: usize = 512 * 1024 * 1024; // 512 MiB

/// 1 MiB sliding window for [`DiskElfSource`]. Streaming a 65 MiB binary then
/// costs ~65 ext2 reads instead of ~16000 page reads.
const EXEC_STREAM_WINDOW: usize = 1024 * 1024;

/// Buffered window backing [`DiskElfSource`] — the valid bytes are
/// `data[0..len]`, covering file range `[offset, offset + len)`.
struct ExecWindow {
    offset: usize,
    len: usize,
    data: alloc::vec::Vec<u8>,
}

/// Backing store for a [`DiskElfSource`] window refill.
enum ExecStreamSource {
    /// In-kernel ext2 by inode (early-boot window / `vfs_server` degraded).
    Kernel(kernel_core::fs::ext2::Ext2Inode),
    /// Engine-unification Phase B: an open `vfs_server` read handle — the routed
    /// post-boot path, read with the kernel `VFS_READ` client (no `EXT2_VOLUME`
    /// lock, write-back-visible). Closed when the `DiskElfSource` is dropped.
    Vfs(u64),
}

/// Phase 85d — a disk-backed, windowed [`crate::mm::elf::ElfBytes`] source for
/// ext2-resident binaries too large to materialize in one kernel-heap buffer (the
/// ~65 MiB static `clang` exceeds the entire 64 MiB heap). Reads ranges on demand
/// through a 1 MiB sliding window, so `mm::elf::load_elf_streaming` never needs a
/// giant allocation. The bytes come either from the in-kernel ext2 engine (boot
/// window) or — once `vfs_server` is registered — from it over IPC
/// (engine-unification Phase B). Only ext2-root binaries stream; a large binary
/// elsewhere falls back to E2BIG (no such case exists in practice).
struct DiskElfSource {
    source: ExecStreamSource,
    size: usize,
    window: spin::Mutex<ExecWindow>,
}

impl Drop for DiskElfSource {
    fn drop(&mut self) {
        if let ExecStreamSource::Vfs(handle) = self.source {
            vfs_service_close(handle);
        }
    }
}

impl DiskElfSource {
    /// Refill the window so it starts at `offset`. Reads up to
    /// `EXEC_STREAM_WINDOW` bytes (clamped to EOF) from the backing source.
    fn refill(&self, win: &mut ExecWindow, offset: usize) -> Result<(), crate::mm::elf::ElfError> {
        use crate::mm::elf::ElfError;
        let to_read = EXEC_STREAM_WINDOW.min(self.size.saturating_sub(offset));
        if win.data.len() < EXEC_STREAM_WINDOW {
            win.data.resize(EXEC_STREAM_WINDOW, 0);
        }
        let n = match &self.source {
            ExecStreamSource::Kernel(inode) => {
                let vol = crate::fs::ext2::EXT2_VOLUME.lock();
                let vol = vol
                    .as_ref()
                    .ok_or(ElfError::MappingFailed("ext2 not mounted (streamed exec)"))?;
                vol.read_file_data(inode, offset as u64, &mut win.data[..to_read])
                    .map_err(|_| ElfError::MappingFailed("ext2 read failed (streamed exec)"))?
            }
            ExecStreamSource::Vfs(handle) => {
                // The kernel `VFS_READ` client caps each round-trip at
                // `VFS_MAX_PREAD` (< `EXEC_STREAM_WINDOW`), so loop to fill the
                // window. A short read before EOF leaves `len` at what landed.
                let mut filled = 0usize;
                while filled < to_read {
                    match vfs_service_read_kernel(
                        *handle,
                        offset + filled,
                        &mut win.data[filled..to_read],
                    ) {
                        Ok(0) => break,
                        Ok(got) => filled += got,
                        Err(_) => {
                            return Err(ElfError::MappingFailed("vfs read failed (streamed exec)"));
                        }
                    }
                }
                filled
            }
        };
        win.offset = offset;
        win.len = n;
        Ok(())
    }
}

impl crate::mm::elf::ElfBytes for DiskElfSource {
    fn total_len(&self) -> usize {
        self.size
    }

    fn read_at(&self, offset: usize, buf: &mut [u8]) -> Result<(), crate::mm::elf::ElfError> {
        use crate::mm::elf::ElfError;
        if buf.is_empty() {
            return Ok(());
        }
        let end = offset
            .checked_add(buf.len())
            .ok_or(ElfError::TruncatedProgramHeader)?;
        if end > self.size {
            return Err(ElfError::TruncatedProgramHeader);
        }
        let mut win = self.window.lock();
        let in_window = offset >= win.offset && end <= win.offset + win.len;
        if !in_window {
            // Window the read so the requested range starts at the window base.
            // Every caller read is <= the phdr table (<= 64 KiB) or one page
            // (4096), both <= EXEC_STREAM_WINDOW, so one refill at `offset`
            // always covers it.
            self.refill(&mut win, offset)?;
            if win.len < buf.len() {
                return Err(ElfError::TruncatedProgramHeader);
            }
        }
        let start = offset - win.offset;
        buf.copy_from_slice(&win.data[start..start + buf.len()]);
        Ok(())
    }
}

/// Phase 85d — resolve a large executable `path` to a streaming
/// [`DiskElfSource`]. Only the ext2 root (where `/usr/bin/clang-18` lives) is
/// supported; the caller falls back to E2BIG for large binaries elsewhere.
fn open_exec_stream(path: &str) -> Result<DiskElfSource, u64> {
    let empty_window = || {
        spin::Mutex::new(ExecWindow {
            offset: 0,
            len: 0,
            data: alloc::vec::Vec::new(),
        })
    };

    // Engine-unification Phase B: post-boot, stream the large binary through the
    // `vfs_server` authority (no `EXT2_VOLUME` lock per refill, write-back-
    // visible). `vfs_service_stat_path` (cached) gives the size; a routed
    // `LARGE_EXEC_MAX` overflow returns E2BIG exactly as the in-kernel branch
    // does. Any vfs miss falls through to the in-kernel path below, which also
    // serves the boot window (`exec_should_route` false → in-kernel loader).
    if exec_should_route(path)
        && let Ok(st) = vfs_service_stat_path(path)
        && st.kind == kernel_core::fs::vfs_protocol::VFS_NODE_FILE
    {
        let size = st.size as usize;
        if size > LARGE_EXEC_MAX {
            log::warn!(
                "[execve] file too large for streaming ({size} bytes > {LARGE_EXEC_MAX} limit): {path}"
            );
            return Err(NEG_E2BIG);
        }
        if let Ok(handle) = vfs_exec_open(path) {
            return Ok(DiskElfSource {
                source: ExecStreamSource::Vfs(handle),
                size,
                window: empty_window(),
            });
        }
    }

    if crate::fs::ext2::is_mounted() && !path.starts_with("/data/") {
        let vol = crate::fs::ext2::EXT2_VOLUME.lock();
        if let Some(vol) = vol.as_ref() {
            let rel = path.trim_start_matches('/');
            if let Ok(inode_num) = vol.resolve_path(rel)
                && let Ok(inode) = vol.read_inode(inode_num)
            {
                let size = inode.size as usize;
                if size > LARGE_EXEC_MAX {
                    log::warn!(
                        "[execve] file too large for streaming ({} bytes > {} limit): {}",
                        size,
                        LARGE_EXEC_MAX,
                        path
                    );
                    return Err(NEG_E2BIG);
                }
                return Ok(DiskElfSource {
                    source: ExecStreamSource::Kernel(inode),
                    size,
                    window: empty_window(),
                });
            }
        }
    }
    // The sole caller invokes this only after `read_file_from_disk` returned
    // `NEG_E2BIG` — i.e. the file provably exists but is too large to buffer. If
    // streaming is unavailable (ext2 not mounted, a `/data/`/FAT32 or tmpfs path,
    // or the ext2 lookup failed), the binary is still "found but too large", so
    // surface E2BIG rather than ENOENT (which would misreport "not found" for a
    // large binary on a non-ext2 mount). Matches this fn's documented contract.
    Err(NEG_E2BIG)
}

/// Check if a path targets the tmpfs mount at `/tmp`.
///
/// Returns `Some(relative_path)` if so (e.g. "/tmp/foo" → "foo").
/// Rejects paths containing `.`, `..`, or empty segments to prevent
/// traversal outside the `/tmp` mount boundary.
/// Return the tmpfs-internal path for `path`, or `None` if `path` does not
/// live on tmpfs.
///
/// The shared tmpfs instance mounts both `/tmp` and `/run` as top-level
/// directories. The returned path preserves the mount-point prefix (`tmp/…`
/// or `run/…`) so the tmpfs tree resolves to the correct sub-tree — callers
/// simply pass the result to `TMPFS.stat`, `TMPFS.write_file`, etc.
///
/// - `/tmp` or `/run` → `Some("tmp")` / `Some("run")` (the mount-point dir).
/// - `/tmp/foo/bar` → `Some("tmp/foo/bar")`.
/// - Anything else, or a path with `.`, `..`, or empty segments → `None`.
///
/// The logic lives in `kernel-core` ([`kernel_core::fs::tmpfs::mount_relative_path`])
/// so it is host-unit-tested — the convention must stay in lockstep with the
/// `Tmpfs::components` keying, and a past divergence (a hand-rolled
/// `strip_prefix("/tmp")`) silently broke chmod/chown on `/tmp` until Phase 85b.
fn tmpfs_relative_path(path: &str) -> Option<&str> {
    kernel_core::fs::tmpfs::mount_relative_path(path)
}

/// Return the relative path within `/data` if this path starts with `/data`.
/// Kept for backwards compatibility with FAT32 fallback.
fn fat32_relative_path(path: &str) -> Option<&str> {
    let trimmed = path.trim_start_matches('/');
    let rest = if trimmed == "data" {
        ""
    } else {
        trimmed.strip_prefix("data/")?
    };

    if !rest.is_empty() {
        for segment in rest.split('/') {
            if segment.is_empty() || segment == "." || segment == ".." {
                return None;
            }
        }
    }

    Some(rest)
}

/// Return the ext2 root-relative path for an absolute path.
///
/// When ext2 is mounted at `/`, every path is potentially on ext2.
/// Returns `None` only for paths claimed by tmpfs (`/tmp`) or that
/// fail traversal validation.
fn ext2_root_path(path: &str) -> Option<&str> {
    // /tmp and /run are always tmpfs, never ext2.
    if path == "/tmp" || path.starts_with("/tmp/") || path == "/run" || path.starts_with("/run/") {
        return None;
    }

    let rest = path.strip_prefix('/').unwrap_or(path);

    // Reject `.`, `..`, and empty segments.
    if !rest.is_empty() {
        for segment in rest.split('/') {
            if segment.is_empty() || segment == "." || segment == ".." {
                return None;
            }
        }
    }

    Some(rest)
}

// ---------------------------------------------------------------------------
// Phase 54: userspace VFS service routing
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub(crate) struct VfsPathStat {
    kind: u64,
    mode: u32,
    uid: u32,
    gid: u32,
    ino: u64,
    size: u64,
    nlink: u64,
    blksize: u64,
    atime: i64,
    mtime: i64,
    ctime: i64,
    /// st_blocks — count of 512-byte blocks allocated (Phase 88 Track B.1).
    blocks: u64,
    symlink_target: Option<alloc::string::String>,
}

/// Returns `true` when `path` (already fully resolved) should be routed
/// through the ring-3 `vfs` service rather than the in-kernel ext2 path.
fn vfs_service_can_handle_path(path: &str) -> bool {
    if is_current_exec_path("/bin/vfs_server") {
        return false;
    }
    if path == "/proc" || path.starts_with("/proc/") || path == "/dev" || path.starts_with("/dev/")
    {
        return false;
    }
    if path == "/data" || path.starts_with("/data/") {
        return false;
    }
    crate::ipc::registry::is_registered("vfs")
        && crate::fs::ramdisk::ramdisk_lookup(path).is_none()
        && ext2_root_path(path).is_some()
}

fn vfs_service_can_list_dir(path: &str) -> bool {
    path != "/"
        && vfs_service_can_handle_path(path)
        && crate::fs::ramdisk::ramdisk_list_dir(path).is_none()
}

/// Whether the ext2 *contents* of `path` can be enumerated through `vfs_server`
/// (engine-unification Phase A). Listing is a MERGE — the ramdisk overlays the
/// ext2 dir rather than shadowing it — so, unlike `vfs_service_can_handle_path`
/// (single-file shadow semantics), a ramdisk-present directory such as `/`,
/// `/bin`, or `/etc` still routes its ext2 portion to the server; the caller
/// merges the ramdisk/virtual overlays on top. Excludes `vfs_server` itself,
/// the kernel-owned virtual filesystems, and `/data` (fat32).
fn vfs_can_list_ext2_dir(path: &str) -> bool {
    if is_current_exec_path("/bin/vfs_server") {
        return false;
    }
    if path == "/proc" || path.starts_with("/proc/") || path == "/dev" || path.starts_with("/dev/")
    {
        return false;
    }
    if path == "/data" || path.starts_with("/data/") {
        return false;
    }
    crate::ipc::registry::is_registered("vfs") && ext2_root_path(path).is_some()
}

fn vfs_bootstrap_mount_action(target: &str, fstype: &str) -> Result<u64, u64> {
    use kernel_core::fs::vfs_protocol::{VFS_MOUNT_EXT2_ROOT, VFS_MOUNT_VFAT_DATA};

    match (target, fstype) {
        ("/", "ext2") => Ok(VFS_MOUNT_EXT2_ROOT),
        ("/data", "vfat") => Ok(VFS_MOUNT_VFAT_DATA),
        _ => Err(NEG_EINVAL),
    }
}

fn vfs_bootstrap_umount_action(target: &str) -> Result<u64, u64> {
    use kernel_core::fs::vfs_protocol::{VFS_UMOUNT_EXT2_ROOT, VFS_UMOUNT_VFAT_DATA};

    match target {
        "/" => Ok(VFS_UMOUNT_EXT2_ROOT),
        "/data" => Ok(VFS_UMOUNT_VFAT_DATA),
        _ => Err(NEG_EINVAL),
    }
}

fn vfs_service_parse_stat_reply(bulk: &[u8]) -> Result<VfsPathStat, u64> {
    use kernel_core::fs::vfs_protocol::{VFS_NODE_SYMLINK, VFS_STAT_REPLY_SIZE};

    if bulk.len() < VFS_STAT_REPLY_SIZE {
        return Err(NEG_EIO);
    }
    let read_word = |index: usize| -> u64 {
        let start = index * 8;
        let mut word = [0u8; 8];
        word.copy_from_slice(&bulk[start..start + 8]);
        u64::from_le_bytes(word)
    };
    let kind = read_word(0);
    let symlink_target = if kind == VFS_NODE_SYMLINK {
        Some(
            alloc::string::String::from_utf8(bulk[VFS_STAT_REPLY_SIZE..].to_vec())
                .map_err(|_| NEG_EIO)?,
        )
    } else {
        None
    };
    Ok(VfsPathStat {
        kind,
        mode: read_word(1) as u32,
        uid: read_word(2) as u32,
        gid: read_word(3) as u32,
        ino: read_word(4),
        size: read_word(5),
        nlink: read_word(6),
        blksize: read_word(7),
        atime: read_word(8) as i64,
        mtime: read_word(9) as i64,
        ctime: read_word(10) as i64,
        blocks: read_word(11),
        symlink_target,
    })
}

fn vfs_service_open(path: &str, flags: u64) -> u64 {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_OPEN;

    let vfs_ep = match registry::lookup_endpoint_id("vfs") {
        Some(ep) => ep,
        None => return NEG_ENOENT,
    };
    let task_id = match scheduler::current_task_id() {
        Some(id) => id,
        None => return NEG_EINVAL,
    };

    // Forward the caller's flags so `vfs_server::handle_open` can enforce
    // its defensive flag-validation contract (reject anything other than
    // read-only, non-creating, non-truncating opens).
    let mut msg = Message::new(VFS_OPEN);
    msg.data[0] = flags;
    msg.data[1] = path.len() as u64;
    scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(path.as_bytes()));

    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return reply.label;
    }

    let packed = reply.data[0];
    let handle = packed & 0xFFFF_FFFF;

    // Phase 88 Track B.1/D — the vfs_server returns the full stat header in the
    // reply bulk; parse it into the fd's metadata snapshot. This replaces the
    // 85d double-resolve (a second `EXT2_VOLUME.resolve_path(path)` here) and the
    // cross-implementation coupling it introduced: fstat now reports the
    // vfs_server's own inode/mode/uid/gid/nlink/size/blocks/times, guaranteed to
    // match what `fstatat` (also served by the vfs_server) reports for the path.
    //
    // A successful (label==0) VFS_OPEN reply is contractually GUARANTEED to carry
    // the stat header: `vfs_server::handle_open` only replies label==0 after
    // `ipc_store_reply_bulk(&stat_header)` succeeds (otherwise it replies EIO).
    // A missing/unparseable bulk here therefore means a protocol/version mismatch
    // or a scheduler bug, not a normal open — so return EIO rather than silently
    // seeding inode=0 (the 85d stat-identity defect this track exists to prevent).
    // Our sole caller treats this EIO as a fall-back trigger and re-opens via the
    // in-kernel ext2 engine (`open_resolved_path`), which builds a complete, real
    // metadata snapshot — so no degraded inode=0 fd is ever constructed and the
    // open transparently recovers. The committed server-side handle is abandoned
    // on this should-never-happen path; that is strictly preferable to a bad fd.
    let meta = match scheduler::take_bulk_data(task_id)
        .ok_or(NEG_EIO)
        .and_then(|bulk| vfs_service_parse_stat_reply(&bulk))
    {
        Ok(st) => crate::process::VfsFileMeta {
            inode: st.ino as u32,
            mode: st.mode,
            uid: st.uid,
            gid: st.gid,
            nlink: st.nlink as u32,
            size: st.size,
            blksize: st.blksize,
            blocks: st.blocks,
            atime: st.atime,
            mtime: st.mtime,
            ctime: st.ctime,
        },
        Err(_) => {
            log::warn!("[vfs] open reply missing/invalid stat header for {path}");
            return NEG_EIO;
        }
    };
    let entry = FdEntry {
        backend: FdBackend::VfsService {
            service_handle: handle,
            meta,
        },
        offset: 0,
        readable: true,
        writable: false,
        cloexec: flags & O_CLOEXEC != 0,
        nonblock: flags & O_NONBLOCK != 0,
    };
    match alloc_fd(3, entry) {
        Some(i) => i as u64,
        None => NEG_EMFILE,
    }
}

fn vfs_service_stat_path(path: &str) -> Result<VfsPathStat, u64> {
    // Phase 89: serve repeated stats / path-walk components from the kernel
    // metadata cache, eliding the ring-3 `vfs_server` IPC entirely (the npm
    // metadata-op storm). Capture the epoch BEFORE the fetch so a mutation
    // racing the IPC can't let a stale line be installed and later served as
    // fresh — see `metacache::store`.
    let at_epoch = crate::fs::metacache::epoch();
    if let Some(cached) = crate::fs::metacache::lookup(path, at_epoch) {
        return cached;
    }

    let result = vfs_service_stat_path_uncached(path);
    crate::fs::metacache::store(path, at_epoch, result.clone());
    result
}

/// The uncached `VFS_STAT_PATH` IPC round-trip to `vfs_server`. Split out so the
/// cache wrapper above stays trivial; never call this directly from the stat
/// path — go through [`vfs_service_stat_path`] so the result is cached.
fn vfs_service_stat_path_uncached(path: &str) -> Result<VfsPathStat, u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_STAT_PATH;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_ENOENT)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let mut msg = Message::new(VFS_STAT_PATH);
    msg.data[0] = path.len() as u64;
    scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(path.as_bytes()));
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    let bulk = scheduler::take_bulk_data(task_id).ok_or(NEG_EIO)?;
    vfs_service_parse_stat_reply(&bulk)
}

fn vfs_service_list_dir(
    path: &str,
    offset: usize,
    user_buf_ptr: u64,
    count: usize,
) -> Result<(usize, usize), u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_LIST_DIR;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_ENOENT)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let mut msg = Message::new(VFS_LIST_DIR);
    msg.data[0] = path.len() as u64;
    msg.data[1] = offset as u64;
    msg.data[2] = count as u64;
    scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(path.as_bytes()));
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }

    let packed = reply.data[0];
    let bytes = (packed & 0xFFFF_FFFF) as usize;
    let next_offset = (packed >> 32) as usize;
    if bytes == 0 {
        return Ok((0, next_offset));
    }
    if bytes > count {
        return Err(NEG_EIO);
    }
    let bulk = scheduler::take_bulk_data(task_id).ok_or(NEG_EIO)?;
    if bulk.len() < bytes {
        return Err(NEG_EIO);
    }
    if UserSliceWo::new(user_buf_ptr, bytes)
        .and_then(|s| s.copy_from_kernel(&bulk[..bytes]))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    Ok((bytes, next_offset))
}

/// One child entry of an ext2 directory as enumerated by the `vfs_server`:
/// `(name, d_type, d_ino)` where `d_ino` is the REAL on-disk inode the server
/// emits (so a caller needs no second `stat`).
type VfsDirChild = (alloc::string::String, u8, u64);

/// Enumerate ALL children of an ext2 directory through the ring-3 `vfs_server`
/// (engine-unification Phase A), draining the paginated `VFS_LIST_DIR` stream
/// into a kernel `Vec` and parsing the `dirent64` records it returns. `.` and
/// `..` are skipped — the getdents root/overlay merge synthesizes those itself.
///
/// This is the listing analog of `vfs_service_stat_path`: it lets the kernel's
/// directory-merge paths (root `/` and ramdisk-overlaid subdirs) source their
/// ext2 entries — names AND real inodes — from the single post-boot engine
/// instead of `EXT2_VOLUME`, so a write-back-deferred create is visible and the
/// in-kernel engine is not consulted for a root listing post-boot. Callers keep
/// the in-kernel `list_dir` as the boot-window / degraded fallback.
fn vfs_service_list_dir_entries(path: &str) -> Result<alloc::vec::Vec<VfsDirChild>, u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_LIST_DIR;

    // One reply page. 64 KiB matches the cap `sys_linux_getdents64` already
    // passes to `vfs_service_list_dir`; it is well within both `vfs_server`'s
    // `recv_buf` and the IPC bulk ceiling.
    const LIST_CHUNK: usize = 64 * 1024;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_ENOENT)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;

    let mut children: alloc::vec::Vec<VfsDirChild> = alloc::vec::Vec::new();
    let mut offset: usize = 0;
    // Bound the page count so a corrupt/garbage `next_offset` can never spin
    // forever (a directory can hold at most a few hundred thousand entries; the
    // server advances the offset by at least one record per non-empty reply).
    for _ in 0..1_000_000 {
        let mut msg = Message::new(VFS_LIST_DIR);
        msg.data[0] = path.len() as u64;
        msg.data[1] = offset as u64;
        msg.data[2] = LIST_CHUNK as u64;
        scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(path.as_bytes()));
        let reply = endpoint::call_msg(task_id, vfs_ep, msg);
        if reply.label != 0 {
            return Err(reply.label);
        }
        let packed = reply.data[0];
        let bytes = (packed & 0xFFFF_FFFF) as usize;
        let next_offset = (packed >> 32) as usize;
        if bytes == 0 {
            break; // end of directory
        }
        if bytes > LIST_CHUNK {
            return Err(NEG_EIO);
        }
        let bulk = scheduler::take_bulk_data(task_id).ok_or(NEG_EIO)?;
        if bulk.len() < bytes {
            return Err(NEG_EIO);
        }
        // Parse the packed dirent64 records: d_ino(8) d_off(8) reclen(2)
        // d_type(1) name(NUL-terminated, padded to reclen).
        let mut pos = 0usize;
        while pos + 19 <= bytes {
            let d_ino = u64::from_ne_bytes(bulk[pos..pos + 8].try_into().unwrap());
            let reclen = u16::from_ne_bytes(bulk[pos + 16..pos + 18].try_into().unwrap()) as usize;
            if reclen < 20 || pos + reclen > bytes {
                return Err(NEG_EIO); // malformed record
            }
            let d_type = bulk[pos + 18];
            let name_bytes = &bulk[pos + 19..pos + reclen];
            let name_end = name_bytes
                .iter()
                .position(|&b| b == 0)
                .unwrap_or(name_bytes.len());
            if let Ok(name) = core::str::from_utf8(&name_bytes[..name_end])
                && name != "."
                && name != ".."
            {
                children.push((alloc::string::String::from(name), d_type, d_ino));
            }
            pos += reclen;
        }
        if next_offset <= offset {
            break; // no forward progress — done (or degenerate)
        }
        offset = next_offset;
    }
    Ok(children)
}

fn vfs_service_mount_action(target: &str, fstype: &str) -> Result<u64, u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_MOUNT_POLICY;

    if is_current_exec_path("/bin/vfs_server") || !crate::ipc::registry::is_registered("vfs") {
        return vfs_bootstrap_mount_action(target, fstype);
    }

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_ENOENT)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let mut bulk = alloc::vec::Vec::from(target.as_bytes());
    bulk.extend_from_slice(fstype.as_bytes());
    let mut msg = Message::new(VFS_MOUNT_POLICY);
    msg.data[0] = target.len() as u64;
    msg.data[1] = fstype.len() as u64;
    scheduler::deliver_bulk(task_id, bulk);
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    Ok(reply.data[0])
}

fn vfs_service_umount_action(target: &str) -> Result<u64, u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_UMOUNT_POLICY;

    if is_current_exec_path("/bin/vfs_server") || !crate::ipc::registry::is_registered("vfs") {
        return vfs_bootstrap_umount_action(target);
    }

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_ENOENT)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let mut msg = Message::new(VFS_UMOUNT_POLICY);
    msg.data[0] = target.len() as u64;
    scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(target.as_bytes()));
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    Ok(reply.data[0])
}

fn vfs_service_should_route(path: &str, flags: u64) -> bool {
    let accmode = flags & 0o3;
    if accmode != 0 {
        return false;
    }
    if flags & (0x40 | 0x200 | 0x400) != 0 {
        return false;
    }
    if !vfs_service_can_handle_path(path) {
        return false;
    }
    if ext2_root_path(path).is_none() {
        return false;
    }
    // Engine-unification Phase A (audit completion): determine regular-file-ness
    // through the cached `vfs_service_stat_path` — the SAME authority that will
    // serve the open — instead of the in-kernel `is_ext2_regular_file`
    // (`EXT2_VOLUME.metadata`). This removes the last hot-path in-kernel root
    // read from the open-routing decision (so it can't disagree with the server,
    // and a write-back-deferred new file routes correctly), and is the
    // precondition for retiring the dual-engine block-cache invalidation.
    matches!(
        vfs_service_stat_path(path),
        Ok(st) if st.kind == kernel_core::fs::vfs_protocol::VFS_NODE_FILE
    )
}

fn vfs_service_read(handle: u64, offset: usize, user_buf_ptr: u64, count: usize) -> u64 {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::{VFS_MAX_PREAD, VFS_READ};

    let vfs_ep = match registry::lookup_endpoint_id("vfs") {
        Some(ep) => ep,
        None => return NEG_EIO,
    };
    let task_id = match scheduler::current_task_id() {
        Some(id) => id,
        None => return NEG_EINVAL,
    };
    let capped = count.min(VFS_MAX_PREAD);

    let mut msg = Message::new(VFS_READ);
    msg.data[0] = handle;
    msg.data[1] = offset as u64;
    msg.data[2] = capped as u64;
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return reply.label;
    }
    let bytes_read = reply.data[0] as usize;
    if bytes_read == 0 {
        return 0;
    }
    if bytes_read > capped {
        return NEG_EIO;
    }
    let bulk = match scheduler::take_bulk_data(task_id) {
        Some(b) => b,
        None => return NEG_EIO,
    };
    if bulk.len() < bytes_read {
        return NEG_EIO;
    }
    if UserSliceWo::new(user_buf_ptr, bytes_read)
        .and_then(|s| s.copy_from_kernel(&bulk[..bytes_read]))
        .is_err()
    {
        return NEG_EFAULT;
    }
    bytes_read as u64
}

// ---------------------------------------------------------------------------
// Phase 95c (Area A.1) — zero-copy demand-fault SHM "read window".
//
// The 95b demand-fill staged each read as an IPC bulk payload: `vfs_server`
// `ipc_store_reply_bulk`s the data into a kernel `Vec`, the kernel
// `take_bulk_data`s it, copies it into a cluster buffer, then copies THAT into
// the faulting frame — a double copy that violates m3OS's "bulk data = page
// grants, never IPC payloads" rule. The read window replaces that transport
// with a shared SHM region (the idiomatic external-pager move): `vfs_server`
// creates + maps a window once at startup and registers it here; on a fault the
// kernel issues `VFS_READ_WINDOW`, `vfs_server` reads file bytes straight into
// the shared window, and the kernel fills the faulting frame from the window's
// frames through its physical map — no IPC bulk, no `take_bulk_data`.
//
// A single window is shared by all faulting tasks, guarded by a non-blocking
// `in_use` flag held across the borrow (issue → reply → frame-fill): a second
// concurrent fault that can't claim it falls back to the legacy bulk path, so
// the optimization never blocks and never serializes correctness. `vfs_server`
// is single-threaded, so file reads already serialize there; the window only
// extends that to the kernel's brief frame-fill memcpy.
// ---------------------------------------------------------------------------

struct VfsReadWindow {
    /// Physical base of the registered SHM window (0 = unregistered).
    phys_base: core::sync::atomic::AtomicU64,
    /// Window size in bytes (a contiguous SHM run from `phys_base`).
    bytes: core::sync::atomic::AtomicU64,
    /// Held across a faulting task's `VFS_READ_WINDOW` borrow so no other writer
    /// (another fault, or `vfs_server` serving another window request) can
    /// overwrite the region before the kernel has copied it into the frame.
    in_use: core::sync::atomic::AtomicBool,
    /// PID of the current borrower — used to reclaim the window if the borrower
    /// is killed mid-fault (otherwise a single such death would wedge the single
    /// window in `in_use` and permanently force the legacy fallback).
    holder_pid: core::sync::atomic::AtomicU32,
}

static VFS_READ_WINDOW: VfsReadWindow = VfsReadWindow {
    phys_base: core::sync::atomic::AtomicU64::new(0),
    bytes: core::sync::atomic::AtomicU64::new(0),
    in_use: core::sync::atomic::AtomicBool::new(false),
    holder_pid: core::sync::atomic::AtomicU32::new(0),
};

/// `SYS_VFS_REGISTER_READ_WINDOW` (0x1024) — `vfs_server` registers its mapped
/// SHM read window. Only the registered `vfs` service owner may register (the
/// window's frames are read by the kernel from its physical map, so a bogus
/// region would let any process feed the demand-fill arbitrary memory). Returns
/// 0 on success, `u64::MAX` on error. Idempotent.
pub(super) fn sys_vfs_register_read_window(shm_id_arg: u64) -> u64 {
    use core::sync::atomic::Ordering;
    // Gate: only the live `vfs_server` process may register the window.
    if !is_current_exec_path("/bin/vfs_server") {
        return u64::MAX;
    }
    if shm_id_arg == 0 || shm_id_arg > u64::from(u32::MAX) {
        return u64::MAX;
    }
    let id = crate::mm::shm::ShmId(shm_id_arg as u32);
    let (start_phys, page_count) = match crate::mm::shm::frames(id) {
        Ok(v) => v,
        Err(_) => return u64::MAX,
    };
    let bytes = (page_count as u64) * 4096;
    // The window must hold at least one demand cluster; reject an undersized
    // region so the fault path can assume `bytes >= VFS_MAX_PREAD` never under-
    // serves a cluster (it clamps the request to `bytes` regardless).
    if bytes < 4096 {
        return u64::MAX;
    }
    VFS_READ_WINDOW.bytes.store(bytes, Ordering::Relaxed);
    VFS_READ_WINDOW
        .phys_base
        .store(start_phys, Ordering::Release);
    log::info!(
        "[vfs] read-window registered: shm_id={} phys={:#x} bytes={}",
        shm_id_arg,
        start_phys,
        bytes
    );
    0
}

/// True once `vfs_server` has registered a read window.
fn vfs_read_window_registered() -> bool {
    use core::sync::atomic::Ordering;
    VFS_READ_WINDOW.phys_base.load(Ordering::Acquire) != 0
}

/// Try to borrow the read window for `pid`. Returns `false` (fall back to the
/// legacy bulk path) if it is unregistered or already in use by a *live* task;
/// if the recorded borrower is dead (killed mid-fault) the window is reclaimed.
pub(crate) fn claim_vfs_read_window(pid: u32) -> bool {
    use core::sync::atomic::Ordering;
    if !vfs_read_window_registered() {
        return false;
    }
    if VFS_READ_WINDOW
        .in_use
        .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
        .is_ok()
    {
        VFS_READ_WINDOW.holder_pid.store(pid, Ordering::Relaxed);
        return true;
    }
    // Busy — reclaim only if the recorded holder is gone (a fault path that was
    // killed while blocked in its `VFS_READ_WINDOW` round-trip, before it could
    // release). This is the single-window liveness guard; without it one such
    // death would wedge the window in `in_use` and force the legacy fallback
    // forever. The reclaim is a single-winner CAS on `holder_pid` so two tasks
    // that simultaneously observe the same dead holder cannot BOTH steal the
    // (still-`in_use`) window and race on its bytes — only the CAS winner
    // proceeds; the loser falls back. (A pid reused by a live process before we
    // look is a false-negative: we simply don't reclaim and fall back — safe.)
    let holder = VFS_READ_WINDOW.holder_pid.load(Ordering::Acquire);
    if holder != 0 && crate::process::PROCESS_TABLE.lock().find(holder).is_none() {
        return VFS_READ_WINDOW
            .holder_pid
            .compare_exchange(holder, pid, Ordering::AcqRel, Ordering::Relaxed)
            .is_ok();
    }
    false
}

/// Release the read window after the borrow completes.
pub(crate) fn release_vfs_read_window() {
    use core::sync::atomic::Ordering;
    VFS_READ_WINDOW.in_use.store(false, Ordering::Release);
}

/// Kernel-side view of the registered window's frames, via the physical-memory
/// map. The caller must hold the borrow (`claim_vfs_read_window`) so the bytes
/// are stable. Returns `None` if unregistered.
///
/// # Safety
/// The returned slice aliases `vfs_server`'s SHM frames; it is only valid while
/// the borrow is held (no concurrent writer) and the window stays registered.
pub(crate) unsafe fn vfs_read_window_slice() -> Option<&'static [u8]> {
    use core::sync::atomic::Ordering;
    let phys = VFS_READ_WINDOW.phys_base.load(Ordering::Acquire);
    if phys == 0 {
        return None;
    }
    let bytes = VFS_READ_WINDOW.bytes.load(Ordering::Relaxed) as usize;
    let virt = crate::mm::phys_offset() + phys;
    Some(unsafe { core::slice::from_raw_parts(virt as *const u8, bytes) })
}

/// Maximum bytes the window can hold (for clamping a cluster request).
fn vfs_read_window_bytes() -> usize {
    use core::sync::atomic::Ordering;
    VFS_READ_WINDOW.bytes.load(Ordering::Relaxed) as usize
}

/// Issue one `VFS_READ_WINDOW` round-trip: `vfs_server` reads up to `len` bytes
/// at file `offset` from open `handle` directly into the shared window's first
/// `len` bytes. Returns the bytes written into the window (0 at EOF) or a
/// negative errno. The caller must hold the window borrow and read the bytes
/// from [`vfs_read_window_slice`] before releasing it. Mirrors
/// [`vfs_service_read_kernel`]'s `call_msg` blocking contract.
pub(crate) fn vfs_read_into_window(handle: u64, offset: usize, len: usize) -> Result<usize, i64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_READ_WINDOW;

    let capped = len.min(vfs_read_window_bytes());
    if capped == 0 {
        return Ok(0);
    }
    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO as i64)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL as i64)?;

    let mut msg = Message::new(VFS_READ_WINDOW);
    msg.data[0] = handle;
    msg.data[1] = offset as u64;
    msg.data[2] = capped as u64;
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label as i64);
    }
    let bytes_read = reply.data[0] as usize;
    if bytes_read > capped {
        return Err(NEG_EIO as i64);
    }
    Ok(bytes_read)
}

/// Resolve the `vfs_server` service handle for a process `fd`, **only** if that
/// fd is backed by `vfs_server` (the one backend the zero-copy read window can
/// fill — `vfs_server` owns those files and is the IPC peer that reads into the
/// window). Returns `None` for every other backend (ramdisk / in-kernel ext2 /
/// tmpfs / fat32), whose pages the window cannot serve, so the demand-fault
/// caller knows to use the legacy per-backend read routing instead.
///
/// Phase 95c (Area A.1). Critically, the value stored in a file-backed VMA is
/// the *process* fd number, NOT the `vfs_server` handle — the handle lives
/// inside `FdBackend::VfsService`. Sending the raw fd number to `vfs_server`
/// (the original A.1 bug) made it `EBADF` every demand read.
pub(crate) fn vfs_service_handle_for_fd(pid: u32, fd: usize) -> Option<u64> {
    let table = crate::process::PROCESS_TABLE.lock();
    let entry = table.find(pid)?.fd_get(fd)?;
    match &entry.backend {
        FdBackend::VfsService { service_handle, .. } => Some(*service_handle),
        _ => None,
    }
}

/// Phase 95b (Area A.2) — kernel-buffer variant of [`vfs_service_read`]: read up
/// to `buf.len()` bytes at `offset` from a `VfsService` handle into a kernel
/// buffer (instead of a user pointer), blocking on the `vfs_server` IPC reply.
///
/// This is the read used by the demand-fault file-backed page filler, so it must
/// be callable from the page-fault handler. That is sound: a ring-3 fault is
/// entered with no kernel locks held (the faulting task was running userspace),
/// so blocking on the synchronous `call_msg` here only switches the faulting task
/// out until `vfs_server` replies — exactly as a syscall-context vfs read does.
/// Returns bytes read (0 at EOF) or a negative errno.
fn vfs_service_read_kernel(handle: u64, offset: usize, buf: &mut [u8]) -> Result<usize, i64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::{VFS_MAX_PREAD, VFS_READ};

    if buf.is_empty() {
        return Ok(0);
    }
    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO as i64)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL as i64)?;
    let capped = buf.len().min(VFS_MAX_PREAD);

    let mut msg = Message::new(VFS_READ);
    msg.data[0] = handle;
    msg.data[1] = offset as u64;
    msg.data[2] = capped as u64;
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label as i64);
    }
    let bytes_read = reply.data[0] as usize;
    if bytes_read == 0 {
        return Ok(0);
    }
    if bytes_read > capped {
        return Err(NEG_EIO as i64);
    }
    let bulk = scheduler::take_bulk_data(task_id).ok_or(NEG_EIO as i64)?;
    if bulk.len() < bytes_read {
        return Err(NEG_EIO as i64);
    }
    buf[..bytes_read].copy_from_slice(&bulk[..bytes_read]);
    Ok(bytes_read)
}

fn vfs_service_close(handle: u64) {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_CLOSE;

    let vfs_ep = match registry::lookup_endpoint_id("vfs") {
        Some(ep) => ep,
        None => return,
    };
    let task_id = match scheduler::current_task_id() {
        Some(id) => id,
        None => return,
    };
    let mut msg = Message::new(VFS_CLOSE);
    msg.data[0] = handle;
    let _ = endpoint::call_msg(task_id, vfs_ep, msg);
}

// ---------------------------------------------------------------------------
// Phase 88 — kernel-side clients for the ext2 write-authority IPC ops.
//
// These make `vfs_server` the single ext2 owner: when the `vfs` service is
// registered, mutating ext2 syscalls route here; otherwise the caller falls
// back to the in-kernel `EXT2_VOLUME` engine (early boot). Every helper
// invalidates the kernel ext2 read cache on success so a subsequent
// kernel-side metadata read (`resolve_path`, exec loader) cannot serve a
// block stale relative to what vfs_server just wrote.
// ---------------------------------------------------------------------------

/// True when the `vfs` service is registered and the current task is NOT the
/// vfs_server itself (which must use the in-kernel engine to avoid recursing
/// into itself).
fn vfs_write_routable() -> bool {
    !is_current_exec_path("/bin/vfs_server") && crate::ipc::registry::is_registered("vfs")
}

/// Ensure a path begins with `/` (the form `vfs_server::resolve_path` expects).
/// `Ext2Disk` fds store the root-relative form without the leading slash.
fn vfs_abs_path(rel_or_abs: &str) -> alloc::string::String {
    if rel_or_abs.starts_with('/') {
        alloc::string::String::from(rel_or_abs)
    } else {
        alloc::format!("/{rel_or_abs}")
    }
}

/// Read file data by path through vfs_server (the coherent read-back path for
/// writable `Ext2Disk` fds). Returns bytes read or a negative errno.
fn vfs_service_pread(path: &str, offset: usize, user_buf_ptr: u64, count: usize) -> u64 {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::{VFS_MAX_PREAD, VFS_PREAD};

    let vfs_ep = match registry::lookup_endpoint_id("vfs") {
        Some(ep) => ep,
        None => return NEG_EIO,
    };
    let task_id = match scheduler::current_task_id() {
        Some(id) => id,
        None => return NEG_EINVAL,
    };
    let abs = vfs_abs_path(path);
    let capped = count.min(VFS_MAX_PREAD);

    let mut msg = Message::new(VFS_PREAD);
    msg.data[0] = abs.len() as u64;
    msg.data[1] = offset as u64;
    msg.data[2] = capped as u64;
    scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(abs.as_bytes()));
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return reply.label;
    }
    let bytes_read = reply.data[0] as usize;
    if bytes_read == 0 {
        return 0;
    }
    if bytes_read > capped {
        return NEG_EIO;
    }
    let bulk = match scheduler::take_bulk_data(task_id) {
        Some(b) => b,
        None => return NEG_EIO,
    };
    if bulk.len() < bytes_read {
        return NEG_EIO;
    }
    if UserSliceWo::new(user_buf_ptr, bytes_read)
        .and_then(|s| s.copy_from_kernel(&bulk[..bytes_read]))
        .is_err()
    {
        return NEG_EFAULT;
    }
    bytes_read as u64
}

/// Write file data by path through vfs_server. `data` is already a kernel-owned
/// copy. Returns `Ok((bytes_written, new_size))` or `Err(negative_errno)`.
fn vfs_service_write(path: &str, offset: u64, data: &[u8]) -> Result<(usize, u32), u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::{VFS_MAX_PWRITE, VFS_WRITE};

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let abs = vfs_abs_path(path);
    // The request packs BOTH the path AND the data into one bulk buffer that
    // lands in vfs_server's recv_buf (sized VFS_MAX_PWRITE), so the data chunk
    // must leave room for the path, else the `path_len + data_len <= recv_buf`
    // bounds check rejects the write with EINVAL. Phase 87 raised this from
    // VFS_MAX_READ (4 KiB) to VFS_MAX_PWRITE (64 KiB) so a write moves up to ~16
    // blocks per round-trip. Callers loop for larger writes.
    let chunk = data.len().min(VFS_MAX_PWRITE.saturating_sub(abs.len()));
    if chunk == 0 {
        // Path alone fills the buffer — no room for data (pathological).
        return Err(NEG_EINVAL);
    }
    let mut bulk = alloc::vec::Vec::with_capacity(abs.len() + chunk);
    bulk.extend_from_slice(abs.as_bytes());
    bulk.extend_from_slice(&data[..chunk]);

    let mut msg = Message::new(VFS_WRITE);
    msg.data[0] = abs.len() as u64;
    msg.data[1] = offset;
    msg.data[2] = chunk as u64;
    scheduler::deliver_bulk(task_id, bulk);
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    crate::fs::ext2::invalidate_cache();
    let n = (reply.data[0] & 0xFFFF_FFFF) as usize;
    let new_size = (reply.data[0] >> 32) as u32;
    Ok((n, new_size))
}

/// Truncate a file by path through vfs_server.
fn vfs_service_truncate(path: &str, length: u64) -> Result<(), u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_TRUNCATE;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let abs = vfs_abs_path(path);
    let mut msg = Message::new(VFS_TRUNCATE);
    msg.data[0] = abs.len() as u64;
    msg.data[1] = length;
    scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(abs.as_bytes()));
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    crate::fs::ext2::invalidate_cache();
    Ok(())
}

/// Set inode attributes (chmod / chown / utimes) by path through `vfs_server`,
/// the single ext2 write owner. Routing the metadata mutation through the owner
/// (rather than the kernel engine writing the inode directly) keeps the server's
/// block cache — and the kernel stat cache it backs — coherent: a direct
/// kernel-engine inode write would leave the server's cached inode block stale
/// (the chmod-then-stat cross-engine bug). `mask` selects which fields apply.
#[allow(clippy::too_many_arguments)]
fn vfs_service_setattr(
    path: &str,
    mask: u64,
    uid: u32,
    gid: u32,
    mode: u16,
    atime: u32,
    mtime: u32,
) -> Result<(), u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_SETATTR;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let abs = vfs_abs_path(path);
    // Only `data[0..3]` are usable payload — the IPC engine reserves `data[3]`
    // for the reply-cap handle it hands the receiver (see `endpoint::call_msg`).
    // uid/gid pack to 16 bits each (the ext2 inode width); ctime is set to "now"
    // by the server, so it need not be carried.
    let abs_len = abs.len() as u64;
    let mut msg = Message::new(VFS_SETATTR);
    msg.data[0] = abs_len;
    msg.data[1] = ((uid as u64 & 0xFFFF) << 48)
        | ((gid as u64 & 0xFFFF) << 32)
        | ((mode as u64 & 0xFFFF) << 16)
        | (mask & 0xFFFF);
    msg.data[2] = ((atime as u64) << 32) | (mtime as u64 & 0xFFFF_FFFF);
    scheduler::deliver_bulk(task_id, alloc::vec::Vec::from(abs.as_bytes()));
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    crate::fs::ext2::invalidate_cache();
    Ok(())
}

/// Create a file/dir/symlink under `parent_abs` through vfs_server. Returns the
/// new inode number or a negative errno.
fn vfs_service_create(
    parent_abs: &str,
    name: &str,
    kind: u64,
    mode: u16,
    uid: u32,
    gid: u32,
    symlink_target: Option<&str>,
) -> Result<u32, u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::{VFS_CREATE, VFS_CREATE_KIND_SHIFT};

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let parent = vfs_abs_path(parent_abs);
    let target = symlink_target.unwrap_or("");

    let mut bulk = alloc::vec::Vec::with_capacity(parent.len() + name.len() + target.len());
    bulk.extend_from_slice(parent.as_bytes());
    bulk.extend_from_slice(name.as_bytes());
    bulk.extend_from_slice(target.as_bytes());

    let mut msg = Message::new(VFS_CREATE);
    msg.data[0] = (parent.len() as u64) | ((name.len() as u64) << 32);
    msg.data[1] = (mode as u64) | (kind << VFS_CREATE_KIND_SHIFT) | ((target.len() as u64) << 32);
    msg.data[2] = uid as u64;
    msg.data[3] = gid as u64;
    scheduler::deliver_bulk(task_id, bulk);
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    crate::fs::ext2::invalidate_cache();
    Ok(reply.data[0] as u32)
}

/// Remove an entry (`is_dir` selects rmdir vs unlink) through vfs_server.
fn vfs_service_unlink(parent_abs: &str, name: &str, is_dir: bool) -> Result<(), u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_UNLINK;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let parent = vfs_abs_path(parent_abs);

    let mut bulk = alloc::vec::Vec::with_capacity(parent.len() + name.len());
    bulk.extend_from_slice(parent.as_bytes());
    bulk.extend_from_slice(name.as_bytes());

    let mut msg = Message::new(VFS_UNLINK);
    msg.data[0] = parent.len() as u64;
    msg.data[1] = name.len() as u64;
    msg.data[2] = if is_dir { 1 } else { 0 };
    scheduler::deliver_bulk(task_id, bulk);
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    crate::fs::ext2::invalidate_cache();
    Ok(())
}

/// Rename `old_abs` → `new_abs` through vfs_server.
fn vfs_service_rename(old_abs: &str, new_abs: &str) -> Result<(), u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_RENAME;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let old = vfs_abs_path(old_abs);
    let new = vfs_abs_path(new_abs);

    let mut bulk = alloc::vec::Vec::with_capacity(old.len() + new.len());
    bulk.extend_from_slice(old.as_bytes());
    bulk.extend_from_slice(new.as_bytes());

    let mut msg = Message::new(VFS_RENAME);
    msg.data[0] = old.len() as u64;
    msg.data[1] = new.len() as u64;
    scheduler::deliver_bulk(task_id, bulk);
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    crate::fs::ext2::invalidate_cache();
    Ok(())
}

/// Hard-link `new_name` under `parent_abs` to the existing `target_abs` inode.
fn vfs_service_link(target_abs: &str, parent_abs: &str, new_name: &str) -> Result<(), u64> {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::fs::vfs_protocol::VFS_LINK;

    let vfs_ep = registry::lookup_endpoint_id("vfs").ok_or(NEG_EIO)?;
    let task_id = scheduler::current_task_id().ok_or(NEG_EINVAL)?;
    let target = vfs_abs_path(target_abs);
    let parent = vfs_abs_path(parent_abs);

    let mut bulk = alloc::vec::Vec::with_capacity(target.len() + parent.len() + new_name.len());
    bulk.extend_from_slice(target.as_bytes());
    bulk.extend_from_slice(parent.as_bytes());
    bulk.extend_from_slice(new_name.as_bytes());

    let mut msg = Message::new(VFS_LINK);
    msg.data[0] = target.len() as u64;
    msg.data[1] = parent.len() as u64;
    msg.data[2] = new_name.len() as u64;
    scheduler::deliver_bulk(task_id, bulk);
    let reply = endpoint::call_msg(task_id, vfs_ep, msg);
    if reply.label != 0 {
        return Err(reply.label);
    }
    crate::fs::ext2::invalidate_cache();
    Ok(())
}

fn open_resolved_path(name: &str, flags: u64, mode_arg: u64) -> u64 {
    // Decode POSIX access mode (O_ACCMODE = 0o3).
    let (readable, writable) = match flags & 0o3 {
        0 => (true, false),     // O_RDONLY
        1 => (false, true),     // O_WRONLY
        2 => (true, true),      // O_RDWR
        _ => return NEG_EINVAL, // invalid combination
    };
    // Phase 66 Track C.2: honor `O_CLOEXEC` and `O_NONBLOCK` at FD
    // construction. POSIX requires CLOEXEC to be applied atomically at
    // `open()` to close the open/fcntl race window; NONBLOCK must take
    // effect on the very FD `open()` returns, not only after a follow-up
    // `fcntl(F_SETFL)`.
    let cloexec = flags & O_CLOEXEC != 0;
    let nonblock = flags & O_NONBLOCK != 0;

    // Phase 27: Permission check for existing files.
    let create = (flags & 0x40) != 0; // O_CREAT
    let file_meta = path_metadata(name);
    if (!create || file_meta.is_some())
        && let Some((fu, fg, fm)) = file_meta
    {
        let (_, _, euid, egid) = current_process_ids();
        let required = (if readable { 4u8 } else { 0 }) | (if writable { 2u8 } else { 0 });
        if required != 0 && !check_permission(fu, fg, fm, euid, egid, required) {
            return NEG_EACCES;
        }
    }

    // Phase 27: When creating a new file, check parent directory write+execute permission.
    if create
        && file_meta.is_none()
        && let Some((pu, pg, pm)) = parent_dir_metadata(name)
    {
        let (_, _, euid_c, egid_c) = current_process_ids();
        if !check_permission(pu, pg, pm, euid_c, egid_c, 3) {
            return NEG_EACCES;
        }
    }

    // Phase 21: /dev/null special file — reads return EOF, writes are discarded.
    // Phase 38: /dev/zero, /dev/urandom, /dev/full device nodes.
    // Placed after flags decode so O_RDONLY/O_WRONLY are respected.
    let dev_backend = match name {
        "/dev/null" => Some(FdBackend::DevNull),
        "/dev/zero" => Some(FdBackend::DevZero),
        "/dev/urandom" | "/dev/random" => Some(FdBackend::DevUrandom),
        "/dev/full" => Some(FdBackend::DevFull),
        _ => None,
    };
    if let Some(backend) = dev_backend {
        let entry = FdEntry {
            backend,
            offset: 0,
            readable,
            writable,
            cloexec,
            nonblock,
        };
        return match alloc_fd(3, entry) {
            Some(i) => i as u64,
            None => NEG_EMFILE,
        };
    }

    // Phase 29: /dev/ptmx — allocate a PTY pair and return the master fd.
    if name == "/dev/ptmx" {
        let pty_id = match crate::pty::alloc_pty() {
            Ok(id) => id,
            Err(()) => return NEG_ENOSPC,
        };
        log::debug!("[pty] allocated PTY pair {}", pty_id);
        let entry = FdEntry {
            backend: FdBackend::PtyMaster { pty_id },
            offset: 0,
            readable: true,
            writable: true,
            cloexec,
            nonblock,
        };
        return match alloc_fd(3, entry) {
            Some(i) => i as u64,
            None => {
                crate::pty::close_master(pty_id);
                NEG_EMFILE
            }
        };
    }

    // Phase 29: /dev/pts/N — open the slave side of PTY N.
    if let Some(suffix) = name.strip_prefix("/dev/pts/") {
        if let Ok(pty_id) = suffix.parse::<u32>() {
            // Check + increment refcount under the same lock to prevent
            // a race where the PTY is freed between check and alloc_fd.
            {
                let mut table = crate::pty::PTY_TABLE.lock();
                match table.get_mut(pty_id as usize).and_then(|s| s.as_mut()) {
                    None => return NEG_ENOENT,
                    Some(pair) if pair.locked => return NEG_EIO,
                    Some(pair) => {
                        pair.slave_refcount += 1;
                        pair.slave_opened = true;
                    }
                }
            }
            let entry = FdEntry {
                backend: FdBackend::PtySlave { pty_id },
                offset: 0,
                readable: true,
                writable: true,
                cloexec,
                nonblock,
            };
            return match alloc_fd(3, entry) {
                Some(i) => i as u64,
                None => {
                    crate::pty::close_slave(pty_id);
                    NEG_EMFILE
                }
            };
        }
        return NEG_ENOENT;
    }

    // /dev/tty — resolve to the calling process's controlling terminal.
    if name == "/dev/tty" {
        let calling_pid = crate::process::current_pid();
        let ctty = {
            let pt = crate::process::PROCESS_TABLE.lock();
            pt.find(calling_pid).and_then(|p| p.controlling_tty.clone())
        };
        let (backend, maybe_pty_id) = match ctty {
            Some(crate::process::ControllingTty::Console) => {
                (FdBackend::DeviceTTY { tty_id: 0 }, None)
            }
            Some(crate::process::ControllingTty::Pty(id)) => {
                let mut table = crate::pty::PTY_TABLE.lock();
                match table.get_mut(id as usize).and_then(|s| s.as_mut()) {
                    None => return NEG_ENXIO,
                    Some(pair) => {
                        pair.slave_refcount += 1;
                    }
                }
                (FdBackend::PtySlave { pty_id: id }, Some(id))
            }
            None => return NEG_ENXIO,
        };
        let entry = FdEntry {
            backend,
            offset: 0,
            readable,
            writable,
            cloexec,
            nonblock,
        };
        return match alloc_fd(3, entry) {
            Some(i) => i as u64,
            None => {
                if let Some(id) = maybe_pty_id {
                    crate::pty::close_slave(id);
                }
                NEG_EMFILE
            }
        };
    }

    let create = flags & O_CREAT != 0;
    let truncate = flags & O_TRUNC != 0;
    let append = flags & O_APPEND != 0;

    // Handle directory opens (Phase 18).
    let o_directory = flags & O_DIRECTORY != 0;
    let path_is_dir = is_directory(name);

    if o_directory && !path_is_dir {
        // O_DIRECTORY set on a non-directory (or non-existent path).
        // Check if the path exists as a file — if so, ENOTDIR.
        if let Some(rel) = tmpfs_relative_path(name) {
            if !rel.is_empty() {
                let tmpfs = crate::fs::tmpfs::TMPFS.lock();
                if tmpfs.stat(rel).is_ok() {
                    return NEG_ENOTDIR;
                }
            }
        } else if crate::fs::ramdisk::get_file(name).is_some() {
            return NEG_ENOTDIR;
        }
        // Path doesn't exist — fall through to normal open which will return ENOENT.
    }

    if path_is_dir {
        // Directories cannot be opened for writing, creation, or truncation.
        if writable || create || truncate {
            return NEG_EISDIR;
        }
        let entry = FdEntry {
            backend: FdBackend::Dir {
                path: alloc::string::String::from(name),
            },
            offset: 0,
            readable: true,
            writable: false,
            cloexec,
            nonblock,
        };
        return match alloc_fd(3, entry) {
            Some(i) => {
                log::debug!("[open] {} → fd {} (dir)", name, i);
                i as u64
            }
            None => NEG_EMFILE,
        };
    }

    if crate::fs::procfs::path_exists(name) {
        if writable || create || truncate || append {
            return NEG_EROFS;
        }
        if !matches!(
            crate::fs::procfs::path_node(name),
            Some(crate::fs::procfs::ProcfsNode::File)
        ) {
            return NEG_ENOENT;
        }
        // `/proc/kmsg` is a live consuming stream: seed its cursor at the
        // oldest byte currently resident in the dmesg ring so a fresh open
        // replays the existing buffer once (matching the prior snapshot's
        // first-read behaviour), then streams messages logged afterwards.
        // Other procfs files use `offset` as an ordinary byte offset (start 0).
        let initial_offset = if name == "/proc/kmsg" {
            crate::serial::dmesg_oldest_seq() as usize
        } else {
            0
        };
        let entry = FdEntry {
            backend: FdBackend::Proc {
                path: alloc::string::String::from(name),
            },
            offset: initial_offset,
            readable: true,
            writable: false,
            cloexec,
            nonblock,
        };
        return match alloc_fd(3, entry) {
            Some(i) => i as u64,
            None => NEG_EMFILE,
        };
    }

    // Check if this is a tmpfs path.
    if let Some(rel) = tmpfs_relative_path(name) {
        if rel.is_empty() {
            // /tmp itself handled as directory above; shouldn't reach here.
            return NEG_EISDIR;
        }

        let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();

        // Open or create the file with caller's ownership.
        let create_mode = ((mode_arg as u16) & 0o7777) & !current_umask();
        let (_, _, caller_euid, caller_egid) = current_process_ids();
        match tmpfs.open_or_create_with_meta(rel, create, caller_euid, caller_egid, create_mode) {
            Ok(_created) => {}
            Err(crate::fs::tmpfs::TmpfsError::NotFound) => return NEG_ENOENT,
            Err(crate::fs::tmpfs::TmpfsError::WrongType) => {
                return NEG_EISDIR;
            }
            Err(crate::fs::tmpfs::TmpfsError::NotADirectory) => {
                return NEG_ENOTDIR;
            }
            Err(_) => return NEG_EINVAL,
        }

        if truncate && writable {
            let _ = tmpfs.truncate(rel, 0);
        }

        let initial_offset = if append {
            tmpfs.file_size(rel).unwrap_or(0)
        } else {
            0
        };

        drop(tmpfs);

        // Allocate an fd slot in the current process's table.
        let entry = FdEntry {
            backend: FdBackend::Tmpfs {
                path: alloc::string::String::from(rel),
            },
            offset: initial_offset,
            readable,
            writable,
            cloexec,
            nonblock,
        };
        match alloc_fd(3, entry) {
            Some(i) => {
                log::debug!("[open] {} → fd {} (tmpfs)", name, i);
                return i as u64;
            }
            None => {
                log::warn!("[open] fd table full");
                return NEG_EMFILE;
            }
        }
    }

    // Phase 24/28: check if this is a /data path (ext2 or FAT32).
    if let Some(rel) = fat32_relative_path(name) {
        if crate::fs::ext2::is_mounted() {
            return open_ext2_file(
                name, rel, readable, writable, create, append, truncate, mode_arg, cloexec,
                nonblock,
            );
        }
        if data_is_mounted() {
            if rel.is_empty() {
                return NEG_EISDIR;
            }
            let mut vol_guard = crate::fs::fat32::FAT32_VOLUME.lock();
            if let Some(vol) = vol_guard.as_mut() {
                match vol.lookup(rel) {
                    Ok(entry) => {
                        if entry.is_dir() {
                            if writable || create || truncate {
                                return NEG_EISDIR;
                            }
                            let fd_entry = FdEntry {
                                backend: FdBackend::Dir {
                                    path: alloc::string::String::from(name),
                                },
                                offset: 0,
                                readable: true,
                                writable: false,
                                cloexec,
                                nonblock,
                            };

                            return match alloc_fd(3, fd_entry) {
                                Some(i) => {
                                    log::debug!("[open] {} → fd {} (fat32 dir)", name, i);
                                    i as u64
                                }
                                None => NEG_EMFILE,
                            };
                        }

                        // Find parent dir cluster for writes.
                        let parts: alloc::vec::Vec<&str> =
                            rel.split('/').filter(|s| !s.is_empty()).collect();
                        let parent_cluster = if parts.len() <= 1 {
                            vol.bpb.root_cluster
                        } else {
                            let parent_path = parts[..parts.len() - 1].join("/");
                            match vol.lookup(&parent_path) {
                                Ok(pe) if pe.is_dir() => pe.start_cluster(),
                                Ok(_) => return NEG_ENOTDIR,
                                Err(_) => return NEG_ENOENT,
                            }
                        };

                        let initial_offset = if append { entry.file_size as usize } else { 0 };

                        let mut fd_entry = FdEntry {
                            backend: FdBackend::Fat32Disk {
                                path: alloc::string::String::from(rel),
                                start_cluster: entry.start_cluster(),
                                file_size: entry.file_size,
                                dir_cluster: parent_cluster,
                            },
                            offset: initial_offset,
                            readable,
                            writable,
                            cloexec,
                            nonblock,
                        };

                        // Phase 31: support O_TRUNC on FAT32 — free the old
                        // cluster chain and reset size to 0 so TCC can overwrite
                        // output files.
                        if truncate && writable {
                            let old_cluster = entry.start_cluster();
                            if old_cluster >= 2 && vol.free_chain(old_cluster).is_err() {
                                return NEG_EIO;
                            }
                            let file_short = rel.rsplit('/').next().unwrap_or(rel);
                            if vol
                                .update_dir_entry(parent_cluster, file_short, 0, 0)
                                .is_err()
                            {
                                return NEG_EIO;
                            }
                            fd_entry.backend = FdBackend::Fat32Disk {
                                path: alloc::string::String::from(rel),
                                start_cluster: 0,
                                file_size: 0,
                                dir_cluster: parent_cluster,
                            };
                            fd_entry.offset = 0;
                        }

                        return match alloc_fd(3, fd_entry) {
                            Some(i) => {
                                log::debug!("[open] {} → fd {} (fat32)", name, i);
                                i as u64
                            }
                            None => NEG_EMFILE,
                        };
                    }
                    Err(kernel_core::fs::fat32::Fat32Error::NotFound) if create => {
                        // Create a new file (same lock guard, no deadlock).
                        let parts: alloc::vec::Vec<&str> =
                            rel.split('/').filter(|s| !s.is_empty()).collect();
                        let (parent_cluster, file_name) = if parts.len() <= 1 {
                            (vol.bpb.root_cluster, rel)
                        } else {
                            let parent_path = parts[..parts.len() - 1].join("/");
                            let parent_cluster = match vol.lookup(&parent_path) {
                                Ok(pe) if pe.is_dir() => pe.start_cluster(),
                                _ => return NEG_ENOENT,
                            };
                            (parent_cluster, parts[parts.len() - 1])
                        };

                        match vol.create_file(parent_cluster, file_name) {
                            Ok(_entry) => {
                                let fd_entry = FdEntry {
                                    backend: FdBackend::Fat32Disk {
                                        path: alloc::string::String::from(rel),
                                        start_cluster: 0,
                                        file_size: 0,
                                        dir_cluster: parent_cluster,
                                    },
                                    offset: 0,
                                    readable,
                                    writable,
                                    cloexec,
                                    nonblock,
                                };

                                // Set ownership and permissions on the newly created file.
                                let create_mode = ((mode_arg as u16) & 0o7777) & !current_umask();
                                let (_, _, caller_euid, caller_egid) = current_process_ids();
                                crate::fs::fat32::set_fat32_meta(
                                    rel,
                                    caller_euid,
                                    caller_egid,
                                    create_mode,
                                );

                                return match alloc_fd(3, fd_entry) {
                                    Some(i) => {
                                        log::debug!("[open] {} → fd {} (fat32 new)", name, i);
                                        i as u64
                                    }
                                    None => NEG_EMFILE,
                                };
                            }
                            Err(_) => return NEG_EIO,
                        }
                    }
                    Err(_) => return NEG_ENOENT,
                }
            }
        } else {
            // FAT32 not mounted — /data doesn't exist.
            return NEG_ENOENT;
        }
    }

    // Phase 92a D.4: a path under a /mnt/usbN secondary mount opens from that
    // mount's own ext2 volume (checked before the root ext2 branch so it is not
    // resolved against the root device).
    if crate::fs::ext2::is_usb_mount_path(name) {
        return open_usb_file(
            name, readable, writable, create, append, truncate, mode_arg, cloexec, nonblock,
        );
    }

    // Phase 28: ext2 root filesystem — try before ramdisk for non-/bin, non-/sbin.
    if crate::fs::ext2::is_mounted()
        && let Some(rel) = ext2_root_path(name)
    {
        // Check if ramdisk has this path (e.g. /bin/cat) — ramdisk takes priority.
        if crate::fs::ramdisk::ramdisk_lookup(name).is_none() {
            return open_ext2_file(
                name, rel, readable, writable, create, append, truncate, mode_arg, cloexec,
                nonblock,
            );
        }
    }

    // Fall through to ramdisk lookup — ramdisk is read-only.
    if writable || create {
        // If ext2 is mounted, try creating there before giving up.
        if crate::fs::ext2::is_mounted()
            && let Some(rel) = ext2_root_path(name)
        {
            return open_ext2_file(
                name, rel, readable, writable, create, append, truncate, mode_arg, cloexec,
                nonblock,
            );
        }
        return NEG_EROFS;
    }

    let content = match crate::fs::ramdisk::get_file(name) {
        Some(c) => c,
        None => {
            // Try ext2 root for anything ramdisk doesn't have.
            if crate::fs::ext2::is_mounted()
                && let Some(rel) = ext2_root_path(name)
            {
                return open_ext2_file(
                    name, rel, readable, writable, create, append, truncate, mode_arg, cloexec,
                    nonblock,
                );
            }
            // Legacy: /etc/* fallback — try /data/etc/* on FAT32 only.
            if let Some(etc_rel) = name.strip_prefix("/etc/")
                && !etc_rel.is_empty()
                && crate::fs::fat32::is_mounted()
            {
                let data_rel = alloc::format!("etc/{}", etc_rel);
                let vol = crate::fs::fat32::FAT32_VOLUME.lock();
                if let Some(vol) = vol.as_ref()
                    && let Ok(entry) = vol.lookup(&data_rel)
                    && !entry.is_dir()
                {
                    let fd_entry = FdEntry {
                        backend: FdBackend::Fat32Disk {
                            path: data_rel,
                            start_cluster: entry.start_cluster(),
                            file_size: entry.file_size,
                            dir_cluster: vol.bpb.root_cluster,
                        },
                        offset: 0,
                        readable: true,
                        writable: false,
                        cloexec,
                        nonblock,
                    };
                    return match alloc_fd(3, fd_entry) {
                        Some(i) => {
                            log::debug!("[open] {} → fd {} (fat32 /etc alias)", name, i);
                            i as u64
                        }
                        None => NEG_EMFILE,
                    };
                }
            }
            log::warn!("[open] file not found: {}", name);
            return NEG_ENOENT;
        }
    };

    let entry = FdEntry {
        backend: FdBackend::Ramdisk {
            content_addr: content.as_ptr() as usize,
            content_len: content.len(),
        },
        offset: 0,
        readable: true,
        writable: false,
        cloexec,
        nonblock,
    };
    match alloc_fd(3, entry) {
        Some(i) => {
            log::debug!("[open] {} → fd {}", name, i);
            i as u64
        }
        None => {
            log::warn!("[open] fd table full");
            NEG_EMFILE
        }
    }
}

pub(super) fn sys_linux_open(path_ptr: u64, flags: u64, mode_arg: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw_name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    open_user_path(AT_FDCWD, raw_name, flags, mode_arg)
}

// ---------------------------------------------------------------------------
// Phase 18: openat(dirfd, path, flags, mode) — syscall 257
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_openat(dirfd: u64, path_ptr: u64, flags: u64) -> u64 {
    // Read mode from SYSCALL_ARG3 (r10 — 4th syscall argument in Linux ABI).
    let mode_arg = per_core_syscall_arg3();
    let mut buf = [0u8; 512];
    let rel_name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    open_user_path(dirfd, rel_name, flags, mode_arg)
}

// Phase 66 Track D.3 — `reap_unused_ext2_inode` body has moved to
// `kernel/src/fs/ext2.rs`. The call site at the bottom of
// `sys_linux_close` now goes through `crate::fs::ext2::*` directly.

// Phase 66 Track D.4 — `vfs_service_close_pub` body has moved to
// `kernel/src/fs/vfs_service.rs`. The IPC primitive is re-exposed as
// `vfs_service_close_internal` so the new module can forward without
// duplicating the message construction.

/// Internal: tell the ring-3 VFS service a handle was closed.
/// Re-exposed at `pub(crate)` so `kernel/src/fs/vfs_service.rs` can
/// forward without duplicating the message construction below.
pub(crate) fn vfs_service_close_internal(service_handle: u64) {
    vfs_service_close(service_handle);
}

// ---------------------------------------------------------------------------
// T015 (close) / T013 (close)
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_close(fd: u64) -> u64 {
    let fd = fd as usize;
    // PID 1 (init) runs `check_control_commands` on every reap-loop
    // iteration: open(/run/init.cmd) → read → close → open(trunc) →
    // close. Two closes per iter at >100 Hz produces ~81K trace lines
    // per minute, drowning out the fork-exec close traces we actually
    // care about. Skip pid 1 so the trace stays focused on the
    // fork-child fd-juggling path that is the typical reason for
    // enabling `exec-trace` in the first place.
    #[cfg(feature = "exec-trace")]
    {
        let pid = crate::process::current_pid();
        if pid != 1 {
            log::info!("[exec-trace] pid={} close fd={}", pid, fd);
        }
    }
    // stdin/stdout/stderr (0–2) are virtual and cannot be closed.
    if fd < 3 {
        return 0;
    }
    if fd >= MAX_FDS {
        return NEG_EBADF;
    }
    let mut ext2_inode = None;
    let mut vfs_handle = None;
    // Close-time cleanup for resource-backed FDs.
    if let Some(entry) = current_fd_entry(fd) {
        match &entry.backend {
            FdBackend::PipeRead { pipe_id } => crate::pipe::pipe_close_reader(*pipe_id),
            FdBackend::PipeWrite { pipe_id } => crate::pipe::pipe_close_writer(*pipe_id),
            FdBackend::EventFd { id } => crate::eventfd::eventfd_close(*id),
            FdBackend::TimerFd { id } => crate::timerfd::timerfd_close(*id),
            FdBackend::Socket { handle } => crate::net::release_socket_pub(*handle),
            FdBackend::UnixSocket { handle } => crate::net::unix::free_unix_socket(*handle),
            FdBackend::PtyMaster { pty_id } => crate::pty::close_master(*pty_id),
            FdBackend::PtySlave { pty_id } => crate::pty::close_slave(*pty_id),
            FdBackend::Epoll { instance_id } => epoll_free(*instance_id),
            FdBackend::Ext2Disk { inode_num, .. } => ext2_inode = Some(*inode_num),
            FdBackend::VfsService { service_handle, .. } => vfs_handle = Some(*service_handle),
            _ => {}
        }
    }
    // Remove this FD from all epoll interest lists to prevent stale references.
    epoll_remove_fd(fd);
    // Phase 69d follow-up: drop any per-fd flock state so an fd-recycle
    // cannot surface the previous holder's lock to a fresh open.
    //
    // If the closing thread is a CLONE_FILES sibling of the lock
    // holder, the shared fd table is about to lose the slot and a
    // different sibling's `(holder_tid, fd)` entry is now stale.
    // Release across every thread-group member that shares this fd
    // table so a sibling's lock cannot survive the close of the fd
    // it was keyed to (PR #177 review fix).
    {
        let pid = crate::process::current_pid();
        let backend_handle = current_fd_entry(fd).and_then(|e| match &e.backend {
            FdBackend::UnixSocket { handle } => Some(*handle),
            _ => None,
        });
        // Collect every tid in the thread group (or just this pid for
        // single-threaded processes).  Held briefly under PROCESS_TABLE
        // lock — the flock module takes its own mutex, no nesting.
        let release_pids: alloc::vec::Vec<u32> = {
            let table = crate::process::PROCESS_TABLE.lock();
            match table.find(pid).and_then(|p| p.thread_group.clone()) {
                Some(tg) => tg.members.lock().clone(),
                None => alloc::vec![pid],
            }
        };
        if let Some(h) = backend_handle {
            crate::flock::unix_socket_release_for_pids(h, &release_pids, fd as u32);
            // Wake any contenders parked on this handle so they can
            // re-attempt the acquire now that this fd's lock is gone.
            crate::net::unix::wake_unix_socket(h);
        }
        crate::flock::release_per_fd_for_pids(&release_pids, fd as u32);
    }
    // Clear the slot and — for VfsService / Ext2Disk backends — decide
    // whether this was the last alias under the SAME PROCESS_TABLE lock
    // acquisition. Two concurrent closes of sibling aliases would otherwise
    // both observe count==0 after each drops its own lock, and both would
    // tear down server-side state (double VFS_CLOSE after a vfs_server
    // handle recycle force-closes an unrelated file; double ext2 inode free
    // corrupts block accounting).
    let mut found = false;
    let mut ext2_reap = None;
    let mut vfs_last_close = None;
    {
        let pid = crate::process::current_pid();
        let mut table = crate::process::PROCESS_TABLE.lock();
        if let Some(proc) = table.find_mut(pid) {
            if let Some(shared) = proc.shared_fd_table.clone() {
                let mut lock = shared.lock();
                if lock[fd].take().is_some() {
                    found = true;
                }
            } else if let Some(slot) = proc.fd_table.get_mut(fd)
                && slot.take().is_some()
            {
                found = true;
            }
        }
        if found {
            if let Some(inode_num) = ext2_inode
                && crate::process::ext2_inode_open_count_locked(&table, inode_num) == 0
            {
                ext2_reap = Some(inode_num);
            }
            if let Some(handle) = vfs_handle
                && crate::process::vfs_handle_open_count_locked(&table, handle) == 0
            {
                vfs_last_close = Some(handle);
            }
        }
    }
    if !found {
        return NEG_EBADF;
    }
    if let Some(inode_num) = ext2_reap {
        crate::fs::ext2::reap_unused_ext2_inode(inode_num);
    }
    if let Some(handle) = vfs_last_close {
        vfs_service_close(handle);
    }
    0
}

fn privileged_exec_credentials(path: &str, exec_is_static_ramdisk: bool) -> Option<(u32, u32)> {
    match (path, exec_is_static_ramdisk) {
        // Until generic setuid-on-exec exists, /bin/su runs with a root
        // effective identity so it can verify passwords via /etc/shadow and
        // then perform the authenticated credential transition.
        ("/bin/su", true) => Some((0, 0)),
        // Phase 55b Track F.3c: nvme-crash-smoke must run with euid=200 so
        // sys_block_read admits it through the privilege gate. Without this,
        // the binary would be rejected before ever reaching the errno mapping.
        // Only granted when the kernel is NOT in hardened mode (the whitelist
        // in BLOCK_READ_ALLOWED is also cfg-gated on !hardened).
        #[cfg(not(feature = "hardened"))]
        ("/bin/nvme-crash-smoke", _) => Some((200, 200)),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// T016: fstat(fd, stat_ptr)
// ---------------------------------------------------------------------------

/// Write a minimal Linux x86_64 `stat` struct to `stat_ptr`.
///
/// Only `st_size` (offset 48) and `st_mode` (offset 24) are filled in;
/// all other fields are zero.  This satisfies musl's `fstat` use in `fopen`.
/// Get uid/gid/mode for a file on the data partition (ext2 or FAT32).
/// Returns `None` if the file is not found or the volume is not mounted.
fn data_file_metadata(rel: &str) -> Option<(u32, u32, u16)> {
    if crate::fs::ext2::is_mounted() {
        return crate::fs::ext2::get_ext2_meta(rel);
    }
    Some(crate::fs::fat32::get_fat32_meta(rel))
}

/// Set permission mode on a data partition file (ext2 or FAT32).
/// Returns 0 on success, NEG_ENOENT if not found, NEG_EIO on error.
fn data_chmod(rel: &str, mode: u16) -> u64 {
    if crate::fs::ext2::is_mounted() {
        // Phase 89: route the mode change through the vfs_server (the single ext2
        // write owner) so its block cache — and the kernel stat cache it backs —
        // stays coherent. A direct kernel-engine inode write would leave the
        // server's cached inode block stale, so a later stat would report the
        // OLD mode (the chmod-then-stat cross-engine bug).
        if vfs_write_routable() {
            use kernel_core::fs::vfs_protocol::VFS_SETATTR_MODE;
            return match vfs_service_setattr(rel, VFS_SETATTR_MODE, 0, 0, mode, 0, 0) {
                Ok(()) => 0,
                Err(e) => e,
            };
        }
        // Direct-engine fallback (boot window / vfs_server-as-writer): bump the
        // stat cache explicitly since `vfs_service_setattr`'s `invalidate_cache`
        // bump is not on this path.
        let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
        let vol = match vol.as_mut() {
            Some(v) => v,
            None => return NEG_EIO,
        };
        let (u, g, _, _, _) = match vol.metadata(rel) {
            Ok(m) => m,
            Err(_) => return NEG_ENOENT,
        };
        match vol.set_metadata(rel, u, g, mode, current_unix_time()) {
            Ok(()) => {
                crate::fs::metacache::bump();
                0
            }
            Err(_) => NEG_EIO,
        }
    } else {
        let (u, g, _) = crate::fs::fat32::get_fat32_meta(rel);
        crate::fs::fat32::set_fat32_meta_and_save(rel, u, g, mode);
        0
    }
}

/// Set ownership on a data partition file (ext2 or FAT32).
/// Returns 0 on success, NEG_ENOENT if not found, NEG_EIO on error.
fn data_chown(rel: &str, new_uid: u32, new_gid: u32) -> u64 {
    if crate::fs::ext2::is_mounted() {
        // Phase 89: route through the vfs_server (single ext2 owner) so its block
        // cache + the kernel stat cache stay coherent (see `data_chmod`).
        if vfs_write_routable() {
            use kernel_core::fs::vfs_protocol::{VFS_SETATTR_GID, VFS_SETATTR_UID};
            return match vfs_service_setattr(
                rel,
                VFS_SETATTR_UID | VFS_SETATTR_GID,
                new_uid,
                new_gid,
                0,
                0,
                0,
            ) {
                Ok(()) => 0,
                Err(e) => e,
            };
        }
        // Direct-engine fallback (boot window / vfs_server-as-writer).
        let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
        let vol = match vol.as_mut() {
            Some(v) => v,
            None => return NEG_EIO,
        };
        let (_, _, mode, _, _) = match vol.metadata(rel) {
            Ok(m) => m,
            Err(_) => return NEG_ENOENT,
        };
        match vol.set_metadata(rel, new_uid, new_gid, mode & 0o7777, current_unix_time()) {
            Ok(()) => {
                crate::fs::metacache::bump();
                0
            }
            Err(_) => NEG_EIO,
        }
    } else {
        let (_, _, m) = crate::fs::fat32::get_fat32_meta(rel);
        crate::fs::fat32::set_fat32_meta_and_save(rel, new_uid, new_gid, m);
        0
    }
}

/// Engine-unification Phase C2-prep: open an ext2-root file/dir **entirely
/// through `vfs_server`** — resolve existence + kind, route the `O_CREAT`/
/// `O_TRUNC` mutation, and build the fd's metadata (inode/size/parent) from the
/// server's stat — so the open never consults the in-kernel `EXT2_VOLUME`. This
/// is the precondition for safe metadata write-back: the prior in-kernel
/// `resolve_path`/`read_inode` here would observe a write-back-DEFERRED create
/// stale (the C1-measured residual), failing an `open` right after its `create`.
///
/// Returns `Some(fd_or_errno)` when the server handled the open (success or a
/// definitive errno), or `None` to fall through to the in-kernel path — used
/// only when the server stat IPC itself fails (degraded vfs), never in steady
/// state. The caller gates this on `vfs_write_routable()`, so the boot window
/// (vfs not yet registered) always takes the in-kernel path below.
#[allow(clippy::too_many_arguments)]
fn open_ext2_file_routed(
    name: &str,
    rel: &str,
    readable: bool,
    writable: bool,
    create: bool,
    append: bool,
    truncate: bool,
    mode_arg: u64,
    cloexec: bool,
    nonblock: bool,
) -> Option<u64> {
    use kernel_core::fs::vfs_protocol::{VFS_NODE_DIR, VFS_NODE_FILE};
    const NEG_EISDIR: u64 = (-21_i64) as u64;
    const NEG_ENOENT: u64 = (-2_i64) as u64;
    const NEG_EMFILE: u64 = (-24_i64) as u64;

    // Existence + kind from the authority.
    let existed = match vfs_service_stat_path(name) {
        Ok(_) => true,
        Err(e) if e == NEG_ENOENT => false,
        // Any other error (IPC/degraded) → let the in-kernel path try.
        Err(_) => return None,
    };

    if existed {
        if truncate
            && writable
            && let Err(e) = vfs_service_truncate(name, 0)
        {
            return Some(e);
        }
    } else if create {
        let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
        let (parent_abs, file_name) = if parts.len() <= 1 {
            ("/", parts.first().copied().unwrap_or(rel))
        } else {
            let name_start = name.len() - parts[parts.len() - 1].len();
            (&name[..name_start], parts[parts.len() - 1])
        };
        let create_mode = ((mode_arg as u16) & 0o7777) & !current_umask();
        let (_, _, caller_euid, caller_egid) = current_process_ids();
        if let Err(e) = vfs_service_create(
            parent_abs,
            file_name,
            VFS_NODE_FILE,
            create_mode,
            caller_euid,
            caller_egid,
            None,
        ) {
            return Some(e);
        }
    } else {
        return Some(NEG_ENOENT);
    }

    // Re-stat for the post-mutation metadata. The create/truncate bumped the
    // kernel stat cache (their `invalidate_cache`), so this resolves fresh.
    let st = match vfs_service_stat_path(name) {
        Ok(s) => s,
        Err(_) => return None,
    };

    if st.kind == VFS_NODE_DIR {
        if writable || create || truncate {
            return Some(NEG_EISDIR);
        }
        let fd_entry = FdEntry {
            backend: FdBackend::Dir {
                path: alloc::string::String::from(name),
            },
            offset: 0,
            readable: true,
            writable: false,
            cloexec,
            nonblock,
        };
        return Some(match alloc_fd(3, fd_entry) {
            Some(i) => i as u64,
            None => NEG_EMFILE,
        });
    }

    // Regular file (a symlink target was already followed by path resolution):
    // an `Ext2Disk` fd whose reads/writes route BY PATH to vfs_server. The
    // inode_num/parent_inode come from the server and are consulted only by the
    // in-kernel fallback (never reached post-boot).
    let parent_ino = {
        let parent = parent_dir(name);
        if parent == "/" {
            kernel_core::fs::ext2::EXT2_ROOT_INO
        } else {
            vfs_service_stat_path(parent)
                .map(|s| s.ino as u32)
                .unwrap_or(kernel_core::fs::ext2::EXT2_ROOT_INO)
        }
    };
    let initial_offset = if append { st.size as usize } else { 0 };
    let fd_entry = FdEntry {
        backend: FdBackend::Ext2Disk {
            path: alloc::string::String::from(rel),
            inode_num: st.ino as u32,
            file_size: st.size as u32,
            parent_inode: parent_ino,
        },
        offset: initial_offset,
        readable,
        writable,
        cloexec,
        nonblock,
    };
    Some(match alloc_fd(3, fd_entry) {
        Some(i) => i as u64,
        None => NEG_EMFILE,
    })
}

/// Open a file on the ext2 partition.
#[allow(clippy::too_many_arguments)]
fn open_ext2_file(
    name: &str,
    rel: &str,
    readable: bool,
    writable: bool,
    create: bool,
    append: bool,
    truncate: bool,
    mode_arg: u64,
    cloexec: bool,
    nonblock: bool,
) -> u64 {
    const NEG_EISDIR: u64 = (-21_i64) as u64;
    const NEG_ENOENT: u64 = (-2_i64) as u64;
    const NEG_EMFILE: u64 = (-24_i64) as u64;
    const NEG_EIO: u64 = (-5_i64) as u64;

    if rel.is_empty() {
        return NEG_EISDIR;
    }

    // Engine-unification Phase C2-prep: post-boot, serve the whole open from the
    // vfs_server authority so it never reads the in-kernel engine (which would
    // see a write-back-deferred create stale). `None` (degraded vfs stat) falls
    // through to the in-kernel path; the boot window (vfs unregistered) skips
    // this entirely.
    if vfs_write_routable()
        && let Some(result) = open_ext2_file_routed(
            name, rel, readable, writable, create, append, truncate, mode_arg, cloexec, nonblock,
        )
    {
        return result;
    }

    // Phase 88: when the vfs_server ext2 authority is registered, route the
    // *mutations* (O_TRUNC of an existing file, O_CREAT of a new one) through
    // it BEFORE touching the kernel engine — and crucially before taking the
    // EXT2_VOLUME spinlock, since the IPC call blocks the task (holding a
    // spinlock across a blocking IPC is the documented SMP-deadlock hazard).
    // After the routed mutation the kernel engine's cache is invalidated, so
    // the resolve below reads the now-current on-disk inode for fd metadata.
    if vfs_write_routable() {
        let exists = crate::fs::ext2::EXT2_VOLUME
            .lock()
            .as_ref()
            .map(|v| v.resolve_path(rel).is_ok());
        match exists {
            Some(true) => {
                // Propagate the vfs_server-provided negative errno (e.g.
                // ENOENT/EACCES) rather than collapsing every failure to EIO, so
                // the routed O_TRUNC path matches the in-kernel fallback and the
                // sibling O_CREAT branch below (which also returns the vfs errno).
                if truncate
                    && writable
                    && let Err(e) = vfs_service_truncate(name, 0)
                {
                    return e;
                }
            }
            Some(false) => {
                if create {
                    let parts: alloc::vec::Vec<&str> =
                        rel.split('/').filter(|s| !s.is_empty()).collect();
                    let (parent_abs, file_name) = if parts.len() <= 1 {
                        ("/", parts.first().copied().unwrap_or(rel))
                    } else {
                        let name_start = name.len() - parts[parts.len() - 1].len();
                        (&name[..name_start], parts[parts.len() - 1])
                    };
                    let create_mode = ((mode_arg as u16) & 0o7777) & !current_umask();
                    let (_, _, caller_euid, caller_egid) = current_process_ids();
                    if let Err(e) = vfs_service_create(
                        parent_abs,
                        file_name,
                        kernel_core::fs::vfs_protocol::VFS_NODE_FILE,
                        create_mode,
                        caller_euid,
                        caller_egid,
                        None,
                    ) {
                        return e;
                    }
                }
                // If the path still does not exist (no create), the resolve
                // below returns ENOENT — matching the kernel-engine path.
            }
            None => return NEG_EIO,
        }
    }

    let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
    let vol = match vol.as_mut() {
        Some(v) => v,
        None => return NEG_EIO,
    };

    match vol.resolve_path(rel) {
        Ok(ino) => {
            let inode = match vol.read_inode(ino) {
                Ok(i) => i,
                Err(_) => return NEG_EIO,
            };

            if inode.is_dir() {
                if writable || create || truncate {
                    return NEG_EISDIR;
                }
                let fd_entry = FdEntry {
                    backend: FdBackend::Dir {
                        path: alloc::string::String::from(name),
                    },
                    offset: 0,
                    readable: true,
                    writable: false,
                    cloexec,
                    nonblock,
                };
                return match alloc_fd(3, fd_entry) {
                    Some(i) => i as u64,
                    None => NEG_EMFILE,
                };
            }

            // Truncate if requested. When the vfs authority is registered the
            // truncate already happened above (routed); only the in-kernel
            // fallback path mutates here.
            let mut inode = inode;
            if truncate
                && writable
                && !vfs_write_routable()
                && vol.truncate_file(ino, &mut inode).is_err()
            {
                return NEG_EIO;
            }

            let initial_offset = if append { inode.size as usize } else { 0 };

            // Find parent inode for writes.
            let parent_ino = {
                let parts: alloc::vec::Vec<&str> =
                    rel.split('/').filter(|s| !s.is_empty()).collect();
                if parts.len() <= 1 {
                    kernel_core::fs::ext2::EXT2_ROOT_INO
                } else {
                    let parent_path = parts[..parts.len() - 1].join("/");
                    match vol.resolve_path(&parent_path) {
                        Ok(p) => p,
                        Err(_) => return NEG_ENOENT,
                    }
                }
            };

            let fd_entry = FdEntry {
                backend: FdBackend::Ext2Disk {
                    path: alloc::string::String::from(rel),
                    inode_num: ino,
                    file_size: inode.size,
                    parent_inode: parent_ino,
                },
                offset: initial_offset,
                readable,
                writable,
                cloexec,
                nonblock,
            };

            match alloc_fd(3, fd_entry) {
                Some(i) => {
                    log::debug!("[open] {} → fd {} (ext2)", name, i);
                    i as u64
                }
                None => NEG_EMFILE,
            }
        }
        Err(kernel_core::fs::ext2::Ext2Error::NotFound) if create && !vfs_write_routable() => {
            // Create a new file (in-kernel fallback only; the vfs-routed path
            // already created it above and resolve() found it in the Ok arm).
            let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
            let (parent_ino, file_name) = if parts.len() <= 1 {
                (kernel_core::fs::ext2::EXT2_ROOT_INO, rel)
            } else {
                let parent_path = parts[..parts.len() - 1].join("/");
                let parent_ino = match vol.resolve_path(&parent_path) {
                    Ok(p) => p,
                    Err(_) => return NEG_ENOENT,
                };
                (parent_ino, parts[parts.len() - 1])
            };

            let create_mode = ((mode_arg as u16) & 0o7777) & !current_umask();
            let (_, _, caller_euid, caller_egid) = current_process_ids();

            match vol.create_file(parent_ino, file_name, create_mode, caller_euid, caller_egid) {
                Ok(new_ino) => {
                    let fd_entry = FdEntry {
                        backend: FdBackend::Ext2Disk {
                            path: alloc::string::String::from(rel),
                            inode_num: new_ino,
                            file_size: 0,
                            parent_inode: parent_ino,
                        },
                        offset: 0,
                        readable,
                        writable,
                        cloexec,
                        nonblock,
                    };
                    match alloc_fd(3, fd_entry) {
                        Some(i) => {
                            log::debug!("[open] {} → fd {} (ext2 new)", name, i);
                            i as u64
                        }
                        None => NEG_EMFILE,
                    }
                }
                Err(_) => NEG_EIO,
            }
        }
        Err(_) => NEG_ENOENT,
    }
}

/// Open a file under a `/mnt/usbN` secondary mount (Phase 92a D.4).
///
/// Resolves (or, with `create`, creates) the file in the mount's own ext2
/// volume and installs an `Ext2Disk` fd whose `path` is the **absolute** mount
/// path — so the read/write syscalls route back to the secondary volume via
/// `with_usb_mount`. The volume work runs inside the `USB_MOUNTS` lock and
/// returns the fd-construction data; the fd-table mutation happens outside the
/// lock.
#[allow(clippy::too_many_arguments)]
fn open_usb_file(
    name: &str,
    readable: bool,
    writable: bool,
    create: bool,
    append: bool,
    truncate: bool,
    mode_arg: u64,
    cloexec: bool,
    nonblock: bool,
) -> u64 {
    const NEG_EISDIR: u64 = (-21_i64) as u64;
    const NEG_ENOENT: u64 = (-2_i64) as u64;
    const NEG_EMFILE: u64 = (-24_i64) as u64;
    const NEG_EIO: u64 = (-5_i64) as u64;

    let create_mode = ((mode_arg as u16) & 0o7777) & !current_umask();
    let (_, _, caller_euid, caller_egid) = current_process_ids();

    // (inode_num, file_size, parent_inode, is_dir)
    let outcome = crate::fs::ext2::with_usb_mount_mut(
        name,
        |vol, rel| -> Result<(u32, u32, u32, bool), u64> {
            if rel.is_empty() || rel == "/" {
                // The mount-point directory itself (e.g. `ls /mnt/usb0` opens it
                // before getdents). Not writable/creatable/truncatable.
                if writable || create || truncate {
                    return Err(NEG_EISDIR);
                }
                let root = kernel_core::fs::ext2::EXT2_ROOT_INO;
                return Ok((root, 0, root, true));
            }
            let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
            let parent_ino = if parts.len() <= 1 {
                kernel_core::fs::ext2::EXT2_ROOT_INO
            } else {
                let parent_path = parts[..parts.len() - 1].join("/");
                vol.resolve_path(&parent_path).map_err(|_| NEG_ENOENT)?
            };
            match vol.resolve_path(rel) {
                Ok(ino) => {
                    let mut inode = vol.read_inode(ino).map_err(|_| NEG_EIO)?;
                    if inode.is_dir() {
                        if writable || create || truncate {
                            return Err(NEG_EISDIR);
                        }
                        return Ok((ino, inode.size, parent_ino, true));
                    }
                    if truncate && writable {
                        vol.truncate_file(ino, &mut inode).map_err(|_| NEG_EIO)?;
                    }
                    Ok((ino, inode.size, parent_ino, false))
                }
                Err(kernel_core::fs::ext2::Ext2Error::NotFound) if create => {
                    let file_name = parts[parts.len() - 1];
                    let new_ino = vol
                        .create_file(parent_ino, file_name, create_mode, caller_euid, caller_egid)
                        .map_err(|_| NEG_EIO)?;
                    Ok((new_ino, 0, parent_ino, false))
                }
                Err(_) => Err(NEG_ENOENT),
            }
        },
    );

    let (ino, file_size, parent_ino, is_dir) = match outcome {
        Some(Ok(t)) => t,
        Some(Err(e)) => return e,
        None => return NEG_ENOENT,
    };

    let backend = if is_dir {
        FdBackend::Dir {
            path: alloc::string::String::from(name),
        }
    } else {
        FdBackend::Ext2Disk {
            // Absolute path so the read/write syscalls route to the USB volume.
            path: alloc::string::String::from(name),
            inode_num: ino,
            file_size,
            parent_inode: parent_ino,
        }
    };
    let initial_offset = if append && !is_dir {
        file_size as usize
    } else {
        0
    };
    let fd_entry = FdEntry {
        backend,
        offset: initial_offset,
        readable: if is_dir { true } else { readable },
        writable: if is_dir { false } else { writable },
        cloexec,
        nonblock,
    };
    match alloc_fd(3, fd_entry) {
        Some(i) => i as u64,
        None => NEG_EMFILE,
    }
}

/// Check if the data partition is mounted (ext2 or FAT32).
fn data_is_mounted() -> bool {
    crate::fs::ext2::is_mounted() || crate::fs::fat32::is_mounted()
}

// Phase 88 Track B.2 — synthetic `st_dev` per mounted filesystem.
//
// POSIX file identity is `(st_dev, st_ino)`: two paths name the same file iff
// the pair matches, and the pair must be unique across filesystems. Leaving
// `st_dev = 0` everywhere let a tmpfs file and an ext2 file that happen to share
// an inode number collide on identity. Each filesystem class gets a stable,
// distinct, nonzero device id below. Values are arbitrary but fixed; the
// in-kernel ext2 root (`Ext2Disk`) and the ring-3 `vfs_server` view of the same
// on-disk filesystem (`VfsService`) deliberately share one id so the SAME file
// reached either way keeps one identity.
const DEV_EXT2_ROOT: u64 = 0x01;
const DEV_TMPFS: u64 = 0x02;
const DEV_RAMDISK: u64 = 0x03;
const DEV_PROCFS: u64 = 0x04;
const DEV_FAT32: u64 = 0x05;
const DEV_DEVFS: u64 = 0x06;

/// Phase 88 Track A — normalized file metadata for the `stat` family.
///
/// Every stat-producing syscall (`fstat`, `stat`/`lstat`/`newfstatat` →
/// `fstatat`, and `statx`) builds one of these per backend and serializes it
/// through the single [`fill_stat`] routine. No syscall hand-assembles a
/// `struct stat` byte-by-byte anymore: that pattern is what let the historical
/// `st_ino = 0` for `VfsService` `fstat` (and the still-zero `st_dev` /
/// `st_blocks` / timestamps) ship unnoticed and break clang's
/// `(st_dev, st_ino)` file-identity dedup. A forgotten field is now
/// structurally impossible — a missing field is a `FileMeta::new()` default,
/// not a silently-skipped offset write. A `cargo xtask check` grep gate
/// (`stat[<n>..` writes) enforces that no new offset assembly creeps back in.
#[derive(Clone, Copy)]
pub(super) struct FileMeta {
    pub dev: u64,
    pub ino: u64,
    pub nlink: u64,
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    pub rdev: u64,
    pub size: u64,
    pub blksize: u64,
    pub blocks: u64,
    pub atime: i64,
    pub mtime: i64,
    pub ctime: i64,
}

impl FileMeta {
    /// A zeroed `FileMeta` with a sane default `st_blksize` of 4096 — the value
    /// every stat path used for non-ext2 backends. ext2 backends override it
    /// with the real on-disk block size.
    pub(super) const fn new() -> Self {
        FileMeta {
            dev: 0,
            ino: 0,
            nlink: 0,
            mode: 0,
            uid: 0,
            gid: 0,
            rdev: 0,
            size: 0,
            blksize: 4096,
            blocks: 0,
            atime: 0,
            mtime: 0,
            ctime: 0,
        }
    }
}

/// Serialize a [`FileMeta`] into a 144-byte x86_64 Linux `struct stat`.
///
/// This is the ONLY place `struct stat` offsets are written. Layout:
/// ```text
///  0: st_dev (u64)       8: st_ino (u64)     16: st_nlink (u64)
/// 24: st_mode (u32)     28: st_uid (u32)     32: st_gid (u32)
/// 36: __pad0 (u32)      40: st_rdev (u64)    48: st_size (i64)
/// 56: st_blksize (i64)  64: st_blocks (i64)
/// 72: st_atim {tv_sec, tv_nsec}   88: st_mtim   104: st_ctim
/// ```
pub(super) fn fill_stat(m: &FileMeta) -> [u8; 144] {
    let mut s = [0u8; 144];
    s[0..8].copy_from_slice(&m.dev.to_ne_bytes());
    s[8..16].copy_from_slice(&m.ino.to_ne_bytes());
    s[16..24].copy_from_slice(&m.nlink.to_ne_bytes());
    s[24..28].copy_from_slice(&m.mode.to_ne_bytes());
    s[28..32].copy_from_slice(&m.uid.to_ne_bytes());
    s[32..36].copy_from_slice(&m.gid.to_ne_bytes());
    // 36..40 __pad0 stays zero.
    s[40..48].copy_from_slice(&m.rdev.to_ne_bytes());
    s[48..56].copy_from_slice(&m.size.to_ne_bytes());
    s[56..64].copy_from_slice(&m.blksize.to_ne_bytes());
    s[64..72].copy_from_slice(&m.blocks.to_ne_bytes());
    // tv_sec only (1 s granularity); the tv_nsec halves at 80/96/112 stay zero.
    s[72..80].copy_from_slice(&m.atime.to_ne_bytes());
    s[88..96].copy_from_slice(&m.mtime.to_ne_bytes());
    s[104..112].copy_from_slice(&m.ctime.to_ne_bytes());
    s
}

/// Serialize `meta` and copy it to the user `struct stat` at `stat_ptr`.
fn write_stat_to_user(stat_ptr: u64, meta: &FileMeta) -> u64 {
    let bytes = fill_stat(meta);
    match UserSliceWo::new(stat_ptr, bytes.len()).and_then(|s| s.copy_from_kernel(&bytes)) {
        Ok(()) => 0,
        Err(_) => NEG_EFAULT,
    }
}

/// Phase 88 Track B.2 — the synthetic `st_dev` for an fd's backend.
///
/// Each filesystem class gets a stable, distinct, nonzero id so that
/// `(st_dev, st_ino)` is unique across filesystems. The in-kernel ext2 root
/// (`Ext2Disk`) and the ring-3 `vfs_server` view of the SAME on-disk fs
/// (`VfsService`) share one id so a file reached either way keeps one identity.
/// Identity-irrelevant backends (sockets, pipes, stdio, epoll, eventfd) report
/// `dev = 0`.
fn stat_dev_for_backend(backend: &FdBackend) -> u64 {
    match backend {
        FdBackend::Ext2Disk { .. } | FdBackend::VfsService { .. } => DEV_EXT2_ROOT,
        FdBackend::Tmpfs { .. } => DEV_TMPFS,
        FdBackend::Ramdisk { .. } => DEV_RAMDISK,
        FdBackend::Proc { .. } => DEV_PROCFS,
        FdBackend::Fat32Disk { .. } => DEV_FAT32,
        FdBackend::DevNull
        | FdBackend::DevZero
        | FdBackend::DevUrandom
        | FdBackend::DevFull
        | FdBackend::DeviceTTY { .. }
        | FdBackend::PtyMaster { .. }
        | FdBackend::PtySlave { .. } => DEV_DEVFS,
        // A directory fd's backend does not say which fs it lives on; re-derive
        // from the path in the SAME routing order `sys_linux_fstatat` /
        // `path_filemeta` use (procfs → tmpfs → ramdisk → ext2), so fstat and
        // fstatat report the same `st_dev` for the same directory.
        FdBackend::Dir { path } => {
            if crate::fs::procfs::stat(path).is_some() {
                DEV_PROCFS
            } else if tmpfs_relative_path(path).is_some() {
                DEV_TMPFS
            } else if crate::fs::ramdisk::ramdisk_lookup(path).is_some() {
                DEV_RAMDISK
            } else {
                DEV_EXT2_ROOT
            }
        }
        _ => 0,
    }
}

pub(super) fn sys_linux_fstat(fd: u64, stat_ptr: u64) -> u64 {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };

    // Build a normalized FileMeta per backend (preserving each backend's prior
    // field values), then serialize once via `fill_stat`.
    let mut meta: FileMeta = match &entry.backend {
        // Phase 88 — a directory fd reports the SAME metadata `fstatat` reports
        // for its path, via the shared `path_filemeta` source of truth. The
        // previous hand-rolled arm left an ext2 directory fd's ino/nlink/size/
        // times at 0 (an `fstat`-vs-`fstatat` identity divergence).
        FdBackend::Dir { path } => match path_filemeta(path) {
            Ok(m) => m,
            Err(err) => return err,
        },
        FdBackend::DevNull | FdBackend::DevZero | FdBackend::DevUrandom | FdBackend::DevFull => {
            let mut m = FileMeta::new();
            m.mode = 0x2000 | 0o666;
            m
        }
        FdBackend::Proc { path } => {
            let Some(st) = crate::fs::procfs::stat(path) else {
                return NEG_ENOENT;
            };
            let mut m = FileMeta::new();
            m.ino = st.ino;
            m.nlink = st.nlink;
            m.mode = st.mode;
            m.uid = st.uid;
            m.gid = st.gid;
            m.size = st.size;
            m
        }
        FdBackend::DeviceTTY { tty_id } => {
            let mut m = FileMeta::new();
            m.mode = 0x2000 | 0o620;
            m.rdev = ((5u64) << 8) | (*tty_id as u64);
            m
        }
        FdBackend::PtyMaster { pty_id } => {
            let mut m = FileMeta::new();
            m.mode = 0x2000 | 0o620;
            m.rdev = ((5u64) << 8) | (2 + *pty_id as u64);
            m
        }
        FdBackend::PtySlave { pty_id } => {
            let mut m = FileMeta::new();
            m.mode = 0x2000 | 0o620;
            m.rdev = ((136u64) << 8) | (*pty_id as u64);
            m
        }
        FdBackend::Socket { .. } | FdBackend::UnixSocket { .. } => {
            let mut m = FileMeta::new();
            m.mode = 0xC000 | 0o755;
            m
        }
        FdBackend::Stdout | FdBackend::Stdin => {
            let mut m = FileMeta::new();
            m.mode = 0x2000 | 0o620;
            m
        }
        FdBackend::PipeRead { .. }
        | FdBackend::PipeWrite { .. }
        | FdBackend::EventFd { .. }
        | FdBackend::TimerFd { .. } => {
            let mut m = FileMeta::new();
            m.mode = 0x1000 | 0o600;
            m
        }
        FdBackend::Ramdisk { content_len, .. } => {
            // Ramdisk files: root-owned, mode 0o755 (all files, including non-executables).
            let mut m = FileMeta::new();
            m.mode = 0x8000 | 0o755;
            m.size = *content_len as u64;
            m
        }
        FdBackend::Tmpfs { path } => {
            let tmpfs = crate::fs::tmpfs::TMPFS.lock();
            match tmpfs.stat(path) {
                Ok(s) => {
                    let mode = if s.is_symlink {
                        0xA000 | 0o777
                    } else if s.is_dir {
                        0x4000 | s.mode as u32
                    } else {
                        0x8000 | s.mode as u32
                    };
                    let mut m = FileMeta::new();
                    m.ino = s.ino;
                    m.nlink = s.nlink;
                    m.mode = mode;
                    m.uid = s.uid;
                    m.gid = s.gid;
                    m.size = s.size as u64;
                    m
                }
                Err(_) => return NEG_ENOENT,
            }
        }
        FdBackend::Fat32Disk {
            path, file_size, ..
        } => {
            let (u, g, mode) = data_file_metadata(path).unwrap_or((0, 0, 0o755));
            let mut m = FileMeta::new();
            m.mode = 0x8000 | mode as u32;
            m.uid = u;
            m.gid = g;
            m.size = *file_size as u64;
            m
        }
        FdBackend::Ext2Disk {
            inode_num,
            file_size,
            ..
        } => {
            // Phase 32: read inode to get timestamps and real metadata.
            let inode_num = *inode_num;
            let vol = crate::fs::ext2::EXT2_VOLUME.lock();
            if let Some(vol) = vol.as_ref()
                && let Ok(inode) = vol.read_inode(inode_num)
            {
                let mut m = FileMeta::new();
                m.ino = inode_num as u64;
                m.nlink = inode.links_count as u64;
                m.mode = inode.mode as u32;
                m.uid = inode.uid as u32;
                m.gid = inode.gid as u32;
                m.size = inode.size as u64; // use inode size, not cached FD size
                m.blksize = vol.block_size as u64;
                m.blocks = inode.blocks as u64;
                m.atime = inode.atime as i64;
                m.mtime = inode.mtime as i64;
                m.ctime = inode.ctime as i64;
                m
            } else {
                // Fallback if inode read fails — use cached FD size.
                let mut m = FileMeta::new();
                m.mode = 0x8000 | 0o755;
                m.size = *file_size as u64;
                m
            }
        }
        FdBackend::Epoll { .. } => {
            let mut m = FileMeta::new();
            m.mode = 0x2000 | 0o600;
            m
        }
        FdBackend::VfsService { meta, .. } => {
            // Phase 88 Track B.1/D — report the full metadata snapshot captured
            // from the VFS_OPEN reply (real inode/mode/uid/gid/nlink/size/blocks/
            // times) so fstat(fd) matches fstatat(path) field-for-field. The
            // st_ino was the field whose absence broke clang's (st_dev, st_ino)
            // dedup; st_dev, st_blocks, and the timestamps were silently zero too.
            // st_dev is assigned uniformly after the match.
            let mut m = FileMeta::new();
            m.ino = meta.inode as u64;
            m.nlink = meta.nlink as u64;
            m.mode = meta.mode;
            m.uid = meta.uid;
            m.gid = meta.gid;
            m.size = meta.size;
            m.blksize = meta.blksize;
            m.blocks = meta.blocks;
            m.atime = meta.atime;
            m.mtime = meta.mtime;
            m.ctime = meta.ctime;
            m
        }
    };

    // Phase 88 Track B.2 — assign the per-filesystem st_dev uniformly so
    // (st_dev, st_ino) is unique across filesystems.
    meta.dev = stat_dev_for_backend(&entry.backend);
    write_stat_to_user(stat_ptr, &meta)
}

/// Phase 88 Track E — `statx(2)` (332). m3OS intentionally returns `-ENOSYS`
/// here rather than implementing the `struct statx` layout natively.
///
/// Rationale (a *documented* decision, not an oversight): glibc and musl's
/// `statx()` wrappers fall back to `newfstatat` when the kernel reports
/// `ENOSYS`, and Phase 88 Track A made that fallback **lossless** — the
/// `fill_stat` serializer populates every `struct stat` field
/// (dev/ino/nlink/mode/uid/gid/size/blocks/times) that `statx` would report, so
/// no metadata is dropped on the fallback path. The earlier post-mortem flagged
/// an ENOSYS `statx` as a "compatibility cliff" specifically because the older
/// `fstat`/`fstatat` paths were themselves buggy (the `st_ino = 0` defect); with
/// those paths now correct and consistent (`fstat == fstatat`), the cliff is
/// gone. A native `statx` (transcoding `FileMeta` → `struct statx` with the
/// `STATX_*` request mask) is a low-value deferred follow-up. The contract is
/// verified by the in-OS `statx → ENOSYS` assertion in `smoke-runner` and by the
/// clang/python toolchain gates, which call `statx` via libc and fall back.
fn sys_linux_statx() -> u64 {
    NEG_ENOSYS
}

pub(super) fn sys_statfs(path_ptr: u64, buf_ptr: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw = match read_user_cstr(path_ptr, &mut buf) {
        Some(p) => p,
        None => return NEG_EFAULT,
    };
    let lexical = match resolve_path_from_dirfd(AT_FDCWD, raw) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let abs = match resolve_existing_fs_path(&lexical, true) {
        Ok(path) => path,
        Err(err) => return err,
    };
    if !statfs_path_exists(&abs) {
        return NEG_ENOENT;
    }
    let stat = statfs_for_path(&abs);
    write_statfs_to_user(buf_ptr, &stat)
}

pub(super) fn sys_fstatfs(fd: u64, buf_ptr: u64) -> u64 {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };

    let stat = match &entry.backend {
        FdBackend::Tmpfs { .. } => tmpfs_statfs(),
        FdBackend::Proc { .. } => proc_statfs(),
        FdBackend::Fat32Disk { .. } => fat32_statfs(),
        FdBackend::Ext2Disk { .. } => ext2_statfs(),
        FdBackend::Ramdisk { .. } => ramdisk_statfs(),
        FdBackend::Dir { path } => statfs_for_path(path),
        FdBackend::DevNull
        | FdBackend::DevZero
        | FdBackend::DevUrandom
        | FdBackend::DevFull
        | FdBackend::DeviceTTY { .. }
        | FdBackend::PtyMaster { .. }
        | FdBackend::PtySlave { .. }
        | FdBackend::Epoll { .. } => ramdisk_statfs(),
        FdBackend::Stdin | FdBackend::Stdout => ramdisk_statfs(),
        FdBackend::PipeRead { .. }
        | FdBackend::PipeWrite { .. }
        | FdBackend::EventFd { .. }
        | FdBackend::TimerFd { .. } => pipefs_statfs(),
        FdBackend::Socket { .. } | FdBackend::UnixSocket { .. } => sockfs_statfs(),
        FdBackend::VfsService { .. } => ext2_statfs(),
    };
    write_statfs_to_user(buf_ptr, &stat)
}

// ---------------------------------------------------------------------------
// Phase 27: chmod, fchmod, chown, fchown
// ---------------------------------------------------------------------------

const NEG_EACCES: u64 = (-13_i64) as u64;

// ---------------------------------------------------------------------------
// Phase 27 Track C: Permission enforcement
// ---------------------------------------------------------------------------

/// Check if a caller has the required permission on a file/directory.
///
/// `required` is a bitmask: 4=read, 2=write, 1=execute.
/// Returns true if access is allowed.
fn check_permission(
    file_uid: u32,
    file_gid: u32,
    file_mode: u16,
    caller_uid: u32,
    caller_gid: u32,
    required: u8,
) -> bool {
    // Root bypasses all permission checks.
    if caller_uid == 0 {
        return true;
    }

    let bits = if caller_uid == file_uid {
        ((file_mode >> 6) & 0o7) as u8
    } else if caller_gid == file_gid {
        ((file_mode >> 3) & 0o7) as u8
    } else {
        (file_mode & 0o7) as u8
    };

    (bits & required) == required
}

/// Get file metadata for permission checking on a resolved absolute path.
fn path_metadata(abs_path: &str) -> Option<(u32, u32, u16)> {
    if let Some(st) = crate::fs::procfs::stat(abs_path) {
        return Some((st.uid, st.gid, (st.mode & 0o7777) as u16));
    }
    if let Some(rel) = tmpfs_relative_path(abs_path) {
        let tmpfs = crate::fs::tmpfs::TMPFS.lock();
        if let Ok(s) = tmpfs.stat(rel) {
            return Some((s.uid, s.gid, s.mode));
        }
        return None;
    }
    // Ramdisk files (/bin/*, /sbin/*) are root-owned, 0o755.
    if crate::fs::ramdisk::ramdisk_lookup(abs_path).is_some() {
        return Some((0, 0, 0o755));
    }
    if abs_path == "/dev" || abs_path == "/dev/pts" {
        return Some((0, 0, 0o755));
    }
    if abs_path == "/dev/null"
        || abs_path == "/dev/zero"
        || abs_path == "/dev/urandom"
        || abs_path == "/dev/random"
        || abs_path == "/dev/full"
        || abs_path == "/dev/tty"
        || abs_path == "/dev/ptmx"
        || abs_path.starts_with("/dev/pts/")
    {
        return Some((0, 0, 0o666));
    }
    if abs_path == "/" || abs_path == "/tmp" {
        return Some((0, 0, 0o755));
    }
    // ext2 root filesystem — check for any path.
    //
    // DAC decisions must stay on kernel-verified metadata: a compromised or
    // misbehaving ring-3 `vfs_server` could otherwise spoof uid/gid/mode via
    // `VFS_STAT_PATH` and defeat the access checks in `open_user_path`. The
    // service is only trusted for user-visible `stat` / `getdents` behavior
    // (see `sys_fstat` / `sys_getdents`), not for enforcement paths.
    if let Some(rel) = ext2_root_path(abs_path)
        && crate::fs::ext2::is_mounted()
    {
        return data_file_metadata(rel);
    }
    // Legacy: /data paths for FAT32 fallback.
    if let Some(rel) = abs_path.strip_prefix("/data/") {
        return data_file_metadata(rel);
    }
    None
}

/// Get metadata for the parent directory of a path.
fn parent_dir_metadata(abs_path: &str) -> Option<(u32, u32, u16)> {
    let trimmed = abs_path.trim_end_matches('/');
    if let Some(pos) = trimmed.rfind('/') {
        let parent = if pos == 0 { "/" } else { &trimmed[..pos] };
        path_metadata(parent)
    } else {
        path_metadata("/")
    }
}

/// Helper to resolve a path and apply a metadata-changing operation.
/// Returns the filesystem-relative path and which FS it belongs to.
enum FsTarget {
    Tmpfs(alloc::string::String),
    /// ext2 root (or FAT32 /data fallback). The string is the root-relative path.
    DiskData(alloc::string::String),
    Ramdisk,
}

fn resolve_fs_target(abs_path: &str) -> FsTarget {
    // `/tmp` and `/run` are the kernel tmpfs mounts. Route them through
    // `tmpfs_relative_path` so the mount-prefix convention (`tmp/…`, `run/…`)
    // matches every other tmpfs syscall path (open/read/write/stat/getdents).
    // The previous hand-rolled `strip_prefix("/tmp")` dropped the mount prefix
    // (yielding a bare `/foo`) and ignored `/run` entirely, so chmod/chown/
    // symlink looked up the wrong tmpfs subtree and returned ENOENT for a file
    // that open/write had just created under `tmp/…`. Phase 85b surfaced this:
    // `git init` does `chmod(.git/config.lock)` on a lockfile it just created in
    // a `/tmp` repo and got "No such file or directory", aborting the init.
    if let Some(rel) = tmpfs_relative_path(abs_path) {
        return FsTarget::Tmpfs(alloc::string::String::from(rel));
    }
    // /data paths always go to disk data (FAT32 or ext2 /data fallback),
    // even when ext2 is mounted at root.
    if abs_path.starts_with("/data/") {
        let rel = abs_path.strip_prefix("/data/").unwrap_or("");
        return FsTarget::DiskData(alloc::string::String::from(rel));
    }
    if crate::fs::procfs::path_node(abs_path).is_some()
        || abs_path == "/dev"
        || abs_path.starts_with("/dev/")
        || crate::fs::ramdisk::ramdisk_lookup(abs_path).is_some()
    {
        return FsTarget::Ramdisk;
    }
    // When ext2 is mounted at root, route non-ramdisk paths to ext2.
    if crate::fs::ext2::is_mounted()
        && let Some(rel) = ext2_root_path(abs_path)
    {
        return FsTarget::DiskData(alloc::string::String::from(rel));
    }
    FsTarget::Ramdisk
}

fn create_parent_is_read_only(abs_path: &str) -> bool {
    let parent = parent_path(abs_path);
    parent != "/"
        && (crate::fs::procfs::path_node(parent).is_some()
            || parent == "/dev"
            || parent.starts_with("/dev/")
            || crate::fs::ramdisk::ramdisk_lookup(parent).is_some())
}

/// `chmod(path, mode)` — change file mode bits (syscall 90).
pub(super) fn sys_linux_chmod(path_ptr: u64, mode_arg: u64) -> u64 {
    sys_linux_chmod_at(AT_FDCWD, path_ptr, mode_arg)
}

/// Phase 94 — `fchmodat(dirfd, pathname, mode, flags)` (syscall 268), also the
/// handler for `fchmodat2`(452). uutils `chmod -R` walks a directory tree via
/// `uucore::safe_traversal` (the TOCTOU-safe fd-relative family that also forced
/// `unlinkat`) and applies modes with `fchmodat2`/`fchmodat(dirfd, name, mode, …)`.
/// musl's `chmod()` is the legacy `SYS_chmod`(90) on x86_64, so non-recursive chmod
/// already worked; only the fd-relative `*at` form was missing. Routes to the
/// dirfd-aware chmod core. The `flags` arg (`AT_SYMLINK_NOFOLLOW`=0x100) is accepted
/// but not specially honored: m3OS chmod always follows symlinks (no `lchmod`),
/// Linux itself returns `EOPNOTSUPP` for it on most filesystems, and the recursive
/// walk has already confirmed each target is not a symlink (so follow == nofollow).
pub(super) fn sys_linux_fchmodat(dirfd: u64, path_ptr: u64, mode_arg: u64, _flags: u64) -> u64 {
    sys_linux_chmod_at(dirfd, path_ptr, mode_arg)
}

/// `chmod` core, dirfd-aware. The `AT_FDCWD` path is byte-equivalent to the prior
/// `resolve_path(&cwd, …)` behaviour for relative and absolute paths; the only
/// difference is an empty path, which now returns `ENOENT` (matching Linux
/// `chmod("")==ENOENT`) instead of degenerately targeting the cwd.
pub(super) fn sys_linux_chmod_at(dirfd: u64, path_ptr: u64, mode_arg: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };
    let lexical = match resolve_path_from_dirfd(dirfd, raw) {
        Ok(p) => p,
        Err(e) => return e,
    };
    let abs = match resolve_existing_fs_path(&lexical, true) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let mode = (mode_arg & 0o7777) as u16;

    // Only owner or root can chmod.
    let (_, _, euid, _) = current_process_ids();

    match resolve_fs_target(&abs) {
        FsTarget::Tmpfs(rel) => {
            let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
            let stat = match tmpfs.stat(&rel) {
                Ok(s) => s,
                Err(_) => return NEG_ENOENT,
            };
            if euid != 0 && euid != stat.uid {
                return NEG_EPERM;
            }
            if tmpfs.chmod(&rel, mode).is_err() {
                return NEG_ENOENT;
            }
            0
        }
        FsTarget::DiskData(rel) => {
            if euid != 0 {
                let (owner, _, _) = match data_file_metadata(&rel) {
                    Some(m) => m,
                    None => return NEG_ENOENT,
                };
                if euid != owner {
                    return NEG_EPERM;
                }
            }
            data_chmod(&rel, mode)
        }
        FsTarget::Ramdisk => NEG_EROFS,
    }
}

/// `fchmod(fd, mode)` — change file mode bits by fd (syscall 91).
pub(super) fn sys_linux_fchmod(fd: u64, mode_arg: u64) -> u64 {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };
    let mode = (mode_arg & 0o7777) as u16;
    let (_, _, euid, _) = current_process_ids();

    match &entry.backend {
        FdBackend::Tmpfs { path } => {
            let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
            let stat = match tmpfs.stat(path) {
                Ok(s) => s,
                Err(_) => return NEG_ENOENT,
            };
            if euid != 0 && euid != stat.uid {
                return NEG_EPERM;
            }
            if tmpfs.chmod(path, mode).is_err() {
                return NEG_ENOENT;
            }
            0
        }
        FdBackend::Fat32Disk { path, .. } | FdBackend::Ext2Disk { path, .. } => {
            if euid != 0 {
                let (owner, _, _) = match data_file_metadata(path) {
                    Some(m) => m,
                    None => return NEG_ENOENT,
                };
                if euid != owner {
                    return NEG_EPERM;
                }
            }
            data_chmod(path, mode)
        }
        FdBackend::Ramdisk { .. } => NEG_EROFS,
        _ => NEG_EBADF,
    }
}

/// `chown(path, uid, gid)` — change file owner (syscall 92).
/// Only root can change file ownership.
pub(super) fn sys_linux_chown(path_ptr: u64, uid_arg: u64, gid_arg: u64) -> u64 {
    sys_linux_chown_at(AT_FDCWD, path_ptr, uid_arg, gid_arg)
}

/// Phase 94 — `fchownat(dirfd, pathname, owner, group, flags)` (syscall 260).
/// uutils `chown -R` walks the tree via `uucore::safe_traversal` and applies
/// ownership with `fchownat(dirfd, name, …)` (the fd-relative sibling of the
/// `unlinkat`/`fchmodat` family). musl's `chown()` is the legacy `SYS_chown`(92)
/// on x86_64 so non-recursive chown already worked; this adds the `*at` form.
/// `flags` (`AT_SYMLINK_NOFOLLOW`=0x100) is accepted but not specially honored —
/// m3OS chown always follows symlinks; the recursive walk targets regular tree
/// entries, where follow-vs-nofollow does not differ.
pub(super) fn sys_linux_fchownat(
    dirfd: u64,
    path_ptr: u64,
    uid_arg: u64,
    gid_arg: u64,
    _flags: u64,
) -> u64 {
    sys_linux_chown_at(dirfd, path_ptr, uid_arg, gid_arg)
}

/// `chown` core, dirfd-aware. The `AT_FDCWD` path is byte-equivalent to the prior
/// `resolve_path(&cwd, …)` behaviour for relative and absolute paths (empty path
/// now returns `ENOENT`, matching Linux).
pub(super) fn sys_linux_chown_at(dirfd: u64, path_ptr: u64, uid_arg: u64, gid_arg: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };
    let lexical = match resolve_path_from_dirfd(dirfd, raw) {
        Ok(p) => p,
        Err(e) => return e,
    };
    let abs = match resolve_existing_fs_path(&lexical, true) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let new_uid = uid_arg as u32;
    let new_gid = gid_arg as u32;

    let (_, _, euid, _) = current_process_ids();
    if euid != 0 {
        return NEG_EPERM;
    }

    match resolve_fs_target(&abs) {
        FsTarget::Tmpfs(rel) => {
            let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
            if tmpfs.chown(&rel, new_uid, new_gid).is_err() {
                return NEG_ENOENT;
            }
            0
        }
        FsTarget::DiskData(rel) => data_chown(&rel, new_uid, new_gid),
        FsTarget::Ramdisk => NEG_EROFS,
    }
}

/// `fchown(fd, uid, gid)` — change file owner by fd (syscall 93).
pub(super) fn sys_linux_fchown(fd: u64, uid_arg: u64, gid_arg: u64) -> u64 {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };
    let new_uid = uid_arg as u32;
    let new_gid = gid_arg as u32;

    let (_, _, euid, _) = current_process_ids();
    if euid != 0 {
        return NEG_EPERM;
    }

    match &entry.backend {
        FdBackend::Tmpfs { path } => {
            let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
            if tmpfs.chown(path, new_uid, new_gid).is_err() {
                return NEG_ENOENT;
            }
            0
        }
        FdBackend::Fat32Disk { path, .. } | FdBackend::Ext2Disk { path, .. } => {
            data_chown(path, new_uid, new_gid)
        }
        FdBackend::Ramdisk { .. } => NEG_EROFS,
        _ => NEG_EBADF,
    }
}

// ---------------------------------------------------------------------------
// T017: lseek(fd, offset, whence)
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_lseek(fd: u64, offset: u64, whence: u64) -> u64 {
    let fd = fd as usize;
    if !(3..MAX_FDS).contains(&fd) {
        return NEG_EBADF;
    }

    let entry = match current_fd_entry(fd) {
        Some(e) => e,
        None => return NEG_EBADF,
    };

    const SEEK_SET: u64 = 0;
    const SEEK_CUR: u64 = 1;
    const SEEK_END: u64 = 2;

    let file_len = match &entry.backend {
        FdBackend::Stdout
        | FdBackend::Stdin
        | FdBackend::PipeRead { .. }
        | FdBackend::PipeWrite { .. }
        | FdBackend::Dir { .. }
        | FdBackend::DevNull
        | FdBackend::DevZero
        | FdBackend::DevUrandom
        | FdBackend::DevFull
        | FdBackend::DeviceTTY { .. }
        | FdBackend::PtyMaster { .. }
        | FdBackend::PtySlave { .. }
        | FdBackend::Proc { .. }
        | FdBackend::Socket { .. }
        | FdBackend::UnixSocket { .. }
        | FdBackend::Epoll { .. }
        | FdBackend::EventFd { .. }
        | FdBackend::TimerFd { .. } => return NEG_EINVAL, // not seekable
        FdBackend::Ramdisk { content_len, .. } => *content_len,
        FdBackend::Tmpfs { path } => {
            let tmpfs = crate::fs::tmpfs::TMPFS.lock();
            match tmpfs.file_size(path) {
                Ok(len) => len,
                Err(_) => return NEG_ENOENT,
            }
        }
        FdBackend::Fat32Disk { file_size, .. } | FdBackend::Ext2Disk { file_size, .. } => {
            *file_size as usize
        }
        FdBackend::VfsService { meta, .. } => meta.size as usize,
    };

    let offset = offset as i64;

    let new_offset: i64 = match whence {
        SEEK_SET => offset,
        SEEK_CUR => match (entry.offset as i64).checked_add(offset) {
            Some(v) => v,
            None => return NEG_EINVAL,
        },
        SEEK_END => match (file_len as i64).checked_add(offset) {
            Some(v) => v,
            None => return NEG_EINVAL,
        },
        _ => return NEG_EINVAL,
    };

    if new_offset < 0 || new_offset as usize > file_len {
        return NEG_EINVAL;
    }

    // Update offset in per-process FD table.
    with_current_fd_mut(fd, |slot| {
        if let Some(e) = slot {
            e.offset = new_offset as usize;
        }
    });
    new_offset as u64
}

// ---------------------------------------------------------------------------
// T018: mmap(addr, len, prot, flags[from SYSCALL_ARG3], fd, offset)
//
// Supports MAP_PRIVATE|MAP_ANONYMOUS and file-backed MAP_PRIVATE|MAP_SHARED.
// File-backed mappings use Strategy A (eager loading): all pages are
// immediately faulted in at mmap time.
// ---------------------------------------------------------------------------

/// Read `buf.len()` bytes from process `pid`'s fd `fd` at file byte `offset`
/// into the kernel buffer `buf`.  Does **not** advance the fd's offset.
/// Returns the number of bytes actually read, or a negative errno on error.
/// Phase 95b (Area A.2) — demand-fault entry point: read one page of file data
/// for a lazy (`MAP_LAZY_FILE`) file-backed mapping into `buf`, by `(pid, fd,
/// file_offset)`. Thin `pub(crate)` wrapper over [`kernel_read_fd_at`] (which
/// handles `VfsService`/ext2/ramdisk/tmpfs/fat32), called from the page-fault
/// handler. Returns bytes read (0 at EOF / past file end) or a negative errno.
pub(crate) fn demand_read_file_page(
    pid: u32,
    fd: usize,
    file_offset: usize,
    buf: &mut [u8],
) -> Result<usize, i64> {
    kernel_read_fd_at(pid, fd, file_offset, buf)
}

fn kernel_read_fd_at(pid: u32, fd: usize, offset: usize, buf: &mut [u8]) -> Result<usize, i64> {
    if buf.is_empty() {
        return Ok(0);
    }
    let entry = {
        let table = crate::process::PROCESS_TABLE.lock();
        match table.find(pid) {
            Some(p) => p.fd_get(fd),
            None => return Err(NEG_EBADF as i64),
        }
    };
    let entry = match entry {
        Some(e) => e,
        None => return Err(NEG_EBADF as i64),
    };
    match &entry.backend {
        FdBackend::Ramdisk {
            content_addr,
            content_len,
        } => {
            if offset >= *content_len {
                return Ok(0);
            }
            let available = content_len - offset;
            let to_read = buf.len().min(available);
            // SAFETY: content_addr is a static ramdisk pointer (lives for 'static).
            let src = unsafe {
                core::slice::from_raw_parts((*content_addr + offset) as *const u8, to_read)
            };
            buf[..to_read].copy_from_slice(src);
            Ok(to_read)
        }
        FdBackend::Tmpfs { path } => {
            let path = path.clone();
            let tmpfs = crate::fs::tmpfs::TMPFS.lock();
            match tmpfs.read_file(&path, offset, buf.len()) {
                Ok(data) => {
                    let n = data.len().min(buf.len());
                    buf[..n].copy_from_slice(&data[..n]);
                    Ok(n)
                }
                Err(crate::fs::tmpfs::TmpfsError::NotFound) => Err(NEG_ENOENT as i64),
                Err(_) => Err(NEG_EIO as i64),
            }
        }
        FdBackend::Fat32Disk {
            start_cluster,
            file_size,
            ..
        } => {
            let start_cluster = *start_cluster;
            let file_size = *file_size;
            if start_cluster < 2 || offset >= file_size as usize {
                return Ok(0);
            }
            let vol = crate::fs::fat32::FAT32_VOLUME.lock();
            match vol.as_ref() {
                Some(v) => v
                    .read_file(start_cluster, file_size, offset, buf)
                    .map_err(|_| NEG_EIO as i64),
                None => Err(NEG_EIO as i64),
            }
        }
        FdBackend::Ext2Disk { inode_num, .. } => {
            let inode_num = *inode_num;
            let vol = crate::fs::ext2::EXT2_VOLUME.lock();
            match vol.as_ref() {
                Some(v) => match v.read_inode(inode_num) {
                    Ok(inode) => v
                        .read_file_data(&inode, offset as u64, buf)
                        .map_err(|_| NEG_EIO as i64),
                    Err(_) => Err(NEG_EIO as i64),
                },
                None => Err(NEG_EIO as i64),
            }
        }
        // Phase 95b (Area A.2) — a `/usr` file on the default boot is served by
        // the ring-3 `vfs_server`. Reading it here (pread-style, by `offset`)
        // blocks on the vfs IPC reply; the demand-fault filler relies on this arm
        // to demand-page a file-backed mapping whose backing fd is `VfsService`.
        FdBackend::VfsService { service_handle, .. } => {
            vfs_service_read_kernel(*service_handle, offset, buf)
        }
        _ => Err(NEG_EINVAL as i64),
    }
}

/// Phase 88 Track G — the write analog of [`kernel_read_fd_at`]: write `buf` at
/// an explicit byte `offset` for the seekable file backends (Tmpfs, ext2,
/// FAT32), WITHOUT reading or mutating the fd's shared position. This makes
/// `pwrite64` atomic under `CLONE_FILES` fd-table sharing and POSIX-correct
/// (non-seekable fds report `ESPIPE`). It mirrors the per-backend write
/// bookkeeping in `sys_linux_write` — ext2 routes to the `vfs_server` write
/// authority when registered (else the in-kernel engine); FAT32 may relocate the
/// start cluster — but updates only the file-identity cache (`file_size` /
/// `start_cluster`), never `entry.offset`.
fn kernel_write_fd_at(pid: u32, fd: usize, offset: usize, buf: &[u8]) -> Result<usize, i64> {
    if buf.is_empty() {
        return Ok(0);
    }
    let entry = {
        let table = crate::process::PROCESS_TABLE.lock();
        match table.find(pid) {
            Some(p) => p.fd_get(fd),
            None => return Err(NEG_EBADF as i64),
        }
    };
    let entry = match entry {
        Some(e) => e,
        None => return Err(NEG_EBADF as i64),
    };
    if !entry.writable {
        return Err(NEG_EBADF as i64);
    }
    match &entry.backend {
        FdBackend::Tmpfs { path } => {
            let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
            match tmpfs.write_file(path, offset, buf) {
                Ok(()) => Ok(buf.len()),
                Err(crate::fs::tmpfs::TmpfsError::NoSpace) => Err(NEG_ENOSPC as i64),
                Err(crate::fs::tmpfs::TmpfsError::NotFound) => Err(NEG_EBADF as i64),
                Err(_) => Err(NEG_EINVAL as i64),
            }
        }
        FdBackend::Ext2Disk {
            inode_num, path, ..
        } => {
            let inode_num = *inode_num;
            let path = path.clone();
            // Route to the vfs_server ext2 write authority when registered, so a
            // later read (this fd or any process) sees coherent bytes.
            if vfs_write_routable() {
                let mut total = 0usize;
                let mut cur_off = offset as u64;
                let mut new_size: Option<u32> = None;
                while total < buf.len() {
                    match vfs_service_write(&path, cur_off, &buf[total..]) {
                        Ok((0, _)) => break,
                        Ok((n, sz)) => {
                            total += n;
                            cur_off += n as u64;
                            new_size = Some(sz);
                        }
                        Err(e) => {
                            if total == 0 {
                                return Err(e as i64);
                            }
                            break;
                        }
                    }
                }
                if let Some(sz) = new_size {
                    with_current_fd_mut(fd, |slot| {
                        if let Some(e) = slot
                            && let FdBackend::Ext2Disk {
                                file_size: ref mut fs,
                                ..
                            } = e.backend
                        {
                            *fs = sz;
                        }
                    });
                }
                return Ok(total);
            }
            // In-kernel ext2 engine fallback.
            let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
            let Some(vol) = vol.as_mut() else {
                return Err(NEG_EIO as i64);
            };
            let mut inode = vol.read_inode(inode_num).map_err(|_| NEG_EIO as i64)?;
            let now = current_unix_time();
            inode.mtime = now;
            inode.ctime = now;
            match vol.write_file_data(inode_num, &mut inode, offset as u64, buf) {
                Ok(n) => {
                    let new_size = inode.size;
                    with_current_fd_mut(fd, |slot| {
                        if let Some(e) = slot
                            && let FdBackend::Ext2Disk {
                                file_size: ref mut fs,
                                ..
                            } = e.backend
                        {
                            *fs = new_size;
                        }
                    });
                    Ok(n)
                }
                Err(_) => Err(NEG_EIO as i64),
            }
        }
        FdBackend::Fat32Disk {
            start_cluster,
            file_size,
            dir_cluster,
            path,
        } => {
            let start_cluster = *start_cluster;
            let current_file_size = *file_size as usize;
            let dir_cluster = *dir_cluster;
            let path = path.clone();
            let mut vol = crate::fs::fat32::FAT32_VOLUME.lock();
            let Some(vol) = vol.as_mut() else {
                return Err(NEG_EIO as i64);
            };
            match vol.write_file(start_cluster, offset, buf, current_file_size) {
                Ok((new_start, new_size)) => {
                    let file_name = path.rsplit('/').next().unwrap_or(&path);
                    if vol
                        .update_dir_entry(dir_cluster, file_name, new_start, new_size as u32)
                        .is_err()
                    {
                        return Err(NEG_EIO as i64);
                    }
                    with_current_fd_mut(fd, |slot| {
                        if let Some(e) = slot
                            && let FdBackend::Fat32Disk {
                                start_cluster: ref mut sc,
                                file_size: ref mut fs,
                                ..
                            } = e.backend
                        {
                            *sc = new_start;
                            *fs = new_size as u32;
                        }
                    });
                    Ok(buf.len())
                }
                Err(_) => Err(NEG_EIO as i64),
            }
        }
        // POSIX pwrite on a non-seekable fd (pipe/FIFO/socket/tty) → ESPIPE.
        _ => Err(NEG_ESPIPE as i64),
    }
}

pub(super) fn sys_linux_mmap(addr_hint: u64, len: u64, prot: u64) -> u64 {
    // Read flags from SYSCALL_ARG3 (r10 at syscall entry).
    // SAFETY: single-CPU, read after every SYSCALL entry stores to SYSCALL_ARG3.
    let flags = per_core_syscall_arg3();

    const MAP_PRIVATE: u64 = 0x02;
    const MAP_ANONYMOUS: u64 = 0x20;
    // MAP_FIXED — Go's allocator (runtime/mem_linux.go) reserves an arena
    // PROT_NONE, then commits it PROT_RW with MAP_FIXED at the *same* address
    // and throws ("cannot map pages in arena address space") if the kernel
    // relocates the mapping. Capture the bit from the raw flags before the
    // mask below drops it (Phase 86d, Track A — hard blocker 1).
    const MAP_FIXED: u64 = 0x10;
    let map_fixed = flags & MAP_FIXED != 0;

    // Mask prot to supported bits only.
    const PROT_MASK: u64 = 0x7; // PROT_READ | PROT_WRITE | PROT_EXEC
    let prot = prot & PROT_MASK;

    // W^X enforcement (C.1 contract clause 1): `mmap` carries no pkey argument
    // (there is no `pkey_mmap` — the JIT/V8 contract is mmap-then-pkey_mprotect,
    // never mmap-W+X), so a plain mmap is the key-0 / non-`Tag` case of the
    // canonical `wx_decision` rule, which rejects W+X. Reject here BEFORE any
    // file-backed dispatch, MAP_FIXED handling, or VMA recording, so a W+X prot
    // can never demand-fault into a live unguarded W+X PTE tagged key 0. Return
    // the identical errno `sys_mprotect`/`mprotect_worker` returns for W+X
    // (`NEG_EINVAL`, -22). Covers anon/file/hint/MAP_FIXED uniformly.
    const PROT_WRITE: u64 = 0x2;
    const PROT_EXEC: u64 = 0x4;
    if prot & PROT_WRITE != 0 && prot & PROT_EXEC != 0 {
        return NEG_EINVAL;
    }

    if flags & MAP_ANONYMOUS == 0 {
        // File-backed mmap — Strategy A (eager loading).
        let fd = per_core_syscall_user_r8() as usize;
        let file_offset = per_core_syscall_user_r9() as usize;
        return sys_mmap_file_backed(addr_hint, len, prot, flags, fd, file_offset);
    }

    let flags = flags & (MAP_PRIVATE | MAP_ANONYMOUS);

    let len = if len == 0 {
        return NEG_EINVAL;
    } else {
        len
    };
    let pages = len.div_ceil(4096);

    let pid = crate::process::current_pid();

    let total_size = match pages.checked_mul(4096) {
        Some(s) => s,
        None => return NEG_EINVAL,
    };

    // MAP_FIXED — honor the *exact* requested address. This is the Go
    // arena-commit contract: a prior PROT_NONE reservation is committed
    // PROT_RW in place at the address the kernel handed back, and Go aborts
    // if the returned address differs. Overwrite/split whatever currently
    // occupies the range and return `addr_hint` unchanged.
    if map_fixed {
        const USER_SPACE_END: u64 = 0x0000_8000_0000_0000;
        // mmap_min_addr floor (Linux default): never honor a fixed mapping over
        // the low NULL-guard pages, so a fixed request can't defeat the
        // null-pointer-deref trap. Go's arena hints start ~0xc000000000, well
        // above this. (Phase 86d Track A reviewer follow-up.)
        const MMAP_MIN_ADDR: u64 = 0x1_0000;
        // The address must be page-aligned and the whole range must stay in
        // canonical user space (~0xc000000000 fits well under USER_SPACE_END).
        if addr_hint < MMAP_MIN_ADDR
            || addr_hint & 0xFFF != 0
            || addr_hint
                .checked_add(total_size)
                .filter(|e| *e <= USER_SPACE_END)
                .is_none()
        {
            return NEG_EINVAL;
        }
        // Clear whatever occupies [addr_hint, addr_hint+total_size): frees any
        // committed frames, removes/splits the overlapping VMAs — neighbor VMAs
        // outside the range are preserved by `VmaTree::remove_range` — and
        // batches a TLB shootdown. For a PROT_NONE reservation this finds no
        // mapped frames and is a cheap no-op that still drops the reservation
        // VMA, so the insert below replaces it cleanly.
        let _ = sys_linux_munmap(addr_hint, total_size);
        // Record the committed VMA at the exact address; demand paging fills
        // frames on first touch with the requested protection.
        let _ = crate::process::with_shared_mm_mut(pid, |_brk_current, _mmap_next, vma_tree| {
            vma_tree.insert(crate::process::MemoryMapping {
                start: addr_hint,
                len: total_size,
                prot,
                flags,
                file_backing: None,                    // anonymous mapping
                pkey: kernel_core::pkey::PKEY_DEFAULT, // tagged later by pkey_mprotect, if at all
            });
        });
        let table = crate::process::PROCESS_TABLE.lock();
        if let Some(proc) = table.find(pid)
            && let Some(ref addr_space) = proc.addr_space
        {
            addr_space.bump_generation();
        }
        return addr_hint;
    }

    // Hint address is ignored for non-fixed mappings: always allocate linearly.
    let _ = addr_hint;
    // Determine base address: use process mmap_next or default ANON_MMAP_BASE.
    const USER_SPACE_END: u64 = 0x0000_8000_0000_0000;
    let base =
        match crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
            let current = if *mmap_next == 0 {
                ANON_MMAP_BASE
            } else {
                *mmap_next
            };
            let next = current
                .checked_add(total_size)
                .filter(|v| *v <= USER_SPACE_END)?;
            *mmap_next = next;
            Some(current)
        }) {
            Some(Some(base)) => base,
            _ => return NEG_EINVAL,
        };

    // Validate that the entire range fits in canonical user space (< 0x0000_8000_0000_0000).
    let range_end = match base.checked_add(total_size) {
        Some(e) => e,
        None => return NEG_EINVAL,
    };
    if range_end > USER_SPACE_END {
        return NEG_EINVAL;
    }

    // Phase 36: demand paging — do NOT allocate physical frames here.
    // Pages are mapped lazily by the page fault handler on first access.
    // Only record the VMA with protection and flags metadata.

    // Record the mapping in the process's tracking list.
    {
        let _ = crate::process::with_shared_mm_mut(pid, |_brk_current, _mmap_next, vma_tree| {
            vma_tree.insert(crate::process::MemoryMapping {
                start: base,
                len: total_size,
                prot,
                flags,
                file_backing: None, // anonymous (demand-paged) mapping
                pkey: kernel_core::pkey::PKEY_DEFAULT, // tagged later by pkey_mprotect, if at all
            });
        });
        // Phase 52d B.3: bump generation — the address space changed
        // (new VMA, pages will be demand-faulted).
        let table = crate::process::PROCESS_TABLE.lock();
        if let Some(proc) = table.find(pid)
            && let Some(ref addr_space) = proc.addr_space
        {
            addr_space.bump_generation();
        }
    }

    base
}

// ---------------------------------------------------------------------------
// File-backed mmap — Strategy A: eager loading.
//
// Allocates physical frames, reads the file data into them, maps them into
// the process page table, and records a VMA entry.  munmap/process teardown
// will free the frames via the normal frame-allocator path.
// ---------------------------------------------------------------------------

fn sys_mmap_file_backed(
    addr_hint: u64,
    len: u64,
    prot: u64,
    flags: u64,
    fd: usize,
    file_offset: usize,
) -> u64 {
    if len == 0 || fd >= crate::process::MAX_FDS {
        return NEG_EINVAL;
    }
    // POSIX mmap(2): the file offset must be a multiple of the page size.
    // A misaligned offset would make both the per-page read offsets
    // (`file_offset + i*4096`) and the `FileBacking` write-back offset
    // ill-defined, so reject it up front like Linux/x86_64 does.
    if file_offset & 0xFFF != 0 {
        return NEG_EINVAL;
    }

    const PROT_WRITE: u64 = 0x2;
    const PROT_EXEC: u64 = 0x4;

    // W^X enforcement (C.1 contract clause 1): a file-backed `mmap` carries no
    // pkey argument, so it is the key-0 / non-`Tag` case of the canonical
    // `wx_decision` rule, which rejects W+X. This path maps eagerly, so a W+X
    // prot would compose a live unguarded W+X PTE tagged key 0 below. Reject
    // here BEFORE any allocation or mapping, with the identical errno
    // `sys_mprotect`/`mprotect_worker` returns for W+X (`NEG_EINVAL`, -22).
    // (`sys_linux_mmap` also rejects this before dispatch; this is the in-function
    // guard for the contract's named entry point.)
    if prot & PROT_WRITE != 0 && prot & PROT_EXEC != 0 {
        return NEG_EINVAL;
    }

    let pages = len.div_ceil(4096);
    let total_size = match pages.checked_mul(4096) {
        Some(s) => s,
        None => return NEG_EINVAL,
    };
    if total_size > 0x0000_8000_0000_0000 {
        return NEG_EINVAL;
    }

    // Phase 95b (Area A.2) — lazy, demand-paged file-backed mapping. The ld-musl
    // loader sets `MAP_LAZY_FILE` on each `PT_LOAD` and keeps the fd open;
    // install a VMA recording `(fd, file_offset)` and allocate NO frames. The
    // page-fault handler then reads a faulting page straight from the file
    // (`kernel_read_fd_at`, which now handles `VfsService`/ext2/ramdisk) on first
    // touch — turning a 162 MB eager load into the small working set actually
    // executed. A plain `MAP_PRIVATE` file mmap (no `MAP_LAZY_FILE`) keeps the
    // eager path below, preserving POSIX mmap-then-close for callers like `lld`.
    {
        const MAP_PRIVATE: u64 = 0x02;
        const MAP_FIXED: u64 = 0x10;
        const USER_SPACE_END: u64 = 0x0000_8000_0000_0000;
        if flags & kernel_core::mm::MAP_LAZY_FILE != 0 {
            let pid = crate::process::current_pid();
            // Stored VMA flags: MAP_PRIVATE + the lazy marker (MAP_FIXED is a
            // placement directive, not a property of the resulting mapping).
            let vma_flags = (flags & MAP_PRIVATE) | kernel_core::mm::MAP_LAZY_FILE;
            let file_backing = Some(crate::process::FileBacking {
                fd: fd as u32,
                offset: file_offset as u64,
            });

            let base = if flags & MAP_FIXED != 0 {
                const MMAP_MIN_ADDR: u64 = 0x1_0000;
                if addr_hint < MMAP_MIN_ADDR
                    || addr_hint & 0xFFF != 0
                    || addr_hint
                        .checked_add(total_size)
                        .filter(|e| *e <= USER_SPACE_END)
                        .is_none()
                {
                    return NEG_EINVAL;
                }
                // Replace whatever occupies [addr_hint, addr_hint+total_size) —
                // the loader's PROT_NONE span reservation, split by remove_range
                // — then record the lazy VMA at the exact requested address.
                let _ = sys_linux_munmap(addr_hint, total_size);
                addr_hint
            } else {
                match crate::process::with_shared_mm_mut(pid, |_b, mmap_next, _v| {
                    let current = if *mmap_next == 0 {
                        ANON_MMAP_BASE
                    } else {
                        *mmap_next
                    };
                    let end = current
                        .checked_add(total_size)
                        .filter(|v| *v <= USER_SPACE_END)?;
                    *mmap_next = end;
                    Some(current)
                }) {
                    Some(Some(b)) => b,
                    _ => return NEG_EINVAL,
                }
            };

            let _ = crate::process::with_shared_mm_mut(pid, |_b, _m, vma_tree| {
                vma_tree.insert(crate::process::MemoryMapping {
                    start: base,
                    len: total_size,
                    prot,
                    flags: vma_flags,
                    file_backing,
                    pkey: kernel_core::pkey::PKEY_DEFAULT,
                });
            });
            if let Some(addr_space) = {
                let table = crate::process::PROCESS_TABLE.lock();
                table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
            } {
                addr_space.bump_generation();
            }
            return base;
        }
    }

    use x86_64::structures::paging::{PageTableFlags, PhysFrame, Size4KiB};

    let mut pt_flags = PageTableFlags::PRESENT | PageTableFlags::USER_ACCESSIBLE;
    if prot & PROT_WRITE != 0 {
        pt_flags |= PageTableFlags::WRITABLE;
    }
    if prot & PROT_EXEC == 0 {
        pt_flags |= PageTableFlags::NO_EXECUTE;
    }

    let pid = crate::process::current_pid();
    let phys_off = crate::mm::phys_offset();
    let addr_space = {
        let table = crate::process::PROCESS_TABLE.lock();
        table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
    };
    // Phase 57e Bug #9 — split the lifecycle so `lock_page_tables()` is held
    // only across the page-table mutation, never across `kernel_read_fd_at`.
    // The previous code held the guard for the entire alloc+read+map loop;
    // each call to `kernel_read_fd_at` for a Fat32/Ext2 fd descends into
    // `virtio_blk::do_request` → `block_current_until`, which switches out
    // the task with `preempt_count >= 1` (the guard's +1).  When the task
    // resumes, `block_current_until`'s post-resume `preempt_enable` only
    // returns count to 1 — the guard's +1 persists.  The IRQ-side preempt
    // gate (`peek_preempt_count_irq`) reads non-zero and refuses to preempt,
    // so the running task monopolises its core for the entire syscall while
    // co-resident Ready tasks starve.  See
    // `docs/handoffs/57e-preempt-full-userspace-hangs.md` Sessions 13–14.

    // Claim a virtual address range — uses the shared-mm lock, not the
    // page-table lock, so no preempt_disable is needed here.
    let base =
        match crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
            let current = if *mmap_next == 0 {
                ANON_MMAP_BASE
            } else {
                *mmap_next
            };
            let end = current
                .checked_add(total_size)
                .filter(|v| *v <= 0x0000_8000_0000_0000)?;
            *mmap_next = end;
            Some(current)
        }) {
            Some(Some(base)) => base,
            _ => return NEG_EINVAL,
        };
    let reservation_end = base + total_size;

    // Get the process CR3 for the mapper.
    let cr3_phys = match addr_space.as_ref().map(|a| a.pml4_phys()) {
        Some(phys) => phys,
        None => {
            let _ =
                crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
                    if *mmap_next == reservation_end {
                        *mmap_next = base;
                    }
                });
            return NEG_EINVAL;
        }
    };
    let cr3_frame = match PhysFrame::<Size4KiB>::from_start_address(cr3_phys) {
        Ok(f) => f,
        Err(_) => {
            let _ =
                crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
                    if *mmap_next == reservation_end {
                        *mmap_next = base;
                    }
                });
            return NEG_EINVAL;
        }
    };

    // Allocate frames and fill from file — NO page-table lock held.  The
    // file read may block in virtio_blk for tens of ms per page; holding
    // the page-table lock across that block is what caused Bug #9.
    let mut mapped_frames: alloc::vec::Vec<PhysFrame<Size4KiB>> = alloc::vec::Vec::new();
    let mut page_buf = alloc::vec![0u8; 4096];

    for i in 0..pages {
        // Zero-before-exposure (D.4): user-visible mmap frame.
        let frame = match crate::mm::frame_allocator::allocate_frame_zeroed() {
            Some(f) => f,
            None => {
                log::warn!("[mmap_file] OOM at page {}/{}", i, pages);
                for f in &mapped_frames {
                    crate::mm::frame_allocator::free_frame(f.start_address().as_u64());
                }
                let _ = crate::process::with_shared_mm_mut(
                    pid,
                    |_brk_current, mmap_next, _vma_tree| {
                        if *mmap_next == reservation_end {
                            *mmap_next = base;
                        }
                    },
                );
                return NEG_ENOMEM;
            }
        };

        // Frame is pre-zeroed by allocate_frame_zeroed (D.4); fill from file.
        let frame_ptr = (phys_off + frame.start_address().as_u64()) as *mut u8;

        // Same unbounded-user-`file_offset` overflow guard as the lazy
        // demand-fault path (`shared_vma_demand_file`): a near-`usize::MAX`
        // page-aligned mmap offset would wrap `file_offset + i*4096` (release
        // build, no panic). Treat overflow as a past-EOF page and leave the
        // already-zeroed frame — never read a wrapped/aliased file region.
        // (`i*4096 < total_size <= 2^47`, so only the outer add can overflow.)
        let Some(read_offset) = file_offset.checked_add((i as usize) * 4096) else {
            mapped_frames.push(frame);
            continue;
        };
        match kernel_read_fd_at(pid, fd, read_offset, &mut page_buf) {
            Ok(n) if n > 0 => unsafe {
                core::ptr::copy_nonoverlapping(page_buf.as_ptr(), frame_ptr, n);
            },
            Ok(_) => {} // EOF or past-end page — leave zeroed
            Err(e) => {
                // I/O error — clean up and abort.
                crate::mm::frame_allocator::free_frame(frame.start_address().as_u64());
                for f in &mapped_frames {
                    crate::mm::frame_allocator::free_frame(f.start_address().as_u64());
                }
                let _ = crate::process::with_shared_mm_mut(
                    pid,
                    |_brk_current, mmap_next, _vma_tree| {
                        if *mmap_next == reservation_end {
                            *mmap_next = base;
                        }
                    },
                );
                return e as u64;
            }
        }

        mapped_frames.push(frame);
    }

    // Map all frames into the process page table — guard held only here.
    let map_failed = {
        let _page_table_guard = addr_space
            .as_ref()
            .map(|addr_space| addr_space.lock_page_tables());

        let mut mapper = unsafe { crate::mm::mapper_for_frame(cr3_frame) };
        unsafe {
            crate::mm::user_space::map_user_frames(&mut mapper, base, &mapped_frames, pt_flags)
        }
        .is_err()
    };
    if map_failed {
        for f in &mapped_frames {
            crate::mm::frame_allocator::free_frame(f.start_address().as_u64());
        }
        let _ = crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
            if *mmap_next == reservation_end {
                *mmap_next = base;
            }
        });
        return NEG_EINVAL;
    }

    // Phase 88 follow-up — record file write-back info for a MAP_SHARED writable
    // file mapping so munmap/msync flush the dirty pages back to the file. m3OS
    // eager-loads file mmaps into anonymous frames, so without this the writes
    // are lost (which left `lld`'s mmap'd output all-zeros → `InvalidMagic`).
    // MAP_PRIVATE / read-only mappings are never written back.
    const MAP_SHARED: u64 = 0x1;
    let file_backing = if prot & PROT_WRITE != 0 && flags & MAP_SHARED != 0 {
        Some(crate::process::FileBacking {
            fd: fd as u32,
            offset: file_offset as u64,
        })
    } else {
        None
    };

    // Record the VMA — uses the shared-mm lock, independent of the
    // page-table lock.  Order (PT mutation before VMA insert) is preserved
    // from the original code.
    let _ = crate::process::with_shared_mm_mut(pid, |_brk_current, _mmap_next, vma_tree| {
        vma_tree.insert(crate::process::MemoryMapping {
            start: base,
            len: total_size,
            prot,
            flags,
            file_backing,
            pkey: kernel_core::pkey::PKEY_DEFAULT, // eager file-backed; retagged by pkey_mprotect, if at all
        });
    });
    if let Some(addr_space) = addr_space.as_ref() {
        crate::smp::tlb::tlb_shootdown_range(addr_space, base, base + total_size);
        addr_space.bump_generation();
    }

    log::info!(
        "[mmap_file] fd={} off={} {}×4K @ {:#x}",
        fd,
        file_offset,
        pages,
        base
    );
    base
}

pub(super) fn sys_linux_munmap(addr: u64, len: u64) -> u64 {
    // Validate: page-aligned address and non-zero length.
    if addr & 0xFFF != 0 || len == 0 {
        return NEG_EINVAL;
    }

    // Must be in userspace canonical range.
    if addr >= 0x0000_8000_0000_0000 {
        return NEG_EINVAL;
    }

    let pages = len.div_ceil(4096) as usize;

    // Validate range doesn't overflow.
    let total_size = match (pages as u64).checked_mul(4096) {
        Some(s) => s,
        None => return NEG_EINVAL,
    };
    if addr.checked_add(total_size).is_none() {
        return NEG_EINVAL;
    }

    use x86_64::registers::control::Cr3;
    use x86_64::structures::paging::{Mapper, Page, PageTable, PageTableFlags, Size4KiB};
    let pid = crate::process::current_pid();
    let addr_space = {
        let table = crate::process::PROCESS_TABLE.lock();
        table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
    };

    let mut unmapped_addrs: alloc::vec::Vec<u64> = alloc::vec::Vec::new();
    let mut frames_to_free: alloc::vec::Vec<u64> = alloc::vec::Vec::new();
    let mut fb_fully_unmapped = false;
    let mut vma_changed = false;

    // Phase 88 follow-up — snapshot file-backed MAP_SHARED writable VMAs that
    // overlap the unmapped range, so each page's dirty contents can be written
    // back to the file before its frame is freed. Empty for the common case
    // (anonymous mappings), which keeps the unmap path unchanged.
    let writeback_vmas: alloc::vec::Vec<(u64, u64, u32, u64)> = // (start, end, fd, file_offset)
        crate::process::with_shared_mm_mut(pid, |_b, _m, vma_tree| {
            vma_tree
                .iter()
                .filter_map(|m| {
                    m.file_backing
                        .filter(|_| m.start < addr + total_size && addr < m.start + m.len)
                        .map(|fb| (m.start, m.start + m.len, fb.fd, fb.offset))
                })
                .collect()
        })
        .unwrap_or_default();
    // (frame_phys, fd, file_offset) for each unmapped page of a writable file VMA.
    let mut writeback: alloc::vec::Vec<(u64, u32, u64)> = alloc::vec::Vec::new();

    {
        // SAFETY: current CR3 is the calling process's page table; this is the
        // same approach used by sys_linux_mmap.
        let mut mapper = unsafe { crate::mm::paging::get_mapper() };
        let _page_table_guard = addr_space
            .as_ref()
            .map(|addr_space| addr_space.lock_page_tables());

        for i in 0..pages {
            let page_addr = addr + (i as u64 * 4096);
            let page: Page<Size4KiB> = Page::containing_address(x86_64::VirtAddr::new(page_addr));

            let guard_frame = unsafe {
                let phys_off = crate::mm::phys_offset();
                let phys_offset_va = x86_64::VirtAddr::new(phys_off);
                let (cr3_frame, _) = Cr3::read();
                let pml4_phys = cr3_frame.start_address().as_u64();

                let p4_idx = ((page_addr >> 39) & 0x1FF) as usize;
                let p3_idx = ((page_addr >> 30) & 0x1FF) as usize;
                let p2_idx = ((page_addr >> 21) & 0x1FF) as usize;
                let p1_idx = ((page_addr >> 12) & 0x1FF) as usize;

                let pml4: &mut PageTable =
                    &mut *(phys_offset_va + pml4_phys).as_mut_ptr::<PageTable>();
                if !pml4[p4_idx].flags().contains(PageTableFlags::PRESENT) {
                    None
                } else {
                    let pdpt: &mut PageTable = &mut *(phys_offset_va
                        + pml4[p4_idx].addr().as_u64())
                    .as_mut_ptr::<PageTable>();
                    if !pdpt[p3_idx].flags().contains(PageTableFlags::PRESENT) {
                        None
                    } else {
                        let pd: &mut PageTable = &mut *(phys_offset_va
                            + pdpt[p3_idx].addr().as_u64())
                        .as_mut_ptr::<PageTable>();
                        if !pd[p2_idx].flags().contains(PageTableFlags::PRESENT) {
                            None
                        } else {
                            let pt: &mut PageTable = &mut *(phys_offset_va
                                + pd[p2_idx].addr().as_u64())
                            .as_mut_ptr::<PageTable>();
                            let flags = pt[p1_idx].flags();
                            if flags.contains(PageTableFlags::BIT_10)
                                && !flags.contains(PageTableFlags::PRESENT)
                            {
                                let frame_phys = pt[p1_idx].addr().as_u64();
                                pt[p1_idx].set_unused();
                                Some((frame_phys, flags.contains(PageTableFlags::BIT_11)))
                            } else {
                                None
                            }
                        }
                    }
                }
            };
            if let Some((frame_phys, is_device_frame)) = guard_frame {
                if !is_device_frame {
                    frames_to_free.push(frame_phys);
                }
                unmapped_addrs.push(page_addr);
                continue;
            }

            // Read PTE flags *before* unmapping to detect device-mapped pages.
            // BIT_11 marks MMIO / hardware frames (e.g. UEFI framebuffer) that are
            // not owned by the frame allocator and must not be freed.
            let is_device_frame = {
                use x86_64::structures::paging::Translate as _;
                use x86_64::structures::paging::mapper::TranslateResult;
                match mapper.translate(x86_64::VirtAddr::new(page_addr)) {
                    TranslateResult::Mapped { flags, .. } => flags.contains(PageTableFlags::BIT_11),
                    _ => false,
                }
            };

            // Try to unmap — silently skip pages that aren't mapped (POSIX allows this).
            match mapper.unmap(page) {
                Ok((frame, flush)) => {
                    // Skip the local TLB flush here — we batch a single shootdown
                    // (which includes a local invlpg) after the loop.
                    flush.ignore();
                    let frame_phys = frame.start_address().as_u64();
                    if !is_device_frame {
                        // Only return system-RAM frames to the allocator after the
                        // batched shootdown has invalidated every stale translation.
                        frames_to_free.push(frame_phys);
                    }
                    // Phase 88 follow-up — queue this page for write-back if it
                    // belongs to a file-backed MAP_SHARED writable mapping.
                    if !writeback_vmas.is_empty() {
                        for &(vs, ve, fd, foff) in &writeback_vmas {
                            if page_addr >= vs && page_addr < ve {
                                writeback.push((frame_phys, fd, foff + (page_addr - vs)));
                                break;
                            }
                        }
                    }
                    unmapped_addrs.push(page_addr);
                }
                Err(_) => {
                    // Page wasn't mapped — skip silently.
                }
            }
        }

        // Update VMA tree: handle full removal, shrink, and split.
        if let Some((changed, fb_gone)) =
            crate::process::with_shared_mm_mut(pid, |_brk_current, _mmap_next, vma_tree| {
                let removed = vma_tree.remove_range(addr, total_size);
                let changed = !removed.is_empty();
                let fb_gone = !vma_tree.any(|m| m.flags & FB_MAPPING_FLAG != 0);
                (changed, fb_gone)
            })
        {
            vma_changed = changed;
            fb_fully_unmapped = fb_gone;
        }
    }
    let freed_count = unmapped_addrs.len();

    // SMP TLB shootdown: batch invalidation for the entire unmapped range.
    // Phase 25 P25-T033 closure (verified Phase 61 C.1): this call wires
    // tlb_shootdown_range into sys_linux_munmap; the per-page unmap loop above
    // defers its local TLB flush (`flush.ignore()`) so the entire range is
    // invalidated in a single batched IPI here. Cross-core regression test:
    // kernel/tests/munmap_tlb_smp.rs.
    if !unmapped_addrs.is_empty() {
        let range_start = *unmapped_addrs.iter().min().unwrap();
        let range_end = *unmapped_addrs.iter().max().unwrap() + 4096;
        if let Some(addr_space) = addr_space.as_ref() {
            crate::smp::tlb::tlb_shootdown_range(addr_space, range_start, range_end);
        }
    }
    // Phase 88 follow-up — write file-backed MAP_SHARED writable mappings back to
    // the file BEFORE the frames are freed. There is no per-page dirty-bit
    // tracking: EVERY unmapped page of such a mapping is written back (correct, if
    // conservative — a never-written page just rewrites identical bytes). Runs
    // after the page-table guard is released (kernel_write_fd_at may block on
    // disk; holding the guard across a block is the Bug #9 hazard) and reads each
    // frame physically through the phys-offset window (the unmapped vaddr is gone,
    // but the frame is still allocated). The fd must still be open + writable —
    // the common mmap/write/munmap/close order — else the write-back is skipped.
    if !writeback.is_empty() {
        let phys_off = crate::mm::phys_offset();
        let mut page_buf = alloc::vec![0u8; 4096];
        for (frame_phys, fd, file_off) in writeback {
            // SAFETY: frame_phys is an allocated user mmap frame (not yet freed);
            // read its 4096 bytes through the kernel's phys-offset window.
            unsafe {
                core::ptr::copy_nonoverlapping(
                    (phys_off + frame_phys) as *const u8,
                    page_buf.as_mut_ptr(),
                    4096,
                );
            }
            let _ = kernel_write_fd_at(pid, fd as usize, file_off as usize, &page_buf);
        }
    }

    for frame_phys in frames_to_free {
        crate::mm::frame_allocator::free_frame(frame_phys);
    }
    if (!unmapped_addrs.is_empty() || vma_changed)
        && let Some(addr_space) = addr_space.as_ref()
    {
        addr_space.bump_generation();
    }

    if freed_count > 0 {
        log::debug!(
            "[munmap] freed {} pages @ {:#x} (len={:#x})",
            freed_count,
            addr,
            len
        );
    }

    // Restore text-console ownership whenever the current process no longer has
    // any framebuffer mappings. That lifecycle is separate from whether this
    // particular munmap call tore down device-backed pages.
    if fb_fully_unmapped && crate::fb::fb_owner_pid() == pid {
        crate::fb::restore_console();
    }

    0
}

// ---------------------------------------------------------------------------
// Phase 93 Track C.1 — mremap(old_addr, old_size, new_size, flags[, new_addr])
//
// Implements the Linux mremap(2) ABI (syscall 25) for the Dynamic C Runtime
// phase. musl's realloc uses mremap to resize large anonymous allocations
// (those originally obtained via mmap) in place or, when the region cannot
// grow in place, by moving the mapping.
//
// Supported flag combinations:
//   0                 — shrink or grow in place only; ENOMEM if blocked.
//   MREMAP_MAYMOVE    — as above, but also permit relocation on grow failure.
//   MREMAP_FIXED      — REJECTED (EINVAL): musl's realloc never uses it;
//                       implementing it would require a 5th syscall argument
//                       and an atomic swap that is not needed for Phase 93.
// ---------------------------------------------------------------------------

/// `mremap(old_addr, old_size, new_size, flags)` — Phase 93 Track C.1.
///
/// Resizes an anonymous anonymous VMA.  For the Dynamic C Runtime the only
/// caller that matters is musl's `__expand_heap` → `mremap` path, which is
/// always an anonymous in-place grow or move; file-backed regions and
/// MREMAP_FIXED are rejected.
pub(super) fn sys_mremap(old_addr: u64, old_size: u64, new_size: u64, flags: u64) -> u64 {
    // Linux flag constants (mremap(2)).
    const MREMAP_MAYMOVE: u64 = 1;
    const MREMAP_FIXED: u64 = 2;

    // --- C.1 step 1: validate arguments ---

    // MREMAP_FIXED is not supported: we do not consume the 5th syscall arg
    // (new_address, in r8) and musl's realloc never sets this flag.
    if flags & MREMAP_FIXED != 0 {
        return NEG_EINVAL;
    }

    // old_addr must be page-aligned.
    if old_addr & 0xFFF != 0 {
        return NEG_EINVAL;
    }

    // Both sizes must be non-zero (Linux mremap rejects them too).
    if old_size == 0 || new_size == 0 {
        return NEG_EINVAL;
    }

    // Page-align both sizes upward (mirrors Linux behaviour and sys_linux_mmap).
    // Use checked arithmetic — matching sys_linux_mmap/sys_linux_munmap — so a
    // pathological near-`u64::MAX` size returns a clean EINVAL instead of
    // wrapping the rounded product to 0 (which would otherwise survive the
    // `new_size == 0` reject above and silently full-unmap the mapping).
    let new_size = match new_size.div_ceil(4096).checked_mul(4096) {
        Some(s) => s,
        None => return NEG_EINVAL,
    };
    let old_size_aligned = match old_size.div_ceil(4096).checked_mul(4096) {
        Some(s) => s,
        None => return NEG_EINVAL,
    };

    const USER_SPACE_END: u64 = 0x0000_8000_0000_0000;
    const MMAP_MIN_ADDR: u64 = 0x1_0000;

    if !(MMAP_MIN_ADDR..USER_SPACE_END).contains(&old_addr) {
        return NEG_EINVAL;
    }
    // The old range must fit in canonical user space.
    if old_addr
        .checked_add(old_size_aligned)
        .filter(|e| *e <= USER_SPACE_END)
        .is_none()
    {
        return NEG_EINVAL;
    }

    let pid = crate::process::current_pid();

    // --- C.1 step 2: locate the covering VMA ---
    //
    // We need:
    //  (a) old_addr is the START of an existing VMA.
    //  (b) The VMA fully covers [old_addr, old_addr + old_size_aligned).
    //  (c) The VMA is anonymous (file_backing.is_none()) — file-backed mremap
    //      would need write-back coherence beyond Phase 93 scope; reject it.
    //
    // Capture VMA metadata before the mutable borrow below.
    let vma_info = crate::process::with_shared_mm_mut(pid, |_b, _m, vma_tree| {
        vma_tree.find_containing(old_addr).and_then(|vma| {
            // Linux mremap requires old_addr be the start of an existing
            // mapping. Our grow-in-place path keys on `vma_tree.remove(old_addr)`
            // and the MAYMOVE/shrink paths assume the located VMA begins at
            // old_addr; if old_addr pointed into the middle of a mapping,
            // `remove(old_addr)` would be a no-op and we could insert an
            // overlapping VMA, corrupting the VMA tree. Reject EINVAL.
            if vma.start != old_addr {
                return None;
            }
            // Linux mremap's `old_size` must describe the WHOLE mapping, not a
            // sub-range. Require an exact length match (`vma.start == old_addr`
            // is already enforced above, and both lengths are page-aligned):
            //
            //  * The MAYMOVE path copies/unmaps only `old_size_aligned` bytes, so
            //    a VMA longer than old_size would leak its tail — [old_addr +
            //    old_size_aligned, vma_end) stays mapped while the caller is
            //    handed a new base as if the whole region had moved.
            //  * The in-place-grow free-space probe keys on `grow_start =
            //    old_addr + old_size_aligned`; if the VMA extended past that it
            //    would overlap its OWN grow window, so the probe would always
            //    (wrongly) report "not free" and force a needless move.
            //
            // The only Phase 93 caller (musl's realloc) always passes the full
            // mapping length, so rejecting the sub-range case with EINVAL — like
            // the mid-VMA old_addr, file-backed, and MREMAP_FIXED rejects — is the
            // correct fail-closed behaviour.
            if vma.len != old_size_aligned {
                return None;
            }
            // File-backed mremap is not implemented in Phase 93.
            if vma.file_backing.is_some() {
                return None;
            }
            Some((vma.prot, vma.flags, vma.pkey))
        })
    });

    let (vma_prot, vma_flags, vma_pkey) = match vma_info {
        Some(Some(info)) => info,
        Some(None) => return NEG_EINVAL,
        None => return NEG_EINVAL, // process gone
    };

    // --- C.1 step 3: no-op case ---
    if new_size == old_size_aligned {
        return old_addr;
    }

    // --- C.1 step 4: shrink (new_size < old_size_aligned) ---
    //
    // Unmap the tail [old_addr+new_size, old_addr+old_size_aligned).
    // sys_linux_munmap handles the PTE clear, frame free, VMA split, and TLB
    // shootdown, so we reuse it directly — no duplication.
    if new_size < old_size_aligned {
        let tail_start = old_addr + new_size;
        let tail_len = old_size_aligned - new_size;
        let ret = sys_linux_munmap(tail_start, tail_len);
        if ret != 0 {
            // munmap failed — propagate errno.
            return ret;
        }
        // Update the VMA to reflect the shrunk length (remove_range inside
        // munmap already split or removed the tail, but the head VMA entry
        // that covers [old_addr, old_addr+new_size) was left with its original
        // length if the tail was a suffix split.  Re-insert with correct len.
        let _ = crate::process::with_shared_mm_mut(pid, |_b, _m, vma_tree| {
            // After munmap the VMA starting at old_addr should already be
            // trimmed by remove_range (partial right-overlap path), but if
            // old_addr was exactly the VMA start we may need to re-normalise.
            // find_containing returns it; if its len already matches new_size
            // no update is needed.
            if let Some(vma) = vma_tree.find_containing(old_addr)
                && vma.start == old_addr
                && vma.len != new_size
            {
                let mut updated = vma.clone();
                updated.len = new_size;
                vma_tree.insert(updated);
            }
        });
        return old_addr;
    }

    // --- C.1 step 5 & 6: grow (new_size > old_size_aligned) ---
    //
    // First try in-place extension: check that [old_addr+old_size_aligned,
    // old_addr+new_size) is free (no overlapping VMA).
    let grow_start = old_addr + old_size_aligned;
    let grow_len = new_size - old_size_aligned;

    // Validate the grown range fits in user space.
    if old_addr
        .checked_add(new_size)
        .filter(|e| *e <= USER_SPACE_END)
        .is_none()
    {
        return NEG_ENOMEM;
    }

    let range_is_free = crate::process::with_shared_mm_mut(pid, |_b, _m, vma_tree| {
        // The growth window must not overlap any existing VMA.  A single
        // find_containing check covers point-in-range; for a full range we
        // check the start AND any VMA whose start falls inside the window.
        if vma_tree.find_containing(grow_start).is_some() {
            return false;
        }
        // Also check whether any VMA starts inside (grow_start, grow_start+grow_len).
        vma_tree.iter().all(|m| {
            // VMA overlaps [grow_start, grow_start+grow_len) iff:
            //   m.start < grow_start+grow_len  AND  m.start+m.len > grow_start
            let m_end = m.start.saturating_add(m.len);
            !(m.start < grow_start.saturating_add(grow_len) && m_end > grow_start)
        })
    })
    .unwrap_or(false);

    if range_is_free {
        // Grow in place: remove the old VMA and insert a new one covering the
        // full new_size.  Anonymous pages are demand-faulted, so no frames need
        // to be allocated for the extension — the page fault handler will do it
        // on first access, just as for a fresh mmap.
        let _ = crate::process::with_shared_mm_mut(pid, |_b, mmap_next, vma_tree| {
            // Remove the old entry (keyed by old_addr) and insert the grown one.
            vma_tree.remove(old_addr);
            vma_tree.insert(crate::process::MemoryMapping {
                start: old_addr,
                len: new_size,
                prot: vma_prot,
                flags: vma_flags,
                file_backing: None,
                pkey: vma_pkey,
            });
            // Advance the bump pointer past the grown top. The non-fixed mmap
            // allocator is a pure bump over `mmap_next` and never consults the
            // VMA tree for conflicts; if we grew the topmost region (the only
            // case where [old_end, new_end) is actually free) without bumping,
            // `mmap_next` would still point inside the now-larger VMA and the
            // next mmap would be handed an overlapping address. Keep this
            // symmetric with the MAYMOVE path and sys_linux_mmap. `new_size`
            // already fits in user space (checked above), so no overflow.
            let grown_end = old_addr + new_size;
            if *mmap_next < grown_end {
                *mmap_next = grown_end;
            }
        });
        // Bump the address-space generation (new VMA range).
        let table = crate::process::PROCESS_TABLE.lock();
        if let Some(proc) = table.find(pid)
            && let Some(ref addr_space) = proc.addr_space
        {
            addr_space.bump_generation();
        }
        return old_addr;
    }

    // Cannot grow in place.
    if flags & MREMAP_MAYMOVE == 0 {
        // Without MREMAP_MAYMOVE the kernel must return ENOMEM.  musl's
        // realloc falls back to malloc(new_size)+memcpy+free(old_ptr) on
        // ENOMEM — correct-but-slower, never a fault.
        return NEG_ENOMEM;
    }

    // MREMAP_MAYMOVE: allocate a fresh anonymous region of new_size, copy all
    // committed (present) pages from the old range into it, then unmap the old
    // range.  The new region is demand-paged: only pages that were already
    // committed in the old range are eagerly copied; the extension pages are
    // left demand-paged (no frames allocated yet).

    // Allocate a new virtual range via the same bump allocator sys_linux_mmap
    // uses.  We record the VMA entry here and let demand faults fill frames for
    // the extension pages.
    let new_base = match crate::process::with_shared_mm_mut(pid, |_b, mmap_next, _vma_tree| {
        let current = if *mmap_next == 0 {
            ANON_MMAP_BASE
        } else {
            *mmap_next
        };
        let next = current
            .checked_add(new_size)
            .filter(|v| *v <= USER_SPACE_END)?;
        *mmap_next = next;
        Some(current)
    }) {
        Some(Some(base)) => base,
        _ => return NEG_ENOMEM,
    };

    // Copy committed (present) pages from old range → new range.
    //
    // Strategy: walk the old range page by page.  For each present PTE, allocate
    // a new frame, copy the page content through the kernel phys-offset window,
    // and map the new frame at the corresponding offset in the new base.  Absent
    // (demand-paged-but-not-yet-faulted) pages are skipped — they will be faulted
    // in on demand at the new address, exactly as a fresh mmap would be.
    //
    // We use the same phys-offset read/write technique as sys_mmap_file_backed
    // (copy_nonoverlapping through phys_off + frame_phys) and the same
    // map_user_frames helper for installing the copied frame.
    //
    // SMAP note: we never read/write user virtual addresses directly; all
    // accesses go through the phys-offset kernel window, so SMAP (which only
    // guards ring-0 accesses to *user-mapped* virtual addresses) is not an issue.
    use x86_64::structures::paging::{PageTableFlags, PhysFrame, Size4KiB};

    let phys_off = crate::mm::phys_offset();
    let addr_space = {
        let table = crate::process::PROCESS_TABLE.lock();
        table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
    };

    let old_pages = (old_size_aligned / 4096) as usize;

    // Build PTE flags matching the VMA's protection bits and pkey, using the
    // same compose_user_pte_flags helper as the demand-fault path in
    // interrupts.rs.  This correctly encodes the protection key into bits 59-62
    // of the PTE and handles PROT_WRITE / PROT_EXEC / PROT_READ.
    let pt_flags = crate::mm::pkey::compose_user_pte_flags(vma_prot, vma_pkey);

    let cr3_phys = match addr_space.as_ref().map(|a| a.pml4_phys()) {
        Some(phys) => phys,
        None => {
            // Roll back mmap_next reservation.
            let _ = crate::process::with_shared_mm_mut(pid, |_b, mmap_next, _vma_tree| {
                if *mmap_next == new_base + new_size {
                    *mmap_next = new_base;
                }
            });
            return NEG_ENOMEM;
        }
    };
    let cr3_frame = match PhysFrame::<Size4KiB>::from_start_address(cr3_phys) {
        Ok(f) => f,
        Err(_) => {
            let _ = crate::process::with_shared_mm_mut(pid, |_b, mmap_next, _vma_tree| {
                if *mmap_next == new_base + new_size {
                    *mmap_next = new_base;
                }
            });
            return NEG_ENOMEM;
        }
    };

    // Collect (page_index, new_frame) pairs for pages that are present in the old
    // range and need to be copied.
    let mut copied_frames: alloc::vec::Vec<(usize, PhysFrame<Size4KiB>)> = alloc::vec::Vec::new();

    {
        // Walk old range PTEs with the page-table guard held (same lock discipline
        // as sys_linux_munmap's PTE walk).
        let _page_table_guard = addr_space
            .as_ref()
            .map(|addr_space| addr_space.lock_page_tables());

        use x86_64::{VirtAddr, registers::control::Cr3, structures::paging::PageTable};

        let (cr3_f, _) = Cr3::read();
        let phys_offset_va = VirtAddr::new(phys_off);

        for i in 0..old_pages {
            let page_vaddr = old_addr + (i as u64 * 4096);
            let p4_idx = ((page_vaddr >> 39) & 0x1FF) as usize;
            let p3_idx = ((page_vaddr >> 30) & 0x1FF) as usize;
            let p2_idx = ((page_vaddr >> 21) & 0x1FF) as usize;
            let p1_idx = ((page_vaddr >> 12) & 0x1FF) as usize;

            let src_phys: Option<u64> = unsafe {
                let pml4: &PageTable =
                    &*(phys_offset_va + cr3_f.start_address().as_u64()).as_ptr::<PageTable>();
                if !pml4[p4_idx].flags().contains(PageTableFlags::PRESENT) {
                    None
                } else {
                    let pdpt: &PageTable =
                        &*(phys_offset_va + pml4[p4_idx].addr().as_u64()).as_ptr::<PageTable>();
                    if !pdpt[p3_idx].flags().contains(PageTableFlags::PRESENT) {
                        None
                    } else {
                        let pd: &PageTable =
                            &*(phys_offset_va + pdpt[p3_idx].addr().as_u64()).as_ptr::<PageTable>();
                        if !pd[p2_idx].flags().contains(PageTableFlags::PRESENT) {
                            None
                        } else {
                            let pt: &PageTable = &*(phys_offset_va + pd[p2_idx].addr().as_u64())
                                .as_ptr::<PageTable>();
                            let pte = &pt[p1_idx];
                            // Only copy present non-guard pages.
                            if pte.flags().contains(PageTableFlags::PRESENT)
                                && !pte.flags().contains(PageTableFlags::BIT_10)
                            {
                                Some(pte.addr().as_u64())
                            } else {
                                None
                            }
                        }
                    }
                }
            };

            if let Some(src_frame_phys) = src_phys {
                // Allocate a new frame for the copy destination.
                let dst_frame = match crate::mm::frame_allocator::allocate_frame_zeroed() {
                    Some(f) => f,
                    None => {
                        // OOM — free already-allocated frames and give up.
                        for (_, f) in &copied_frames {
                            crate::mm::frame_allocator::free_frame(f.start_address().as_u64());
                        }
                        let _ =
                            crate::process::with_shared_mm_mut(pid, |_b, mmap_next, _vma_tree| {
                                if *mmap_next == new_base + new_size {
                                    *mmap_next = new_base;
                                }
                            });
                        return NEG_ENOMEM;
                    }
                };
                // Copy page content through the kernel phys-offset window.
                // SAFETY: both src_frame_phys and dst_frame are valid allocated
                // frames; phys_off is the kernel's direct physmap offset.
                unsafe {
                    core::ptr::copy_nonoverlapping(
                        (phys_off + src_frame_phys) as *const u8,
                        (phys_off + dst_frame.start_address().as_u64()) as *mut u8,
                        4096,
                    );
                }
                copied_frames.push((i, dst_frame));
            }
            // Absent (demand-paged) pages: skip — they will fault in at the new VA.
        }
    }

    // Map the copied frames into the new virtual range.
    if !copied_frames.is_empty() {
        let map_result = {
            let _page_table_guard = addr_space
                .as_ref()
                .map(|addr_space| addr_space.lock_page_tables());
            let mut mapper = unsafe { crate::mm::mapper_for_frame(cr3_frame) };
            let mut failed = false;
            for (i, frame) in &copied_frames {
                let vaddr = new_base + (*i as u64 * 4096);
                let page = match x86_64::structures::paging::Page::<Size4KiB>::from_start_address(
                    x86_64::VirtAddr::new(vaddr),
                ) {
                    Ok(p) => p,
                    Err(_) => {
                        failed = true;
                        break;
                    }
                };
                use x86_64::structures::paging::Mapper as _;
                let mut frame_alloc = crate::mm::paging::GlobalFrameAlloc;
                let table_flags = PageTableFlags::PRESENT
                    | PageTableFlags::WRITABLE
                    | PageTableFlags::USER_ACCESSIBLE;
                // Defer local TLB flush — the TLB shootdown after munmap covers it.
                let map_ok = unsafe {
                    mapper
                        .map_to_with_table_flags(
                            page,
                            *frame,
                            pt_flags,
                            table_flags,
                            &mut frame_alloc,
                        )
                        .map(|f| f.ignore())
                        .is_ok()
                };
                if !map_ok {
                    failed = true;
                    break;
                }
            }
            failed
        };
        if map_result {
            // Mapping failed partway. Before freeing the copied frames, unmap
            // any leaf PTEs we already installed in the new range — otherwise we
            // would leave dangling *present* PTEs pointing at frames returned to
            // the allocator (a use-after-free within the process's own address
            // space, reachable via a stale TLB entry since no VMA is recorded to
            // demand-fault them). Empty intermediate page-table levels are left
            // unreclaimed, matching sys_linux_munmap's convention (OOM-only path).
            {
                let _page_table_guard = addr_space
                    .as_ref()
                    .map(|addr_space| addr_space.lock_page_tables());
                let mut mapper = unsafe { crate::mm::mapper_for_frame(cr3_frame) };
                use x86_64::structures::paging::Mapper as _;
                for (i, _) in &copied_frames {
                    let vaddr = new_base + (*i as u64 * 4096);
                    if let Ok(page) =
                        x86_64::structures::paging::Page::<Size4KiB>::from_start_address(
                            x86_64::VirtAddr::new(vaddr),
                        )
                        && let Ok((_f, flush)) = mapper.unmap(page)
                    {
                        // Local invlpg is batched into the shootdown below.
                        flush.ignore();
                    }
                }
            }
            // Shoot down the new range on all cores (outside the page-table lock
            // to avoid the IF-masking deadlock the fork CoW path documents) so no
            // stale TLB entry can alias a frame we are about to free.
            if let Some(ref a) = addr_space {
                crate::smp::tlb::tlb_shootdown_range(a, new_base, new_base + new_size);
            }
            for (_, f) in &copied_frames {
                crate::mm::frame_allocator::free_frame(f.start_address().as_u64());
            }
            let _ = crate::process::with_shared_mm_mut(pid, |_b, mmap_next, _vma_tree| {
                if *mmap_next == new_base + new_size {
                    *mmap_next = new_base;
                }
            });
            return NEG_ENOMEM;
        }
    }

    // Record the new VMA.
    let _ = crate::process::with_shared_mm_mut(pid, |_b, _m, vma_tree| {
        vma_tree.insert(crate::process::MemoryMapping {
            start: new_base,
            len: new_size,
            prot: vma_prot,
            flags: vma_flags,
            file_backing: None,
            pkey: vma_pkey,
        });
    });

    // Unmap the old range (frees old frames, removes old VMA, TLB shootdown).
    //
    // This munmap cannot legitimately fail here: old_addr/old_size_aligned were
    // already validated as page-aligned, non-zero, in-range, and non-overflowing
    // at the top of this function — the only conditions under which
    // sys_linux_munmap returns an error. The new region lives at a fresh
    // bump-allocated `new_base` that is disjoint from old_addr, so a failure
    // could never produce an *overlap* — only a leak of the old mapping. We
    // still surface a non-zero return rather than silently dropping it: a leak
    // here would be a kernel-invariant violation worth logging.
    let unmap_ret = sys_linux_munmap(old_addr, old_size_aligned);
    if unmap_ret != 0 {
        log::error!(
            "[mremap] pid={} MAYMOVE: unexpected munmap failure (ret={:#x}) freeing old range {:#x}+{:#x}; old mapping leaked",
            pid,
            unmap_ret,
            old_addr,
            old_size_aligned,
        );
    }

    // Bump address-space generation for new VMA.
    let table = crate::process::PROCESS_TABLE.lock();
    if let Some(proc) = table.find(pid)
        && let Some(ref addr_space) = proc.addr_space
    {
        addr_space.bump_generation();
    }

    log::debug!(
        "[mremap] pid={} old={:#x}+{:#x} → new={:#x}+{:#x} (MAYMOVE)",
        pid,
        old_addr,
        old_size_aligned,
        new_base,
        new_size,
    );

    new_base
}

// ---------------------------------------------------------------------------
// Phase 36: mprotect(addr, len, prot) — change page permissions on mapped
// regions. Updates PTEs in-place and splits VMAs at mprotect boundaries.
// ---------------------------------------------------------------------------

/// The outcome of the single W^X enforcement decision.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WxDecision {
    /// Not a W+X request (or a non-W+X request that needs no W^X gating). The
    /// request proceeds unchanged.
    NotWx,
    /// A W+X request that must be rejected with `EINVAL` — Phase 75 v1 behavior,
    /// preserved exactly.
    Rejected,
    /// A W+X request that is the documented pkey-guarded "W^X v2" exception:
    /// permitted under the carried non-default write-deny key. Carries the key
    /// for the one-per-grant positive log line.
    GuardedV2 { pkey: u8 },
}

/// The W^X enforcement decision, shared by `sys_mprotect` and
/// `sys_pkey_mprotect`. **This is the single point at which the kernel decides
/// whether a W+X mapping is permitted** — the invariant is enforced identically
/// on every path that can produce a W+X PTE (the audit below enumerates them).
///
/// Phase 90a Track C.1 implements the A.1 W^X v2 contract VERBATIM
/// (`docs/roadmap/tasks/90a-memory-protection-keys-tasks.md`):
///
/// > 1. `sys_mmap` with `PROT_WRITE|PROT_EXEC` → rejected, unchanged from Phase 75.
/// > 2. `sys_mprotect` with `PROT_WRITE|PROT_EXEC` → rejected, unchanged from Phase 75.
/// > 3. `sys_pkey_mprotect(addr, len, prot, pkey)`:
/// >    a. with `pkey == 0` (or `pkey == -1`, the untag-Linux-alias) it behaves
/// >       exactly like `sys_mprotect` — W+X rejected;
/// >    b. with a non-default `pkey` that is **allocated** and whose **alloc-time
/// >       `init_access_rights` include `PKEY_DISABLE_WRITE` or
/// >       `PKEY_DISABLE_ACCESS`**, and PKU active (CR4.PKE set),
/// >       `PROT_READ|PROT_WRITE|PROT_EXEC` is **permitted** and the range's PTEs
/// >       are tagged with the key; the kernel logs one positive
/// >       `[wx] v2-guarded W+X mapping (pkey=N)` line per grant;
/// >    c. any other W+X request through `sys_pkey_mprotect` (unallocated key,
/// >       key allocated with permissive init rights, PKU absent) → rejected with
/// >       the same errno as (1)/(2).
/// > 4. No other syscall or fault path may produce a W+X PTE; the C.1
/// >    enforcement-point audit enumerates them.
///
/// # Enforcement-point audit (C.1) — every path that can produce a W+X PTE
///
/// A W+X *PTE* requires both `WRITABLE` set and `NO_EXECUTE` clear in a live
/// user PTE. Every such composition is gated, and all but the v2 exception
/// reject:
///
/// - **`sys_mprotect`** — routes through `mprotect_worker` with a `Preserve`
///   decision → this guard returns `Rejected` for W+X (clause 2). v1 unchanged.
/// - **`sys_pkey_mprotect`** — routes through `mprotect_worker` with the
///   classified key decision → this guard (clauses 3.a/3.b/3.c). The *only*
///   `GuardedV2` producer.
/// - **`sys_mmap` (anon + file-backed)** — `mmap` carries no pkey argument
///   (there is no `pkey_mmap`; V8's contract is mmap-then-`pkey_mprotect`,
///   never mmap-W+X), so it can only express the unguarded (key-0) case. A W+X
///   *prot* there would otherwise demand-fault / eager-map into a LIVE W+X PTE
///   tagged key 0 that never touches the v2 guard, so **both `sys_linux_mmap`
///   (anon) and `sys_mmap_file_backed` reject W+X at mmap entry** (contract
///   clause 1) with the **same errno as `mprotect`** (`NEG_EINVAL`, -22). This
///   is the key-0 / non-`Tag` case of the canonical `wx_decision` rule applied
///   eagerly at the mmap entry point: a plain `mmap` is the `Preserve`/`Default`
///   decision, which `wx_decision` classifies as `Rejected` for W+X. The VMA is
///   still recorded with `PKEY_DEFAULT` for the accepted (non-W+X) cases, and
///   the only route to an executable+writable page is a subsequent guarded
///   `mprotect`/`pkey_mprotect` — back through `mprotect_worker`'s single gate.
/// - **Demand-fault PTE composition** (`compose_user_pte_flags`) — composes from
///   the VMA's `prot` + `pkey`. The VMA only carries a non-default `pkey` after a
///   `pkey_mprotect(.., Tag(k))` that *this guard already permitted* (clause
///   3.b); a `pkey_mprotect` that this guard rejected never tags the VMA, so a
///   later fault cannot resurrect a W+X mapping the guard refused.
/// - **ELF segment load / file-backed eager mmap** — compose key 0 only
///   (`mm/pkey.rs` audit rows). Key 0 is never write-deny (`rights(0) == None`,
///   `denies_write(0) == false`), so even if such a path requested W+X it would
///   fall to `Rejected` here — they have no way to express a v2 key.
/// - **CoW fork copy / CoW fault resolution** — carry the parent PTE's whole
///   flag word (key field included) and only toggle `WRITABLE`/`BIT_9`; they
///   never *introduce* a new W+X combination. A CoW page that was R-X stays
///   non-writable; a writable page stays non-executable.
///
/// So a W+X PTE can only be *introduced* through `mprotect_worker` (called by
/// both `sys_mprotect` and `sys_pkey_mprotect`), gated by `wx_decision`; the
/// `mmap` entry points reject W+X up front with the same `wx_decision` rule and
/// the same errno, so no `mmap` path can install an unguarded W+X PTE either.
/// Returns the [`WxDecision`].
fn wx_decision(
    prot: u64,
    key_decision: kernel_core::pkey::PkeyMprotectKey,
    table: &kernel_core::pkey::PkeyTable,
) -> WxDecision {
    use kernel_core::pkey::PkeyMprotectKey;
    const PROT_WRITE: u64 = 0x2;
    const PROT_EXEC: u64 = 0x4;

    // Only W+X requests are gated; everything else proceeds untouched.
    if prot & PROT_WRITE == 0 || prot & PROT_EXEC == 0 {
        return WxDecision::NotWx;
    }

    // The pkey-guarded v2 exception — the pure decision lives in host-tested
    // `kernel_core::pkey::wx_v2_permits` so the accept/reject matrix is unit
    // tested. PKU must be *enforcing* on this core before we grant a W+X
    // exception. `pku_usable()` alone is insufficient: it only proves the CPU
    // advertises PKU + the XSAVE PKRU component and *never* inspects `CR4.PKE`
    // (see `cpuid::probe_pku`). A "present-but-inactive" posture (PKU usable yet
    // `CR4.PKE` clear) would otherwise let the v2 grant through with the
    // protection-key MMU check disabled — i.e. an *unguarded* W+X mapping, since
    // a write-deny key traps nothing when PKE is off. Also require this core's
    // live `CR4.PKE` bit, so the grant only ever rides real enforcement.
    let pku_active =
        crate::arch::x86_64::cpuid::pku_usable() && crate::arch::x86_64::cpuid::cr4_pke_enabled();
    if kernel_core::pkey::wx_v2_permits(table, key_decision, pku_active) {
        // `wx_v2_permits` only returns true for a `Tag(k)` decision, so this
        // extraction always succeeds; default to Rejected defensively otherwise.
        if let PkeyMprotectKey::Tag(pkey) = key_decision {
            return WxDecision::GuardedV2 { pkey };
        }
    }
    WxDecision::Rejected
}

pub(super) fn sys_mprotect(addr: u64, len: u64, prot: u64) -> u64 {
    // Plain `mprotect` preserves each PTE's existing protection key — Linux
    // models `mprotect` as `pkey_mprotect(.., -1)`. The shared worker carries
    // the `Preserve` decision (no key field is written).
    mprotect_worker(
        addr,
        len,
        prot,
        kernel_core::pkey::PkeyMprotectKey::Preserve,
    )
}

/// Shared `mprotect` / `pkey_mprotect` worker (Phase 90a Track B.3).
///
/// `key_decision` is the pre-validated outcome of classifying the requested
/// protection key against the calling process's [`PkeyTable`]:
/// - `Preserve` — plain `mprotect`; each PTE keeps its existing key field;
/// - `Default` — tag the range with key 0 (clears the key field);
/// - `Tag(k)` — tag the range with non-default key `k`, and record `k` on the
///   covering VMAs so a **future demand-fault** in the range composes a tagged
///   PTE.
///
/// (`Invalid` is rejected by the `sys_pkey_mprotect` caller before reaching
/// here.) The VMA/permission/TLB machinery below is identical for both
/// syscalls — only the key handling differs.
fn mprotect_worker(
    addr: u64,
    len: u64,
    prot: u64,
    key_decision: kernel_core::pkey::PkeyMprotectKey,
) -> u64 {
    use kernel_core::pkey::{PkeyMprotectKey, with_pkey};

    // Mask prot to supported POSIX bits only.
    let prot = prot & 0x7; // PROT_READ | PROT_WRITE | PROT_EXEC

    const PROT_READ: u64 = 0x1;
    const PROT_WRITE: u64 = 0x2;
    const PROT_EXEC: u64 = 0x4;

    // Phase 75 / 90a W^X enforcement — the single shared guard point (see
    // `wx_decision`). It runs before page-alignment validation, the VMA walk,
    // and any PTE mutation so that no partial state is left behind on rejection.
    // The supported JIT pattern is documented in
    // `docs/appendix/architecture-and-syscalls.md` (allocate RW-, write machine
    // code, then `mprotect` to R-X); the pkey-guarded W+X v2 exception (Track
    // C.1) is the only path that permits W+X, and only under a non-default
    // write-deny key with PKU active.
    let pid = crate::process::current_pid();
    // The classification already consulted this process's PkeyTable; re-snapshot
    // it for the W^X v2 rights check (`denies_write`). A snapshot is sufficient —
    // a single-threaded syscall cannot race its own table.
    let pkey_table = crate::process::shared_pkey_table(pid).unwrap_or_default();
    match wx_decision(prot, key_decision, &pkey_table) {
        WxDecision::NotWx => {}
        WxDecision::Rejected => return NEG_EINVAL,
        WxDecision::GuardedV2 { pkey } => {
            // Exactly one positive line per granted W+X mapping. The D.3 gate
            // greps for this; the v1-rejection error line must be ABSENT here.
            log::info!("[wx] v2-guarded W+X mapping (pkey={})", pkey);
        }
    }

    // For a `Tag(k)` decision, the key field is rewritten with `k` on every PTE
    // in the range. `Preserve` (plain `mprotect`) leaves the field untouched.
    // `Default` (`pkey_mprotect(pkey=0)`) writes key 0 — clearing the field,
    // which is a no-op on the common untagged PTE (already 0) but normalises any
    // stale tag. The `set_key`/`new_key` pair below applies the tag when set.
    let set_key: Option<u8> = match key_decision {
        PkeyMprotectKey::Tag(k) => Some(k),
        // `Default` (pkey==0) means "tag with key 0", i.e. clear the field;
        // since every untagged PTE already carries 0 this is a no-op, but we
        // still write it so an eagerly-mapped range that somehow carried a
        // stale tag is normalised. Preserve leaves the field untouched.
        PkeyMprotectKey::Default => Some(0),
        PkeyMprotectKey::Preserve => None,
        PkeyMprotectKey::Invalid => return NEG_EINVAL, // defensive; caller pre-checks
    };

    // Validate: page-aligned address and non-zero length.
    if addr & 0xFFF != 0 || len == 0 {
        return NEG_EINVAL;
    }
    if addr >= 0x0000_8000_0000_0000 {
        return NEG_EINVAL;
    }

    let total_size = len.div_ceil(4096) * 4096; // round up to page boundary
    let mprotect_end = match addr.checked_add(total_size) {
        Some(e) => e,
        None => return NEG_EINVAL,
    };

    // Validate that the entire range is covered by VMAs (or stack/brk regions).
    // For now, we are permissive: if the address falls outside tracked VMAs
    // (e.g. stack, brk, ELF segments), we still update PTEs but don't fail.
    // This matches the musl stack guard use case where mprotect targets
    // ELF loader-mapped regions not tracked as VMAs.

    use x86_64::registers::control::Cr3;
    use x86_64::structures::paging::{PageTable, PageTableFlags};

    let phys_off = crate::mm::phys_offset();
    let phys_offset_va = x86_64::VirtAddr::new(phys_off);

    let (cr3_frame, _) = Cr3::read();
    let pml4_phys = cr3_frame.start_address().as_u64();
    // `pid` is bound above at the W^X guard.
    let addr_space = {
        let table = crate::process::PROCESS_TABLE.lock();
        table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
    };

    // Build the new PTE flags from prot.
    let mut new_flags = PageTableFlags::PRESENT | PageTableFlags::USER_ACCESSIBLE;
    if prot & PROT_WRITE != 0 {
        new_flags |= PageTableFlags::WRITABLE;
    }
    if prot & PROT_EXEC == 0 {
        new_flags |= PageTableFlags::NO_EXECUTE;
    }
    // PROT_NONE: clear PRESENT to trap all accesses.
    let is_prot_none = prot & (PROT_READ | PROT_WRITE | PROT_EXEC) == 0;

    let pages = total_size / 4096;
    let mut changed_addrs: alloc::vec::Vec<u64> = alloc::vec::Vec::new();
    let mut vma_changed = false;
    {
        let _page_table_guard = addr_space
            .as_ref()
            .map(|addr_space| addr_space.lock_page_tables());

        for i in 0..pages {
            let page_addr = addr + i * 4096;
            let p4_idx = ((page_addr >> 39) & 0x1FF) as usize;
            let p3_idx = ((page_addr >> 30) & 0x1FF) as usize;
            let p2_idx = ((page_addr >> 21) & 0x1FF) as usize;
            let p1_idx = ((page_addr >> 12) & 0x1FF) as usize;

            unsafe {
                let pml4: &mut PageTable =
                    &mut *(phys_offset_va + pml4_phys).as_mut_ptr::<PageTable>();
                if !pml4[p4_idx].flags().contains(PageTableFlags::PRESENT) {
                    continue; // Not yet demand-mapped — VMA prot update suffices.
                }
                let pdpt: &mut PageTable =
                    &mut *(phys_offset_va + pml4[p4_idx].addr().as_u64()).as_mut_ptr::<PageTable>();
                if !pdpt[p3_idx].flags().contains(PageTableFlags::PRESENT) {
                    continue;
                }
                let pd: &mut PageTable =
                    &mut *(phys_offset_va + pdpt[p3_idx].addr().as_u64()).as_mut_ptr::<PageTable>();
                if !pd[p2_idx].flags().contains(PageTableFlags::PRESENT) {
                    continue;
                }
                let pt: &mut PageTable =
                    &mut *(phys_offset_va + pd[p2_idx].addr().as_u64()).as_mut_ptr::<PageTable>();
                let old_flags = pt[p1_idx].flags();
                let is_guard_page = old_flags.contains(PageTableFlags::BIT_10);
                if !old_flags.contains(PageTableFlags::PRESENT) && !is_guard_page && !is_prot_none {
                    continue; // Not yet demand-mapped.
                }

                if old_flags.contains(PageTableFlags::PRESENT) || is_guard_page {
                    let old_addr = pt[p1_idx].addr();
                    let is_cow = old_flags.contains(PageTableFlags::BIT_9);
                    let mut final_flags = old_flags;
                    if is_prot_none {
                        // Clear PRESENT to make the page trap on any access.
                        final_flags &= !PageTableFlags::PRESENT;
                        final_flags &= !PageTableFlags::WRITABLE;
                        final_flags |= PageTableFlags::BIT_10; // mark as guard page
                    } else {
                        final_flags |= PageTableFlags::PRESENT | PageTableFlags::USER_ACCESSIBLE;
                        final_flags &= !PageTableFlags::BIT_10;
                        // Preserve CoW marker. If the page is CoW, keep it
                        // non-writable — the CoW fault handler will make it
                        // writable after copying.
                        final_flags &= !PageTableFlags::WRITABLE;
                        if !is_cow && new_flags.contains(PageTableFlags::WRITABLE) {
                            final_flags |= PageTableFlags::WRITABLE;
                        }
                        final_flags &= !PageTableFlags::NO_EXECUTE;
                        if new_flags.contains(PageTableFlags::NO_EXECUTE) {
                            final_flags |= PageTableFlags::NO_EXECUTE;
                        }
                        if is_cow {
                            final_flags |= PageTableFlags::BIT_9;
                        }
                    }
                    // Phase 90a B.3 — stamp the protection key into PTE bits
                    // 59..=62 when this is a `pkey_mprotect` with a key to set
                    // (`Tag(k)` or `Default`/key 0). `Preserve` (plain mprotect,
                    // `set_key == None`) leaves the existing key field untouched
                    // — `final_flags` already started from `old_flags`, so the
                    // tag carries through. `with_pkey` rewrites only the 4-bit
                    // key field; all other bits (just computed above) are intact.
                    if let Some(key) = set_key {
                        final_flags =
                            PageTableFlags::from_bits_truncate(with_pkey(final_flags.bits(), key));
                    }
                    if final_flags != old_flags {
                        pt[p1_idx].set_addr(old_addr, final_flags);
                        changed_addrs.push(page_addr);
                    }
                }
            }
        }

        // Update VMA protection bits (and, for pkey_mprotect, the key) and split
        // VMAs at the mprotect boundaries.
        if let Some(changed) =
            crate::process::with_shared_mm_mut(pid, |_brk_current, _mmap_next, vma_tree| {
                let prot_changed = vma_tree.any(|m| {
                    let m_end = m.start.saturating_add(m.len);
                    m.start < mprotect_end && m_end > addr && m.prot != prot
                });
                // Phase 90a B.3 — when this is a key-setting pkey_mprotect, the
                // covering VMAs must record the key so a FUTURE demand-fault in
                // the range composes a tagged PTE (see `demand_map_vma_page` →
                // `shared_vma_prot_and_pkey`). Detect a key change too, so a
                // pkey-only change (prot unchanged) still splits + retags.
                let key_changed = if let Some(key) = set_key {
                    vma_tree.any(|m| {
                        let m_end = m.start.saturating_add(m.len);
                        m.start < mprotect_end && m_end > addr && m.pkey != key
                    })
                } else {
                    false
                };
                let changed = prot_changed || key_changed;
                if changed {
                    let range_len = mprotect_end - addr;
                    // update_range_prot splits VMAs at the boundaries and sets
                    // the new prot; it preserves each piece's pkey. For a
                    // key-setting request, follow with update_range_pkey on the
                    // same (now-split) boundaries to stamp the key.
                    vma_tree.update_range_prot(addr, range_len, prot);
                    if let Some(key) = set_key {
                        vma_tree.update_range_pkey(addr, range_len, key);
                    }
                }
                changed
            })
        {
            vma_changed = changed;
        }
    }

    // Batch TLB shootdown for all changed pages.
    if !changed_addrs.is_empty() {
        let range_start = *changed_addrs.iter().min().unwrap();
        let range_end = *changed_addrs.iter().max().unwrap() + 4096;
        if let Some(addr_space) = addr_space.as_ref() {
            crate::smp::tlb::tlb_shootdown_range(addr_space, range_start, range_end);
        }
    }

    if (!changed_addrs.is_empty() || vma_changed)
        && let Some(addr_space) = addr_space.as_ref()
    {
        addr_space.bump_generation();
    }

    0
}

// ---------------------------------------------------------------------------
// Phase 90a Track B.3 — Memory Protection Keys syscalls (Linux 329/330/331).
//
// `pkey_alloc(flags, init_access_rights)` hands out a non-default protection key
// (1..=15) from the per-address-space `PkeyTable`, records its init rights, and
// applies them to the calling thread's live PKRU. `pkey_free(pkey)` returns a
// key to the pool. `pkey_mprotect(addr, len, prot, pkey)` is `mprotect` that
// also tags the range's PTEs (and VMAs) with `pkey`. The pure validation logic
// (flags/rights, the -1 alias, key-range/allocated checks) lives in host-tested
// `kernel_core::pkey`; these handlers wire it to PKRU, the syscall ABI, and the
// shared `mprotect_worker`.
// ---------------------------------------------------------------------------

/// `pkey_alloc(flags, init_access_rights)` — Linux nr 330.
///
/// Returns the new key (1..=15) on success, or a negative errno:
/// - `EINVAL` — `flags != 0`, or `init_access_rights` sets a bit outside
///   `PKEY_DISABLE_ACCESS | PKEY_DISABLE_WRITE`;
/// - `ENOSPC` — no PKU on this CPU (Linux: zero keys available), or all 15
///   allocatable keys are in use.
///
/// On success the key is allocated in the per-address-space table (with its
/// rights recorded for the W^X v2 rule) **and** the init rights are written to
/// the calling thread's live PKRU (B.4 carries that across context switches).
pub(super) fn sys_pkey_alloc(flags: u64, init_access_rights: u64) -> u64 {
    use kernel_core::pkey::{AllocOutcome, PKEY_ACCESS_MASK};

    // No PKU on this CPU → Linux returns ENOSPC (zero keys available). Checked
    // first so a no-PKU machine never touches the table or PKRU.
    if !crate::arch::x86_64::cpuid::pku_usable() {
        return NEG_ENOSPC;
    }

    // Validate the argument bit-widths up front (the table also rejects these,
    // but doing it here keeps the errno mapping local and explicit). `flags` and
    // `init_access_rights` are passed as C `unsigned int`s.
    if flags != 0 || (init_access_rights & !(PKEY_ACCESS_MASK as u64)) != 0 {
        return NEG_EINVAL;
    }

    let pid = crate::process::current_pid();
    let flags32 = flags as u32;
    let rights32 = init_access_rights as u32;

    let outcome =
        crate::process::with_shared_pkey_table_mut(pid, |table| table.alloc(flags32, rights32));

    match outcome {
        Some(AllocOutcome::Ok(key)) => {
            // Apply the new key's init rights to THIS thread's live PKRU. PKU is
            // usable (checked above), so RDPKRU/WRPKRU do not #UD.
            // B.4 carries this across context switches via XSAVE component 9.
            crate::arch::x86_64::pkru::apply_init_rights(key, rights32);
            key as u64
        }
        Some(AllocOutcome::NoSpace) => NEG_ENOSPC,
        Some(AllocOutcome::Invalid) => NEG_EINVAL,
        None => NEG_EINVAL, // no process — should not happen from a live syscall
    }
}

/// `pkey_free(pkey)` — Linux nr 331.
///
/// Returns 0 on success, or `EINVAL` for key 0 (reserved), an out-of-range key,
/// or a not-currently-allocated key. Freeing does **not** untag pages (Linux
/// semantics — see `PkeyTable::free`); a later `pkey_alloc` may reuse the key
/// value, after which stale-tagged pages fall under the new owner's rights.
pub(super) fn sys_pkey_free(pkey: u64) -> u64 {
    use kernel_core::pkey::{FreeOutcome, NUM_PKEYS};

    // An out-of-range key is EINVAL without consulting the table (the table also
    // rejects it, but the u64→u8 narrowing must be guarded first).
    if pkey >= NUM_PKEYS as u64 {
        return NEG_EINVAL;
    }
    let key = pkey as u8;
    let pid = crate::process::current_pid();

    match crate::process::with_shared_pkey_table_mut(pid, |table| table.free(key)) {
        Some(FreeOutcome::Ok) => 0,
        _ => NEG_EINVAL,
    }
}

/// `pkey_mprotect(addr, len, prot, pkey)` — Linux nr 329.
///
/// Applies `prot` to `[addr, addr+len)` exactly like `mprotect`, and also tags
/// the range's PTEs (and covering VMAs) with `pkey`:
/// - `pkey == -1` (the Linux alias, [`is_preserve_key`]) → identical to plain
///   `mprotect`; the existing key field is preserved;
/// - `pkey == 0` → tag with the default key (clears the field);
/// - a non-default key must be **allocated** in this process, else `EINVAL`;
/// - W+X goes through the same single guard point as `mprotect` ([`wx_decision`]):
///   rejected unless this is the Track C.1 pkey-guarded W^X v2 exception (a
///   non-default, allocated, write-deny key with PKU active), in which case it
///   is permitted and the range's PTEs are tagged with the key.
pub(super) fn sys_pkey_mprotect(addr: u64, len: u64, prot: u64, pkey: u64) -> u64 {
    use kernel_core::pkey::{PkeyMprotectKey, classify_pkey_mprotect};

    let pid = crate::process::current_pid();

    // Classify the key argument against this process's table BEFORE touching any
    // VMA or PTE. A snapshot read is sufficient — `alloc`/`free` cannot race a
    // single-threaded syscall on its own table, and `with_shared_pkey_table_mut`
    // publishes atomically under the process-table lock.
    let table = crate::process::shared_pkey_table(pid).unwrap_or_default();
    let decision = classify_pkey_mprotect(&table, pkey);
    if decision == PkeyMprotectKey::Invalid {
        return NEG_EINVAL;
    }

    mprotect_worker(addr, len, prot, decision)
}

// ---------------------------------------------------------------------------
// Phase 33 Track F: meminfo syscall (0x1001)
//
// Writes a text summary of kernel memory statistics into a user buffer.
// arg0 = user buffer address, arg1 = buffer length.
// Returns number of bytes written, or 0 on error.
// ---------------------------------------------------------------------------

pub(super) fn sys_meminfo(buf_addr: u64, buf_len: u64) -> u64 {
    use core::fmt::Write;

    if buf_addr == 0 || buf_len == 0 {
        return 0;
    }

    // Gather stats
    let heap = crate::mm::heap::heap_stats();
    let frames = crate::mm::frame_allocator::frame_stats();
    let slabs = crate::mm::slab::all_slab_stats();
    let sc_stats = crate::mm::slab::size_class_slab_stats();

    // Format into a stack buffer — 4 KiB to accommodate new size-class rows.
    let mut tmp = [0u8; 4096];
    let mut writer = BufWriter::new(&mut tmp);

    let _ = writeln!(writer, "=== Kernel Memory Info ===");
    let _ = writeln!(writer);
    let _ = writeln!(
        writer,
        "Allocator: {}",
        if heap.size_class_active {
            "size-class (slab + page-backed)"
        } else {
            "bootstrap (monotonic)"
        }
    );
    let _ = writeln!(writer);
    let _ = writeln!(writer, "Bootstrap Heap:");
    let _ = writeln!(
        writer,
        "  total: {} KiB  used: {} KiB  free: {} KiB",
        heap.total_size / 1024,
        heap.used_bytes / 1024,
        heap.free_bytes / 1024
    );
    let _ = writeln!(
        writer,
        "  allocs: {}  deallocs: {}",
        heap.alloc_count, heap.dealloc_count
    );
    if heap.size_class_active {
        let _ = writeln!(
            writer,
            "  slab pages: {}  large pages: {}",
            heap.slab_pages, heap.page_backed_pages
        );
    }
    let _ = writeln!(writer);
    let _ = writeln!(writer, "Frames (4 KiB pages):");
    let _ = writeln!(
        writer,
        "  total: {}  free: {}  available: {}  allocated: {}",
        frames.total_frames, frames.free_frames, frames.available_frames, frames.allocated_frames
    );
    let _ = writeln!(
        writer,
        "  memory: {} MiB total, {} MiB free, {} MiB available",
        frames.total_frames * 4 / 1024,
        frames.free_frames * 4 / 1024,
        frames.available_frames * 4 / 1024
    );
    let _ = write!(writer, "  buddy orders:");
    for (order, &count) in frames.free_by_order.iter().enumerate() {
        if count > 0 {
            let _ = write!(writer, " o{}={}", order, count);
        }
    }
    let _ = writeln!(writer);
    if frames.per_cpu_cached > 0 {
        let _ = writeln!(
            writer,
            "  per-cpu cached: {} (reclaimable, not in MemFree)",
            frames.per_cpu_cached
        );
    }
    let _ = writeln!(writer);
    let _ = writeln!(writer, "Slab Caches (named):");
    fn fmt_slab(w: &mut BufWriter<'_>, name: &str, s: &kernel_core::slab::SlabStats) {
        let _ = writeln!(
            w,
            "  {}: slabs={} active={} free={}",
            name, s.total_slabs, s.active_objects, s.free_slots
        );
    }
    fmt_slab(&mut writer, "task(1KiB)", &slabs.task);
    fmt_slab(&mut writer, "fd(64B)   ", &slabs.fd);
    fmt_slab(&mut writer, "endpt(128B)", &slabs.endpoint);
    fmt_slab(&mut writer, "pipe(4KiB)", &slabs.pipe);
    fmt_slab(&mut writer, "sock(256B)", &slabs.socket);
    fmt_slab(&mut writer, "xsave     ", &slabs.xsave);
    if heap.size_class_active {
        let _ = writeln!(writer);
        let _ = writeln!(writer, "Size Classes (slab backing):");
        let classes = kernel_core::size_class::SIZE_CLASSES;
        for (i, stats) in sc_stats.iter().enumerate() {
            if stats.total_slabs > 0 || stats.active_objects > 0 {
                let _ = writeln!(
                    writer,
                    "  {}B: slabs={} active={} free={}",
                    classes[i], stats.total_slabs, stats.active_objects, stats.free_slots
                );
            }
        }
    }

    let written = writer.pos;

    // Copy to user buffer
    let copy_len = written.min(buf_len as usize);
    if UserSliceWo::new(buf_addr, tmp[..copy_len].len())
        .and_then(|s| s.copy_from_kernel(&tmp[..copy_len]))
        .is_err()
    {
        return 0;
    }

    copy_len as u64
}

/// Tiny stack buffer writer for formatting meminfo output.
struct BufWriter<'a> {
    buf: &'a mut [u8],
    pos: usize,
}

impl<'a> BufWriter<'a> {
    fn new(buf: &'a mut [u8]) -> Self {
        Self { buf, pos: 0 }
    }
}

impl core::fmt::Write for BufWriter<'_> {
    fn write_str(&mut self, s: &str) -> core::fmt::Result {
        let bytes = s.as_bytes();
        let remaining = self.buf.len() - self.pos;
        let len = bytes.len().min(remaining);
        self.buf[self.pos..self.pos + len].copy_from_slice(&bytes[..len]);
        self.pos += len;
        Ok(())
    }
}

// ---------------------------------------------------------------------------
// Phase 47 Track A: framebuffer info syscall (0x1005)
//
// Writes a packed FbInfo struct into a user-supplied buffer.
// arg0 = user buffer pointer, arg1 = buffer length (must be >= 20 bytes)
// Returns 0 on success, NEG_EINVAL on bad arguments or unsupported pixel
// format (only RGB and BGR are supported), NEG_EFAULT if the copy to
// userspace fails.
// ---------------------------------------------------------------------------

#[repr(C)]
struct FbInfo {
    width: u32,
    height: u32,
    stride: u32,
    bpp: u32,
    pixel_format: u32,
}

pub(super) fn sys_framebuffer_info(buf_addr: u64, buf_len: u64) -> u64 {
    const USER_LIMIT: u64 = 0x0000_8000_0000_0000;
    const FB_INFO_SIZE: u64 = core::mem::size_of::<FbInfo>() as u64;

    if buf_addr == 0 || buf_addr >= USER_LIMIT || buf_len < FB_INFO_SIZE {
        return NEG_EINVAL;
    }

    let (width, height, stride, bpp, pixel_format) = match crate::fb::framebuffer_raw_info() {
        Some(info) => info,
        None => return NEG_EINVAL,
    };

    let pixel_format_val: u32 = match pixel_format {
        bootloader_api::info::PixelFormat::Rgb => 0,
        bootloader_api::info::PixelFormat::Bgr => 1,
        _ => return NEG_EINVAL,
    };

    let info = FbInfo {
        width: width as u32,
        height: height as u32,
        stride: stride as u32,
        bpp: bpp as u32,
        pixel_format: pixel_format_val,
    };

    let info_bytes = unsafe {
        core::slice::from_raw_parts(&info as *const FbInfo as *const u8, FB_INFO_SIZE as usize)
    };
    if UserSliceWo::new(buf_addr, info_bytes.len())
        .and_then(|s| s.copy_from_kernel(info_bytes))
        .is_err()
    {
        return NEG_EFAULT;
    }
    0
}

// ---------------------------------------------------------------------------
// Phase 47 Track A: framebuffer mmap syscall (0x1006)
//
// Maps the physical framebuffer into the calling process's address space.
// Returns the userspace virtual address on success, NEG_EBUSY if another
// process already owns the framebuffer, or NEG_EINVAL on other errors.
// ---------------------------------------------------------------------------

/// Internal flag bit stored in `MemoryMapping.flags` to identify the
/// framebuffer mapping.  The lower bits are POSIX MAP_* flags; this bit
/// lives in the OS-private range and is never returned to userspace.
const FB_MAPPING_FLAG: u64 = 1 << 32;

pub(super) fn sys_framebuffer_mmap() -> u64 {
    let (buf_virt, byte_len) = match crate::fb::framebuffer_buf_addr() {
        Some(v) => v,
        None => {
            log::warn!("[fb_mmap] framebuffer_buf_addr() returned None — FB not initialised");
            return NEG_EINVAL;
        }
    };

    // Translate the kernel virtual address of the framebuffer to its physical
    // address by walking the kernel page tables.  The bootloader may map the
    // framebuffer at a UEFI-provided virtual address that is NOT inside the
    // phys_off direct-map region, so `buf_virt - phys_off` would compute the
    // wrong physical address and cause PhysFrame::from_start_address to fail.
    let buf_phys = {
        use x86_64::structures::paging::Translate;
        // SAFETY: get_mapper() must not alias another live OffsetPageTable.
        // We create and immediately drop this mapper (before the user mapper
        // created below) so there is no aliasing of the same page table.
        let mapper = unsafe { crate::mm::paging::get_mapper() };
        match mapper.translate_addr(x86_64::VirtAddr::new(buf_virt)) {
            Some(phys) => {
                let pa = phys.as_u64();
                if pa % 4096 != 0 {
                    log::warn!("[fb_mmap] FB phys addr {:#x} not page-aligned", pa);
                    return NEG_EINVAL;
                }
                pa
            }
            None => {
                log::warn!(
                    "[fb_mmap] translate_addr({:#x}) failed — FB virt not mapped?",
                    buf_virt
                );
                return NEG_EINVAL;
            }
        }
        // mapper dropped here — no aliasing with the user mapper created below
    };

    let num_pages = (byte_len as u64).div_ceil(4096);
    let total_size = num_pages * 4096;

    // Build array of PhysFrame for each page of the framebuffer.
    let mut frames = alloc::vec::Vec::new();
    for i in 0..num_pages {
        let phys_addr = x86_64::PhysAddr::new(buf_phys + i * 4096);
        let frame = match x86_64::structures::paging::PhysFrame::<
            x86_64::structures::paging::Size4KiB,
        >::from_start_address(phys_addr)
        {
            Ok(f) => f,
            Err(_) => {
                log::warn!(
                    "[fb_mmap] PhysFrame::from_start_address({:#x}) failed",
                    phys_addr
                );
                return NEG_EINVAL;
            }
        };
        frames.push(frame);
    }

    let pid = crate::process::current_pid();
    let addr_space = {
        let table = crate::process::PROCESS_TABLE.lock();
        table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
    };
    // Atomically claim the framebuffer via compare-and-swap before touching
    // page tables.  This eliminates the TOCTOU window that the old two-step
    // check-then-store had: two racing processes can no longer both observe
    // owner==0 and proceed to map.
    let raw_input_enabled = !is_current_exec_path("/bin/display_server");
    if !crate::fb::try_yield_console(pid, raw_input_enabled) {
        return NEG_EBUSY;
    }

    let virt_addr = {
        let _page_table_guard = addr_space
            .as_ref()
            .map(|addr_space| addr_space.lock_page_tables());

        // Determine the virtual address for the mapping in the process address
        // space. Release the console claim on any early error so another
        // process can retry.
        let virt_addr =
            match crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
                let current = if *mmap_next == 0 {
                    ANON_MMAP_BASE
                } else {
                    *mmap_next
                };
                let base = (current + 4095) & !4095;
                // Guard against pushing mmap_next past the canonical user-space limit.
                const USER_SPACE_END: u64 = 0x0000_8000_0000_0000;
                let end = base
                    .checked_add(total_size)
                    .filter(|v| *v <= USER_SPACE_END)?;
                *mmap_next = end;
                Some(base)
            }) {
                Some(Some(base)) => base,
                _ => {
                    crate::fb::release_console_claim(pid);
                    return NEG_EINVAL;
                }
            };
        let reservation_end = virt_addr + total_size;

        // Get the process page table and map the frames.
        let cr3_phys = match addr_space.as_ref().map(|a| a.pml4_phys()) {
            Some(phys) => phys,
            None => {
                crate::fb::release_console_claim(pid);
                return NEG_EINVAL;
            }
        };

        let cr3_frame = match x86_64::structures::paging::PhysFrame::<
            x86_64::structures::paging::Size4KiB,
        >::from_start_address(cr3_phys)
        {
            Ok(f) => f,
            Err(_) => {
                crate::fb::release_console_claim(pid);
                return NEG_EINVAL;
            }
        };

        let mut mapper = unsafe { crate::mm::mapper_for_frame(cr3_frame) };

        use x86_64::structures::paging::PageTableFlags;
        // BIT_11 is an OS-available bit used here to mark "device/hardware frame —
        // do not return to the frame allocator on process teardown".  The frame
        // allocator only owns system-RAM frames; the UEFI framebuffer is MMIO.
        //
        // NO_CACHE sets PCD (bit 4) in the 4 KiB PTE leaf, selecting PAT index 2
        // (PCD=1 / PWT=0 / PAT-bit=0) = Write-Combining after pat::init programs
        // that slot to WC — mirroring pat.rs::set_range_write_combining's type
        // selection.  WRITE_THROUGH (PWT) and the PAT bit (HUGE_PAGE / bit 7 in a
        // 4 KiB PTE) are both absent from this set, preserving PAT index 2 rather
        // than index 6 (UC-) or 3 (UC).
        //
        // pat::init runs on the BSP at kernel/src/lib.rs:309 and on every AP at
        // kernel/src/smp/boot.rs:423, before any compositor WC mapping is faulted
        // in — satisfying the Intel SDM per-core PAT requirement that every logical
        // CPU mapping a shared WC region agree on the memory type.
        let flags = PageTableFlags::PRESENT
            | PageTableFlags::WRITABLE
            | PageTableFlags::USER_ACCESSIBLE
            | PageTableFlags::NO_EXECUTE
            | PageTableFlags::BIT_11
            | PageTableFlags::NO_CACHE; // PCD=1, PWT=0, PAT-bit=0 → PAT index 2 (WC)

        if unsafe { crate::mm::user_space::map_user_frames(&mut mapper, virt_addr, &frames, flags) }
            .is_err()
        {
            // Roll back the reservation only if no later mapping has advanced
            // the shared cursor since this mapping claimed the range.
            let _ =
                crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
                    if *mmap_next == reservation_end {
                        *mmap_next = virt_addr;
                    }
                });
            crate::fb::release_console_claim(pid);
            return NEG_EINVAL;
        }

        // WC readback sentinel: walk the user page table to confirm the mapped leaf
        // has PCD=1 / PWT=0 / PAT=0 (= PAT index 2, WC).  Emitted once per FB map;
        // a QEMU boot can assert the sentinel line contains "PCD=1 PWT=0 PAT=0".
        {
            use x86_64::structures::paging::Translate as _;
            use x86_64::structures::paging::mapper::TranslateResult;
            match mapper.translate(x86_64::VirtAddr::new(virt_addr)) {
                TranslateResult::Mapped {
                    flags: leaf_flags, ..
                } => {
                    let pcd = leaf_flags.contains(PageTableFlags::NO_CACHE) as u8;
                    let pwt = leaf_flags.contains(PageTableFlags::WRITE_THROUGH) as u8;
                    // In a 4 KiB PTE the PAT bit is bit 7, modelled as HUGE_PAGE
                    // by the x86_64 crate.
                    let pat = leaf_flags.contains(PageTableFlags::HUGE_PAGE) as u8;
                    log::info!(
                        "[fb-wc] user FB leaf flags: PCD={} PWT={} PAT={} (WC idx2)",
                        pcd,
                        pwt,
                        pat
                    );
                }
                _ => {
                    log::warn!(
                        "[fb-wc] user FB virt {:#x} — leaf readback failed (not mapped?)",
                        virt_addr
                    );
                }
            }
        }

        // Record the mapping in the process table while the page-table lock is held.
        let _ = crate::process::with_shared_mm_mut(pid, |_brk_current, _mmap_next, vma_tree| {
            vma_tree.insert(crate::process::MemoryMapping {
                start: virt_addr,
                len: total_size,
                prot: 3,                               // PROT_READ | PROT_WRITE
                flags: 1 | FB_MAPPING_FLAG,            // MAP_SHARED + internal FB marker
                file_backing: None,                    // framebuffer device mapping
                pkey: kernel_core::pkey::PKEY_DEFAULT, // device mapping — never pkey-tagged
            });
        });
        virt_addr
    };
    if let Some(addr_space) = addr_space.as_ref() {
        crate::smp::tlb::tlb_shootdown_range(addr_space, virt_addr, virt_addr + total_size);
        addr_space.bump_generation();
    }

    // Ownership was claimed atomically at the top of this function via
    // try_yield_console (compare_exchange).  No second store needed here.

    log::info!(
        "[framebuffer_mmap] pid={} mapped {} pages @ {:#x}",
        pid,
        num_pages,
        virt_addr
    );
    virt_addr
}

// ---------------------------------------------------------------------------
// Phase 57d follow-up: shared-memory region syscalls (0x1018..=0x101A)
//
// `sys_shm_create` allocates a new SHM region of the requested byte
// length and returns the assigned `ShmId` (zero-extended into u64).
// `sys_shm_map` maps an existing region into the caller's address
// space and returns the user virtual address. `sys_shm_unmap` reverses
// the map and decrements the registry refcount.
//
// The chosen wire shape is "ShmId travels as a plain integer": Phase
// 56's single-client display protocol does not need cap-secure grant
// semantics, and the hot path (`term` writing pixels into the region
// and `display_server` reading them) is the same direct memory access
// that capability-secured SHM would provide. A future multi-client
// build can wrap the id inside a `Capability::Grant` without changing
// the kernel registry — the cap variant already has the right shape
// (`frame, page_count, writable`).
// ---------------------------------------------------------------------------

/// SHM-mapped pages set this bit on their leaf PTEs so
/// `mm::free_process_page_table` skips them during process-exit
/// teardown — the SHM registry's refcount is the single source of
/// truth for when frames return to the buddy allocator. Same mechanism
/// the framebuffer mapping uses.
fn shm_pte_flags() -> x86_64::structures::paging::PageTableFlags {
    use x86_64::structures::paging::PageTableFlags;
    PageTableFlags::PRESENT
        | PageTableFlags::WRITABLE
        | PageTableFlags::USER_ACCESSIBLE
        | PageTableFlags::NO_EXECUTE
        | PageTableFlags::BIT_11
}

pub(super) fn sys_shm_create(byte_len: u64) -> u64 {
    if byte_len == 0 {
        return u64::MAX;
    }
    let pid = crate::process::current_pid();
    let result = crate::mm::shm::create(byte_len as usize, pid);
    // Always log the create with the post-create buddy state. This
    // is the diagnostic seam the leak hunts need: walking the boot
    // transcript pairs every shm_create with the resulting free-page
    // count so we see exactly when the buddy starts running out and
    // which creates consumed the headroom.
    let (free, total) = crate::mm::frame_allocator::free_frame_count();
    match &result {
        Ok((id, _, page_count)) => {
            log::info!(
                "[shm] create ok pid={} byte_len={} pages={} id={} buddy={}/{}",
                pid,
                byte_len,
                page_count,
                id.0,
                free,
                total
            );
        }
        Err(crate::mm::shm::ShmError::ProcessCapExceeded) => {
            log::warn!(
                "[shm] create: per-process cap exceeded pid={} byte_len={} buddy={}/{}",
                pid,
                byte_len,
                free,
                total
            );
        }
        Err(e) => {
            log::warn!(
                "[shm] create failed pid={} byte_len={} err={:?} buddy={}/{}",
                pid,
                byte_len,
                e,
                free,
                total
            );
        }
    }
    match result {
        Ok((id, _start_phys, _page_count)) => u64::from(id.0),
        Err(_) => u64::MAX,
    }
}

pub(super) fn sys_shm_map(shm_id_arg: u64) -> u64 {
    if shm_id_arg == 0 || shm_id_arg > u64::from(u32::MAX) {
        log::warn!(
            "[shm] map: invalid shm_id_arg={:#x} from pid={}",
            shm_id_arg,
            crate::process::current_pid()
        );
        return u64::MAX;
    }
    let id = crate::mm::shm::ShmId(shm_id_arg as u32);

    // Increment refcount up front; if any later step fails we decref
    // on the way out. Holds the SHM frames live across the
    // page-table-mapping path even if we yield to wait on a lock.
    let (start_phys, page_count) = match crate::mm::shm::incref(id) {
        Ok(v) => v,
        Err(e) => {
            log::warn!(
                "[shm] map: incref({:?}) failed err={:?} pid={}",
                id,
                e,
                crate::process::current_pid()
            );
            return u64::MAX;
        }
    };
    let total_size = (page_count as u64) * 4096;

    // The SHM region is a single contiguous run from `start_phys`
    // for `page_count` pages, so we feed it directly to the
    // contiguous-mapping helper instead of building a per-page
    // `Vec<PhysFrame>` scratch (~63 KiB at 4K resolution). The
    // per-call kernel-heap alloc was the dominant fragmenter of
    // the buddy allocator under the steady-state per-frame
    // `AttachSharedBuffer` traffic clients emit; eliminating it
    // bounds `sys_shm_map`'s allocation footprint to a few small
    // entries (the VMA tree node + the page-table-walk's frame
    // allocator overhead).
    use x86_64::structures::paging::{PhysFrame, Size4KiB};

    let pid = crate::process::current_pid();
    let addr_space = {
        let table = crate::process::PROCESS_TABLE.lock();
        table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
    };

    let virt_addr = {
        let _page_table_guard = addr_space
            .as_ref()
            .map(|addr_space| addr_space.lock_page_tables());

        // Claim a virtual address range from the process's anon-mmap
        // cursor so we don't collide with an existing mapping.
        const USER_SPACE_END: u64 = 0x0000_8000_0000_0000;
        let virt_addr =
            match crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
                let current = if *mmap_next == 0 {
                    ANON_MMAP_BASE
                } else {
                    *mmap_next
                };
                let base = (current + 4095) & !4095;
                let end = base
                    .checked_add(total_size)
                    .filter(|v| *v <= USER_SPACE_END)?;
                *mmap_next = end;
                Some(base)
            }) {
                Some(Some(base)) => base,
                _ => {
                    log::warn!("[shm] map: with_shared_mm_mut returned None pid={}", pid);
                    let _ = crate::mm::shm::decref(id);
                    return u64::MAX;
                }
            };
        let reservation_end = virt_addr + total_size;

        let cr3_phys = match addr_space.as_ref().map(|a| a.pml4_phys()) {
            Some(phys) => phys,
            None => {
                log::warn!("[shm] map: no addr_space for pid={}", pid);
                let _ = crate::mm::shm::decref(id);
                return u64::MAX;
            }
        };
        let cr3_frame = match PhysFrame::<Size4KiB>::from_start_address(cr3_phys) {
            Ok(f) => f,
            Err(_) => {
                log::warn!(
                    "[shm] map: cr3 not page-aligned pid={} cr3={:#x}",
                    pid,
                    cr3_phys.as_u64()
                );
                let _ = crate::mm::shm::decref(id);
                return u64::MAX;
            }
        };
        let mut mapper = unsafe { crate::mm::mapper_for_frame(cr3_frame) };

        if unsafe {
            crate::mm::user_space::map_user_frames_contiguous(
                &mut mapper,
                virt_addr,
                start_phys,
                page_count as u64,
                shm_pte_flags(),
            )
        }
        .is_err()
        {
            log::warn!(
                "[shm] map: map_user_frames_contiguous failed pid={} virt={:#x} pages={}",
                pid,
                virt_addr,
                page_count
            );
            // Roll back the reservation if no other mapping advanced
            // the cursor in between, then drop our refcount.
            let _ =
                crate::process::with_shared_mm_mut(pid, |_brk_current, mmap_next, _vma_tree| {
                    if *mmap_next == reservation_end {
                        *mmap_next = virt_addr;
                    }
                });
            let _ = crate::mm::shm::decref(id);
            return u64::MAX;
        }

        // Record a VMA so munmap / process teardown can find it. We
        // pack the SHM id into the high bits of `flags` so unmap can
        // recover it without a separate kernel-side table.
        let _ = crate::process::with_shared_mm_mut(pid, |_brk_current, _mmap_next, vma_tree| {
            vma_tree.insert(crate::process::MemoryMapping {
                start: virt_addr,
                len: total_size,
                prot: 3, // PROT_READ | PROT_WRITE
                flags: shm_vma_flags(id),
                file_backing: None,                    // shared-memory mapping
                pkey: kernel_core::pkey::PKEY_DEFAULT, // shm mapping — never pkey-tagged
            });
        });
        virt_addr
    };

    if let Some(addr_space) = addr_space.as_ref() {
        crate::smp::tlb::tlb_shootdown_range(addr_space, virt_addr, virt_addr + total_size);
        addr_space.bump_generation();
    }

    virt_addr
}

/// Phase 80 Track A.6 — reclaim a dying process's SHM *mapper* references.
///
/// Process exit runs [`crate::mm::shm::release_creator`], which drops only
/// the refs a process held *as the creator*. A process that mapped someone
/// else's region (e.g. the audio `ac97`/`hda` driver mapping `audio_server`'s
/// PCM ring) and then crashed without `sys_shm_unmap` would otherwise leave
/// its `incref` outstanding forever — the registry refcount never reaches
/// zero, so the region's frames are never returned to the buddy (a permanent
/// leak across every driver restart). The page-table teardown already unmaps
/// the VA range but deliberately does **not** free SHM-marked frames (they
/// belong to the registry, not the process), so the decref must happen here.
///
/// Walks the dying pid's VMA tree for `SHM_VMA_FLAG_MARKER` entries, collects
/// their ids under the mm lock, then decrefs each outside the lock (the final
/// decref returns the frames to the buddy). Idempotent against a clean
/// `sys_shm_unmap` exit, which already removed the VMA entry.
pub(super) fn release_shm_mappings_for_pid(pid: u32) {
    let ids: alloc::vec::Vec<crate::mm::shm::ShmId> =
        crate::process::with_shared_mm_mut(pid, |_brk, _mmap_next, vma_tree| {
            vma_tree
                .iter()
                .filter(|m| m.flags & SHM_VMA_FLAG_MARKER != 0)
                .filter_map(|m| shm_id_from_vma_flags(m.flags))
                .collect()
        })
        .unwrap_or_default();
    for id in ids {
        let _ = crate::mm::shm::decref(id);
    }
}

pub(super) fn sys_shm_unmap(user_va: u64) -> u64 {
    if user_va == 0 || !user_va.is_multiple_of(4096) {
        return u64::MAX;
    }
    let pid = crate::process::current_pid();
    // Look up the VMA registered by `sys_shm_map` to recover the
    // mapping length and the SHM id we packed into `flags`.
    let info = crate::process::with_shared_mm_mut(pid, |_brk, _mmap_next, vma_tree| {
        vma_tree
            .iter()
            .find(|m| m.start == user_va && (m.flags & SHM_VMA_FLAG_MARKER) != 0)
            .map(|m| (m.len, shm_id_from_vma_flags(m.flags)))
    });
    let (len, id) = match info {
        Some(Some((len, Some(id)))) => (len, id),
        _ => return u64::MAX,
    };

    let addr_space = {
        let table = crate::process::PROCESS_TABLE.lock();
        table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
    };

    {
        let _page_table_guard = addr_space
            .as_ref()
            .map(|addr_space| addr_space.lock_page_tables());

        let cr3_phys = match addr_space.as_ref().map(|a| a.pml4_phys()) {
            Some(phys) => phys,
            None => return u64::MAX,
        };
        use x86_64::structures::paging::{Page, PhysFrame, Size4KiB};
        let cr3_frame = match PhysFrame::<Size4KiB>::from_start_address(cr3_phys) {
            Ok(f) => f,
            Err(_) => return u64::MAX,
        };
        let mut mapper = unsafe { crate::mm::mapper_for_frame(cr3_frame) };
        let pages = len / 4096;
        use x86_64::structures::paging::Mapper;
        for i in 0..pages {
            let vaddr = x86_64::VirtAddr::new(user_va + i * 4096);
            let page: Page<Size4KiB> = Page::containing_address(vaddr);
            // Use unmap directly. Frame ownership transfers back to
            // the SHM registry's refcount path, not to the buddy
            // allocator — that's why `BIT_11` was set on the PTEs at
            // map time.
            if let Ok((_frame, flush)) = mapper.unmap(page) {
                flush.flush();
            }
        }
    }

    if let Some(addr_space) = addr_space.as_ref() {
        crate::smp::tlb::tlb_shootdown_range(addr_space, user_va, user_va + len);
        addr_space.bump_generation();
    }

    // Drop the VMA entry.
    let _ = crate::process::with_shared_mm_mut(pid, |_brk, _mmap_next, vma_tree| {
        vma_tree.remove(user_va);
    });

    // Decrement refcount; if this was the last reference, frames go
    // back to the buddy.
    let _ = crate::mm::shm::decref(id);
    0
}

pub(super) fn sys_shm_destroy(shm_id_arg: u64) -> u64 {
    if shm_id_arg == 0 || shm_id_arg > u64::from(u32::MAX) {
        return u64::MAX;
    }
    let id = crate::mm::shm::ShmId(shm_id_arg as u32);
    let pid = crate::process::current_pid();
    match crate::mm::shm::decref(id) {
        Ok(was_last_ref) => {
            let (free, total) = crate::mm::frame_allocator::free_frame_count();
            log::info!(
                "[shm] destroy pid={} id={} last_ref={} buddy={}/{}",
                pid,
                id.0,
                was_last_ref,
                free,
                total
            );
            0
        }
        Err(e) => {
            log::warn!("[shm] destroy failed pid={} id={} err={:?}", pid, id.0, e);
            u64::MAX
        }
    }
}

/// Syscall `SHM_SIZE` (0x1022): return the byte length of an existing
/// shared-memory region (`page_count * 4096`), or `u64::MAX` if the id is
/// invalid or unknown.
///
/// The region size is not refcount/ownership-sensitive (any holder of the id
/// could already map it), so this performs a plain lookup via
/// [`crate::mm::shm::frames`] without touching the refcount. The receiver of an
/// SHM-backed transport queries this before forming a slice over a peer-supplied
/// region, so it can reject an under-sized region rather than read past it.
pub(super) fn sys_shm_size(shm_id_arg: u64) -> u64 {
    if shm_id_arg == 0 || shm_id_arg > u64::from(u32::MAX) {
        return u64::MAX;
    }
    let id = crate::mm::shm::ShmId(shm_id_arg as u32);
    match crate::mm::shm::frames(id) {
        Ok((_start_phys, page_count)) => u64::from(page_count) * 4096,
        Err(_) => u64::MAX,
    }
}

/// Marker bit in `MemoryMapping.flags` that distinguishes SHM-mapped
/// regions from regular anonymous mappings. Sits in the OS-private
/// flag range (above the public POSIX MAP_* bits, like `FB_MAPPING_FLAG`).
const SHM_VMA_FLAG_MARKER: u64 = 1 << 33;

/// Pack an SHM id into a `MemoryMapping.flags` value. The id occupies
/// bits 0..32 (low 32 bits); the SHM marker bit is OR'd on top.
fn shm_vma_flags(id: crate::mm::shm::ShmId) -> u64 {
    SHM_VMA_FLAG_MARKER | u64::from(id.0)
}

/// Recover an SHM id from a flags value previously produced by
/// `shm_vma_flags`. Returns `None` if the SHM marker bit is not set.
fn shm_id_from_vma_flags(flags: u64) -> Option<crate::mm::shm::ShmId> {
    if (flags & SHM_VMA_FLAG_MARKER) == 0 {
        return None;
    }
    Some(crate::mm::shm::ShmId(flags as u32))
}

// ---------------------------------------------------------------------------
// Phase 56 Track B.1: explicit framebuffer release syscall (0x1014)
//
// Counterpart to FRAMEBUFFER_MMAP. Tears down the framebuffer mapping in
// the calling process's address space and restores the kernel console.
// Returns 0 on success, NEG_EPERM if the caller does not own the FB,
// NEG_ENOENT if the caller owns the FB but no FB-flagged VMA was found
// (already munmapped — restore is still triggered for safety).
// ---------------------------------------------------------------------------

pub(super) fn sys_framebuffer_release() -> u64 {
    let pid = crate::process::current_pid();
    if crate::fb::fb_owner_pid() != pid {
        return NEG_EPERM;
    }

    // Locate the FB-flagged VMA so we can hand its (addr, len) to the
    // existing munmap path; that path already restores the console once
    // every FB-flagged mapping has been torn down.
    let fb_mapping = crate::process::with_shared_mm_mut(pid, |_brk, _mmap_next, vma_tree| {
        vma_tree
            .iter()
            .find(|m| (m.flags & FB_MAPPING_FLAG) != 0)
            .map(|m| (m.start, m.len))
    });

    match fb_mapping {
        Some(Some((addr, len))) => sys_linux_munmap(addr, len),
        _ => {
            // Owner flag was set but no VMA matched — restore the console
            // anyway so the system isn't stuck with a yielded screen.
            crate::fb::restore_console();
            NEG_ENOENT
        }
    }
}

// ---------------------------------------------------------------------------
// Phase 57d follow-up: framebuffer yield / reacquire (0x101C / 0x101D)
//
// Tier 1 of the fullscreen-takeover mechanism. `FB_YIELD` lets the
// current FB owner (typically `display_server`) drop ownership without
// unmapping its FB VMA or repainting the kernel console: the caller's
// pixel mapping survives so a subsequent `FB_REACQUIRE` can resume
// composing without re-walking the page tables. While yielded, no
// process owns the framebuffer (`fb_owner_pid() == 0`) and the next
// caller of `FRAMEBUFFER_MMAP` (e.g. `doom`) wins the CAS atomically.
//
// `FB_REACQUIRE` is the inverse: take ownership back assuming a
// previously-yielded VMA still exists. Used by `display_server` once
// the takeover program exits, after `/bin/fb-takeover` has reported
// the child's status. See `docs/appendix/fb-takeover-tiers.md`.
// ---------------------------------------------------------------------------

pub(super) fn sys_fb_yield() -> u64 {
    let pid = crate::process::current_pid();
    // Phase 70 — fb-takeover Tier 3 lands DOOM as a display_server
    // client; SYS_FB_YIELD is only kept for the deprecated wrapper.
    // Log every caller so a later cleanup phase can confirm all
    // callers are gone before removing the dispatch arm.
    log::warn!(
        "SYS_FB_YIELD called by pid {pid}; syscall is deprecated (Phase 70), scheduled for removal"
    );
    if crate::fb::fb_owner_pid() != pid {
        return NEG_EPERM;
    }
    // Soft release: mark the FB unowned but keep the caller's VMA so a
    // later `FB_REACQUIRE` can avoid re-allocating page tables. The
    // kernel console stays yielded (CONSOLE_YIELDED=true) so any pixel
    // writes the next owner makes are not overpainted by stale console
    // text. See `release_console_claim` for the exact ordering.
    crate::fb::release_console_claim(pid);
    0
}

pub(super) fn sys_fb_reacquire() -> u64 {
    let pid = crate::process::current_pid();
    // Phase 70 — paired with the SYS_FB_YIELD deprecation warn above.
    log::warn!(
        "SYS_FB_REACQUIRE called by pid {pid}; syscall is deprecated (Phase 70), scheduled for removal"
    );
    let raw_input_enabled = !is_current_exec_path("/bin/display_server");

    // Verify the caller still has an FB VMA — `FB_REACQUIRE` is meant
    // for the post-yield path where the caller never tore its mapping
    // down. A caller without an FB VMA should use `FRAMEBUFFER_MMAP`
    // instead so the pages get mapped properly.
    let has_fb_vma = crate::process::with_shared_mm_mut(pid, |_brk, _mmap_next, vma_tree| {
        vma_tree.iter().any(|m| (m.flags & FB_MAPPING_FLAG) != 0)
    });
    if !matches!(has_fb_vma, Some(true)) {
        return NEG_ENOENT;
    }

    // Atomically claim ownership. `try_yield_console` uses a CAS so a
    // concurrent claimer cannot race past us, re-asserts
    // `CONSOLE_YIELDED=true` plus the raw-input routing flag, and
    // (for `raw_input_enabled = false`) injects synthetic key-release
    // scancodes so kbd_server clears any state stuck across the
    // takeover session.
    if crate::fb::try_yield_console(pid, raw_input_enabled) {
        0
    } else {
        NEG_EBUSY
    }
}

// ---------------------------------------------------------------------------
// Phase 73 follow-up — page-flip the hardware framebuffer (0x101F)
//
// Dual-purpose syscall:
//   * arg0 == u64::MAX → query mode, returns `back_y_offset_pixels` as a
//     u64. Returns 0 if VBE double-buffering was not enabled at boot
//     (caller falls back to the memcpy path).
//   * arg0 ∈ { 0, back_y_offset_pixels } → write the value to the VBE
//     Y_OFFSET register and return 0. The flip is applied by the
//     display device on the next scanout cycle.
//   * any other arg0 → NEG_EINVAL.
//
// The "query" sentinel avoids a separate syscall for capability discovery
// and keeps `sys_framebuffer_info`'s wire format unchanged.
// ---------------------------------------------------------------------------

const PAGEFLIP_QUERY: u64 = u64::MAX;

pub(super) fn sys_framebuffer_pageflip(arg0: u64) -> u64 {
    if arg0 == PAGEFLIP_QUERY {
        return crate::fb::framebuffer_back_y_offset_pixels() as u64;
    }
    if !crate::fb::vbe::doublebuffer_ready() {
        return NEG_ENOSYS;
    }
    let pid = crate::process::current_pid();
    if crate::fb::fb_owner_pid() != pid {
        return NEG_EPERM;
    }
    let y_offset = match u32::try_from(arg0) {
        Ok(v) => v,
        Err(_) => return NEG_EINVAL,
    };
    // WC store barrier: the user framebuffer is mapped Write-Combining (PCD=1,
    // PAT index 2).  WC writes are weakly ordered and may remain in the CPU's
    // WC write-combining buffers until an SFENCE flushes them.  Issuing SFENCE
    // here guarantees that all compositor blit stores are globally visible before
    // the display controller latches the page-flip address — preventing a torn
    // frame from appearing on the panel.  SFENCE does not touch SSE/XMM state
    // and is safe in the soft-float kernel target.
    // SAFETY: sfence is a memory-ordering instruction; it has no side effects
    // beyond ordering stores to WC and other memory types.
    unsafe {
        core::arch::asm!("sfence", options(nostack, preserves_flags));
    }
    // SAFETY: ring-0 context; VBE I/O ports are device-owned.
    match unsafe { crate::fb::vbe::pageflip(y_offset) } {
        Ok(()) => 0,
        Err(crate::fb::vbe::FlipError::NotReady) => NEG_ENOSYS,
        Err(crate::fb::vbe::FlipError::BadOffset) => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// Phase 56 Track B.2 — read one decoded mouse packet (0x1015)
//
// Pops the next `MousePacket` from the kernel-side AUX ring (fed by IRQ12 in
// `arch::x86_64::interrupts::mouse_handler`) and copies its 8-byte
// little-endian wire encoding into the user buffer. Returns 0 on a successful
// copy, `NEG_EAGAIN` when the ring is empty, and `NEG_EINVAL` / `NEG_EFAULT`
// for invalid pointer / length / copy_to_user failure.
// ---------------------------------------------------------------------------

/// Diagnostic: read one of the PS/2 ISR counters. See `PS2_DIAG_COUNTER`.
pub(super) fn sys_ps2_diag_counter(selector: u64) -> u64 {
    use core::sync::atomic::Ordering;
    match selector {
        0 => super::ps2::MOUSE_BYTES_SEEN.load(Ordering::Relaxed),
        1 => super::ps2::MOUSE_PACKETS_PRODUCED.load(Ordering::Relaxed),
        2 => super::ps2::MOUSE_RING_DROPS.load(Ordering::Relaxed),
        3 => super::ps2::IRQ1_ENTRIES.load(Ordering::Relaxed),
        4 => super::ps2::IRQ12_ENTRIES.load(Ordering::Relaxed),
        _ => 0,
    }
}

pub(super) fn sys_read_mouse_packet(buf_ptr: u64, buf_len: u64) -> u64 {
    if buf_ptr == 0 || (buf_len as usize) < super::ps2::MOUSE_PACKET_WIRE_SIZE {
        return NEG_EINVAL;
    }
    let Some(packet) = super::ps2::read_mouse_packet() else {
        return NEG_EAGAIN;
    };
    let mut wire = [0u8; super::ps2::MOUSE_PACKET_WIRE_SIZE];
    super::ps2::encode_packet(&packet, &mut wire);
    if UserSliceWo::new(buf_ptr, wire.len())
        .and_then(|s| s.copy_from_kernel(&wire))
        .is_err()
    {
        return NEG_EFAULT;
    }
    0
}

// ---------------------------------------------------------------------------
// Phase 56 Track B.3 — frame-tick metadata + drain (0x1016 / 0x1017)
//
// `sys_frame_tick_hz` returns the configured tick rate in Hz.
// `sys_frame_tick_drain` returns the number of ticks accumulated since the
// last drain — the kernel keeps a saturating counter so userspace polling
// loops never observe a queue blow-up.
// ---------------------------------------------------------------------------

pub(super) fn sys_frame_tick_hz() -> u64 {
    crate::time::frame_tick_hz() as u64
}

pub(super) fn sys_frame_tick_drain() -> u64 {
    crate::time::frame_tick_drain() as u64
}

// ---------------------------------------------------------------------------
// Phase 47 Track B: raw scancode syscall (0x1007)
//
// Returns the next raw PS/2 scancode from the keyboard ring buffer,
// or 0 if no scancode is available (non-blocking).
// ---------------------------------------------------------------------------

pub(super) fn sys_read_scancode() -> u64 {
    let pid = crate::process::current_pid();
    if crate::fb::fb_owner_pid() != pid {
        return 0;
    }

    // Use the dedicated raw/game-input ring buffer.  This buffer is only
    // populated by the keyboard IRQ handler when a process owns the
    // framebuffer and only readable by that same owner process, ensuring the
    // kbd_server never steals break codes that DOOM needs to detect key-up
    // events and that a non-owner cannot read another process's raw stream.
    match super::interrupts::read_raw_scancode() {
        Some(sc) => sc as u64,
        None => 0,
    }
}

// ---------------------------------------------------------------------------
// Phase 52: stdin push from userspace
// ---------------------------------------------------------------------------

/// Read one scancode from the TTY keyboard ring buffer (non-blocking).
///
/// Returns the scancode as u64, or 0 if the buffer is empty.
/// Unlike `sys_read_scancode` (0x1007) which reads the raw/DOOM buffer,
/// this reads the TTY-routed buffer used by the keyboard service.
pub(super) fn sys_read_kbd_scancode() -> u64 {
    match super::interrupts::read_scancode() {
        Some(sc) => sc as u64,
        None => 0,
    }
}

/// Push bytes from a userspace buffer into the kernel stdin buffer.
///
/// arg0 = user buffer pointer, arg1 = byte count.
/// Returns 0 on success, NEG_EFAULT on bad pointer.
pub(super) fn sys_stdin_push(buf_ptr: u64, len: u64) -> u64 {
    const USER_LIMIT: u64 = 0x0000_8000_0000_0000;
    if buf_ptr == 0 || buf_ptr >= USER_LIMIT || len == 0 || len > 4096 {
        return NEG_EINVAL;
    }
    let len = len as usize;
    let mut buf = [0u8; 4096];
    if UserSliceRo::new(buf_ptr, len)
        .and_then(|s| s.copy_to_kernel(&mut buf[..len]))
        .is_err()
    {
        return NEG_EFAULT;
    }
    for &b in &buf[..len] {
        crate::stdin::push_char(b);
    }
    0
}

// ---------------------------------------------------------------------------
// Phase 52: signal a process group from userspace
// ---------------------------------------------------------------------------

/// Send a signal to all processes in a foreground process group.
///
/// arg0 = signal number, arg1 = unused (uses current FG_PGID).
/// Returns 0 on success.
pub(super) fn sys_signal_process_group(sig: u64, _arg1: u64) -> u64 {
    let fg = crate::process::FG_PGID.load(core::sync::atomic::Ordering::Relaxed);
    if fg == 0 {
        return 0;
    }
    crate::process::send_signal_to_group(fg, sig as u32);
    0
}

// ---------------------------------------------------------------------------
// Phase 52: get termios flags from TTY0
// ---------------------------------------------------------------------------

/// Return termios flags to a userspace buffer.
///
/// arg0 = user buffer pointer (must hold at least 32 bytes:
///        c_lflag(4) + c_iflag(4) + c_oflag(4) + c_cc[19] + pad(1) = 32).
/// arg1 = buffer length.
/// Returns 0 on success, NEG_EFAULT on bad pointer, NEG_EINVAL on bad size.
pub(super) fn sys_get_termios_flags(buf_ptr: u64, buf_len: u64) -> u64 {
    const NEEDED: usize = 32; // 4+4+4+19+1
    const USER_LIMIT: u64 = 0x0000_8000_0000_0000;
    if buf_ptr == 0 || buf_ptr >= USER_LIMIT || (buf_len as usize) < NEEDED {
        return NEG_EINVAL;
    }
    let t = crate::tty::TTY0.lock();
    let mut out = [0u8; NEEDED];
    out[0..4].copy_from_slice(&t.ldisc.termios.c_lflag.to_le_bytes());
    out[4..8].copy_from_slice(&t.ldisc.termios.c_iflag.to_le_bytes());
    out[8..12].copy_from_slice(&t.ldisc.termios.c_oflag.to_le_bytes());
    out[12..31].copy_from_slice(&t.ldisc.termios.c_cc);
    out[31] = 0; // padding
    drop(t);
    if UserSliceWo::new(buf_ptr, out.len())
        .and_then(|s| s.copy_from_kernel(&out))
        .is_err()
    {
        return NEG_EFAULT;
    }
    0
}

// ---------------------------------------------------------------------------
// Phase 52: signal EOF on kernel stdin
// ---------------------------------------------------------------------------

/// Signal EOF on the kernel stdin buffer.
///
/// Returns 0 always.
pub(super) fn sys_stdin_signal_eof() -> u64 {
    crate::stdin::signal_eof();
    0
}

// ---------------------------------------------------------------------------
// Phase 52c: push_raw_input(byte) — kernel-side line discipline
// ---------------------------------------------------------------------------

/// Push a single raw input byte through the kernel's line discipline.
///
/// The byte is processed through TTY0's LineDiscipline which handles iflag
/// transforms, signal generation, canonical editing, and echo generation.
/// Echo output goes to the active console sinks (serial + framebuffer).
pub(super) fn sys_push_raw_input(byte_arg: u64) -> u64 {
    let byte = byte_arg as u8;

    // Process through LineDiscipline under TTY0 lock.
    let mut eof_signal = false;
    let result = {
        let mut tty = crate::tty::TTY0.lock();
        tty.ldisc.process_byte(byte, &mut |data| {
            if data.is_empty() {
                eof_signal = true;
            } else {
                for &b in data {
                    crate::stdin::push_char(b);
                }
            }
        })
    };

    if eof_signal {
        crate::stdin::signal_eof();
    }

    // Handle the result: signals and echo.
    match result {
        kernel_core::tty::LdiscResult::Consumed => {}
        kernel_core::tty::LdiscResult::Signal(sig) => {
            let fg = crate::process::FG_PGID.load(core::sync::atomic::Ordering::Relaxed);
            if fg != 0 {
                let name = match sig {
                    2 => "^C",
                    20 => "^Z",
                    3 => "^\\",
                    _ => "",
                };
                console_echo_bytes(name.as_bytes());
                console_echo_bytes(b"\n");
                crate::process::send_signal_to_group(fg, sig as u32);
            } else {
                // No foreground group — push raw byte.
                crate::stdin::push_char(byte);
            }
        }
        kernel_core::tty::LdiscResult::Pushed { ref echo }
        | kernel_core::tty::LdiscResult::LineComplete { ref echo } => {
            if let Some(count) = echo.erase_count() {
                for _ in 0..count {
                    console_echo_bytes(b"\x08 \x08");
                }
            } else if !echo.is_empty() {
                console_echo_bytes(echo.as_slice());
            }
        }
    }

    0
}

/// Write raw echo bytes to the serial console and framebuffer console.
fn console_echo_bytes(bytes: &[u8]) {
    serial_echo_bytes(bytes);
    framebuffer_echo_bytes(bytes);
}

/// Mirror echo bytes to the framebuffer console without heap allocation.
fn framebuffer_echo_bytes(bytes: &[u8]) {
    if let Ok(s) = core::str::from_utf8(bytes) {
        crate::fb::write_str(s);
        return;
    }

    let mut encoded = [0u8; 2];
    for &byte in bytes {
        let s = char::from(byte).encode_utf8(&mut encoded);
        crate::fb::write_str(s);
    }
}

/// Write raw bytes to the serial console (COM1).
fn serial_echo_bytes(bytes: &[u8]) {
    for &b in bytes {
        unsafe {
            while x86_64::instructions::port::Port::<u8>::new(0x3FD).read() & 0x20 == 0 {}
            x86_64::instructions::port::Port::new(0x3F8).write(b);
        }
    }
}

// ---------------------------------------------------------------------------
// Phase 54: sys_block_read — raw sector reads for ring-3 storage servers
// ---------------------------------------------------------------------------

/// Allowed caller binaries for raw block reads.
///
/// In production (`hardened` feature), only supervised storage servers
/// may call `sys_block_read`. Without `hardened`, the integration test
/// binary `/bin/nvme-crash-smoke` is also permitted so it can observe
/// `EAGAIN` from the kernel facade's `DriverRestarting` path — a
/// behaviour that is only visible through `RemoteBlockDevice`, not through
/// the direct IPC channel the smoke binary normally uses.
const STORAGE_SERVICE_UID: u32 = 200;
#[cfg(not(feature = "hardened"))]
const BLOCK_READ_ALLOWED: &[&str] = &[
    "/bin/vfs_server",
    "/bin/fat_server",
    "/bin/nvme-crash-smoke",
];
#[cfg(feature = "hardened")]
const BLOCK_READ_ALLOWED: &[&str] = &["/bin/vfs_server", "/bin/fat_server"];

/// Read raw disk sectors into a userspace buffer.
///
/// # Arguments
///   - `start_sector`: absolute LBA of the first sector
///   - `count`: number of 512-byte sectors to read
///   - `buf_ptr`: userspace destination address
///   - `buf_len`: size of the destination buffer in bytes
///
/// # Returns
///
/// Returns 0 on success, or a negative errno on error:
///
/// | `BlockDriverError` | byte | errno returned     |
/// |---|---|---|
/// | `Ok`               | 0    | 0 (success)        |
/// | `IoError`          | 1    | `NEG_EIO` (-5)     |
/// | `InvalidLba`       | 2    | `NEG_EIO` (-5)     |
/// | `DeviceAbsent`     | 3    | `NEG_EIO` (-5)     |
/// | `Busy`             | 4    | `NEG_EAGAIN` (-11) |
/// | `DriverRestarting` | 5    | `NEG_EAGAIN` (-11) |
/// | `InvalidRequest`   | 6    | `NEG_EIO` (-5)     |
///
/// `Busy` and `DriverRestarting` map to `EAGAIN` so callers can distinguish
/// a temporary driver restart from a permanent I/O failure. The mapping is
/// the single source of truth in
/// `kernel_core::driver_ipc::block::block_error_to_neg_errno`
/// (tested in `kernel-core/src/driver_ipc/block.rs`, Phase 55b Track F.3c).
///
/// Capped at 128 sectors (64 KiB) per call for safety.
///
/// Only supervised storage services may call this syscall. The kernel requires
/// both a dedicated service euid (`STORAGE_SERVICE_UID = 200`) and an expected
/// service binary path so ordinary users cannot gain raw-disk access by
/// directly exec'ing a public `/bin/*_server` binary.
fn sys_block_read(start_sector: u64, count: u64, buf_ptr: u64, buf_len: u64) -> u64 {
    // Restrict to supervised storage services.
    {
        let pid = crate::process::current_pid();
        let table = crate::process::PROCESS_TABLE.lock();
        let allowed = table.find(pid).is_some_and(|p| {
            p.euid == STORAGE_SERVICE_UID && BLOCK_READ_ALLOWED.iter().any(|a| p.exec_path == *a)
        });
        if !allowed {
            return NEG_EPERM;
        }
    }

    const MAX_SECTORS: usize = 128; // 64 KiB

    let count = count as usize;
    if count == 0 || count > MAX_SECTORS {
        return NEG_EINVAL;
    }

    let needed = count * 512;
    if needed > buf_len as usize {
        return NEG_EINVAL;
    }

    let mut kernel_buf = alloc::vec![0u8; needed];
    match crate::blk::read_sectors(start_sector, count, &mut kernel_buf) {
        Ok(()) => {
            if UserSliceWo::new(buf_ptr, needed)
                .and_then(|s| s.copy_from_kernel(&kernel_buf))
                .is_err()
            {
                return NEG_EFAULT;
            }
            0
        }
        // Propagate the driver error byte through the documented errno mapping.
        // DriverRestarting (5) and Busy (4) → EAGAIN (-11); all others → EIO (-5).
        // Single source of truth: kernel_core::driver_ipc::block::block_error_to_neg_errno.
        Err(error_byte) => {
            kernel_core::driver_ipc::block::block_error_to_neg_errno(error_byte) as u64
        }
    }
}

// ---------------------------------------------------------------------------
// Phase 55b Track F.3d-2: sys_block_write — raw sector writes for ring-3
// storage servers and integration tests
// ---------------------------------------------------------------------------

/// Allowed caller binaries for raw block writes.
///
/// The write whitelist is intentionally identical to `BLOCK_READ_ALLOWED`:
/// only supervised storage servers and (in non-hardened builds) the
/// `nvme-crash-smoke` integration test binary may issue raw disk writes.
/// The symmetric design means the same privilege gate governs both paths,
/// simplifying the audit surface.
#[cfg(not(feature = "hardened"))]
const BLOCK_WRITE_ALLOWED: &[&str] = &[
    "/bin/vfs_server",
    "/bin/fat_server",
    "/bin/nvme-crash-smoke",
];
#[cfg(feature = "hardened")]
const BLOCK_WRITE_ALLOWED: &[&str] = &["/bin/vfs_server", "/bin/fat_server"];

/// Phase 87: commit the block device's write-back cache to media (`blk::flush`).
///
/// Lets the supervised storage service (vfs_server) force a device `FLUSH`
/// periodically / on demand so write-back buffered writes become durable on
/// physical media without waiting for clean shutdown — bounding a host
/// crash / power-loss data-loss window. Gated identically to `sys_block_write`
/// (euid == `STORAGE_SERVICE_UID` and exec path in `BLOCK_WRITE_ALLOWED`).
///
/// Returns 0 when the caller is authorized — regardless of whether the device
/// flush actually succeeded — or `NEG_EPERM` if the caller is not an authorized
/// storage service. The flush is best-effort: `blk::flush` logs a warning on
/// driver error and its result is intentionally NOT surfaced through this
/// return value, mirroring the shutdown flush. Callers must not treat a 0
/// return as proof the write-back cache reached media.
fn sys_block_flush() -> u64 {
    {
        let pid = crate::process::current_pid();
        let table = crate::process::PROCESS_TABLE.lock();
        let allowed = table.find(pid).is_some_and(|p| {
            p.euid == STORAGE_SERVICE_UID && BLOCK_WRITE_ALLOWED.iter().any(|a| p.exec_path == *a)
        });
        if !allowed {
            return NEG_EPERM;
        }
    }
    crate::blk::flush();
    0
}

/// Write raw disk sectors from a userspace buffer.
///
/// # Arguments
///   - `start_sector`: absolute LBA of the first sector
///   - `count`: number of 512-byte sectors to write
///   - `buf_ptr`: userspace source address
///   - `buf_len`: size of the source buffer in bytes
///
/// # Returns
///
/// Returns 0 on success, or a negative errno on error.
/// The errno mapping is identical to `sys_block_read`:
///
/// | `BlockDriverError` | byte | errno returned     |
/// |---|---|---|
/// | `Ok`               | 0    | 0 (success)        |
/// | `IoError`          | 1    | `NEG_EIO` (-5)     |
/// | `InvalidLba`       | 2    | `NEG_EIO` (-5)     |
/// | `DeviceAbsent`     | 3    | `NEG_EIO` (-5)     |
/// | `Busy`             | 4    | `NEG_EAGAIN` (-11) |
/// | `DriverRestarting` | 5    | `NEG_EAGAIN` (-11) |
/// | `InvalidRequest`   | 6    | `NEG_EIO` (-5)     |
///
/// `DriverRestarting` maps to `EAGAIN` so callers can distinguish a temporary
/// driver restart from a permanent I/O failure. Single source of truth:
/// `kernel_core::driver_ipc::block::block_error_to_neg_errno`.
///
/// Capped at 128 sectors (64 KiB) per call, matching `sys_block_read`.
///
/// Privilege gate is symmetric with `sys_block_read`: euid must equal
/// `STORAGE_SERVICE_UID` (200) and the exec path must appear in
/// `BLOCK_WRITE_ALLOWED`. This prevents unprivileged callers from issuing
/// raw disk writes through the facade.
fn sys_block_write(start_sector: u64, count: u64, buf_ptr: u64, buf_len: u64) -> u64 {
    // Restrict to supervised storage services (symmetric with sys_block_read).
    {
        let pid = crate::process::current_pid();
        let table = crate::process::PROCESS_TABLE.lock();
        let allowed = table.find(pid).is_some_and(|p| {
            p.euid == STORAGE_SERVICE_UID && BLOCK_WRITE_ALLOWED.iter().any(|a| p.exec_path == *a)
        });
        if !allowed {
            return NEG_EPERM;
        }
    }

    const MAX_SECTORS: usize = 128; // 64 KiB — matches sys_block_read cap

    let count = count as usize;
    if count == 0 || count > MAX_SECTORS {
        return NEG_EINVAL;
    }

    let needed = count * 512;
    if needed > buf_len as usize {
        return NEG_EINVAL;
    }

    // Copy the data from userspace into a kernel-owned buffer before
    // dispatching to the block layer so we hold no user pointer across
    // the potential IPC boundary to the ring-3 NVMe driver.
    let mut kernel_buf = alloc::vec![0u8; needed];
    if UserSliceRo::new(buf_ptr, needed)
        .and_then(|s| s.copy_to_kernel(&mut kernel_buf))
        .is_err()
    {
        return NEG_EFAULT;
    }

    match crate::blk::write_sectors(start_sector, count, &kernel_buf) {
        Ok(()) => {
            // Phase 95c — record the written range so the next `invalidate_cache`
            // (after this routed mutation) drops ONLY these blocks from the
            // in-kernel ext2 cache, not the whole thing. This is the choke point
            // for every `vfs_server` root mutation, so the record is complete.
            crate::fs::ext2::record_dirty_root_write(start_sector, count);
            0
        }
        // Propagate the driver error byte through the documented errno mapping.
        // DriverRestarting (5) and Busy (4) → EAGAIN (-11); all others → EIO (-5).
        // Single source of truth: kernel_core::driver_ipc::block::block_error_to_neg_errno.
        Err(error_byte) => {
            kernel_core::driver_ipc::block::block_error_to_neg_errno(error_byte) as u64
        }
    }
}

// ---------------------------------------------------------------------------
// T020: brk(addr)
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_brk(addr: u64) -> u64 {
    let pid = crate::process::current_pid();
    let addr_space = {
        let table = crate::process::PROCESS_TABLE.lock();
        table.find(pid).and_then(|p| p.addr_space.as_ref().cloned())
    };
    let mut result = 0;
    let mut shootdown_end = 0;
    let mut grew_any = false;
    let current = {
        let _page_table_guard = addr_space
            .as_ref()
            .map(|addr_space| addr_space.lock_page_tables());

        // Always initialise brk_current to BRK_BASE if it is still 0, regardless
        // of the requested addr.  This ensures that even a first call with a
        // nonzero addr has a valid base to grow from, and if page mapping fails
        // later we still have a consistent brk_current.
        let current_brk =
            match crate::process::with_shared_mm_mut(pid, |brk_current, _mmap_next, _vma_tree| {
                if *brk_current == 0 {
                    *brk_current = BRK_BASE;
                }
                *brk_current
            }) {
                Some(current) => current,
                None => return 0,
            };

        // brk(0) or no-advance: just return current break.
        if addr == 0 || addr <= current_brk {
            result = current_brk;
        } else {
            // Align new break up to page boundary.
            let new_brk = match addr.checked_add(0xFFF) {
                Some(v) => v & !0xFFF,
                None => {
                    result = current_brk;
                    0
                }
            };
            // Reject non-canonical / kernel-range addresses.
            if result == 0 && new_brk > 0x0000_7FFF_FFFF_FFFF {
                result = current_brk;
            }
            if result == 0 {
                let pages_needed = (new_brk - current_brk) / 4096;

                use x86_64::{VirtAddr, structures::paging::PageTableFlags};
                let flags = PageTableFlags::PRESENT
                    | PageTableFlags::WRITABLE
                    | PageTableFlags::USER_ACCESSIBLE
                    | PageTableFlags::NO_EXECUTE;
                let mut committed_brk = current_brk;

                for i in 0..pages_needed {
                    let vaddr = VirtAddr::new(current_brk + i * 4096);
                    // Zero-before-exposure (D.4): user-visible brk frame.
                    let frame = match crate::mm::frame_allocator::allocate_frame_zeroed() {
                        Some(f) => f,
                        None => {
                            log::warn!("[brk] out of frames at page {}/{}", i, pages_needed);
                            result = committed_brk;
                            break;
                        }
                    };
                    if unsafe {
                        crate::mm::paging::map_current_user_page_locked(vaddr, frame, flags)
                    }
                    .is_err()
                    {
                        log::warn!("[brk] map_current_user_page failed at page {}", i);
                        crate::mm::frame_allocator::free_frame(frame.start_address().as_u64());
                        result = committed_brk;
                        break;
                    }
                    committed_brk = current_brk + (i + 1) * 4096;
                    let _ = crate::process::with_shared_mm_mut(
                        pid,
                        |brk_current, _mmap_next, _vma_tree| *brk_current = committed_brk,
                    );
                    grew_any = true;
                }

                if result == 0 {
                    result = committed_brk;
                }
                shootdown_end = committed_brk;
            }
        }
        current_brk
    };

    if grew_any
        && shootdown_end > current
        && let Some(addr_space) = addr_space.as_ref()
    {
        crate::smp::tlb::tlb_shootdown_range(addr_space, current, shootdown_end);
        addr_space.bump_generation();
    }

    // Omit per-call log to avoid flooding serial during high-alloc workloads.
    result
}

// ---------------------------------------------------------------------------
// T023: writev(fd, iov, iovcnt)
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_writev(fd: u64, iov_ptr: u64, iovcnt: u64) -> u64 {
    if iovcnt > 1024 {
        return NEG_EINVAL;
    }
    let iovcnt = iovcnt as usize;
    let mut total = 0u64;
    for i in 0..iovcnt {
        // struct iovec { void *base (8B), size_t len (8B) }
        let offset = match (i as u64).checked_mul(16) {
            Some(v) => v,
            None => return NEG_EFAULT,
        };
        let iov_addr = match iov_ptr.checked_add(offset) {
            Some(a) => a,
            None => return NEG_EFAULT,
        };
        let mut iov_bytes = [0u8; 16];
        if UserSliceRo::new(iov_addr, iov_bytes.len())
            .and_then(|s| s.copy_to_kernel(&mut iov_bytes))
            .is_err()
        {
            if total == 0 {
                return NEG_EFAULT;
            }
            break;
        }
        let base = u64::from_ne_bytes(iov_bytes[0..8].try_into().unwrap());
        let len = u64::from_ne_bytes(iov_bytes[8..16].try_into().unwrap());
        if len == 0 {
            continue;
        }
        let written = sys_linux_write(fd, base, len);
        if (written as i64) < 0 {
            // If no bytes transferred yet, propagate the error.
            if total == 0 {
                return written;
            }
            break;
        }
        if written == 0 {
            break;
        }
        total += written;
        // Short write: fewer bytes than requested means we should stop.
        if written < len {
            break;
        }
    }
    total
}

// ---------------------------------------------------------------------------
// T023: readv(fd, iov, iovcnt)
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_readv(fd: u64, iov_ptr: u64, iovcnt: u64) -> u64 {
    if iovcnt > 1024 {
        return NEG_EINVAL;
    }
    let iovcnt = iovcnt as usize;
    let mut total = 0u64;
    for i in 0..iovcnt {
        let offset = match (i as u64).checked_mul(16) {
            Some(v) => v,
            None => return NEG_EFAULT,
        };
        let iov_addr = match iov_ptr.checked_add(offset) {
            Some(a) => a,
            None => return NEG_EFAULT,
        };
        let mut iov_bytes = [0u8; 16];
        if UserSliceRo::new(iov_addr, iov_bytes.len())
            .and_then(|s| s.copy_to_kernel(&mut iov_bytes))
            .is_err()
        {
            if total == 0 {
                return NEG_EFAULT;
            }
            break;
        }
        let base = u64::from_ne_bytes(iov_bytes[0..8].try_into().unwrap());
        let len = u64::from_ne_bytes(iov_bytes[8..16].try_into().unwrap());
        if len == 0 {
            continue;
        }
        let n = sys_linux_read(fd, base, len);
        if (n as i64) < 0 {
            // If no bytes transferred yet, propagate the error.
            if total == 0 {
                return n;
            }
            break;
        }
        if n == 0 {
            break; // EOF
        }
        total += n;
        // Short read: fewer bytes than requested means EOF / no more data.
        if n < len {
            break;
        }
    }
    total
}

// ---------------------------------------------------------------------------
// T024: getcwd(buf, size) — return per-process working directory
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_getcwd(buf_ptr: u64, size: u64) -> u64 {
    let cwd = current_cwd();
    let cwd_bytes = cwd.as_bytes();
    let total_len = cwd_bytes.len() + 1; // include null terminator
    if (size as usize) < total_len {
        const NEG_ERANGE: u64 = (-34_i64) as u64;
        return NEG_ERANGE;
    }
    // Copy path, then write a single null terminator — no heap allocation.
    if UserSliceWo::new(buf_ptr, cwd_bytes.len())
        .and_then(|s| s.copy_from_kernel(cwd_bytes))
        .is_err()
    {
        return NEG_EFAULT;
    }
    let terminator_ptr = match buf_ptr.checked_add(cwd_bytes.len() as u64) {
        Some(p) => p,
        None => return NEG_EFAULT,
    };
    if UserSliceWo::new(terminator_ptr, [0u8].len())
        .and_then(|s| s.copy_from_kernel(&[0u8]))
        .is_err()
    {
        return NEG_EFAULT;
    }
    // Linux getcwd returns the length of the path (including null terminator).
    total_len as u64
}

// ---------------------------------------------------------------------------
// T024: chdir(path) — resolve path, validate directory, update process cwd
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_chdir(path_ptr: u64) -> u64 {
    // MOUNT_OP_LOCK intentionally not held — `resolve_existing_fs_path`
    // can issue blocking IPC via the VFS service (Phase 54).
    let mut buf = [0u8; 512];
    let name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    let lexical = match resolve_path_from_dirfd(AT_FDCWD, name) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let resolved = match resolve_existing_fs_path(&lexical, true) {
        Ok(path) => path,
        Err(err) => return err,
    };

    // Phase 27: Execute (search) permission on target directory.
    if let Some((fu, fg, fm)) = path_metadata(&resolved) {
        let (_, _, euid, egid) = current_process_ids();
        if !check_permission(fu, fg, fm, euid, egid, 1) {
            return NEG_EACCES;
        }
    }

    // Verify the resolved path exists and is a directory.
    if !is_directory(&resolved) {
        // Path is not a directory — check if it exists at all to choose error.
        if let Some(rel) = tmpfs_relative_path(&resolved) {
            if !rel.is_empty() {
                let tmpfs = crate::fs::tmpfs::TMPFS.lock();
                if tmpfs.stat(rel).is_ok() {
                    return NEG_ENOTDIR;
                }
            }
        } else if crate::fs::ramdisk::ramdisk_lookup(&resolved).is_some() {
            return NEG_ENOTDIR;
        }
        return NEG_ENOENT;
    }

    let pid = crate::process::current_pid();
    let mut table = crate::process::PROCESS_TABLE.lock();
    if let Some(proc) = table.find_mut(pid) {
        proc.cwd = resolved;
    }
    0
}

// ---------------------------------------------------------------------------
// T025: ioctl — TIOCGWINSZ only
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_ioctl(fd: u64, req: u64, arg: u64) -> u64 {
    // Musl declares ioctl(int, int, ...) — the request code is sign-extended
    // from 32 bits.  Truncate to u32 so _IOR/_IOW constants with bit 31 set
    // (e.g., TIOCGPTN = 0x80045430) compare correctly.
    let req = (req as u32) as u64;
    use kernel_core::tty::{TERMIOS_SIZE, WINSIZE_SIZE};
    const TCGETS: u64 = 0x5401;
    const TCSETS: u64 = 0x5402;
    const TCSETSW: u64 = 0x5403;
    const TCSETSF: u64 = 0x5404;
    const TIOCGPGRP: u64 = 0x540F;
    const TIOCSPGRP: u64 = 0x5410;
    const TIOCGWINSZ: u64 = 0x5413;
    const TIOCSWINSZ: u64 = 0x5414;
    const NEG_ENOTTY: u64 = (-25_i64) as u64;

    const TIOCGPTN: u64 = 0x80045430; // _IOR('T', 0x30, unsigned int)

    // Check if the fd is a TTY or PTY; non-TTY fds return ENOTTY.
    let fd_idx = fd as usize;
    let backend = if fd_idx < MAX_FDS {
        current_fd_entry(fd_idx).map(|e| e.backend.clone())
    } else {
        None
    };

    // FIONBIO toggles O_NONBLOCK on ANY fd (pipe / socket / file), like Linux —
    // NOT just TTYs, so it must be handled BEFORE the `is_tty` ENOTTY gate below.
    // Rust std's `FileDesc::set_nonblocking` (Linux target) issues
    // `ioctl(fd, FIONBIO, &c_int)`; `std::process::read_output` uses it to drain a
    // child's stdout+stderr pipes via `poll` (see library/std/src/process.rs:2385,
    // `wait_with_output`). Returning ENOTTY for the pipe fd made rustc panic while
    // reading `rust-lld`'s output, blocking on-device codegen (Phase 95b). Mirror
    // the `fcntl(F_SETFL, O_NONBLOCK)` path: set the `FdEntry.nonblock` flag the
    // read paths already honor (EAGAIN when set + no data).
    const FIONBIO: u64 = 0x5421;
    if req == FIONBIO {
        if backend.is_none() {
            return NEG_EBADF;
        }
        let mut val = [0u8; 4];
        if UserSliceRo::new(arg, val.len())
            .and_then(|s| s.copy_to_kernel(&mut val))
            .is_err()
        {
            return NEG_EFAULT;
        }
        let nonblock = i32::from_ne_bytes(val) != 0;
        with_current_fd_mut(fd_idx, |slot| {
            if let Some(e) = slot {
                e.nonblock = nonblock;
            }
        });
        return 0;
    }

    let is_tty = matches!(
        &backend,
        Some(FdBackend::DeviceTTY { .. })
            | Some(FdBackend::PtyMaster { .. })
            | Some(FdBackend::PtySlave { .. })
    );

    if !is_tty {
        return NEG_ENOTTY;
    }

    // Helper: extract PTY ID from the backend (if it's a PTY FD).
    let pty_id = match &backend {
        Some(FdBackend::PtyMaster { pty_id }) | Some(FdBackend::PtySlave { pty_id }) => {
            Some(*pty_id)
        }
        _ => None,
    };
    let is_pty_master = matches!(&backend, Some(FdBackend::PtyMaster { .. }));

    // TIOCGPTN: return PTY number for master fds.
    if req == TIOCGPTN {
        if let Some(FdBackend::PtyMaster { pty_id }) = &backend {
            let bytes = (*pty_id).to_ne_bytes();
            if UserSliceWo::new(arg, bytes.len())
                .and_then(|s| s.copy_from_kernel(&bytes))
                .is_err()
            {
                return NEG_EFAULT;
            }
            return 0;
        }
        return NEG_EINVAL;
    }

    const TIOCSPTLCK: u64 = 0x40045431;
    const TIOCGRANTPT: u64 = 0x5417;
    const TIOCSCTTY: u64 = 0x540E;
    const TIOCNOTTY: u64 = 0x5422;

    // TIOCSPTLCK: lock/unlock the PTY slave.
    if req == TIOCSPTLCK {
        if let Some(id) = pty_id
            && is_pty_master
        {
            let mut lock_val = [0u8; 4];
            if UserSliceRo::new(arg, lock_val.len())
                .and_then(|s| s.copy_to_kernel(&mut lock_val))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let val = i32::from_ne_bytes(lock_val);
            let mut table = crate::pty::PTY_TABLE.lock();
            if let Some(Some(pair)) = table.get_mut(id as usize) {
                pair.locked = val != 0;
                return 0;
            }
            return NEG_EIO;
        }
        return NEG_EINVAL; // not a PTY master
    }

    // TIOCGRANTPT: no-op (permissions not enforced yet).
    if req == TIOCGRANTPT {
        return 0;
    }

    // TIOCSCTTY: set controlling terminal for the session.
    if req == TIOCSCTTY {
        if let Some(FdBackend::PtySlave { pty_id }) = &backend {
            let calling_pid = crate::process::current_pid();
            let pty_id_val = *pty_id;
            let caller_pgid = {
                let pt = crate::process::PROCESS_TABLE.lock();
                pt.find(calling_pid).map(|p| p.pgid).unwrap_or(0)
            };
            let mut pt = crate::process::PROCESS_TABLE.lock();
            if let Some(proc) = pt.find_mut(calling_pid) {
                // Must be session leader with no controlling terminal.
                if proc.session_id != calling_pid || proc.controlling_tty.is_some() {
                    return NEG_EPERM;
                }
                proc.controlling_tty = Some(crate::process::ControllingTty::Pty(pty_id_val));
            }
            drop(pt);
            // Linux 4.6+ behaviour: when a session leader binds an empty-fg-pgrp
            // controlling tty via TIOCSCTTY, automatically populate the PTY's
            // foreground process group with the caller's pgid. Without this,
            // `close_master`'s SIGHUP-to-fg-pgrp path is a no-op (sends to
            // pgid 0) and the ion shell never receives SIGHUP on disconnect.
            if caller_pgid != 0 {
                crate::pty::set_slave_fg_pgid(pty_id_val, caller_pgid);
            }
            return 0;
        }
        return NEG_EINVAL;
    }

    // TIOCNOTTY: release controlling terminal.
    if req == TIOCNOTTY {
        let calling_pid = crate::process::current_pid();
        let mut pt = crate::process::PROCESS_TABLE.lock();
        if let Some(proc) = pt.find_mut(calling_pid) {
            proc.controlling_tty = None;
        }
        return 0;
    }

    match req {
        TCGETS => {
            if let Some(id) = pty_id {
                // Phase 69a Track B: termios lives on the slave; the master
                // is not a terminal device, so it returns ENOTTY (matches
                // Linux n_tty.c — the master fd's tty_operations->ioctl is
                // distinct from the slave's).
                if is_pty_master {
                    return NEG_ENOTTY;
                }
                let table = crate::pty::PTY_TABLE.lock();
                if let Some(Some(pair)) = table.get(id as usize) {
                    let src = unsafe {
                        core::slice::from_raw_parts(
                            &pair.termios as *const _ as *const u8,
                            TERMIOS_SIZE,
                        )
                    };
                    if UserSliceWo::new(arg, src.len())
                        .and_then(|s| s.copy_from_kernel(src))
                        .is_err()
                    {
                        return NEG_EFAULT;
                    }
                    return 0;
                }
                return NEG_EIO;
            }
            // Console TTY0.
            let tty = crate::tty::TTY0.lock();
            let src = unsafe {
                core::slice::from_raw_parts(
                    &tty.ldisc.termios as *const _ as *const u8,
                    TERMIOS_SIZE,
                )
            };
            if UserSliceWo::new(arg, src.len())
                .and_then(|s| s.copy_from_kernel(src))
                .is_err()
            {
                return NEG_EFAULT;
            }
            0
        }
        TCSETS | TCSETSW => {
            let mut buf = [0u8; TERMIOS_SIZE];
            if UserSliceRo::new(arg, buf.len())
                .and_then(|s| s.copy_to_kernel(&mut buf))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let new_termios = unsafe {
                core::ptr::read_unaligned(buf.as_ptr() as *const kernel_core::tty::Termios)
            };
            if let Some(id) = pty_id {
                if is_pty_master {
                    return NEG_ENOTTY;
                }
                let mut table = crate::pty::PTY_TABLE.lock();
                if let Some(Some(pair)) = table.get_mut(id as usize) {
                    pair.termios = new_termios;
                    return 0;
                }
                return NEG_EIO;
            }
            crate::tty::TTY0.lock().ldisc.termios = new_termios;
            0
        }
        TCSETSF => {
            let mut buf = [0u8; TERMIOS_SIZE];
            if UserSliceRo::new(arg, buf.len())
                .and_then(|s| s.copy_to_kernel(&mut buf))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let new_termios = unsafe {
                core::ptr::read_unaligned(buf.as_ptr() as *const kernel_core::tty::Termios)
            };
            if let Some(id) = pty_id {
                if is_pty_master {
                    return NEG_ENOTTY;
                }
                let mut table = crate::pty::PTY_TABLE.lock();
                if let Some(Some(pair)) = table.get_mut(id as usize) {
                    pair.edit_buf.clear();
                    pair.m2s.clear();
                    pair.eof_pending = false;
                    pair.termios = new_termios;
                    return 0;
                }
                return NEG_EIO;
            }
            crate::stdin::flush();
            let mut tty = crate::tty::TTY0.lock();
            tty.ldisc.edit_buf.clear();
            tty.ldisc.termios = new_termios;
            0
        }
        TIOCGPGRP => {
            if let Some(id) = pty_id {
                let table = crate::pty::PTY_TABLE.lock();
                if let Some(Some(pair)) = table.get(id as usize) {
                    let pgid = pair.slave_fg_pgid;
                    let bytes = (pgid as i32).to_ne_bytes();
                    if UserSliceWo::new(arg, bytes.len())
                        .and_then(|s| s.copy_from_kernel(&bytes))
                        .is_err()
                    {
                        return NEG_EFAULT;
                    }
                    return 0;
                }
                return NEG_EIO;
            }
            let tty = crate::tty::TTY0.lock();
            let pgid = tty.fg_pgid;
            let bytes = (pgid as i32).to_ne_bytes();
            if UserSliceWo::new(arg, bytes.len())
                .and_then(|s| s.copy_from_kernel(&bytes))
                .is_err()
            {
                return NEG_EFAULT;
            }
            0
        }
        TIOCSPGRP => {
            let mut bytes = [0u8; 4];
            if UserSliceRo::new(arg, bytes.len())
                .and_then(|s| s.copy_to_kernel(&mut bytes))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let pgid = i32::from_ne_bytes(bytes) as u32;
            if let Some(id) = pty_id {
                let mut table = crate::pty::PTY_TABLE.lock();
                if let Some(Some(pair)) = table.get_mut(id as usize) {
                    pair.slave_fg_pgid = pgid;
                    return 0;
                }
                return NEG_EIO;
            }
            crate::tty::TTY0.lock().fg_pgid = pgid;
            crate::process::FG_PGID.store(pgid, core::sync::atomic::Ordering::Relaxed);
            0
        }
        TIOCGWINSZ => {
            if let Some(id) = pty_id {
                let table = crate::pty::PTY_TABLE.lock();
                if let Some(Some(pair)) = table.get(id as usize) {
                    let src = unsafe {
                        core::slice::from_raw_parts(
                            &pair.winsize as *const _ as *const u8,
                            WINSIZE_SIZE,
                        )
                    };
                    if UserSliceWo::new(arg, src.len())
                        .and_then(|s| s.copy_from_kernel(src))
                        .is_err()
                    {
                        return NEG_EFAULT;
                    }
                    return 0;
                }
                return NEG_EIO;
            }
            let tty = crate::tty::TTY0.lock();
            let src = unsafe {
                core::slice::from_raw_parts(&tty.winsize as *const _ as *const u8, WINSIZE_SIZE)
            };
            if UserSliceWo::new(arg, src.len())
                .and_then(|s| s.copy_from_kernel(src))
                .is_err()
            {
                return NEG_EFAULT;
            }
            0
        }
        TIOCSWINSZ => {
            let mut buf = [0u8; WINSIZE_SIZE];
            if UserSliceRo::new(arg, buf.len())
                .and_then(|s| s.copy_to_kernel(&mut buf))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let new_ws = unsafe {
                core::ptr::read_unaligned(buf.as_ptr() as *const kernel_core::tty::Winsize)
            };
            if let Some(id) = pty_id {
                let mut table = crate::pty::PTY_TABLE.lock();
                if let Some(Some(pair)) = table.get_mut(id as usize) {
                    let changed = pair.winsize.ws_row != new_ws.ws_row
                        || pair.winsize.ws_col != new_ws.ws_col;
                    pair.winsize = new_ws;
                    let fg = pair.slave_fg_pgid;
                    drop(table);
                    if changed && fg != 0 {
                        crate::process::send_signal_to_group(fg, crate::process::SIGWINCH);
                    }
                    return 0;
                }
                return NEG_EIO;
            }
            let mut tty = crate::tty::TTY0.lock();
            let changed =
                tty.winsize.ws_row != new_ws.ws_row || tty.winsize.ws_col != new_ws.ws_col;
            tty.winsize = new_ws;
            let fg = tty.fg_pgid;
            drop(tty);
            if changed && fg != 0 {
                crate::process::send_signal_to_group(fg, crate::process::SIGWINCH);
            }
            0
        }
        _ => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// T026: uname(buf) — writes a fixed struct utsname
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_uname(buf_ptr: u64) -> u64 {
    // struct utsname: 6 fields of 65 bytes each = 390 bytes
    let mut utsname = [0u8; 390];
    let fill = |dst: &mut [u8], s: &[u8]| {
        let n = s.len().min(dst.len() - 1);
        dst[..n].copy_from_slice(&s[..n]);
    };
    fill(&mut utsname[0..65], b"m3os"); // sysname
    fill(&mut utsname[65..130], b"m3os"); // nodename
    fill(&mut utsname[130..195], env!("CARGO_PKG_VERSION").as_bytes()); // release
    fill(&mut utsname[195..260], env!("CARGO_PKG_VERSION").as_bytes()); // version
    fill(&mut utsname[260..325], b"x86_64"); // machine
    // domainname left as zero
    if UserSliceWo::new(buf_ptr, utsname.len())
        .and_then(|s| s.copy_from_kernel(&utsname))
        .is_err()
    {
        return NEG_EFAULT;
    }
    0
}

// ---------------------------------------------------------------------------
// T026 (via path): newfstatat(dirfd, path, stat_ptr, flags)
// ---------------------------------------------------------------------------

/// Phase 88 — the single source of truth for *path-based* `stat` metadata.
///
/// Given an already-resolved absolute path, build the full [`FileMeta`] for it
/// (with `st_dev` set per filesystem), or an errno on failure. `sys_linux_fstatat`
/// (by path) AND `sys_linux_fstat`'s `FdBackend::Dir` arm (by fd) both call this,
/// so the by-path and by-fd answers cannot diverge — closing the exact
/// `(st_dev, st_ino)`/metadata inconsistency Phase 88 exists to eliminate (the
/// `fstat`-on-a-directory-fd path previously reported `ino=nlink=size=times=0`).
fn path_filemeta(name: &str) -> Result<FileMeta, u64> {
    if let Some(st) = crate::fs::procfs::stat(name) {
        let mut m = FileMeta::new();
        m.dev = DEV_PROCFS;
        m.ino = st.ino;
        m.nlink = st.nlink;
        m.mode = st.mode;
        m.uid = st.uid;
        m.gid = st.gid;
        m.size = st.size;
        return Ok(m);
    }

    // Check tmpfs first.
    if let Some(rel) = tmpfs_relative_path(name) {
        let tmpfs = crate::fs::tmpfs::TMPFS.lock();
        let st = match tmpfs.stat(rel) {
            Ok(s) => s,
            Err(crate::fs::tmpfs::TmpfsError::NotFound) => return Err(NEG_ENOENT),
            Err(crate::fs::tmpfs::TmpfsError::NotADirectory) => {
                return Err(NEG_ENOTDIR);
            }
            Err(_) => return Err(NEG_EINVAL),
        };
        // Phase 69d follow-up: if this tmpfs path is currently bound
        // to a Unix-domain socket, stat must report `S_IFSOCK`
        // (0xC000) instead of `S_IFREG` (0x8000) — tmux's
        // `S_ISSOCK(sb.st_mode)` check on the socket file refuses
        // with "access not allowed" otherwise, which surfaces after
        // a detach + reconnect when the client revalidates the
        // already-bound socket.
        let is_bound_socket =
            !st.is_dir && !st.is_symlink && crate::net::unix::lookup_path(name).is_some();
        let mode: u32 = if st.is_dir {
            0x4000 | st.mode as u32
        } else if st.is_symlink {
            0xA000 | 0o777
        } else if is_bound_socket {
            0xC000 | st.mode as u32
        } else {
            0x8000 | st.mode as u32
        };
        let mut m = FileMeta::new();
        m.dev = DEV_TMPFS;
        m.ino = st.ino;
        m.nlink = st.nlink;
        m.mode = mode;
        m.uid = st.uid;
        m.gid = st.gid;
        m.size = st.size as u64;
        drop(tmpfs);
        return Ok(m);
    }

    // Phase 92a D.4: a /mnt/usbN path stats against the secondary mount's own
    // ext2 volume (checked before ramdisk/root-ext2, matching the open/getdents
    // routing precedence). Without this, stat falls through to the root device
    // and returns ENOENT for a file that exists on the USB volume — and its
    // `st_ino` would not match the getdents64 `d_ino` from the same volume.
    // `with_usb_mount` short-circuits to None when no secondary mount is active.
    if let Some(res) = crate::fs::ext2::with_usb_mount(name, |vol, rel| {
        let ino = match vol.resolve_path(rel) {
            Ok(ino) => ino,
            Err(kernel_core::fs::ext2::Ext2Error::NotFound) => return Err(NEG_ENOENT),
            Err(kernel_core::fs::ext2::Ext2Error::NotDirectory) => return Err(NEG_ENOTDIR),
            Err(_) => return Err(NEG_EIO),
        };
        let inode = vol.read_inode(ino).map_err(|_| NEG_EIO)?;
        let mut m = FileMeta::new();
        m.dev = DEV_EXT2_ROOT;
        m.ino = ino as u64;
        m.nlink = inode.links_count as u64;
        m.mode = inode.mode as u32;
        m.uid = inode.uid as u32;
        m.gid = inode.gid as u32;
        m.size = inode.size as u64;
        m.blksize = vol.block_size as u64;
        m.blocks = inode.blocks as u64;
        m.atime = inode.atime as i64;
        m.mtime = inode.mtime as i64;
        m.ctime = inode.ctime as i64;
        Ok(m)
    }) {
        return res;
    }

    // Check ramdisk tree (supports directories and hierarchical paths).
    match crate::fs::ramdisk::ramdisk_lookup(name) {
        Some(crate::fs::ramdisk::RamdiskNode::File { content }) => {
            let mut m = FileMeta::new();
            m.dev = DEV_RAMDISK;
            m.mode = 0x8000 | 0o755; // S_IFREG + executable (ramdisk binaries)
            m.size = content.len() as u64;
            Ok(m)
        }
        Some(crate::fs::ramdisk::RamdiskNode::Dir { .. }) => {
            let mut m = FileMeta::new();
            m.dev = DEV_RAMDISK;
            m.mode = 0x4000 | 0o755; // S_IFDIR
            Ok(m)
        }
        None => {
            // ext2 root filesystem: stat any path.
            if crate::fs::ext2::is_mounted()
                && let Some(rel) = ext2_root_path(name)
            {
                if vfs_service_can_handle_path(name)
                    && let Ok(vfs_stat) = vfs_service_stat_path(name)
                {
                    let mut m = FileMeta::new();
                    m.dev = DEV_EXT2_ROOT;
                    m.ino = vfs_stat.ino;
                    m.nlink = vfs_stat.nlink;
                    m.mode = vfs_stat.mode;
                    m.uid = vfs_stat.uid;
                    m.gid = vfs_stat.gid;
                    m.size = vfs_stat.size;
                    m.blksize = vfs_stat.blksize;
                    m.blocks = vfs_stat.blocks;
                    m.atime = vfs_stat.atime;
                    m.mtime = vfs_stat.mtime;
                    m.ctime = vfs_stat.ctime;
                    return Ok(m);
                }
                let vol = crate::fs::ext2::EXT2_VOLUME.lock();
                if let Some(vol) = vol.as_ref()
                    && let Ok(ino) = vol.resolve_path(rel)
                    && let Ok(inode) = vol.read_inode(ino)
                {
                    let mut m = FileMeta::new();
                    m.dev = DEV_EXT2_ROOT;
                    m.ino = ino as u64;
                    m.nlink = inode.links_count as u64;
                    m.mode = inode.mode as u32;
                    m.uid = inode.uid as u32;
                    m.gid = inode.gid as u32;
                    m.size = inode.size as u64;
                    m.blksize = vol.block_size as u64;
                    m.blocks = inode.blocks as u64;
                    // Phase 32: populate timestamps from ext2 inode.
                    m.atime = inode.atime as i64;
                    m.mtime = inode.mtime as i64;
                    m.ctime = inode.ctime as i64;
                    return Ok(m);
                }
            }
            // Device special files.
            if name == "/dev/null"
                || name == "/dev/zero"
                || name == "/dev/urandom"
                || name == "/dev/random"
                || name == "/dev/full"
                || name == "/dev/ptmx"
                // `/dev/tty` (controlling terminal) — report a char device like
                // the others. Without this, `stat("/dev/tty")` falls through to
                // the ext2/`vfs_server` path and hangs on a `VFS_STAT_PATH` IPC
                // for a node the service does not own (Claude Code startup hang).
                || name == "/dev/tty"
                || name.starts_with("/dev/pts/")
            {
                let mut m = FileMeta::new();
                m.dev = DEV_DEVFS;
                m.mode = 0x2000 | 0o666; // S_IFCHR | rw-rw-rw-
                return Ok(m);
            }
            // Also handle "/" specially.
            if name == "/" {
                let mut m = FileMeta::new();
                m.dev = DEV_EXT2_ROOT;
                m.mode = 0x4000 | 0o755;
                return Ok(m);
            }
            Err(NEG_ENOENT)
        }
    }
}

pub(super) fn sys_linux_fstatat(dirfd: u64, path_ptr: u64, stat_ptr: u64, flags: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw_name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    let lexical = match resolve_path_from_dirfd(dirfd, raw_name) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let resolved = match resolve_existing_fs_path(&lexical, flags & AT_SYMLINK_NOFOLLOW == 0) {
        Ok(path) => path,
        Err(err) => return err,
    };

    match path_filemeta(&resolved) {
        Ok(m) => write_stat_to_user(stat_ptr, &m),
        Err(err) => err,
    }
}

pub(super) fn sys_symlink(target_ptr: u64, linkpath_ptr: u64) -> u64 {
    sys_symlinkat(target_ptr, AT_FDCWD, linkpath_ptr)
}

pub(super) fn sys_symlinkat(target_ptr: u64, dirfd: u64, linkpath_ptr: u64) -> u64 {
    let mut target_buf = [0u8; 4096];
    let target = match read_user_cstr(target_ptr, &mut target_buf) {
        Some(s) => s,
        None => return NEG_EFAULT,
    };

    let mut link_buf = [0u8; 512];
    let raw_link = match read_user_cstr(linkpath_ptr, &mut link_buf) {
        Some(s) => s,
        None => return NEG_EFAULT,
    };

    let lexical = match resolve_path_from_dirfd(dirfd, raw_link) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let resolved = match resolve_parent_components(&lexical) {
        Ok(path) => path,
        Err(err) => return err,
    };

    if path_node_nofollow(&resolved).is_ok() {
        return NEG_EEXIST;
    }

    if let Some((pu, pg, pm)) = parent_dir_metadata(&resolved) {
        let (_, _, euid, egid) = current_process_ids();
        if !check_permission(pu, pg, pm, euid, egid, 3) {
            return NEG_EACCES;
        }
    }
    if create_parent_is_read_only(&resolved) {
        return NEG_EROFS;
    }

    match resolve_fs_target(&resolved) {
        FsTarget::Tmpfs(rel) => {
            let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
            let (_, _, euid, egid) = current_process_ids();
            match tmpfs.create_symlink_with_meta(&rel, target, euid, egid) {
                Ok(()) => 0,
                Err(crate::fs::tmpfs::TmpfsError::AlreadyExists) => NEG_EEXIST,
                Err(crate::fs::tmpfs::TmpfsError::NotFound) => NEG_ENOENT,
                Err(crate::fs::tmpfs::TmpfsError::NotADirectory) => NEG_ENOTDIR,
                Err(_) => NEG_EIO,
            }
        }
        FsTarget::DiskData(rel) => {
            if !crate::fs::ext2::is_mounted() {
                return NEG_EROFS;
            }
            let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
            if parts.is_empty() {
                return NEG_EINVAL;
            }
            let link_name = parts[parts.len() - 1];
            let (_, _, euid, egid) = current_process_ids();

            // Phase 88: route ext2 symlink creation to the vfs_server authority
            // when registered (before taking the EXT2_VOLUME spinlock).
            if vfs_write_routable() {
                let name_start = resolved.len() - link_name.len();
                let parent_abs = if parts.len() == 1 {
                    "/"
                } else {
                    &resolved[..name_start]
                };
                return match vfs_service_create(
                    parent_abs,
                    link_name,
                    kernel_core::fs::vfs_protocol::VFS_NODE_SYMLINK,
                    0o777,
                    euid,
                    egid,
                    Some(target),
                ) {
                    Ok(_) => 0,
                    Err(e) => e,
                };
            }

            let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
            let Some(vol) = vol.as_mut() else {
                return NEG_EIO;
            };
            let (parent_ino, link_name) = if parts.len() == 1 {
                (kernel_core::fs::ext2::EXT2_ROOT_INO, parts[0])
            } else {
                let parent_rel = parts[..parts.len() - 1].join("/");
                match vol.resolve_path(&parent_rel) {
                    Ok(ino) => (ino, parts[parts.len() - 1]),
                    Err(kernel_core::fs::ext2::Ext2Error::NotDirectory) => return NEG_ENOTDIR,
                    Err(kernel_core::fs::ext2::Ext2Error::NotFound) => return NEG_ENOENT,
                    Err(_) => return NEG_EIO,
                }
            };
            match vol.create_symlink(parent_ino, link_name, target, euid, egid) {
                Ok(_) => 0,
                Err(kernel_core::fs::ext2::Ext2Error::AlreadyExists) => NEG_EEXIST,
                Err(kernel_core::fs::ext2::Ext2Error::NotDirectory) => NEG_ENOTDIR,
                Err(kernel_core::fs::ext2::Ext2Error::NotFound) => NEG_ENOENT,
                Err(kernel_core::fs::ext2::Ext2Error::OutOfSpace) => NEG_ENOSPC,
                Err(_) => NEG_EIO,
            }
        }
        FsTarget::Ramdisk => NEG_EROFS,
    }
}

pub(super) fn sys_readlink(path_ptr: u64, buf_ptr: u64, buf_len: u64) -> u64 {
    sys_readlinkat(AT_FDCWD, path_ptr, buf_ptr, buf_len)
}

pub(super) fn sys_readlinkat(dirfd: u64, path_ptr: u64, buf_ptr: u64, buf_len: u64) -> u64 {
    if buf_len == 0 {
        return NEG_EINVAL;
    }
    let mut path_buf = [0u8; 512];
    let raw_path = match read_user_cstr(path_ptr, &mut path_buf) {
        Some(s) => s,
        None => return NEG_EFAULT,
    };
    let lexical = match resolve_path_from_dirfd(dirfd, raw_path) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let resolved = match resolve_existing_fs_path(&lexical, false) {
        Ok(path) => path,
        Err(err) => return err,
    };

    let target = match path_node_nofollow(&resolved) {
        Ok(PathNodeKind::Symlink(target)) => target,
        Ok(_) => return NEG_EINVAL,
        Err(err) => return err,
    };

    let to_copy = core::cmp::min(target.len(), buf_len as usize);
    if UserSliceWo::new(buf_ptr, to_copy)
        .and_then(|s| s.copy_from_kernel(&target.as_bytes()[..to_copy]))
        .is_err()
    {
        return NEG_EFAULT;
    }
    to_copy as u64
}

pub(super) fn sys_link(oldpath_ptr: u64, newpath_ptr: u64) -> u64 {
    sys_linkat(AT_FDCWD, oldpath_ptr, AT_FDCWD, newpath_ptr, 0)
}

pub(super) fn sys_linkat(
    olddirfd: u64,
    oldpath_ptr: u64,
    newdirfd: u64,
    newpath_ptr: u64,
    flags: u64,
) -> u64 {
    if flags & !AT_SYMLINK_FOLLOW != 0 {
        return NEG_EINVAL;
    }
    let mut old_buf = [0u8; 512];
    let raw_old = match read_user_cstr(oldpath_ptr, &mut old_buf) {
        Some(path) => path,
        None => return NEG_EFAULT,
    };
    let mut new_buf = [0u8; 512];
    let raw_new = match read_user_cstr(newpath_ptr, &mut new_buf) {
        Some(path) => path,
        None => return NEG_EFAULT,
    };

    let old_lexical = match resolve_path_from_dirfd(olddirfd, raw_old) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let follow_old = flags & AT_SYMLINK_FOLLOW != 0;
    let old_resolved = match resolve_existing_fs_path(&old_lexical, follow_old) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let new_lexical = match resolve_path_from_dirfd(newdirfd, raw_new) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let new_resolved = match resolve_parent_components(&new_lexical) {
        Ok(path) => path,
        Err(err) => return err,
    };

    if path_node_nofollow(&new_resolved).is_ok() {
        return NEG_EEXIST;
    }
    if let Some((pu, pg, pm)) = parent_dir_metadata(&new_resolved) {
        let (_, _, euid, egid) = current_process_ids();
        if !check_permission(pu, pg, pm, euid, egid, 3) {
            return NEG_EACCES;
        }
    }
    if create_parent_is_read_only(&new_resolved) {
        return NEG_EROFS;
    }

    let old_target = resolve_fs_target(&old_resolved);
    let new_target = resolve_fs_target(&new_resolved);
    match (&old_target, &new_target) {
        (FsTarget::DiskData(_), FsTarget::DiskData(_)) => {}
        (FsTarget::DiskData(_), _) | (_, FsTarget::DiskData(_)) => return NEG_EXDEV,
        _ => return NEG_EROFS,
    }
    if !crate::fs::ext2::is_mounted() {
        return NEG_EROFS;
    }

    let FsTarget::DiskData(old_rel) = old_target else {
        return NEG_EROFS;
    };
    let FsTarget::DiskData(new_rel) = new_target else {
        return NEG_EROFS;
    };

    // Phase 88: route ext2 hard-link to the vfs_server authority when
    // registered (before taking the EXT2_VOLUME spinlock).
    if vfs_write_routable() {
        let parts: alloc::vec::Vec<&str> = new_rel.split('/').filter(|s| !s.is_empty()).collect();
        if parts.is_empty() {
            return NEG_EEXIST;
        }
        let link_name = parts[parts.len() - 1];
        let name_start = new_resolved.len() - link_name.len();
        let new_parent_abs = if parts.len() == 1 {
            "/"
        } else {
            &new_resolved[..name_start]
        };
        return match vfs_service_link(&old_resolved, new_parent_abs, link_name) {
            Ok(()) => 0,
            Err(e) => e,
        };
    }

    let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
    let Some(vol) = vol.as_mut() else {
        return NEG_EIO;
    };
    let old_ino = match vol.resolve_path(&old_rel) {
        Ok(ino) => ino,
        Err(kernel_core::fs::ext2::Ext2Error::NotFound) => return NEG_ENOENT,
        Err(kernel_core::fs::ext2::Ext2Error::NotDirectory) => return NEG_ENOTDIR,
        Err(_) => return NEG_EIO,
    };
    let old_inode = match vol.read_inode(old_ino) {
        Ok(inode) => inode,
        Err(_) => return NEG_EIO,
    };
    if old_inode.is_dir() {
        return NEG_EPERM;
    }

    let parts: alloc::vec::Vec<&str> = new_rel.split('/').filter(|s| !s.is_empty()).collect();
    if parts.is_empty() {
        return NEG_EEXIST;
    }
    let (parent_ino, link_name) = if parts.len() == 1 {
        (kernel_core::fs::ext2::EXT2_ROOT_INO, parts[0])
    } else {
        let parent_path = parts[..parts.len() - 1].join("/");
        match vol.resolve_path(&parent_path) {
            Ok(ino) => (ino, parts[parts.len() - 1]),
            Err(kernel_core::fs::ext2::Ext2Error::NotFound) => return NEG_ENOENT,
            Err(kernel_core::fs::ext2::Ext2Error::NotDirectory) => return NEG_ENOTDIR,
            Err(_) => return NEG_EIO,
        }
    };

    match vol.create_hard_link(parent_ino, link_name, old_ino) {
        Ok(()) => 0,
        Err(kernel_core::fs::ext2::Ext2Error::AlreadyExists) => NEG_EEXIST,
        Err(kernel_core::fs::ext2::Ext2Error::IsDirectory) => NEG_EPERM,
        Err(kernel_core::fs::ext2::Ext2Error::NotDirectory) => NEG_ENOTDIR,
        Err(kernel_core::fs::ext2::Ext2Error::NotFound) => NEG_ENOENT,
        Err(kernel_core::fs::ext2::Ext2Error::OutOfSpace) => NEG_ENOSPC,
        Err(_) => NEG_EIO,
    }
}

// ---------------------------------------------------------------------------
// Phase 32: utimensat(dirfd, path, times, flags) — syscall 280
// ---------------------------------------------------------------------------

/// Get approximate current Unix timestamp from LAPIC tick counter.
fn current_unix_time() -> u32 {
    let ticks = crate::arch::x86_64::interrupts::tick_count();
    (ticks / TICKS_PER_SEC) as u32
}

pub(super) fn sys_utimensat(_dirfd: u64, path_ptr: u64, times_ptr: u64, _flags: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw_name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    let cwd = current_cwd();
    let resolved = resolve_path(&cwd, raw_name);
    let name: &str = &resolved;

    // Read the times array if provided.
    // struct timespec { tv_sec: i64, tv_nsec: i64 } × 2 = 32 bytes
    // times[0] = atime, times[1] = mtime
    // UTIME_NOW = 0x3FFFFFFF, UTIME_OMIT = 0x3FFFFFFE
    const UTIME_NOW: i64 = 0x3FFFFFFF;
    const UTIME_OMIT: i64 = 0x3FFFFFFE;

    let now = current_unix_time();
    let (new_atime, new_mtime) = if times_ptr == 0 {
        // NULL times → set both to current time
        (now, now)
    } else {
        let mut tbuf = [0u8; 32];
        if UserSliceRo::new(times_ptr, tbuf.len())
            .and_then(|s| s.copy_to_kernel(&mut tbuf))
            .is_err()
        {
            return NEG_EFAULT;
        }
        let a_sec = i64::from_ne_bytes(tbuf[0..8].try_into().unwrap());
        let a_nsec = i64::from_ne_bytes(tbuf[8..16].try_into().unwrap());
        let m_sec = i64::from_ne_bytes(tbuf[16..24].try_into().unwrap());
        let m_nsec = i64::from_ne_bytes(tbuf[24..32].try_into().unwrap());

        let atime = if a_nsec == UTIME_NOW {
            now
        } else if a_nsec == UTIME_OMIT {
            u32::MAX // sentinel: don't change
        } else {
            // Validate timespec: tv_sec >= 0, tv_sec fits u32, tv_nsec in [0, 1e9)
            // Reject u32::MAX (collides with internal OMIT sentinel)
            if a_sec < 0 || a_sec >= u32::MAX as i64 || !(0..1_000_000_000).contains(&a_nsec) {
                return NEG_EINVAL;
            }
            a_sec as u32
        };
        let mtime = if m_nsec == UTIME_NOW {
            now
        } else if m_nsec == UTIME_OMIT {
            u32::MAX // sentinel: don't change
        } else {
            if m_sec < 0 || m_sec >= u32::MAX as i64 || !(0..1_000_000_000).contains(&m_nsec) {
                return NEG_EINVAL;
            }
            m_sec as u32
        };
        (atime, mtime)
    };

    // ext2 root filesystem
    if crate::fs::ext2::is_mounted()
        && let Some(rel) = ext2_root_path(name)
    {
        // Phase 89: route through the vfs_server (single ext2 owner) so its block
        // cache + the kernel stat cache stay coherent (see `data_chmod`).
        if vfs_write_routable() {
            use kernel_core::fs::vfs_protocol::{VFS_SETATTR_ATIME, VFS_SETATTR_MTIME};
            let mut mask = 0u64;
            if new_atime != u32::MAX {
                mask |= VFS_SETATTR_ATIME;
            }
            if new_mtime != u32::MAX {
                mask |= VFS_SETATTR_MTIME;
            }
            return match vfs_service_setattr(rel, mask, 0, 0, 0, new_atime, new_mtime) {
                Ok(()) => 0,
                Err(e) => e,
            };
        }
        // Direct-engine fallback (boot window / vfs_server-as-writer).
        let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
        if let Some(vol) = vol.as_mut()
            && let Ok(ino) = vol.resolve_path(rel)
            && let Ok(mut inode) = vol.read_inode(ino)
        {
            if new_atime != u32::MAX {
                inode.atime = new_atime;
            }
            if new_mtime != u32::MAX {
                inode.mtime = new_mtime;
            }
            if new_atime != u32::MAX || new_mtime != u32::MAX {
                inode.ctime = now; // ctime always updated when any timestamp changes
            }
            if vol.write_inode(ino, &inode).is_err() {
                return NEG_EIO;
            }
            crate::fs::metacache::bump();
            return 0;
        }
        return NEG_ENOENT;
    }

    // tmpfs
    if tmpfs_relative_path(name).is_some() {
        // tmpfs doesn't track timestamps yet — return ENOSYS
        return NEG_ENOSYS;
    }

    NEG_ENOENT
}

// ---------------------------------------------------------------------------
// Phase 13: mkdir(pathname) — syscall 83
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_mkdir(path_ptr: u64, mode: u64) -> u64 {
    sys_linux_mkdirat(AT_FDCWD, path_ptr, mode)
}

/// Phase 94 — `mkdirat(dirfd, pathname, mode)` (syscall 258). uutils `install -D`
/// creates the destination's parent dirs via `uucore::safe_traversal`'s
/// `create_dir_all_safe`, which issues `mkdirat(dirfd, name, mode)` (the
/// fd-relative sibling of `unlinkat`/`fchmodat`/`fchownat`). musl's `mkdir()` is
/// the legacy `SYS_mkdir`(83) on x86_64 so `mkdir`/`mkdir -p`/`cp -r` dir creation
/// already worked; this adds the `*at` form. The `AT_FDCWD` path is byte-equivalent
/// to the prior `sys_linux_mkdir` behaviour (which already routed through
/// `resolve_path_from_dirfd(AT_FDCWD, …)`).
pub(super) fn sys_linux_mkdirat(dirfd: u64, path_ptr: u64, mode: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw_name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    // mkdir() should resolve parent symlinks but operate on the lexical basename.
    let lexical = match resolve_path_from_dirfd(dirfd, raw_name) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let resolved = match resolve_parent_components(&lexical) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let name: &str = &resolved;

    // Phase 27: Write+execute permission on parent directory.
    if let Some((pu, pg, pm)) = parent_dir_metadata(name) {
        let (_, _, euid, egid) = current_process_ids();
        if !check_permission(pu, pg, pm, euid, egid, 3) {
            return NEG_EACCES;
        }
    }

    // Phase 88: route ext2 mkdir to the vfs_server authority when registered
    // (before taking the EXT2_VOLUME spinlock — the IPC blocks the task).
    if crate::fs::ext2::is_mounted()
        && vfs_write_routable()
        && let Some(rel) = ext2_root_path(name)
        && !rel.is_empty()
    {
        let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
        let dir_name = parts[parts.len() - 1];
        let name_start = name.len() - dir_name.len();
        let parent_abs = if parts.len() <= 1 {
            "/"
        } else {
            &name[..name_start]
        };
        let (_, _, mk_euid, mk_egid) = current_process_ids();
        let create_mode = ((mode as u16) & 0o7777) & !current_umask();
        return match vfs_service_create(
            parent_abs,
            dir_name,
            kernel_core::fs::vfs_protocol::VFS_NODE_DIR,
            create_mode,
            mk_euid,
            mk_egid,
            None,
        ) {
            Ok(_) => {
                log::debug!("[mkdir] {} (ext2 via vfs)", name);
                0
            }
            Err(e) => e,
        };
    }

    // Phase 28: ext2 root mkdir.
    if crate::fs::ext2::is_mounted()
        && let Some(rel) = ext2_root_path(name)
        && !rel.is_empty()
    {
        let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
        if let Some(vol) = vol.as_mut() {
            let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
            let (parent_ino, dir_name) = if parts.len() <= 1 {
                (kernel_core::fs::ext2::EXT2_ROOT_INO, rel)
            } else {
                let parent_path = parts[..parts.len() - 1].join("/");
                match vol.resolve_path(&parent_path) {
                    Ok(p) => (p, parts[parts.len() - 1]),
                    Err(_) => return NEG_ENOENT,
                }
            };
            let (_, _, mk_euid, mk_egid) = current_process_ids();
            let create_mode = ((mode as u16) & 0o7777) & !current_umask();
            return match vol.create_directory(parent_ino, dir_name, create_mode, mk_euid, mk_egid) {
                Ok(_) => {
                    log::debug!("[mkdir] {} (ext2)", name);
                    0
                }
                Err(kernel_core::fs::ext2::Ext2Error::AlreadyExists) => NEG_EEXIST,
                Err(_) => NEG_EIO,
            };
        }
        return NEG_EIO;
    }

    // Legacy: /data mkdir (ext2 or FAT32 fallback).
    if let Some(rel) = fat32_relative_path(name) {
        if rel.is_empty() {
            return NEG_EINVAL;
        }
        if crate::fs::ext2::is_mounted() {
            let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
            if let Some(vol) = vol.as_mut() {
                let parts: alloc::vec::Vec<&str> =
                    rel.split('/').filter(|s| !s.is_empty()).collect();
                let (parent_ino, dir_name) = if parts.len() <= 1 {
                    (kernel_core::fs::ext2::EXT2_ROOT_INO, rel)
                } else {
                    let parent_path = parts[..parts.len() - 1].join("/");
                    match vol.resolve_path(&parent_path) {
                        Ok(p) => (p, parts[parts.len() - 1]),
                        Err(_) => return NEG_ENOENT,
                    }
                };
                let (_, _, mk_euid, mk_egid) = current_process_ids();
                let create_mode = ((mode as u16) & 0o7777) & !current_umask();
                return match vol.create_directory(
                    parent_ino,
                    dir_name,
                    create_mode,
                    mk_euid,
                    mk_egid,
                ) {
                    Ok(_) => {
                        log::debug!("[mkdir] {} (ext2)", name);
                        0
                    }
                    Err(kernel_core::fs::ext2::Ext2Error::AlreadyExists) => NEG_EEXIST,
                    Err(_) => NEG_EIO,
                };
            }
            return NEG_EIO;
        }
        if crate::fs::fat32::is_mounted() {
            let mut vol = crate::fs::fat32::FAT32_VOLUME.lock();
            if let Some(vol) = vol.as_mut() {
                let parts: alloc::vec::Vec<&str> =
                    rel.split('/').filter(|s| !s.is_empty()).collect();
                let (parent_cluster, dir_name) = if parts.len() <= 1 {
                    (vol.bpb.root_cluster, rel)
                } else {
                    let parent_path = parts[..parts.len() - 1].join("/");
                    let parent_cluster = match vol.lookup(&parent_path) {
                        Ok(pe) if pe.is_dir() => pe.start_cluster(),
                        _ => return NEG_ENOENT,
                    };
                    (parent_cluster, parts[parts.len() - 1])
                };
                return match vol.mkdir(parent_cluster, dir_name) {
                    Ok(_) => {
                        log::debug!("[mkdir] {} (fat32)", name);
                        let (_, _, mk_euid2, mk_egid2) = current_process_ids();
                        let create_mode = ((mode as u16) & 0o7777) & !current_umask();
                        crate::fs::fat32::set_fat32_meta(rel, mk_euid2, mk_egid2, create_mode);
                        0
                    }
                    Err(kernel_core::fs::fat32::Fat32Error::AlreadyExists) => NEG_EEXIST,
                    Err(_) => NEG_EIO,
                };
            }
        }
        return NEG_ENOENT;
    }

    let rel = match tmpfs_relative_path(name) {
        Some(r) => r,
        None => return NEG_EROFS, // can only mkdir in tmpfs or /data
    };
    if rel.is_empty() {
        return NEG_EINVAL; // can't mkdir /tmp itself
    }

    let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
    let (_, _, mk_euid, mk_egid) = current_process_ids();
    let create_mode = ((mode as u16) & 0o7777) & !current_umask();
    match tmpfs.mkdir_with_meta(rel, mk_euid, mk_egid, create_mode) {
        Ok(()) => {
            log::debug!("[mkdir] {}", name);
            0
        }
        Err(crate::fs::tmpfs::TmpfsError::AlreadyExists) => NEG_EEXIST,
        Err(crate::fs::tmpfs::TmpfsError::NotFound) => NEG_ENOENT,
        Err(crate::fs::tmpfs::TmpfsError::NotADirectory) => NEG_ENOTDIR,
        Err(_) => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// Phase 13: rmdir(pathname) — syscall 84
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_rmdir(path_ptr: u64) -> u64 {
    sys_linux_rmdir_at(AT_FDCWD, path_ptr)
}

/// Phase 94 — `unlinkat(dirfd, pathname, flags)` (syscall 263). Routes to the
/// rmdir core when `AT_REMOVEDIR` is set, else the unlink core. Both cores are
/// dirfd-aware (via `resolve_path_from_dirfd`), so uutils rm's `safe-traversal`
/// (`openat` the parent dir, then `unlinkat(dirfd, name, …)` / `fstatat`) removes
/// files and directories correctly. m3OS already supports `openat`/`newfstatat`
/// real dirfds; `unlinkat` was the one missing piece — surfaced by
/// `coreutils-smoke` (uutils `rm -r` removed nothing without it).
pub(super) fn sys_linux_unlinkat(dirfd: u64, path_ptr: u64, flags: u64) -> u64 {
    const AT_REMOVEDIR: u64 = 0x200;
    if flags & AT_REMOVEDIR != 0 {
        sys_linux_rmdir_at(dirfd, path_ptr)
    } else {
        sys_linux_unlink_at(dirfd, path_ptr)
    }
}

/// `rmdir` core, dirfd-aware. The `AT_FDCWD` path is byte-equivalent to the prior
/// `resolve_path(&cwd, …)` behaviour for relative and absolute paths; the only
/// difference is an empty path, which now returns `ENOENT` (matching Linux
/// `rmdir("")==ENOENT`) instead of the prior cwd-dependent `EROFS`/`EINVAL`.
pub(super) fn sys_linux_rmdir_at(dirfd: u64, path_ptr: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw_name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    let resolved = match resolve_path_from_dirfd(dirfd, raw_name) {
        Ok(p) => p,
        Err(e) => return e,
    };
    let name: &str = &resolved;

    // Phase 27: Write+execute permission on parent directory.
    if let Some((pu, pg, pm)) = parent_dir_metadata(name) {
        let (_, _, euid, egid) = current_process_ids();
        if !check_permission(pu, pg, pm, euid, egid, 3) {
            return NEG_EACCES;
        }
    }

    // Phase 88: route ext2 rmdir to the vfs_server authority when registered.
    if crate::fs::ext2::is_mounted()
        && vfs_write_routable()
        && let Some(rel) = ext2_root_path(name)
        && !rel.is_empty()
    {
        let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
        let dir_name = parts[parts.len() - 1];
        let name_start = name.len() - dir_name.len();
        let parent_abs = if parts.len() <= 1 {
            "/"
        } else {
            &name[..name_start]
        };
        return match vfs_service_unlink(parent_abs, dir_name, true) {
            Ok(()) => {
                log::info!("[rmdir] {} (ext2 via vfs)", name);
                0
            }
            Err(e) => e,
        };
    }

    let rel = match tmpfs_relative_path(name) {
        Some(r) => r,
        None => return NEG_EROFS,
    };
    if rel.is_empty() {
        return NEG_EINVAL; // can't rmdir /tmp itself
    }

    let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
    match tmpfs.rmdir(rel) {
        Ok(()) => {
            log::info!("[rmdir] {}", name);
            0
        }
        Err(crate::fs::tmpfs::TmpfsError::NotEmpty) => NEG_ENOTEMPTY,
        Err(crate::fs::tmpfs::TmpfsError::NotFound) => NEG_ENOENT,
        Err(
            crate::fs::tmpfs::TmpfsError::WrongType | crate::fs::tmpfs::TmpfsError::NotADirectory,
        ) => NEG_ENOTDIR,
        Err(_) => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// Phase 13: unlink(pathname) — syscall 87
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_unlink(path_ptr: u64) -> u64 {
    sys_linux_unlink_at(AT_FDCWD, path_ptr)
}

/// `unlink` core, dirfd-aware (see `sys_linux_unlinkat`). The `AT_FDCWD` path is
/// byte-equivalent to the prior behaviour.
pub(super) fn sys_linux_unlink_at(dirfd: u64, path_ptr: u64) -> u64 {
    let mut buf = [0u8; 512];
    let raw_name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    // unlink() should resolve parent symlinks but unlink the lexical final component.
    let lexical = match resolve_path_from_dirfd(dirfd, raw_name) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let resolved = match resolve_parent_components(&lexical) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let name: &str = &resolved;

    // Phase 27: Write+execute permission on parent directory.
    // Phase 66: Sticky-bit (S_ISVTX) enforcement before any inode mutation.
    // If the target entry's metadata cannot be obtained (missing path),
    // skip the sticky check entirely and let the unlink path below return
    // -ENOENT rather than masking it as -EACCES.
    let (_, _, euid, egid) = current_process_ids();
    if let Some((pu, pg, pm)) = parent_dir_metadata(name) {
        if !check_permission(pu, pg, pm, euid, egid, 3) {
            return NEG_EACCES;
        }
        if let Some((file_uid, _, _)) = path_metadata(name)
            && kernel_core::fs::mode::check_sticky(pm, file_uid, pu, euid, euid == 0).is_err()
        {
            return NEG_EACCES;
        }
    }

    // Phase 88: route ext2 unlink to the vfs_server authority when registered
    // AND no open fd aliases the target inode. When a fd still aliases it
    // (delete-on-close), the in-kernel engine below is used: it correctly
    // DEFERS inode/block reclamation until the last close (its
    // `ext2_inode_open_count` check), and the dir-entry removal it writes to
    // disk is observed by vfs_server's uncached reads — so the view stays
    // coherent either way.
    if crate::fs::ext2::is_mounted()
        && vfs_write_routable()
        && let Some(rel) = ext2_root_path(name)
        && !rel.is_empty()
    {
        let target_ino = crate::fs::ext2::EXT2_VOLUME
            .lock()
            .as_ref()
            .and_then(|v| v.resolve_path(rel).ok());
        let open_refs = target_ino
            .map(crate::process::ext2_inode_open_count)
            .unwrap_or(0);
        if open_refs == 0 {
            let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
            let file_name = parts[parts.len() - 1];
            let name_start = name.len() - file_name.len();
            let parent_abs = if parts.len() <= 1 {
                "/"
            } else {
                &name[..name_start]
            };
            return match vfs_service_unlink(parent_abs, file_name, false) {
                Ok(()) => {
                    log::debug!("[unlink] {} (ext2 via vfs)", name);
                    0
                }
                Err(e) => e,
            };
        }
    }

    // Phase 28: ext2 root unlink.
    if crate::fs::ext2::is_mounted()
        && let Some(rel) = ext2_root_path(name)
        && !rel.is_empty()
    {
        let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
        if let Some(vol) = vol.as_mut() {
            let parts: alloc::vec::Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
            let parent_ino = if parts.len() <= 1 {
                kernel_core::fs::ext2::EXT2_ROOT_INO
            } else {
                let parent_path = parts[..parts.len() - 1].join("/");
                match vol.resolve_path(&parent_path) {
                    Ok(p) => p,
                    Err(_) => return NEG_ENOENT,
                }
            };
            let file_name = parts.last().copied().unwrap_or(rel);
            return match vol.delete_file(parent_ino, file_name) {
                Ok(()) => {
                    log::debug!("[unlink] {} (ext2)", name);
                    0
                }
                Err(kernel_core::fs::ext2::Ext2Error::NotFound) => NEG_ENOENT,
                Err(kernel_core::fs::ext2::Ext2Error::IsDirectory) => NEG_EISDIR,
                Err(_) => NEG_EIO,
            };
        }
        return NEG_EIO;
    }

    // Legacy: /data unlink (ext2 or FAT32 fallback).
    if let Some(rel) = fat32_relative_path(name) {
        if rel.is_empty() {
            return NEG_EINVAL;
        }
        if crate::fs::ext2::is_mounted() {
            let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
            if let Some(vol) = vol.as_mut() {
                let parts: alloc::vec::Vec<&str> =
                    rel.split('/').filter(|s| !s.is_empty()).collect();
                let parent_ino = if parts.len() <= 1 {
                    kernel_core::fs::ext2::EXT2_ROOT_INO
                } else {
                    let parent_path = parts[..parts.len() - 1].join("/");
                    match vol.resolve_path(&parent_path) {
                        Ok(p) => p,
                        Err(_) => return NEG_ENOENT,
                    }
                };
                let file_name = parts.last().copied().unwrap_or(rel);
                return match vol.delete_file(parent_ino, file_name) {
                    Ok(()) => {
                        log::debug!("[unlink] {} (ext2)", name);
                        0
                    }
                    Err(kernel_core::fs::ext2::Ext2Error::NotFound) => NEG_ENOENT,
                    Err(kernel_core::fs::ext2::Ext2Error::IsDirectory) => NEG_EISDIR,
                    Err(_) => NEG_EIO,
                };
            }
            return NEG_EIO;
        }
        if crate::fs::fat32::is_mounted() {
            let mut vol = crate::fs::fat32::FAT32_VOLUME.lock();
            if let Some(vol) = vol.as_mut() {
                let parts: alloc::vec::Vec<&str> =
                    rel.split('/').filter(|s| !s.is_empty()).collect();
                let (parent_cluster, file_name) = if parts.len() <= 1 {
                    (vol.bpb.root_cluster, rel)
                } else {
                    let parent_path = parts[..parts.len() - 1].join("/");
                    let parent_cluster = match vol.lookup(&parent_path) {
                        Ok(pe) if pe.is_dir() => pe.start_cluster(),
                        _ => return NEG_ENOENT,
                    };
                    (parent_cluster, parts[parts.len() - 1])
                };
                return match vol.unlink(parent_cluster, file_name) {
                    Ok(()) => {
                        log::debug!("[unlink] {} (fat32)", name);
                        0
                    }
                    Err(kernel_core::fs::fat32::Fat32Error::NotFound) => NEG_ENOENT,
                    Err(kernel_core::fs::fat32::Fat32Error::IsDir) => NEG_EISDIR,
                    Err(_) => NEG_EIO,
                };
            }
        }
        return NEG_ENOENT;
    }

    let rel = match tmpfs_relative_path(name) {
        Some(r) => r,
        None => return NEG_EROFS,
    };
    if rel.is_empty() {
        return NEG_EINVAL;
    }

    let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
    match tmpfs.unlink(rel) {
        Ok(()) => {
            log::debug!("[unlink] {}", name);
            0
        }
        Err(crate::fs::tmpfs::TmpfsError::NotFound) => NEG_ENOENT,
        Err(crate::fs::tmpfs::TmpfsError::WrongType) => NEG_EISDIR,
        Err(crate::fs::tmpfs::TmpfsError::NotADirectory) => NEG_ENOTDIR,
        Err(_) => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// Phase 13: rename(oldpath, newpath) — syscall 82
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_rename(old_ptr: u64, new_ptr: u64) -> u64 {
    let mut buf1 = [0u8; 512];
    let old_raw = match read_user_cstr(old_ptr, &mut buf1) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };
    // Copy old_raw to owned string since we need buf for new_raw too.
    let mut old_owned = [0u8; 512];
    let old_len = old_raw.len();
    old_owned[..old_len].copy_from_slice(old_raw.as_bytes());

    let mut buf2 = [0u8; 512];
    let new_raw = match read_user_cstr(new_ptr, &mut buf2) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    let old_str_raw = core::str::from_utf8(&old_owned[..old_len]).unwrap();
    let old_lexical = match resolve_path_from_dirfd(AT_FDCWD, old_str_raw) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let new_lexical = match resolve_path_from_dirfd(AT_FDCWD, new_raw) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let old_resolved = match resolve_parent_components(&old_lexical) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let new_resolved = match resolve_parent_components(&new_lexical) {
        Ok(path) => path,
        Err(err) => return err,
    };

    // Phase 27: Write+execute permission on both parent directories.
    // Phase 66: Sticky-bit (S_ISVTX) enforcement on the source parent
    // directory before any rename mutation. POSIX semantics: a sticky
    // source parent gates the rename even if the destination parent is
    // unrelated. If the source path's metadata cannot be obtained the
    // sticky check is skipped so the rename path can return -ENOENT
    // rather than masking it as -EACCES.
    {
        let (_, _, euid, egid) = current_process_ids();
        if let Some((pu, pg, pm)) = parent_dir_metadata(&old_resolved) {
            if !check_permission(pu, pg, pm, euid, egid, 3) {
                return NEG_EACCES;
            }
            if let Some((file_uid, _, _)) = path_metadata(&old_resolved)
                && kernel_core::fs::mode::check_sticky(pm, file_uid, pu, euid, euid == 0).is_err()
            {
                return NEG_EACCES;
            }
        }
        // Destination parent: write+execute. Additionally, if the
        // destination entry already exists, rename-over is effectively an
        // unlink of the destination — POSIX requires the same sticky-bit
        // semantics there. Only enforce when path_metadata(&new_resolved)
        // succeeds so a missing destination still gets the natural
        // rename-creates-new-entry path.
        if let Some((pu, pg, pm)) = parent_dir_metadata(&new_resolved) {
            if !check_permission(pu, pg, pm, euid, egid, 3) {
                return NEG_EACCES;
            }
            if let Some((dest_uid, _, _)) = path_metadata(&new_resolved)
                && kernel_core::fs::mode::check_sticky(pm, dest_uid, pu, euid, euid == 0).is_err()
            {
                return NEG_EACCES;
            }
        }
    }

    // Phase 88: ext2 rename routes to the vfs_server authority when both paths
    // live on the ext2 root and the service is registered. Cross-filesystem
    // renames (one side tmpfs/ext2) remain EXDEV/EROFS as before.
    if crate::fs::ext2::is_mounted()
        && vfs_write_routable()
        && let Some(old_e) = ext2_root_path(&old_resolved)
        && let Some(new_e) = ext2_root_path(&new_resolved)
        && !old_e.is_empty()
        && !new_e.is_empty()
    {
        return match vfs_service_rename(&old_resolved, &new_resolved) {
            Ok(()) => {
                log::info!(
                    "[rename] {} → {} (ext2 via vfs)",
                    old_resolved,
                    new_resolved
                );
                0
            }
            Err(e) => e,
        };
    }

    let old_rel = match tmpfs_relative_path(&old_resolved) {
        Some(r) => r,
        None => return NEG_EROFS,
    };
    let new_rel = match tmpfs_relative_path(&new_resolved) {
        Some(r) => r,
        None => return NEG_EROFS,
    };

    let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
    match tmpfs.rename(old_rel, new_rel) {
        Ok(()) => {
            log::info!("[rename] {} → {}", old_resolved, new_resolved);
            0
        }
        Err(crate::fs::tmpfs::TmpfsError::NotFound) => NEG_ENOENT,
        Err(_) => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// Phase 24: mount(source, target, fstype) — syscall 165
// ---------------------------------------------------------------------------

/// Probe a USB block device (`dev_id`) for an ext2 partition and return its
/// start LBA (the `base_lba` for [`crate::fs::ext2::mount_usb`]). Handles:
///   * whole-disk ext2, no partition table → 0 (the `usb-mount-smoke` case);
///   * a classic MBR with a Linux (0x83) partition;
///   * a GPT (protective MBR + "EFI PART" header), e.g. the bare-metal boot
///     stick which is `[ESP FAT] + [ext2 logs]` — find the ext2 partition.
///
/// Detection is by the ext2 magic at the candidate start (not the partition
/// type byte), so any layout that actually holds an ext2 is found. The ext2
/// superblock sits 1024 B into the partition → LBA `start + 2`, magic `0xEF53`
/// (LE) at superblock offset 56. Returns 0 when no ext2 is found (the caller's
/// mount then fails cleanly).
fn usb_ext2_base_lba(dev_id: u32) -> u64 {
    let mut read =
        |lba: u64, buf: &mut [u8; 512]| crate::blk::read_sectors_dev(dev_id, lba, 1, buf).is_ok();
    gpt_ext2_scan(&mut read).unwrap_or(0)
}

/// Phase 106 A.3 — the same scan against the ROOT block path (virtio or
/// the remote slot 0, whatever `crate::blk::read_sectors` routes to).
/// `Some(0)` = whole-disk ext2; `None` = nothing found.
fn root_gpt_ext2_base_lba() -> Option<u64> {
    let mut read = |lba: u64, buf: &mut [u8; 512]| crate::blk::read_sectors(lba, 1, buf).is_ok();
    gpt_ext2_scan(&mut read)
}

/// Locate an ext2 filesystem on a possibly-partitioned disk, reading
/// through `read_lba`: whole-disk superblock first, then a GPT walk
/// (protective MBR `0xEE` → `EFI PART` → 128-byte entries → ext2 magic
/// at each `first_lba`), then classic MBR type entries. Extracted from
/// the Phase 92a `usb_ext2_base_lba` so the Phase 106 root mount can
/// run the identical probe over the routed block layer.
fn gpt_ext2_scan(read_lba: &mut dyn FnMut(u64, &mut [u8; 512]) -> bool) -> Option<u64> {
    let has_ext2_at = |read: &mut dyn FnMut(u64, &mut [u8; 512]) -> bool, lba: u64| -> bool {
        let mut sb = [0u8; 512];
        read(lba + 2, &mut sb) && sb[56] == 0x53 && sb[57] == 0xEF
    };
    // 1. Whole-disk ext2 (base_lba = 0) — preserves the existing behaviour.
    if has_ext2_at(read_lba, 0) {
        return Some(0);
    }
    // 2. Partition table at LBA 0 (MBR signature required).
    let mut lba0 = [0u8; 512];
    if !read_lba(0, &mut lba0) || lba0[510] != 0x55 || lba0[511] != 0xAA {
        return None;
    }
    // GPT: a protective MBR's first partition entry (offset 446) has type 0xEE.
    if lba0[450] == 0xEE {
        let mut hdr = [0u8; 512];
        if read_lba(1, &mut hdr) && &hdr[0..8] == b"EFI PART" {
            let part_lba = u64::from_le_bytes(hdr[72..80].try_into().unwrap_or([0; 8]));
            let esize = u32::from_le_bytes(hdr[84..88].try_into().unwrap_or([0; 4])) as usize;
            if part_lba != 0 && esize == 128 {
                // Size the scan from the GPT header's partition-entry count
                // (bytes 80..84) instead of assuming the 128-entry default, so an
                // ext2 partition beyond entry 128 is still found. Capped at 256
                // sectors (≥1024 standard entries) to keep mount bounded against
                // a hostile header.
                let num_entries =
                    u32::from_le_bytes(hdr[80..84].try_into().unwrap_or([0; 4])) as u64;
                let scan_sectors = ((num_entries * esize as u64).div_ceil(512)).min(256);
                for sec in 0..scan_sectors {
                    let mut ent = [0u8; 512];
                    if !read_lba(part_lba + sec, &mut ent) {
                        break;
                    }
                    for k in 0..4usize {
                        let off = k * 128;
                        let first = u64::from_le_bytes(
                            ent[off + 32..off + 40].try_into().unwrap_or([0; 8]),
                        );
                        if first != 0 && has_ext2_at(read_lba, first) {
                            return Some(first);
                        }
                    }
                }
            }
        }
        return None;
    }
    // 3. Classic MBR: 4 × 16-byte entries at offset 446 (type at +4, LBA at +8).
    for e in 0..4usize {
        let off = 446 + e * 16;
        if lba0[off + 4] == 0 {
            continue;
        }
        let start = u32::from_le_bytes(lba0[off + 8..off + 12].try_into().unwrap_or([0; 4])) as u64;
        if start != 0 && has_ext2_at(read_lba, start) {
            return Some(start);
        }
    }
    None
}

pub(super) fn sys_linux_mount(source_ptr: u64, target_ptr: u64, fstype_ptr: u64) -> u64 {
    let (_, _, euid, _) = current_process_ids();
    if euid != 0 {
        return NEG_EPERM;
    }
    let mut buf_target = [0u8; 512];
    let target = match read_user_cstr(target_ptr, &mut buf_target) {
        Some(s) => s,
        None => return NEG_EFAULT,
    };

    let mut buf_fstype = [0u8; 512];
    let fstype = match read_user_cstr(fstype_ptr, &mut buf_fstype) {
        Some(s) => s,
        None => return NEG_EFAULT,
    };

    // Resolve the target BEFORE taking MOUNT_OP_LOCK — path resolution can
    // issue blocking IPC, and holding a spinlock across that call deadlocks
    // SMP peers (Phase 54 SMP race).
    let cwd = current_cwd();
    let lexical_target = resolve_path(&cwd, target);
    let resolved_target = match resolve_existing_fs_path(&lexical_target, true) {
        Ok(path) => path,
        Err(err) => return err,
    };
    if !matches!(path_node_nofollow(&resolved_target), Ok(PathNodeKind::Dir)) {
        return NEG_ENOTDIR;
    }

    // Phase 92a D.4: a USB mass-storage mount — source `/dev/usbN`, fstype ext2.
    // Unlike the root mount (whose device is ignored / MBR-probed on virtio-blk),
    // this resolves the source to a `usbN.block` ring-3 backend in the multi-
    // device registry and mounts a *second* ext2 volume at the target prefix.
    {
        let mut buf_source = [0u8; 512];
        let source = match read_user_cstr(source_ptr, &mut buf_source) {
            Some(s) => s,
            // A NULL source (ptr == 0) is the legitimate "device ignored" idiom
            // the root/vfs mount path below relies on, so treat it as empty and
            // fall through. A non-null but unreadable pointer is a genuine fault
            // — return EFAULT rather than silently falling through to a root
            // mount now that the source is semantically meaningful (/dev/usbN).
            None if source_ptr == 0 => "",
            None => return NEG_EFAULT,
        };
        if let Some(idx) = source
            .strip_prefix("/dev/usb")
            .and_then(|s| s.parse::<u32>().ok())
        {
            if fstype != "ext2" {
                return NEG_EINVAL;
            }
            let _mount_guard = MOUNT_OP_LOCK.lock();
            let svc = alloc::format!("usb{idx}.block");
            let dev_name = alloc::format!("usb{idx}");
            let dev_id = match crate::blk::register_remote_device(&svc, &dev_name) {
                Some(id) => id,
                None => {
                    log::error!("[mount] no '{svc}' block backend registered");
                    return NEG_ENODEV;
                }
            };
            // Locate the ext2: a bare whole-disk ext2 (base_lba = 0, the
            // smoke-test case) OR a partition on a GPT/MBR-partitioned device
            // (the bare-metal boot stick is `[ESP] + [ext2 logs]`). See
            // `usb_ext2_base_lba`.
            let base_lba = usb_ext2_base_lba(dev_id);
            match crate::fs::ext2::mount_usb(&resolved_target, base_lba, dev_id) {
                Ok(displaced) => {
                    // Replacing a mount at the same prefix orphans the old
                    // backend's registry slot — free it so repeated remounts
                    // don't leak blk::remote slots (MAX_REMOTE_BLOCK).
                    if let Some(old_dev_id) = displaced {
                        crate::blk::unregister_remote_device(old_dev_id);
                    }
                    log::info!(
                        "[mount] usb{idx} (dev_id={dev_id}) mounted at {resolved_target} (ext2)"
                    );
                    return 0;
                }
                Err(e) => {
                    log::error!("[mount] usb{idx} ext2 mount failed: {e:?}");
                    crate::blk::unregister_remote_device(dev_id);
                    return NEG_EIO;
                }
            }
        }
    }

    let action = match vfs_service_mount_action(&resolved_target, fstype) {
        Ok(action) => action,
        Err(err) => {
            log::warn!(
                "[mount] rejected mount target={} fstype={}: {}",
                resolved_target,
                fstype,
                err as i64
            );
            return err;
        }
    };

    // Serialize the actual mount mutation with other mount/umount operations.
    let _mount_guard = MOUNT_OP_LOCK.lock();

    if action == kernel_core::fs::vfs_protocol::VFS_MOUNT_EXT2_ROOT {
        let base_lba = match crate::blk::mbr::probe_ext2() {
            Some((lba, _)) => lba,
            None => {
                // Phase 106 A.3 — a GPT boot stick (ESP first, rootfs
                // after) is invisible to the MBR probe; run the same
                // GPT-aware scan the secondary USB mount uses, over the
                // routed block layer (virtio or the remote root slot).
                match root_gpt_ext2_base_lba() {
                    Some(lba) => {
                        log::info!("[mount] GPT ext2 root partition at LBA {lba}");
                        lba
                    }
                    None => {
                        log::error!("[mount] no ext2 partition found on the root block device");
                        // Phase 106 C.3 — if an auto-discovery service
                        // adopted the root slot but its device has no
                        // ext2 (e.g. a blank internal NVMe present during
                        // a USB-image install boot), release + skip it so
                        // init's retry loop re-evaluates to the next
                        // candidate (AHCI, then the bootable USB).
                        crate::blk::release_root_and_skip();
                        return NEG_ENODEV;
                    }
                }
            }
        };
        match crate::fs::ext2::mount_ext2(base_lba) {
            Ok(()) => {
                log::info!("[mount] virtio-blk mounted at {} (ext2)", resolved_target);
                0
            }
            Err(e) => {
                log::error!("[mount] ext2 mount failed: {:?}", e);
                NEG_EIO
            }
        }
    } else if action == kernel_core::fs::vfs_protocol::VFS_MOUNT_VFAT_DATA {
        let (base_lba, _sector_count) = match crate::blk::mbr::probe() {
            Some(p) => p,
            None => {
                log::error!("[mount] no FAT32 partition found on virtio-blk");
                return NEG_ENODEV;
            }
        };
        match crate::fs::fat32::mount_fat32(base_lba) {
            Ok(()) => {
                log::info!(
                    "[mount] {} mounted at {} (vfat)",
                    "virtio-blk",
                    resolved_target
                );
                0
            }
            Err(e) => {
                log::error!("[mount] FAT32 mount failed: {:?}", e);
                NEG_EIO
            }
        }
    } else {
        NEG_EINVAL
    }
}

pub(super) fn sys_linux_umount2(target_ptr: u64, flags: u64) -> u64 {
    if flags != 0 {
        return NEG_EINVAL;
    }

    let (_, _, euid, _) = current_process_ids();
    if euid != 0 {
        return NEG_EPERM;
    }

    let mut buf_target = [0u8; 512];
    let target = match read_user_cstr(target_ptr, &mut buf_target) {
        Some(s) => s,
        None => return NEG_EFAULT,
    };

    // Resolve the target BEFORE taking MOUNT_OP_LOCK — path resolution can
    // issue blocking IPC, and holding a spinlock across that call deadlocks
    // SMP peers (Phase 54 SMP race).
    let cwd = current_cwd();
    let lexical_target = resolve_path(&cwd, target);
    let resolved_target = match resolve_existing_fs_path(&lexical_target, true) {
        Ok(path) => path,
        Err(err) => return err,
    };
    if !matches!(path_node_nofollow(&resolved_target), Ok(PathNodeKind::Dir)) {
        return NEG_ENOTDIR;
    }

    // Phase 92 C.4: a USB mass-storage unmount — target `/mnt/usbN`. Mirrors the
    // `/dev/usbN` branch in `sys_linux_mount`: tear down the secondary ext2
    // volume and free its `blk::remote` registry slot. Reached both by a
    // voluntary `umount /mnt/usbN` and by the `usb-storage` daemon when it
    // observes its device hot-unplugged. Removable-media semantics: the device
    // is (or may be) physically gone, so this path forces the teardown without a
    // busy check — leaving the mount stale is the exact bug C.4 closes; a
    // process still holding the mount gets IO errors on its next access (the
    // backing block device is unregistered). `unmount_usb` returns `None` for a
    // non-USB target, so `/` and `/data` fall through to the action path below.
    {
        let _mount_guard = MOUNT_OP_LOCK.lock();
        if let Some(dev_id) = crate::fs::ext2::unmount_usb(&resolved_target) {
            crate::blk::unregister_remote_device(dev_id);
            log::info!("[mount] unmounted USB {resolved_target} (dev_id={dev_id})");
            return 0;
        }
    }

    let action = match vfs_service_umount_action(&resolved_target) {
        Ok(action) => action,
        Err(err) => return err,
    };

    // Serialize the actual umount mutation with other mount/umount operations.
    let _mount_guard = MOUNT_OP_LOCK.lock();

    let table = crate::process::PROCESS_TABLE.lock();
    let busy = table.iter().any(|proc| {
        mount_contains_path(&resolved_target, &proc.cwd)
            || proc
                .fd_table_snapshot()
                .iter()
                .flatten()
                .any(|entry| mount_holds_fd(&resolved_target, &entry.backend))
    });
    drop(table);
    if busy {
        return NEG_EBUSY;
    }

    match action {
        kernel_core::fs::vfs_protocol::VFS_UMOUNT_EXT2_ROOT => {
            if !crate::fs::ext2::is_mounted() {
                return NEG_EINVAL;
            }
            crate::fs::ext2::unmount_ext2();
        }
        kernel_core::fs::vfs_protocol::VFS_UMOUNT_VFAT_DATA => {
            if !crate::fs::fat32::is_mounted() {
                return NEG_EINVAL;
            }
            crate::fs::fat32::unmount_fat32();
        }
        _ => return NEG_EINVAL,
    }

    log::info!("[mount] unmounted {}", resolved_target);
    0
}

fn mount_contains_path(target: &str, path: &str) -> bool {
    match target {
        "/" => {
            if path == "/tmp"
                || path.starts_with("/tmp/")
                || path == "/proc"
                || path.starts_with("/proc/")
                || path == "/dev"
                || path.starts_with("/dev/")
            {
                return false;
            }
            crate::fs::ramdisk::ramdisk_lookup(path).is_none()
        }
        "/data" => path == "/data" || path.starts_with("/data/"),
        _ => false,
    }
}

fn mount_holds_fd(target: &str, backend: &FdBackend) -> bool {
    match (target, backend) {
        ("/", FdBackend::Ext2Disk { .. })
        | ("/", FdBackend::VfsService { .. })
        | ("/data", FdBackend::Fat32Disk { .. }) => true,
        (_, FdBackend::Dir { path }) => mount_contains_path(target, path),
        _ => false,
    }
}

// ---------------------------------------------------------------------------
// Phase 13: truncate(path, length) — syscall 76
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_truncate(path_ptr: u64, length: u64) -> u64 {
    // Linux truncate() takes a signed off_t.
    let length_i64 = length as i64;
    if length_i64 < 0 {
        return NEG_EINVAL;
    }

    let mut buf = [0u8; 512];
    let raw_name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    // Resolve path against current process's working directory.
    let cwd = current_cwd();
    let resolved = resolve_path(&cwd, raw_name);
    let name: &str = &resolved;

    let rel = match tmpfs_relative_path(name) {
        Some(r) => r,
        None => return NEG_EROFS,
    };
    if rel.is_empty() {
        return NEG_EISDIR;
    }

    let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
    match tmpfs.truncate(rel, length_i64 as usize) {
        Ok(()) => 0,
        Err(crate::fs::tmpfs::TmpfsError::NotFound) => NEG_ENOENT,
        Err(crate::fs::tmpfs::TmpfsError::NoSpace) => NEG_ENOSPC,
        Err(crate::fs::tmpfs::TmpfsError::WrongType) => NEG_EISDIR,
        Err(_) => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// Phase 13: ftruncate(fd, length) — syscall 77
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_ftruncate(fd: u64, length: u64) -> u64 {
    // Linux ftruncate() takes a signed off_t.
    let length_i64 = length as i64;
    if length_i64 < 0 {
        return NEG_EINVAL;
    }

    let fd_idx = fd as usize;
    if !(3..MAX_FDS).contains(&fd_idx) {
        return NEG_EBADF;
    }

    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };

    if !entry.writable {
        return NEG_EBADF;
    }

    match &entry.backend {
        FdBackend::Stdout
        | FdBackend::Stdin
        | FdBackend::PipeRead { .. }
        | FdBackend::PipeWrite { .. }
        | FdBackend::Dir { .. }
        | FdBackend::DevNull
        | FdBackend::DevZero
        | FdBackend::DevUrandom
        | FdBackend::DevFull
        | FdBackend::DeviceTTY { .. }
        | FdBackend::PtyMaster { .. }
        | FdBackend::PtySlave { .. }
        | FdBackend::Proc { .. }
        | FdBackend::Socket { .. }
        | FdBackend::UnixSocket { .. }
        | FdBackend::Epoll { .. }
        | FdBackend::EventFd { .. }
        | FdBackend::TimerFd { .. } => NEG_EINVAL,
        FdBackend::Ramdisk { .. } => NEG_EROFS,
        FdBackend::Tmpfs { path } => {
            let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
            match tmpfs.truncate(path, length_i64 as usize) {
                Ok(()) => 0,
                Err(crate::fs::tmpfs::TmpfsError::NoSpace) => NEG_ENOSPC,
                Err(_) => NEG_EINVAL,
            }
        }
        FdBackend::Fat32Disk { .. } => {
            // FAT32 truncate not yet implemented.
            NEG_EINVAL
        }
        FdBackend::Ext2Disk {
            path, inode_num, ..
        } => {
            let path = path.clone();
            let inode_num = *inode_num;
            // Phase 88: route ext2 ftruncate to the vfs_server authority when
            // registered (coherent), else fall back to the in-kernel engine.
            if vfs_write_routable() {
                match vfs_service_truncate(&path, length) {
                    Ok(()) => {
                        with_current_fd_mut(fd_idx, |slot| {
                            if let Some(e) = slot
                                && let FdBackend::Ext2Disk {
                                    file_size: ref mut fs,
                                    ..
                                } = e.backend
                            {
                                *fs = length.min(u32::MAX as u64) as u32;
                            }
                        });
                        return 0;
                    }
                    Err(e) => return e,
                }
            }
            // In-kernel fallback: only truncate-to-0 is supported (the engine's
            // `truncate_file` frees all blocks).
            if length != 0 {
                return NEG_EINVAL;
            }
            let mut vol = crate::fs::ext2::EXT2_VOLUME.lock();
            let Some(vol) = vol.as_mut() else {
                return NEG_EIO;
            };
            let Ok(mut inode) = vol.read_inode(inode_num) else {
                return NEG_EIO;
            };
            match vol.truncate_file(inode_num, &mut inode) {
                Ok(()) => {
                    with_current_fd_mut(fd_idx, |slot| {
                        if let Some(e) = slot
                            && let FdBackend::Ext2Disk {
                                file_size: ref mut fs,
                                ..
                            } = e.backend
                        {
                            *fs = 0;
                        }
                    });
                    0
                }
                Err(_) => NEG_EIO,
            }
        }
        FdBackend::VfsService { .. } => NEG_EROFS, // read-only
    }
}

// ---------------------------------------------------------------------------
// Phase 13: fsync(fd) — syscall 74 (no-op for tmpfs)
// ---------------------------------------------------------------------------

pub(super) fn sys_linux_fsync(fd: u64) -> u64 {
    let fd_idx = fd as usize;
    if !(3..MAX_FDS).contains(&fd_idx) {
        return NEG_EBADF;
    }
    if current_fd_entry(fd_idx).is_none() {
        return NEG_EBADF;
    }
    0 // no-op: tmpfs has no persistence
}

// ---------------------------------------------------------------------------
// Phase 13: getdents64(fd, buf, count) — syscall 217
// ---------------------------------------------------------------------------

/// Phase 88 Track B.3 — the real inode number for `abs_path`, resolved by the
/// SAME routing `stat` uses, so `getdents64` `d_ino` always matches `stat`
/// `st_ino` for the same entry (the prior synthetic `idx + 1` `d_ino` violated
/// that POSIX invariant). Returns 0 for backends with no real inode (ramdisk,
/// fat32, device nodes) — consistent with their `st_ino = 0`.
fn path_ino(abs_path: &str) -> u64 {
    if let Some(st) = crate::fs::procfs::stat(abs_path) {
        return st.ino;
    }
    if let Some(rel) = tmpfs_relative_path(abs_path) {
        let tmpfs = crate::fs::tmpfs::TMPFS.lock();
        return tmpfs.stat(rel).map(|s| s.ino).unwrap_or(0);
    }
    // Phase 92a D.4: a /mnt/usbN path resolves its inode in the secondary
    // mount's own ext2 volume, so getdents64 `d_ino` and `stat` `st_ino` carry
    // the real inode (not 0) and agree — the Phase 88 Track B.3 invariant.
    // `with_usb_mount` short-circuits to None when no secondary mount is active.
    if let Some(Some(ino)) =
        crate::fs::ext2::with_usb_mount(abs_path, |vol, rel| vol.resolve_path(rel).ok())
    {
        return ino as u64;
    }
    if crate::fs::ext2::is_mounted()
        && let Some(rel) = ext2_root_path(abs_path)
    {
        // Engine-unification Phase A: resolve the inode through the `vfs_server`
        // authority whenever it is registered, so getdents64 `d_ino` reflects a
        // routed (possibly write-back-deferred) create/rename and the in-kernel
        // ext2 engine is not consulted for a root read post-boot. The cached
        // `vfs_service_stat_path` is the SAME source `stat`/`path_filemeta` use,
        // so `d_ino` always matches `st_ino` for the entry. The in-kernel
        // `EXT2_VOLUME` resolve stays as the boot-window / degraded fallback.
        if vfs_service_can_handle_path(abs_path)
            && let Ok(st) = vfs_service_stat_path(abs_path)
        {
            return st.ino;
        }
        let vol = crate::fs::ext2::EXT2_VOLUME.lock();
        if let Some(vol) = vol.as_ref()
            && let Ok(ino) = vol.resolve_path(rel)
        {
            return ino as u64;
        }
    }
    0
}

/// The parent-directory path of `path` (e.g. `/etc` → `/`, `/a/b` → `/a`,
/// `/` → `/`). Used to give the `..` dirent its real inode.
fn parent_dir(path: &str) -> &str {
    match path.rfind('/') {
        Some(0) | None => "/",
        Some(i) => &path[..i],
    }
}

pub(super) fn sys_linux_getdents64(fd: u64, buf_ptr: u64, count: u64) -> u64 {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }

    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };

    let dir_path = match &entry.backend {
        FdBackend::Dir { path } => path.clone(),
        _ => return NEG_ENOTDIR,
    };
    if let Some((uid, gid, mode)) = path_metadata(&dir_path) {
        let (_, _, euid, egid) = current_process_ids();
        if !check_permission(uid, gid, mode, euid, egid, 4) {
            return NEG_EACCES;
        }
    }

    let offset = entry.offset;
    let max_bytes = (count as usize).min(64 * 1024);

    fn dirent_type_for_path(path: &str, is_dir: bool) -> u8 {
        if is_dir {
            DT_DIR
        } else {
            match path_node_nofollow(path) {
                Ok(PathNodeKind::Symlink(_)) => DT_LNK,
                Ok(PathNodeKind::Dir) => DT_DIR,
                _ => DT_REG,
            }
        }
    }

    // Collect directory entries: [(".", DT_DIR), ("..", DT_DIR), ...children...]
    let mut entries: alloc::vec::Vec<(alloc::string::String, u8)> = alloc::vec::Vec::new();
    entries.push((alloc::string::String::from("."), DT_DIR));
    entries.push((alloc::string::String::from(".."), DT_DIR));

    // Engine-unification Phase A: when a root/overlaid directory's ext2 entries
    // are sourced from `vfs_server`, the server already returns each child's
    // REAL d_ino — stash it by name so the serialization loop emits it directly
    // instead of a second per-entry `path_ino` resolve. A name absent from this
    // map (`.`/`..`, ramdisk overlays, virtual mounts, tmpfs/procfs/fat32) falls
    // back to `path_ino` as before.
    let mut vfs_inos: alloc::collections::BTreeMap<alloc::string::String, u64> =
        alloc::collections::BTreeMap::new();

    if crate::fs::procfs::is_dir(&dir_path) {
        match crate::fs::procfs::list_dir(&dir_path) {
            Some(children) => {
                for (name, is_dir) in children {
                    let child_path = if dir_path == "/" {
                        alloc::format!("/{name}")
                    } else {
                        alloc::format!("{dir_path}/{name}")
                    };
                    entries.push((name, dirent_type_for_path(&child_path, is_dir)));
                }
            }
            None => return NEG_ENOENT,
        }
    } else if let Some(rel) = tmpfs_relative_path(&dir_path) {
        let children = {
            let tmpfs = crate::fs::tmpfs::TMPFS.lock();
            match tmpfs.list_dir(rel) {
                Ok(children) => children,
                Err(_) => return NEG_ENOENT,
            }
        };
        for (name, is_dir) in children {
            let child_path = if dir_path == "/" {
                alloc::format!("/{name}")
            } else {
                alloc::format!("{dir_path}/{name}")
            };
            entries.push((name, dirent_type_for_path(&child_path, is_dir)));
        }
    } else if crate::fs::ext2::is_usb_mount_path(&dir_path) {
        // Phase 92a D.4: list a /mnt/usbN secondary mount from its own ext2
        // volume (caught before the root ext2 branch so it is not resolved
        // against the root device). A volume read/parse error must surface as
        // an errno (like the procfs/tmpfs branches above) rather than being
        // swallowed into a silently-empty directory.
        let children =
            match crate::fs::ext2::with_usb_mount(&dir_path, |vol, rel| vol.list_dir(rel)) {
                Some(Ok(children)) => children,
                Some(Err(kernel_core::fs::ext2::Ext2Error::NotFound)) => return NEG_ENOENT,
                Some(Err(kernel_core::fs::ext2::Ext2Error::NotDirectory)) => return NEG_ENOTDIR,
                Some(Err(_)) => return NEG_EIO,
                // The mount was removed between the lock-free active check and
                // re-acquiring the USB_MOUNTS lock (raced unmount).
                None => return NEG_ENOENT,
            };
        for (name, is_dir) in children {
            entries.push((name, if is_dir { DT_DIR } else { DT_REG }));
        }
    } else if dir_path == "/" {
        // Root directory: merge ext2 root + ramdisk overlays + virtual mounts.
        // Start with ext2 root entries if mounted.
        let mut seen = alloc::collections::BTreeSet::new();
        if crate::fs::ext2::is_mounted() {
            // Engine-unification Phase A: source the ext2 root's entries from the
            // `vfs_server` authority when registered (real d_ino, write-back-
            // visible). The in-kernel `list_dir` is the boot-window fallback.
            let routed = if vfs_can_list_ext2_dir("/") {
                vfs_service_list_dir_entries("/").ok()
            } else {
                None
            };
            if let Some(routed) = routed {
                for (name, d_type, d_ino) in routed {
                    seen.insert(name.clone());
                    vfs_inos.insert(name.clone(), d_ino);
                    entries.push((name, d_type));
                }
            } else {
                let children = {
                    let vol = crate::fs::ext2::EXT2_VOLUME.lock();
                    vol.as_ref().and_then(|vol| vol.list_dir("/").ok())
                };
                if let Some(children) = children {
                    for (name, is_dir) in children {
                        seen.insert(name.clone());
                        let child_path = alloc::format!("/{name}");
                        entries.push((name, dirent_type_for_path(&child_path, is_dir)));
                    }
                }
            }
        }
        // Overlay ramdisk top-level dirs (/bin, /sbin, /etc).
        if let Some(ramdisk_children) = crate::fs::ramdisk::ramdisk_list_dir("/") {
            for (name, is_dir) in ramdisk_children {
                if !seen.contains(&name) {
                    seen.insert(name.clone());
                    entries.push((name, if is_dir { DT_DIR } else { DT_REG }));
                }
            }
        }
        // Add virtual mount points.
        if !seen.contains("tmp") {
            entries.push((alloc::string::String::from("tmp"), DT_DIR));
        }
        if !seen.contains("run") {
            entries.push((alloc::string::String::from("run"), DT_DIR));
        }
        if !seen.contains("proc") {
            entries.push((alloc::string::String::from("proc"), DT_DIR));
        }
        if !seen.contains("dev") {
            entries.push((alloc::string::String::from("dev"), DT_DIR));
        }
        if crate::fs::fat32::is_mounted() && !seen.contains("data") {
            entries.push((alloc::string::String::from("data"), DT_DIR));
        }
    } else if crate::fs::ext2::is_mounted() {
        // ext2 subdirectory listing (e.g. /home, /etc).
        if let Some(rel) = ext2_root_path(&dir_path) {
            if vfs_service_can_list_dir(&dir_path) {
                match vfs_service_list_dir(&dir_path, offset, buf_ptr, max_bytes) {
                    Ok((bytes, next_offset)) => {
                        if bytes == 0 {
                            return 0;
                        }
                        with_current_fd_mut(fd_idx, |slot| {
                            if let Some(e) = slot {
                                e.offset = next_offset;
                            }
                        });
                        return bytes as u64;
                    }
                    Err(err) => return err,
                }
            }
            // Merge entries from both ramdisk and ext2 for overlaid dirs.
            let mut seen = alloc::collections::BTreeSet::new();
            if let Some(children) = crate::fs::ramdisk::ramdisk_list_dir(&dir_path) {
                for (name, is_dir) in children {
                    seen.insert(name.clone());
                    entries.push((name, if is_dir { DT_DIR } else { DT_REG }));
                }
            }
            // Engine-unification Phase A: source the ext2 portion of an overlaid
            // dir from the `vfs_server` authority when registered (real d_ino,
            // write-back-visible); the in-kernel `list_dir` is the fallback.
            let routed = if vfs_can_list_ext2_dir(&dir_path) {
                vfs_service_list_dir_entries(&dir_path).ok()
            } else {
                None
            };
            if let Some(routed) = routed {
                for (name, d_type, d_ino) in routed {
                    if !seen.contains(&name) {
                        vfs_inos.insert(name.clone(), d_ino);
                        entries.push((name, d_type));
                    }
                }
            } else {
                let children = {
                    let vol = crate::fs::ext2::EXT2_VOLUME.lock();
                    vol.as_ref().and_then(|vol| vol.list_dir(rel).ok())
                };
                if let Some(children) = children {
                    for (name, is_dir) in children {
                        if !seen.contains(&name) {
                            let child_path = if dir_path == "/" {
                                alloc::format!("/{name}")
                            } else {
                                alloc::format!("{dir_path}/{name}")
                            };
                            entries.push((name, dirent_type_for_path(&child_path, is_dir)));
                        }
                    }
                }
            }
        }
    } else if let Some(rel) = fat32_relative_path(&dir_path) {
        // Legacy: /data directory listing for FAT32 fallback.
        if crate::fs::fat32::is_mounted() {
            let vol = crate::fs::fat32::FAT32_VOLUME.lock();
            if let Some(vol) = vol.as_ref() {
                let dir_cluster = if rel.is_empty() {
                    vol.bpb.root_cluster
                } else {
                    match vol.lookup(rel) {
                        Ok(e) if e.is_dir() => e.start_cluster(),
                        _ => return NEG_ENOENT,
                    }
                };
                match vol.list_dir(dir_cluster) {
                    Ok(children) => {
                        for (name, is_dir) in children {
                            entries.push((name, if is_dir { DT_DIR } else { DT_REG }));
                        }
                    }
                    Err(_) => return NEG_EIO,
                }
            }
        }
    } else {
        // Ramdisk directory listing.
        if let Some(children) = crate::fs::ramdisk::ramdisk_list_dir(&dir_path) {
            for (name, is_dir) in children {
                entries.push((name, if is_dir { DT_DIR } else { DT_REG }));
            }
        }
    }

    if offset >= entries.len() {
        return 0; // end of directory
    }

    // Serialize into a kernel buffer, then copy to userspace.
    let mut out: alloc::vec::Vec<u8> = alloc::vec::Vec::new();
    let mut idx = offset;

    while idx < entries.len() {
        let (ref name, d_type) = entries[idx];
        let name_bytes = name.as_bytes();
        // reclen = 19 (fixed fields) + name_len + 1 (null), rounded up to 8
        let reclen = (19 + name_bytes.len() + 1 + 7) & !7;

        if out.len() + reclen > max_bytes {
            if out.is_empty() {
                // Even one entry doesn't fit — EINVAL.
                return NEG_EINVAL;
            }
            break;
        }

        let start = out.len();
        out.resize(start + reclen, 0); // zero-pad

        // Phase 88 Track B.3 — emit the entry's REAL inode (matching `stat`
        // `st_ino`), not a synthetic `idx + 1`. Reconstruct the entry's absolute
        // path and resolve it the same way `stat` does.
        let child_abs = if name.as_str() == "." {
            dir_path.clone()
        } else if name.as_str() == ".." {
            alloc::string::String::from(parent_dir(&dir_path))
        } else if dir_path == "/" {
            alloc::format!("/{name}")
        } else {
            alloc::format!("{dir_path}/{name}")
        };
        // Engine-unification Phase A: prefer the real d_ino the `vfs_server`
        // already returned for a routed ext2 child; only resolve via `path_ino`
        // for entries with no stashed inode (`.`/`..`, ramdisk, virtual mounts,
        // tmpfs/procfs/fat32).
        let d_ino: u64 = match vfs_inos.get(name) {
            Some(&ino) => ino,
            None => path_ino(&child_abs),
        };
        let d_off: i64 = (idx + 1) as i64;
        out[start..start + 8].copy_from_slice(&d_ino.to_ne_bytes());
        out[start + 8..start + 16].copy_from_slice(&d_off.to_ne_bytes());
        out[start + 16..start + 18].copy_from_slice(&(reclen as u16).to_ne_bytes());
        out[start + 18] = d_type;
        out[start + 19..start + 19 + name_bytes.len()].copy_from_slice(name_bytes);
        // null terminator and padding are already zero from resize

        idx += 1;
    }

    if out.is_empty() {
        return 0;
    }

    if UserSliceWo::new(buf_ptr, out.len())
        .and_then(|s| s.copy_from_kernel(&out))
        .is_err()
    {
        return NEG_EFAULT;
    }

    // Update the fd offset so the next call resumes.
    with_current_fd_mut(fd_idx, |slot| {
        if let Some(e) = slot {
            e.offset = idx;
        }
    });

    out.len() as u64
}

pub(super) fn sys_umask(mask: u64) -> u64 {
    let new_mask = (mask as u16) & 0o777;
    let pid = crate::process::current_pid();
    let mut table = crate::process::PROCESS_TABLE.lock();
    let Some(proc) = table.find_mut(pid) else {
        return 0o022;
    };
    let old = proc.umask;
    proc.umask = new_mask;
    old as u64
}

// ---------------------------------------------------------------------------
// arch_prctl(code, addr) — syscall 158 (musl TLS initialization)
// ---------------------------------------------------------------------------

/// Handles `ARCH_SET_FS` (0x1002) which musl uses to set the FS.base MSR for
/// thread-local storage.  Other sub-commands return -EINVAL.
pub(super) fn sys_linux_arch_prctl(code: u64, addr: u64) -> u64 {
    const ARCH_SET_FS: u64 = 0x1002;
    match code {
        ARCH_SET_FS => {
            let vaddr = match x86_64::VirtAddr::try_new(addr) {
                Ok(v) => v,
                Err(_) => return NEG_EINVAL,
            };
            x86_64::registers::model_specific::FsBase::write(vaddr);
            // Save FS.base to process table for context-switch restore.
            let pid = crate::process::current_pid();
            let mut table = crate::process::PROCESS_TABLE.lock();
            if let Some(proc) = table.find_mut(pid) {
                proc.fs_base = addr;
            }
            0
        }
        _ => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// prctl(option, arg2, arg3, arg4, arg5) — syscall 157
// ---------------------------------------------------------------------------
//
// Phase 69d follow-up: tmux issues `prctl(PR_SET_NAME, "tmux: ...")` to
// give its server process a recognisable name in `/proc/<pid>/comm`. We
// implement PR_SET_NAME / PR_GET_NAME fully.  A small allow-list of
// cosmetic options (PR_SET_PDEATHSIG, PR_GET_PDEATHSIG, PR_SET_DUMPABLE,
// PR_GET_DUMPABLE, PR_SET_KEEPCAPS) succeed silently so common runtime
// calls don't trip `unhandled syscall 157` log noise.  Everything else
// — including security-sensitive options like PR_SET_NO_NEW_PRIVS and
// PR_SET_SECCOMP — returns -EINVAL so callers learn that requested
// semantics were not applied (PR #177 review fix).

/// `PR_SET_NAME` — write a 16-byte name (15 visible + NUL) into the
/// caller's `comm` slot.  Argument: pointer to a NUL-terminated string.
const PR_SET_NAME: u64 = 15;
/// `PR_GET_NAME` — read the current 16-byte `comm` slot into the caller.
const PR_GET_NAME: u64 = 16;
/// Allow-list of cosmetic prctl options that return success silently.
/// These are non-security-affecting on m3OS:
/// * `PR_SET_PDEATHSIG = 1`, `PR_GET_PDEATHSIG = 2` — parent-death signal (no kernel support)
/// * `PR_GET_DUMPABLE = 3`, `PR_SET_DUMPABLE = 4` — core dump flag (no core dumps on m3OS)
/// * `PR_SET_KEEPCAPS = 8`, `PR_GET_KEEPCAPS = 7` — keep capabilities across setuid (no caps on m3OS)
/// * `PR_SET_TIMING = 14`, `PR_GET_TIMING = 13` — process timing mode (cosmetic)
const PRCTL_COSMETIC_OPTIONS: &[u64] = &[1, 2, 3, 4, 7, 8, 13, 14];

pub(super) fn sys_prctl(option: u64, arg2: u64, _arg3: u64) -> u64 {
    match option {
        PR_SET_NAME => {
            // Caller passes a pointer to a NUL-terminated C string.  We
            // copy byte-by-byte (stopping at NUL or after 15 visible
            // bytes) so a valid short string at the very end of a mapped
            // region succeeds — copying a fixed 16 bytes up front would
            // EFAULT despite the terminator being inside the mapping.
            let mut buf = [0u8; 16];
            let mut visible_end = 0usize;
            for (i, slot) in buf.iter_mut().enumerate().take(15) {
                let mut byte = [0u8; 1];
                let Ok(slice) = UserSliceRo::new(arg2 + i as u64, 1) else {
                    return NEG_EFAULT;
                };
                if slice.copy_to_kernel(&mut byte).is_err() {
                    return NEG_EFAULT;
                }
                if byte[0] == 0 {
                    break;
                }
                *slot = byte[0];
                visible_end = i + 1;
            }
            let pid = crate::process::current_pid();
            let mut table = crate::process::PROCESS_TABLE.lock();
            if let Some(proc) = table.find_mut(pid) {
                proc.set_comm(&buf[..visible_end]);
            }
            0
        }
        PR_GET_NAME => {
            let pid = crate::process::current_pid();
            let comm = {
                let table = crate::process::PROCESS_TABLE.lock();
                table.find(pid).map(|p| p.comm).unwrap_or([0u8; 16])
            };
            if UserSliceWo::new(arg2, comm.len())
                .and_then(|s| s.copy_from_kernel(&comm))
                .is_err()
            {
                return NEG_EFAULT;
            }
            0
        }
        // Cosmetic allow-list returns success.  Unknown options fall
        // through to -EINVAL so callers don't see silent success on
        // security-sensitive ops the kernel does not implement
        // (PR_SET_NO_NEW_PRIVS, PR_SET_SECCOMP, PR_SET_MM, …).
        opt if PRCTL_COSMETIC_OPTIONS.contains(&opt) => 0,
        _ => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// flock(fd, op) — syscall 73
// ---------------------------------------------------------------------------
//
// Phase 69d follow-up: tmux's client/server coordination uses
// `flock(LOCK_EX | LOCK_NB)` on the socket file to guarantee a single
// server.  We implement two layers:
//
// * Cross-fd, cross-process locking on `UnixSocket` kernel objects.
//   Two opens of the same socket file see each other's locks.
//
// * Per-(pid, fd) bookkeeping for every other backend.  This is what a
//   single-process tmux relies on for self-coordination and lets
//   `LOCK_UN` actually unlock without the kernel needing to coordinate
//   across separate inodes for path-backed fds.

pub(super) fn sys_flock(fd: u64, op: u64) -> u64 {
    use crate::flock::{
        FlockMode, FlockOutcome, LOCK_EX, LOCK_NB, LOCK_SH, LOCK_UN, release_per_fd_for_pids,
        set_per_fd, unix_socket_acquire_exclusive, unix_socket_acquire_shared,
        unix_socket_release_for_pids,
    };
    const NEG_EWOULDBLOCK: u64 = (-11_i64) as u64;

    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };
    let op = op as i32;
    let nonblock = op & LOCK_NB != 0;
    let mode = op & !LOCK_NB;

    let pid = crate::process::current_pid();
    let fd_u32 = fd_idx as u32;

    // Pull out the UnixSocket handle if this fd points at one, so the
    // global cross-fd registry can coordinate two opens of the same socket.
    let unix_handle: Option<usize> = match &entry.backend {
        FdBackend::UnixSocket { handle } => Some(*handle),
        _ => None,
    };

    // Phase 69d follow-up (PR #177 review fix): the blocking flock
    // path uses register-before-recheck — register on the wait queue
    // first, retry the acquire under registration, only then block.
    // A release that fires between the initial WouldBlock and
    // `register` is caught by the post-register retry; a release that
    // fires after register but before block is caught by `woken`
    // already being `true` when `block_current_until` checks it.  The
    // shape mirrors `unix_stream_read` / `pipe_read`.
    //
    // Phase 69d follow-up (PR #177 third-pass review fix): the closure
    // also revalidates the fd before each acquire attempt — a
    // CLONE_FILES sibling can close the fd (freeing the UnixSocket
    // handle) while this task sleeps; without revalidation the
    // waiter would acquire a lock on a recycled / closed handle.
    // The closure returns `Err(NEG_EBADF)` when the fd no longer
    // points at the same UnixSocket, propagating up out of
    // `flock_wait_blocking` so the caller surfaces EBADF instead.
    fn flock_wait_blocking(
        h: usize,
        nonblock: bool,
        mut try_acquire: impl FnMut() -> Result<FlockOutcome, u64>,
    ) -> Result<(), u64> {
        loop {
            match try_acquire()? {
                FlockOutcome::Acquired => return Ok(()),
                FlockOutcome::WouldBlock => {}
            }
            if nonblock {
                return Err(NEG_EWOULDBLOCK);
            }
            if has_pending_signal() {
                return Err(NEG_EINTR);
            }
            let task_id = match crate::task::scheduler::current_task_id() {
                Some(id) => id,
                None => return Err(NEG_EINTR),
            };
            let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
            let wq = &crate::net::unix::UNIX_SOCKET_WAITQUEUES[h];
            wq.register(task_id, &woken);
            // Phase 69d follow-up (PR #177 fifth-pass review fix): the
            // post-register `try_acquire()` may return `Err(EBADF)`
            // when the fd was closed under us by a CLONE_FILES
            // sibling.  The earlier `try_acquire()?` would early-
            // return WITHOUT deregistering the waiter, leaving a
            // stale entry on the queue that subsequent wakers would
            // touch.  Match the outcome explicitly so every exit
            // path goes through `wq.deregister`.
            match try_acquire() {
                Ok(FlockOutcome::Acquired) => {
                    wq.deregister(task_id);
                    return Ok(());
                }
                Ok(FlockOutcome::WouldBlock) => {}
                Err(e) => {
                    wq.deregister(task_id);
                    return Err(e);
                }
            }
            let _ = crate::task::scheduler::block_current_until(
                crate::task::TaskState::BlockedOnRecv,
                &woken,
                None,
            );
            wq.deregister(task_id);
            // Loop back: a fresh signal check + acquire retry runs at top.
        }
    }

    let revalidate_handle = |h: usize| -> bool {
        match current_fd_entry(fd_idx).map(|e| e.backend) {
            Some(FdBackend::UnixSocket { handle }) => handle == h,
            _ => false,
        }
    };

    match mode {
        LOCK_SH => {
            if let Some(h) = unix_handle
                && let Err(e) = flock_wait_blocking(h, nonblock, || {
                    if !revalidate_handle(h) {
                        return Err(NEG_EBADF);
                    }
                    Ok(unix_socket_acquire_shared(h, pid, fd_u32))
                })
            {
                return e;
            }
            set_per_fd(pid, fd_u32, Some(FlockMode::Shared));
            0
        }
        LOCK_EX => {
            if let Some(h) = unix_handle
                && let Err(e) = flock_wait_blocking(h, nonblock, || {
                    if !revalidate_handle(h) {
                        return Err(NEG_EBADF);
                    }
                    Ok(unix_socket_acquire_exclusive(h, pid, fd_u32))
                })
            {
                return e;
            }
            set_per_fd(pid, fd_u32, Some(FlockMode::Exclusive));
            0
        }
        LOCK_UN => {
            // Phase 69d follow-up (PR #177 review fix): in a
            // CLONE_FILES thread group the fd table is shared, so a
            // sibling can hold the actual `(holder_pid, fd)` lock
            // entry while another sibling issues the LOCK_UN.  Mirror
            // the close-path's thread-group sweep so an explicit
            // unlock from any sibling clears the lock for every
            // sibling that could have taken it on this fd.
            let release_pids: alloc::vec::Vec<u32> = {
                let table = crate::process::PROCESS_TABLE.lock();
                match table.find(pid).and_then(|p| p.thread_group.clone()) {
                    Some(tg) => tg.members.lock().clone(),
                    None => alloc::vec![pid],
                }
            };
            if let Some(h) = unix_handle {
                unix_socket_release_for_pids(h, &release_pids, fd_u32);
                // Wake any contenders parked on this handle so they can
                // re-attempt their acquire now that we've released.
                crate::net::unix::wake_unix_socket(h);
            }
            // Either remove or no-op — both are safe.  Sweep every
            // member's `(pid, fd)` per-fd entry so the side-table can't
            // surface a sibling's stale lock after this call returns.
            release_per_fd_for_pids(&release_pids, fd_u32);
            0
        }
        _ => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// set_tid_address(tidptr) — syscall 218 (musl TLS initialization)
// ---------------------------------------------------------------------------

/// `set_tid_address(tidptr)` — store the `clear_child_tid` pointer for the
/// calling thread and return the caller's TID.
///
/// musl calls this during `__init_tls` to record the address that the kernel
/// should clear (and futex-wake) when the thread exits.
pub(super) fn sys_linux_set_tid_address(tidptr: u64) -> u64 {
    let pid = crate::process::current_pid();

    {
        let mut table = crate::process::PROCESS_TABLE.lock();
        if let Some(proc) = table.find_mut(pid) {
            proc.clear_child_tid = tidptr;
            proc.tid as u64
        } else {
            pid as u64
        }
    }
}

// ===========================================================================
// Phase 21 — Ion Shell: syscall stubs for musl/nix runtime
// ===========================================================================

// ---------------------------------------------------------------------------
// access(path, mode) — syscall 21
// ---------------------------------------------------------------------------

/// Check if a path exists. Ignores the mode argument (no permission model).
pub(super) fn sys_access(path_ptr: u64) -> u64 {
    let mut buf = [0u8; 512];
    let name = match read_user_cstr(path_ptr, &mut buf) {
        Some(n) => n,
        None => return NEG_EFAULT,
    };

    let cwd = current_cwd();
    let lexical = resolve_path(&cwd, name);
    match resolve_existing_fs_path(&lexical, true) {
        Ok(_) => 0,
        Err(err) => {
            if lexical.starts_with("/usr/") {
                let rel = lexical.trim_start_matches('/');
                let vol = crate::fs::fat32::FAT32_VOLUME.lock();
                if let Some(vol) = vol.as_ref()
                    && vol.lookup(rel).is_ok()
                {
                    return 0;
                }
            }
            err
        }
    }
}

// ---------------------------------------------------------------------------
// clone(flags, ...) — syscall 56
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Clone flags (Phase 40)
// ---------------------------------------------------------------------------

const SIGCHLD: u64 = 17;
const CLONE_VM: u64 = 0x0000_0100;
#[allow(dead_code)]
const CLONE_FS: u64 = 0x0000_0200;
#[allow(dead_code)]
const CLONE_FILES: u64 = 0x0000_0400;
#[allow(dead_code)]
const CLONE_SIGHAND: u64 = 0x0000_0800;
const CLONE_THREAD: u64 = 0x0001_0000;
const CLONE_VFORK: u64 = 0x0000_4000;
const CLONE_SETTLS: u64 = 0x0008_0000;
const CLONE_PARENT_SETTID: u64 = 0x0010_0000;
const CLONE_CHILD_CLEARTID: u64 = 0x0020_0000;
const CLONE_CHILD_SETTID: u64 = 0x0100_0000;

/// Parse clone(2) flags and dispatch to the appropriate implementation.
///
/// Linux clone ABI: flags (rdi), child_stack (rsi), parent_tidptr (rdx),
/// child_tidptr (r10), tls (r8).
pub(super) fn sys_clone(
    flags: u64,
    child_stack: u64,
    parent_tidptr: u64,
    child_tidptr: u64,
    tls: u64,
    user_rip: u64,
    user_rsp: u64,
) -> u64 {
    // CLONE_THREAD requires CLONE_VM — threads must share address space.
    if flags & CLONE_THREAD != 0 && flags & CLONE_VM == 0 {
        log::warn!("sys_clone: CLONE_THREAD without CLONE_VM");
        return NEG_EINVAL;
    }

    // Thread creation path (Phase 40).
    if flags & CLONE_THREAD != 0 {
        return sys_clone_thread(
            flags,
            child_stack,
            parent_tidptr,
            child_tidptr,
            tls,
            user_rip,
        );
    }

    // musl uses clone(SIGCHLD, NULL, ...) as a fork fallback.
    // Accept flags == SIGCHLD, flags == 0, or the CLONE_VM|CLONE_VFORK
    // combination used by musl's posix_spawn/system() — treat all as fork.
    //
    // For the CLONE_VM|CLONE_VFORK case (musl's posix_spawn / system),
    // honour the caller-provided `child_stack`: musl's clone wrapper
    // pushes the child's `args` and target function onto child_stack
    // before issuing the syscall, then in the child branch does
    // `pop rdi; call *rdx`. If we ignore `child_stack` and reuse the
    // parent's RSP, the child pops random bytes from the (CoW-shared)
    // parent stack as `args` and the called function dereferences
    // garbage — m3os.log line 808 onward shows the resulting GPF in
    // musl's posix_spawn `child` at +0xa4 with `r12 = 0x001628c481480424`
    // (a non-canonical value composed of x86 instruction bytes that
    // confirm the bogus pointer landed in code memory).
    //
    // For plain fork (`flags == 0` or `SIGCHLD`), child_stack is
    // typically NULL and the child legitimately reuses the parent's
    // RSP. Fall through to that semantic in those cases.
    let fork_flags =
        flags & !(CLONE_CHILD_SETTID | CLONE_CHILD_CLEARTID | CLONE_PARENT_SETTID | CLONE_SETTLS);
    if fork_flags == 0 || fork_flags == SIGCHLD {
        sys_fork(user_rip, user_rsp)
    } else if fork_flags == (CLONE_VM | CLONE_VFORK | SIGCHLD)
        || fork_flags == (CLONE_VM | CLONE_VFORK)
    {
        let child_rsp = if child_stack != 0 {
            child_stack
        } else {
            user_rsp
        };
        sys_fork(user_rip, child_rsp)
    } else {
        log::warn!("sys_clone: unsupported flags {flags:#x}");
        NEG_ENOSYS
    }
}

// ---------------------------------------------------------------------------
// clone(CLONE_THREAD) — Phase 40, Track C
// ---------------------------------------------------------------------------

/// Create a new thread sharing the parent's address space.
///
/// The child thread:
/// - gets a new PID/TID but shares the parent's TGID
/// - shares the parent's page table (no CoW clone)
/// - shares the parent's fd table and signal actions via Arc
/// - gets its own kernel stack
/// - starts executing in userspace at `user_rip` with RSP = `child_stack`
fn sys_clone_thread(
    flags: u64,
    child_stack: u64,
    parent_tidptr: u64,
    child_tidptr: u64,
    tls: u64,
    user_rip: u64,
) -> u64 {
    use crate::process::{
        PROCESS_TABLE, Process, ProcessState, ThreadGroup, alloc_kernel_stack_pub,
    };
    use alloc::sync::Arc;

    let parent_pid = crate::process::current_pid();
    log::info!(
        "[p{}] clone_thread(flags={:#x}, child_stack={:#x})",
        parent_pid,
        flags,
        child_stack
    );

    if child_stack == 0 {
        log::warn!("sys_clone_thread: child_stack is NULL");
        return NEG_EINVAL;
    }

    // Gather parent state under lock.
    let parent_info = {
        let table = PROCESS_TABLE.lock();
        match table.find(parent_pid) {
            Some(p) => {
                let parent_addr_space = match p.addr_space.as_ref() {
                    Some(a) => alloc::sync::Arc::clone(a),
                    None => {
                        log::warn!("sys_clone_thread: parent has no page table");
                        return NEG_EINVAL;
                    }
                };
                Some((
                    parent_addr_space,
                    p.tgid,
                    p.ppid,
                    p.brk_current,
                    p.mmap_next,
                    p.pgid,
                    p.cwd.clone(),
                    p.blocked_signals,
                    p.signal_actions_snapshot(),
                    p.fs_base,
                    (p.uid, p.gid, p.euid, p.egid),
                    p.umask,
                    p.session_id,
                    p.controlling_tty.clone(),
                    p.vma_tree.clone(),
                    p.exec_path.clone(),
                    p.cmdline.clone(),
                    p.fd_table_snapshot(),
                    p.thread_group.clone(),
                    p.shared_fd_table.clone(),
                    p.shared_signal_actions.clone(),
                ))
            }
            None => None,
        }
    };

    let (
        parent_addr_space,
        parent_tgid,
        parent_ppid,
        parent_brk,
        parent_mmap,
        parent_pgid,
        parent_cwd,
        parent_blocked_signals,
        parent_signal_actions,
        parent_fs_base,
        parent_ids,
        parent_umask,
        parent_session_id,
        parent_ctty,
        parent_mappings,
        parent_exec_path,
        parent_cmdline,
        parent_fds,
        parent_thread_group,
        parent_shared_fd,
        parent_shared_sig,
    ) = match parent_info {
        Some(info) => info,
        None => {
            log::warn!("sys_clone_thread: parent {} not found", parent_pid);
            return NEG_EINVAL;
        }
    };

    let child_tgid = parent_tgid;

    // Create or join the ThreadGroup.
    let (child_pid, thread_group) = match parent_thread_group {
        Some(tg) => {
            if tg.exit_owner.load(core::sync::atomic::Ordering::Acquire) != 0 {
                log::warn!(
                    "sys_clone_thread: parent {} thread group is exiting",
                    parent_pid
                );
                return NEG_EBUSY;
            }
            // Parent already in a thread group — add child unless teardown
            // claimed ownership while we raced to the membership lock.
            let child_pid = {
                let mut members = tg.members.lock();
                if tg.exit_owner.load(core::sync::atomic::Ordering::Acquire) != 0 {
                    log::warn!(
                        "sys_clone_thread: parent {} thread group began exit during clone",
                        parent_pid
                    );
                    return NEG_EBUSY;
                }
                let child_pid = crate::process::alloc_pid_pub();
                members.push(child_pid);
                child_pid
            };
            (child_pid, tg)
        }
        None => {
            // First thread creation — create a new group with parent as leader.
            let child_pid = crate::process::alloc_pid_pub();
            let tg = Arc::new(ThreadGroup {
                leader_tid: parent_tgid,
                members: crate::task::scheduler::IrqSafeMutex::new(alloc::vec![
                    parent_tgid,
                    child_pid
                ]),
                exit_owner: core::sync::atomic::AtomicU32::new(0),
            });
            // Set the parent's thread_group under lock.
            {
                let mut table = PROCESS_TABLE.lock();
                if let Some(p) = table.find_mut(parent_pid) {
                    p.thread_group = Some(tg.clone());
                }
            }
            (child_pid, tg)
        }
    };

    // Share fd table only when CLONE_FILES is set; otherwise child gets a
    // private copy (shared_fd_table stays None).
    // Clone parent_fds before the potential move into an Arc so it remains
    // available for the non-shared path in the child Process builder.
    let child_fds_copy = parent_fds.clone();
    let shared_fd = if flags & CLONE_FILES != 0 {
        Some(match parent_shared_fd {
            Some(arc) => arc,
            None => {
                let arc = Arc::new(crate::task::scheduler::IrqSafeMutex::new(parent_fds));
                // Update parent to use shared fd table.
                {
                    let mut table = PROCESS_TABLE.lock();
                    if let Some(p) = table.find_mut(parent_pid) {
                        p.shared_fd_table = Some(arc.clone());
                    }
                }
                arc
            }
        })
    } else {
        None
    };

    // Share signal actions only when CLONE_SIGHAND is set; otherwise child
    // gets its own private copy.
    let shared_sig = if flags & CLONE_SIGHAND != 0 {
        Some(match parent_shared_sig {
            Some(arc) => arc,
            None => {
                let arc = Arc::new(crate::task::scheduler::IrqSafeMutex::new(
                    parent_signal_actions,
                ));
                {
                    let mut table = PROCESS_TABLE.lock();
                    if let Some(p) = table.find_mut(parent_pid) {
                        p.shared_signal_actions = Some(arc.clone());
                    }
                }
                arc
            }
        })
    } else {
        None
    };

    // Allocate a NEW kernel stack for the child thread.
    let kstack_top = alloc_kernel_stack_pub();

    // Phase 110 A.3b part 5 — the shared user half maps only the creating
    // task's kstack top page; this thread's ring-3 interrupt frames push onto
    // ITS kstack top on the user CR3, so map that page too (no-op while KPTI
    // is inactive).
    //
    // A.4 fail-closed: on mapping failure the thread must not start — its
    // first ring-3 interrupt would push the CPU frame onto an unmapped kstack
    // top on the user CR3 and escalate #PF → #DF, killing the whole thread
    // group. Fail the clone cleanly instead (the freshly-allocated kstack
    // leaks, like the other rare OOM error returns).
    if !parent_addr_space.kpti_map_thread_kstack(kstack_top) {
        const NEG_ENOMEM: u64 = (-12_i64) as u64;
        return NEG_ENOMEM;
    }

    // Determine TLS: if CLONE_SETTLS, use the provided tls value.
    let child_fs_base = if flags & CLONE_SETTLS != 0 {
        tls
    } else {
        parent_fs_base
    };

    // Determine clear_child_tid.
    let child_clear_tid = if flags & CLONE_CHILD_CLEARTID != 0 {
        child_tidptr
    } else {
        0
    };

    // Build the child Process entry.
    let child_proc = Process {
        pid: child_pid,
        tid: child_pid,
        tgid: child_tgid,
        clear_child_tid: child_clear_tid,
        ppid: parent_ppid,
        state: ProcessState::Ready,
        addr_space: Some(parent_addr_space), // SHARED — same AddressSpace via Arc
        kernel_stack_top: kstack_top,
        entry_point: user_rip,
        user_stack_top: child_stack,
        exit_code: None,
        stop_signal: 0,
        stop_reported: false,
        brk_current: parent_brk,
        mmap_next: parent_mmap,
        pgid: parent_pgid,
        fd_table: {
            // When sharing via Arc, snapshot from the shared table;
            // otherwise use the private copy.
            if let Some(ref arc) = shared_fd {
                arc.lock().clone()
            } else {
                child_fds_copy
            }
        },
        pending_signals: 0,
        blocked_signals: parent_blocked_signals,
        signal_actions: {
            if let Some(ref arc) = shared_sig {
                *arc.lock()
            } else {
                parent_signal_actions
            }
        },
        alt_stack_base: 0,
        alt_stack_size: 0,
        alt_stack_flags: 0,
        cwd: parent_cwd,
        fs_base: child_fs_base,
        uid: parent_ids.0,
        gid: parent_ids.1,
        euid: parent_ids.2,
        egid: parent_ids.3,
        umask: parent_umask,
        session_id: parent_session_id,
        controlling_tty: parent_ctty,
        vma_tree: parent_mappings,
        // Phase 90a B.3 — the protection-key table is a property of the address
        // space. A `clone`/`fork` child inherits a copy of the parent's table
        // here; for a `CLONE_VM` thread the shared-mm sync below keeps all
        // threads' copies identical (the canonical table is the tgid's). Reset
        // to a fresh table if the parent is gone.
        pkey_table: {
            crate::process::PROCESS_TABLE
                .lock()
                .find(parent_pid)
                .map(|p| p.pkey_table)
                .unwrap_or_default()
        },
        exec_path: parent_exec_path,
        cmdline: parent_cmdline,
        start_ticks: crate::arch::x86_64::interrupts::tick_count(),
        thread_group: Some(thread_group),
        shared_fd_table: shared_fd,
        shared_signal_actions: shared_sig,
        // Threads inherit the parent's comm; `prctl(PR_SET_NAME)` then
        // gives each thread its own name as Linux does.
        comm: {
            crate::process::PROCESS_TABLE
                .lock()
                .find(parent_pid)
                .map(|p| p.comm)
                .unwrap_or([0u8; 16])
        },
        // A fork child starts untraced (Linux: tracing is not inherited by
        // default); the child sets it via PTRACE_TRACEME after fork.
        #[cfg(feature = "ptrace")]
        ptrace: crate::process::ptrace::Ptrace::default(),
    };

    PROCESS_TABLE.lock().insert(child_proc);
    crate::process::sync_shared_mm_state(child_pid);

    // CLONE_PARENT_SETTID: write child TID to parent_tidptr in userspace.
    if flags & CLONE_PARENT_SETTID != 0 && parent_tidptr != 0 {
        let tid_bytes = (child_pid as i32).to_ne_bytes();
        let _ = UserSliceWo::new(parent_tidptr, tid_bytes.len())
            .and_then(|s| s.copy_from_kernel(&tid_bytes));
    }

    // CLONE_CHILD_SETTID: write child TID to child_tidptr in userspace.
    // Since we share the address space, we can write it now from the parent context.
    if flags & CLONE_CHILD_SETTID != 0 && child_tidptr != 0 {
        let tid_bytes = (child_pid as i32).to_ne_bytes();
        let _ = UserSliceWo::new(child_tidptr, tid_bytes.len())
            .and_then(|s| s.copy_from_kernel(&tid_bytes));
    }

    crate::task::spawn_fork_task(
        crate::process::make_fork_ctx_for_thread(child_pid, user_rip, child_stack),
        "clone-thread",
    );

    log::debug!("[p{}] clone_thread → child tid {}", parent_pid, child_pid);
    child_pid as u64
}

// ---------------------------------------------------------------------------
// fcntl(fd, cmd, arg) — syscall 72
// ---------------------------------------------------------------------------

/// Minimal fcntl: F_DUPFD, F_GETFD, F_SETFD, F_GETFL, F_SETFL.
pub(super) fn sys_fcntl(fd: u64, cmd: u64, arg: u64) -> u64 {
    const F_DUPFD: u64 = 0;
    const F_GETFD: u64 = 1;
    const F_SETFD: u64 = 2;
    const F_GETFL: u64 = 3;
    const F_SETFL: u64 = 4;
    const F_DUPFD_CLOEXEC: u64 = 1030;

    match cmd {
        F_DUPFD | F_DUPFD_CLOEXEC => {
            // Find the next free fd >= arg, duplicate oldfd into it.
            let set_cloexec = cmd == F_DUPFD_CLOEXEC;
            let oldfd = fd as usize;
            let min_fd = arg as usize;
            if oldfd >= MAX_FDS {
                return NEG_EBADF;
            }
            if min_fd >= MAX_FDS {
                return NEG_EINVAL;
            }
            let mut entry = match current_fd_entry(oldfd) {
                Some(e) => e,
                None => return NEG_EBADF,
            };
            if set_cloexec {
                entry.cloexec = true;
            }
            // Remember backend info so we only bump refcount on successful alloc.
            let backend_clone = entry.backend.clone();
            match alloc_fd(min_fd, entry) {
                Some(new_fd) => {
                    // Increment refcount only after successful allocation.
                    match &backend_clone {
                        FdBackend::PipeRead { pipe_id } => {
                            crate::pipe::pipe_add_reader(*pipe_id);
                        }
                        FdBackend::PipeWrite { pipe_id } => {
                            crate::pipe::pipe_add_writer(*pipe_id);
                        }
                        FdBackend::PtyMaster { pty_id } => {
                            crate::pty::add_master_ref(*pty_id);
                        }
                        FdBackend::PtySlave { pty_id } => {
                            crate::pty::add_slave_ref(*pty_id);
                        }
                        FdBackend::Socket { handle } => {
                            crate::net::add_socket_ref(*handle);
                        }
                        FdBackend::UnixSocket { handle } => {
                            crate::net::unix::add_unix_socket_ref(*handle);
                        }
                        FdBackend::Epoll { instance_id } => {
                            epoll_add_ref(*instance_id);
                        }
                        // Phase 86d Track D — eventfd is refcounted like the
                        // other dup paths (sys_dup/sys_dup2); fcntl(F_DUPFD)
                        // must bump it too, else closing either fd frees the
                        // object under the other.
                        FdBackend::EventFd { id } => {
                            crate::eventfd::eventfd_add_ref(*id);
                        }
                        // Phase 89 Track A.1 — same for timerfd (sys_dup/sys_dup2
                        // already bump it; fcntl(F_DUPFD) must stay symmetric).
                        FdBackend::TimerFd { id } => {
                            crate::timerfd::timerfd_add_ref(*id);
                        }
                        _ => {}
                    }
                    new_fd as u64
                }
                None => NEG_EMFILE,
            }
        }
        F_GETFD => {
            // Return FD_CLOEXEC (1) if cloexec is set.
            match current_fd_entry(fd as usize) {
                Some(e) => {
                    if e.cloexec {
                        1
                    } else {
                        0
                    }
                }
                None => NEG_EBADF,
            }
        }
        F_SETFD => {
            // arg & 1 = FD_CLOEXEC. Must return EBADF for a closed/out-of-range
            // fd (like F_GETFD / F_SETFL) — NOT silent success. Otherwise a
            // "set FD_CLOEXEC on every fd until EBADF" loop (Node 22's libuv does
            // exactly this at startup) never terminates: m3OS reported success
            // for fd 0,1,2,… into the millions, busy-looping the process forever.
            if current_fd_entry(fd as usize).is_none() {
                return NEG_EBADF;
            }
            let cloexec = arg & 1 != 0;
            with_current_fd_mut(fd as usize, |slot| {
                if let Some(e) = slot {
                    e.cloexec = cloexec;
                }
            });
            0
        }
        F_GETFL => {
            const O_NONBLOCK: u64 = 0x800;
            const O_RDONLY: u64 = 0;
            const O_WRONLY: u64 = 1;
            const O_RDWR: u64 = 2;
            match current_fd_entry(fd as usize) {
                Some(e) => {
                    let mut flags = match (e.readable, e.writable) {
                        (true, true) => O_RDWR,
                        (false, true) => O_WRONLY,
                        _ => O_RDONLY,
                    };
                    if e.nonblock {
                        flags |= O_NONBLOCK;
                    }
                    flags
                }
                None => NEG_EBADF,
            }
        }
        F_SETFL => {
            const O_NONBLOCK: u64 = 0x800;
            if current_fd_entry(fd as usize).is_none() {
                return NEG_EBADF;
            }
            let nonblock = arg & O_NONBLOCK != 0;
            with_current_fd_mut(fd as usize, |slot| {
                if let Some(e) = slot {
                    e.nonblock = nonblock;
                }
            });
            0
        }
        _ => NEG_EINVAL,
    }
}

// ---------------------------------------------------------------------------
// getrandom(buf, buflen, flags) — syscall 318 (Phase 86a Track A.4 rewrite)
// ---------------------------------------------------------------------------

/// getrandom flags (Linux-compatible).
const GRND_NONBLOCK: u64 = 0x0001;
const GRND_RANDOM: u64 = 0x0002;
const GRND_INSECURE: u64 = 0x0004;
const GRND_KNOWN_FLAGS: u64 = GRND_NONBLOCK | GRND_RANDOM | GRND_INSECURE;

/// Monotonic seconds-since-boot counter for reseed timing.
/// Tracks seconds at last reseed (coarse: compare tick_count / TICKS_PER_SEC).
static LAST_RESEED_TICKS: core::sync::atomic::AtomicU64 = core::sync::atomic::AtomicU64::new(0);

/// Reseed the CSPRNG if the output ceiling or 60-second interval has been reached.
/// Non-blocking; uses `gather_seed_entropy()` which never sleeps.
fn maybe_reseed_csprng() {
    use core::sync::atomic::Ordering;
    if kernel_core::csprng::global_needs_reseed() {
        let (seed, bits, _src) = gather_seed_entropy();
        kernel_core::csprng::global_reseed(&seed, bits);
        let now = crate::arch::x86_64::interrupts::tick_count();
        LAST_RESEED_TICKS.store(now, Ordering::Relaxed);
        return;
    }
    // 60-second interval check (coarse, based on tick counter)
    let now = crate::arch::x86_64::interrupts::tick_count();
    let last = LAST_RESEED_TICKS.load(Ordering::Relaxed);
    let elapsed_secs = now.saturating_sub(last) / TICKS_PER_SEC;
    if elapsed_secs >= 60 {
        let (seed, bits, _src) = gather_seed_entropy();
        kernel_core::csprng::global_reseed(&seed, bits);
        LAST_RESEED_TICKS.store(now, Ordering::Relaxed);
    }
}

/// Fill the user buffer at `buf_ptr` (length `len`) from `fill_fn`, using a
/// 256-byte stack chunk loop so we never allocate a large kernel buffer.
///
/// Preserves the ≤256-byte single-call atomicity required by
/// `userspace/sshd/src/getrandom_impl.rs` (ret == len contract): the chunk
/// loop fills the ENTIRE requested length and returns `len`, never a short
/// count.
fn getrandom_fill_user(buf_ptr: u64, len: usize, insecure: bool) -> Result<usize, ()> {
    let mut chunk = [0u8; 256];
    let mut written = 0usize;
    while written < len {
        let to_fill = (len - written).min(chunk.len());
        if insecure {
            kernel_core::csprng::global_fill_insecure(&mut chunk[..to_fill]);
        } else {
            // Invariant: the DRBG transitions to READY monotonically — once
            // READY it never reverts.  `sys_getrandom` pre-checks readiness
            // before entering the secure branch (and falls back to insecure
            // when still not ready), so `global_fill` here must always
            // succeed.  A `NotReady` error here would be a logic bug.
            debug_assert!(
                kernel_core::csprng::global_ready(),
                "getrandom secure branch entered while DRBG is not READY (monotonic invariant violated)"
            );
            kernel_core::csprng::global_fill(&mut chunk[..to_fill]).map_err(|_| ())?;
        }
        UserSliceWo::new(buf_ptr + written as u64, to_fill)
            .and_then(|s| s.copy_from_kernel(&chunk[..to_fill]))?;
        written += to_fill;
    }
    Ok(len)
}

/// `getrandom(buf, buflen, flags)` — syscall 318.
///
/// Flags:
///   `GRND_NONBLOCK (0x01)` — return `EAGAIN` if DRBG is not yet `READY`.
///   `GRND_RANDOM   (0x02)` — honored; same DRBG, not rejected.
///   `GRND_INSECURE (0x04)` — serve even when DRBG is not `READY`.
///   `GRND_INSECURE | GRND_RANDOM` together → `EINVAL` (Linux semantics).
///   Unknown flag bits → `EINVAL`.
///
/// Always fills the exact requested length (no cap, no short count).
/// Performs a best-effort reseed at the output ceiling or after 60 seconds.
pub(super) fn sys_getrandom(buf_ptr: u64, buflen: u64, flags: u64) -> u64 {
    let len = buflen as usize;
    if len == 0 {
        return 0;
    }

    // Validate flags.
    if flags & !GRND_KNOWN_FLAGS != 0 {
        return NEG_EINVAL;
    }
    if flags & GRND_INSECURE != 0 && flags & GRND_RANDOM != 0 {
        // Linux: GRND_INSECURE and GRND_RANDOM are mutually exclusive.
        return NEG_EINVAL;
    }

    let insecure = flags & GRND_INSECURE != 0;

    // Opportunistically reseed before serving (non-blocking).
    maybe_reseed_csprng();

    let result = if insecure {
        // GRND_INSECURE: serve regardless of READY state.
        getrandom_fill_user(buf_ptr, len, true)
    } else {
        // Secure path: check READY.
        if !kernel_core::csprng::global_ready() {
            if flags & GRND_NONBLOCK != 0 {
                // GRND_NONBLOCK + not ready → EAGAIN.
                return NEG_EAGAIN;
            }
            // Blocking-style: do a best-effort synchronous re-gather then serve.
            // In practice the DRBG is already READY because A.3 seeds at boot
            // before any userspace runs; this path is a safety net.  Gate it to
            // at most one attempt per boot: on a degraded (no-RDSEED/RDRAND)
            // boot `gather_seed_entropy()` credits 0 bits, so the DRBG can never
            // reach READY and an ungated call would re-gather entropy and emit a
            // "[csprng] seeded …" log line on *every* secure getrandom, flooding
            // the serial console.  A second attempt adds no credited bits, so
            // one is enough; thereafter we just serve insecure (below).
            static SAFETY_RESEED_DONE: core::sync::atomic::AtomicBool =
                core::sync::atomic::AtomicBool::new(false);
            if !SAFETY_RESEED_DONE.swap(true, core::sync::atomic::Ordering::Relaxed) {
                seed_csprng_early();
            }
        }
        // After the best-effort re-seed, serve insecure if still not ready
        // (degraded-TSC-only boot path) so we never deadlock.
        let still_insecure = !kernel_core::csprng::global_ready();
        getrandom_fill_user(buf_ptr, len, still_insecure)
    };

    match result {
        Ok(n) => {
            // Opportunistically reseed after serving too.
            maybe_reseed_csprng();
            n as u64
        }
        Err(()) => NEG_EFAULT,
    }
}

// ---------------------------------------------------------------------------
// Phase 84 Track D.3 / C.4 — mitigation reporter + STIBP opt-in (m3OS-native)
// ---------------------------------------------------------------------------

/// D.3 — copy the boot-populated mitigation report wire bytes into a user
/// buffer. `sys_mitigations_status(buf_ptr, buf_len) -> isize`: bytes written on
/// success, `-EINVAL` if the buffer is too small, `-EFAULT` on a bad pointer.
///
/// Reads the boot snapshot (`mitigations::report()`), **never** a re-`rdmsr` of
/// the write-mostly SPEC_CTRL MSR.
pub(super) fn sys_mitigations_status(buf_ptr: u64, buf_len: u64) -> u64 {
    use kernel_core::spectre::MITIGATION_REPORT_WIRE_LEN;
    let bytes = crate::mitigations::report().encode();
    if (buf_len as usize) < MITIGATION_REPORT_WIRE_LEN {
        return NEG_EINVAL;
    }
    if UserSliceWo::new(buf_ptr, MITIGATION_REPORT_WIRE_LEN)
        .and_then(|s| s.copy_from_kernel(&bytes[..]))
        .is_err()
    {
        return NEG_EFAULT;
    }
    MITIGATION_REPORT_WIRE_LEN as u64
}

/// C.4 — m3OS-native STIBP opt-in (m3OS has no Linux `prctl`).
/// `sys_set_spec_ctrl(enable_stibp) -> isize`: 0 on success. Records the calling
/// process's opt-in; the scheduler applies/clears `SPEC_CTRL.STIBP` at dispatch
/// **only** on STIBP-capable silicon with mitigations not disabled (a no-op on
/// the QEMU test lanes). Default is off (no opt-in).
pub(super) fn sys_set_spec_ctrl(enable: u64) -> u64 {
    let pid = crate::process::current_pid();
    crate::mitigations::set_stibp_opt_in(pid, enable != 0);
    0
}

// ---------------------------------------------------------------------------
// Phase 103 Track E — cpufreq syscalls (0x1160/0x1161)
// ---------------------------------------------------------------------------

/// `sys_power_set_perf(target) -> isize`: apply a governor target on the
/// abstract 1–255 scale. Root-only — an HWP request caps the whole
/// package's clock, so an unprivileged caller could throttle the system.
/// A successful no-op when no mechanism was probed (every QEMU lane), so
/// `powerd`'s policy loop is platform-independent.
pub(super) fn sys_power_set_perf(target: u64) -> u64 {
    let (_, _, euid, _) = current_process_ids();
    if euid != 0 {
        return NEG_EPERM;
    }
    if target == 0 || target > 255 {
        return NEG_EINVAL;
    }
    crate::arch::x86_64::cpufreq::apply_target(target as u8);
    0
}

/// `sys_power_enter_sleep() -> isize`: enter ACPI S3 and return after
/// resume (Phase 103 F.3). Root-only — a suspend stops the machine for
/// every user. 0 = resumed; -ENOSYS when the platform never registered
/// `\_S3`/has no FACS (powerd stays fail-closed); other negative errno
/// on a refused entry, always with the machine live.
pub(super) fn sys_power_enter_sleep() -> u64 {
    let (_, _, euid, _) = current_process_ids();
    if euid != 0 {
        return NEG_EPERM;
    }
    crate::arch::x86_64::suspend::enter_sleep_s3() as u64
}

/// `sys_power_cpufreq_status(buf_ptr, buf_len) -> isize`: copy the
/// [`kernel_core::power::syscalls::CpufreqStatusWire`] snapshot (probed
/// mechanism + last target + cumulative scheduler CPU times) into a user
/// buffer. Read-only, ungated — same posture as `SYS_MITIGATIONS_STATUS`.
pub(super) fn sys_power_cpufreq_status(buf_ptr: u64, buf_len: u64) -> u64 {
    use kernel_core::power::syscalls::CPUFREQ_STATUS_WIRE_LEN;
    let bytes = crate::arch::x86_64::cpufreq::status().encode();
    if (buf_len as usize) < CPUFREQ_STATUS_WIRE_LEN {
        return NEG_EINVAL;
    }
    if UserSliceWo::new(buf_ptr, CPUFREQ_STATUS_WIRE_LEN)
        .and_then(|s| s.copy_from_kernel(&bytes[..]))
        .is_err()
    {
        return NEG_EFAULT;
    }
    CPUFREQ_STATUS_WIRE_LEN as u64
}

// ---------------------------------------------------------------------------
// Phase 106 Track C — installer raw block syscalls (0x117x)
// ---------------------------------------------------------------------------

/// Every raw block syscall is gated on the installer's unforgeable exec
/// path (`/sbin/installer`) — raw cross-device I/O bypasses the
/// filesystem permission layer, so it must never be ambient. Same trust
/// model as the `/drivers/` device-host gate: `exec_path` is written by
/// the kernel at `execve`, so ring 3 cannot spoof it.
fn is_installer_process() -> bool {
    is_current_exec_path(kernel_core::installer::INSTALLER_EXEC_PATH)
}

/// Validate a raw request's `dev_id`, `start_lba`, and `count`, and
/// compute the byte length. `dev_id 0` is the root device; `1..` are
/// registered secondary slots. Returns `Err(errno)` on any violation
/// (never a panic / OOB).
fn raw_request_bytes(dev_id: u64, count: u64) -> Result<usize, u64> {
    use kernel_core::installer::{SECTOR_BYTES, raw_count_ok};
    if !raw_count_ok(count) {
        return Err(NEG_EINVAL);
    }
    if dev_id > u64::from(u32::MAX) {
        return Err(NEG_EINVAL);
    }
    if dev_id != 0 && !crate::blk::is_remote_device_registered(dev_id as u32) {
        return Err(NEG_ENODEV);
    }
    // count ≤ MAX_SECTORS_PER_RAW_REQUEST (256) so this cannot overflow.
    Ok((count * SECTOR_BYTES) as usize)
}

/// `sys_blk_resolve_dev(name_ptr, name_len) -> isize`: register (or
/// look up) a block-device service by name and return its `dev_id`.
/// Installer-gated. `name_len` is bounded to a service-name-sized
/// buffer.
pub(super) fn sys_blk_resolve_dev(name_ptr: u64, name_len: u64) -> u64 {
    if !is_installer_process() {
        return NEG_EPERM;
    }
    // Service names are short ("nvme.block", "usb0.block", …).
    if name_len == 0 || name_len > 64 {
        return NEG_EINVAL;
    }
    let mut buf = [0u8; 64];
    let len = name_len as usize;
    if UserSliceRo::new(name_ptr, len)
        .and_then(|s| s.copy_to_kernel(&mut buf[..len]))
        .is_err()
    {
        return NEG_EFAULT;
    }
    let Ok(name) = core::str::from_utf8(&buf[..len]) else {
        return NEG_EINVAL;
    };
    // The device_name is a stable per-service handle label; reuse the
    // service basename before ".block" as the display name.
    let dev_name = name.strip_suffix(".block").unwrap_or(name);
    match crate::blk::register_remote_device(name, dev_name) {
        Some(dev_id) => dev_id as u64,
        None => NEG_ENODEV,
    }
}

/// `sys_blk_raw_read(dev_id, start_lba, count, buf_ptr) -> isize`:
/// copy `count` sectors from `dev_id` into the user buffer. Returns the
/// byte count, or a negative errno. Installer-gated.
pub(super) fn sys_blk_raw_read(dev_id: u64, start_lba: u64, count: u64, buf_ptr: u64) -> u64 {
    if !is_installer_process() {
        return NEG_EPERM;
    }
    let bytes = match raw_request_bytes(dev_id, count) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let mut kbuf = alloc::vec![0u8; bytes];
    let io = if dev_id == 0 {
        crate::blk::read_sectors(start_lba, count as usize, &mut kbuf)
    } else {
        crate::blk::read_sectors_dev(dev_id as u32, start_lba, count as usize, &mut kbuf)
    };
    if io.is_err() {
        return NEG_EIO;
    }
    if UserSliceWo::new(buf_ptr, bytes)
        .and_then(|s| s.copy_from_kernel(&kbuf))
        .is_err()
    {
        return NEG_EFAULT;
    }
    bytes as u64
}

/// `sys_blk_raw_write(dev_id, start_lba, count, buf_ptr) -> isize`:
/// copy `count` sectors from the user buffer to `dev_id`. Destructive —
/// installer-gated. Returns the byte count, or a negative errno.
pub(super) fn sys_blk_raw_write(dev_id: u64, start_lba: u64, count: u64, buf_ptr: u64) -> u64 {
    if !is_installer_process() {
        return NEG_EPERM;
    }
    let bytes = match raw_request_bytes(dev_id, count) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let mut kbuf = alloc::vec![0u8; bytes];
    if UserSliceRo::new(buf_ptr, bytes)
        .and_then(|s| s.copy_to_kernel(&mut kbuf))
        .is_err()
    {
        return NEG_EFAULT;
    }
    let io = if dev_id == 0 {
        crate::blk::write_sectors(start_lba, count as usize, &kbuf)
    } else {
        crate::blk::write_sectors_dev(dev_id as u32, start_lba, count as usize, &kbuf)
    };
    if io.is_err() {
        return NEG_EIO;
    }
    bytes as u64
}

/// `sys_blk_raw_flush(dev_id) -> isize`: flush `dev_id`'s write-back
/// cache (0 on success, negative errno). Installer-gated.
pub(super) fn sys_blk_raw_flush(dev_id: u64) -> u64 {
    if !is_installer_process() {
        return NEG_EPERM;
    }
    if dev_id > u64::from(u32::MAX) {
        return NEG_EINVAL;
    }
    if dev_id == 0 {
        crate::blk::flush();
        return 0;
    }
    if !crate::blk::is_remote_device_registered(dev_id as u32) {
        return NEG_ENODEV;
    }
    match crate::blk::flush_dev(dev_id as u32) {
        Ok(()) => 0,
        Err(_) => NEG_EIO,
    }
}

// ---------------------------------------------------------------------------
// Track D debug probe — SYS_KSTACK_OVERFLOW_TEST (0x1150)
// (docs/handoffs/2026-06-14-claude-smp-tlb-shootdown-kstack-panic.md)
// ---------------------------------------------------------------------------
//
// Feature-gated (`kstack-overflow-test`); absent in production (the number
// falls through to ENOSYS). Deliberately overflows the calling task's per-task
// kernel stack so the controlled-kill recovery path can be exercised end-to-end
// on plain TCG: the recursion marches RSP into the slot's guard page, the
// resulting ring-0 #PF/#DF is recognised as a kstack overflow, and the offending
// process is SIGSEGV-killed while the rest of the system keeps running.

/// m3OS-native syscall number for the Track D overflow probe (0x114x block).
#[cfg(feature = "kstack-overflow-test")]
pub const SYS_KSTACK_OVERFLOW_TEST: u64 = 0x1150;

/// Recurse with a sizable written local buffer so each frame consumes ~1 KiB
/// and the 64 KiB kernel stack is exhausted in well under 100 frames. Not tail
/// recursion (the result is combined *after* the recursive call), so the
/// compiler cannot rewrite it into a loop; `black_box` + volatile keep the
/// buffer live and un-elided.
#[cfg(feature = "kstack-overflow-test")]
#[inline(never)]
#[allow(unconditional_recursion)]
fn kstack_overflow_recurse(depth: u64) -> u64 {
    let mut buf = [0u8; 1024];
    for (i, b) in buf.iter_mut().enumerate() {
        unsafe { core::ptr::write_volatile(b, (depth as u8).wrapping_add(i as u8)) };
    }
    let tail = unsafe { core::ptr::read_volatile(&buf[(depth as usize) & 1023]) } as u64;
    core::hint::black_box(tail).wrapping_add(kstack_overflow_recurse(depth.wrapping_add(1)))
}

/// `SYS_KSTACK_OVERFLOW_TEST` handler — never returns normally (the recursion
/// overflows the kstack and the fault handler kills this process first).
#[cfg(feature = "kstack-overflow-test")]
pub(super) fn sys_kstack_overflow_test() -> u64 {
    log::warn!(
        "[kstack-test] pid {} deliberately overflowing its kernel stack (Track D recovery probe)",
        crate::process::current_pid(),
    );
    core::hint::black_box(kstack_overflow_recurse(core::hint::black_box(0)))
}

// ---------------------------------------------------------------------------
// Track C.1 panic-quiesce demo — SYS_PANIC_TEST (0x1151)
// ---------------------------------------------------------------------------
//
// Feature-gated (`panic-test`); absent in production (the number falls through
// to the default dispatch arm → `NEG_ENOSYS`). Deliberately `panic!()`s the
// calling core so the panic-path AP-quiesce (`smp::panic_quiesce_aps`, Phase 99
// Track C.1) can be demonstrated end-to-end: with sibling cores actively writing
// COM1, the quiesce must halt them BEFORE the banner prints so it lands
// uninterleaved. Used by the `panic-test-smoke` gate.

/// m3OS-native Track C.1 demo syscall. Never returns (the panic halts this core
/// after the AP-quiesce + banner print).
#[cfg(feature = "panic-test")]
pub const SYS_PANIC_TEST: u64 = 0x1151;

/// `SYS_PANIC_TEST` handler — never returns (panics through the real
/// `handle_panic` → `panic_quiesce_aps` path; not a `cfg(test)` build, so the
/// quiesce-and-print code actually runs).
#[cfg(feature = "panic-test")]
pub(super) fn sys_panic_test() -> u64 {
    // The sentinel is what `panic-test-smoke` asserts appears CONTIGUOUS with the
    // `KERNEL PANIC at …` banner (proof the sibling COM1 spam was quiesced first).
    panic!(
        "PANICTEST_SENTINEL deliberate Track-C.1 panic from pid {}",
        crate::process::current_pid()
    );
}

// ---------------------------------------------------------------------------
// Track D — sys_ptrace (0x1152) + the ptrace-stop trampoline
// ---------------------------------------------------------------------------
//
// Feature-gated (`ptrace`); absent in production (the number falls through to
// `NEG_ENOSYS`, and the #BP DPL-3 gate + trap consumers are all `cfg`-off). The
// tracer (`m3gdbserver`) drives a traced tracee via this syscall; a tracee's
// ring-3 debug trap redirects into `ptrace_stop_trampoline` below.

/// m3OS reuses the Linux `ptrace` request numbers for the practical subset.
#[cfg(feature = "ptrace")]
pub const SYS_PTRACE: u64 = 0x1152;

/// Phase 111 Track D — ptrace-stop continuation. A traced tracee's `#BP`/`#DB`
/// handler redirects its `iretq` here (the `fault_kill_trampoline` technique)
/// so the stop-and-wait runs in a normal, blockable ring-0 context instead of
/// inside the exception handler. Notifies the tracer, parks the tracee until it
/// issues `CONT`/`SINGLESTEP`/`DETACH`/`KILL`, then re-enters userspace with the
/// (possibly `SETREGS`-modified) registers. Never returns.
#[cfg(feature = "ptrace")]
pub extern "C" fn ptrace_stop_trampoline() -> ! {
    // IRET restored the (cleared) IF from the redirected frame; re-enable so the
    // park loop is scheduled against, mirroring `fault_kill_trampoline`.
    x86_64::instructions::interrupts::enable();
    ptrace_park_and_resume()
}

/// Park the current (traced) tracee until the tracer resumes it, then re-enter
/// userspace with the resulting registers (or terminate on `KILL`). Shared by
/// the `#BP`/`#DB` stop trampoline and the `execve` exec-stop — both call this
/// from a normal, blockable ring-0 context (interrupts already enabled). Never
/// returns.
#[cfg(feature = "ptrace")]
pub fn ptrace_park_and_resume() -> ! {
    match crate::process::ptrace::enter_stop_and_wait() {
        crate::process::ptrace::ResumeAction::Kill => {
            let pid = crate::process::current_pid();
            terminate_thread_group_and_exit(pid, -(crate::process::ptrace::SIGTRAP as i32));
        }
        crate::process::ptrace::ResumeAction::Resume(regs) => {
            // SAFETY: `regs` holds valid userspace RIP/RSP (captured at the trap
            // / the new image's entry, or set via SETREGS); resume to ring 3.
            unsafe { restore_and_enter_userspace(&regs) }
        }
    }
}

/// View a `SavedUserRegs` as its raw `#[repr(C)]` bytes (18 × u64 = 144 bytes)
/// for the GETREGS/SETREGS userspace copy.
#[cfg(feature = "ptrace")]
fn saved_regs_bytes(regs: &crate::signal::SavedUserRegs) -> &[u8] {
    // SAFETY: `SavedUserRegs` is `#[repr(C)]` plain `u64`s with no padding.
    unsafe {
        core::slice::from_raw_parts(
            regs as *const _ as *const u8,
            core::mem::size_of::<crate::signal::SavedUserRegs>(),
        )
    }
}

/// `sys_ptrace(request, pid, addr, data)` — the practical ptrace subset
/// (`TRACEME`, `PEEK/POKE TEXT/DATA`, `CONT`, `KILL`, `SINGLESTEP`,
/// `GETREGS`/`SETREGS`, `DETACH`). Linux request numbers.
#[cfg(feature = "ptrace")]
pub(super) fn sys_ptrace(request: u64, pid: u64, addr: u64, data: u64) -> u64 {
    use crate::process::ptrace::{self, PtraceResume};

    // Linux PTRACE_* request constants (the subset we implement).
    const TRACEME: u64 = 0;
    const PEEKTEXT: u64 = 1;
    const PEEKDATA: u64 = 2;
    const POKETEXT: u64 = 4;
    const POKEDATA: u64 = 5;
    const CONT: u64 = 7;
    const KILL: u64 = 8;
    const SINGLESTEP: u64 = 9;
    const GETREGS: u64 = 12;
    const SETREGS: u64 = 13;
    const DETACH: u64 = 17;

    let caller = crate::process::current_pid();
    let tracee = pid as u32;

    match request {
        TRACEME => ptrace::traceme() as u64,
        PEEKTEXT | PEEKDATA => match ptrace::peek(caller, tracee, addr) {
            Some(word) => word,
            None => NEG_EFAULT,
        },
        POKETEXT | POKEDATA => ptrace::poke(caller, tracee, addr, data) as u64,
        CONT => ptrace::resume(caller, tracee, PtraceResume::Cont) as u64,
        KILL => ptrace::resume(caller, tracee, PtraceResume::Kill) as u64,
        SINGLESTEP => ptrace::resume(caller, tracee, PtraceResume::Step) as u64,
        DETACH => ptrace::resume(caller, tracee, PtraceResume::Detach) as u64,
        GETREGS => match ptrace::getregs(caller, tracee) {
            Some(regs) => {
                let bytes = saved_regs_bytes(&regs);
                match UserSliceWo::new(data, bytes.len()) {
                    Ok(s) if s.copy_from_kernel(bytes).is_ok() => 0,
                    _ => NEG_EFAULT,
                }
            }
            None => NEG_ESRCH,
        },
        SETREGS => {
            let mut buf = [0u8; core::mem::size_of::<crate::signal::SavedUserRegs>()];
            match UserSliceRo::new(data, buf.len()) {
                Ok(s) if s.copy_to_kernel(&mut buf).is_ok() => {
                    // SAFETY: `SavedUserRegs` is `#[repr(C)]` plain `u64`s; any
                    // 144-byte pattern is a valid value.
                    let regs = unsafe {
                        core::ptr::read_unaligned(
                            buf.as_ptr() as *const crate::signal::SavedUserRegs
                        )
                    };
                    ptrace::setregs(caller, tracee, regs) as u64
                }
                _ => NEG_EFAULT,
            }
        }
        _ => NEG_ENOSYS,
    }
}

// ---------------------------------------------------------------------------
// gettimeofday(tv) — syscall 96
// ---------------------------------------------------------------------------

/// LAPIC ticks per second (~1000 Hz timer = 1ms per tick).
pub(crate) const TICKS_PER_SEC: u64 = 1000;

/// Read the current time as (seconds, microseconds) since Unix epoch,
/// using TSC for sub-millisecond precision.
///
/// Falls back to tick-counter coarse time if TSC calibration is not yet done
/// (should only happen during very early boot).
#[inline]
fn tsc_now_us() -> (u64, u64) {
    let boot_epoch = crate::rtc::BOOT_EPOCH_SECS.load(core::sync::atomic::Ordering::Relaxed);
    let tsc_per_ms = crate::arch::x86_64::apic::tsc_per_ms();
    if tsc_per_ms == 0 {
        // TSC not calibrated yet — fall back to tick counter.
        let ticks = crate::arch::x86_64::interrupts::tick_count();
        let sec = boot_epoch + ticks / TICKS_PER_SEC;
        let us = (ticks % TICKS_PER_SEC) * (1_000_000 / TICKS_PER_SEC);
        return (sec, us);
    }
    let boot_tsc = crate::arch::x86_64::apic::boot_tsc();
    let now_tsc = unsafe { core::arch::x86_64::_rdtsc() };
    let elapsed_tsc = now_tsc.wrapping_sub(boot_tsc);
    // elapsed_ms = elapsed_tsc / tsc_per_ms
    let elapsed_ms = elapsed_tsc / tsc_per_ms;
    // sub-ms fraction in microseconds
    let frac_us = (elapsed_tsc % tsc_per_ms) * 1_000 / tsc_per_ms;
    let total_us = elapsed_ms * 1_000 + frac_us;
    let sec = boot_epoch + total_us / 1_000_000;
    let us = total_us % 1_000_000;
    (sec, us)
}

/// Return wall-clock time (CLOCK_REALTIME) as struct timeval.
pub(super) fn sys_gettimeofday(tv_ptr: u64) -> u64 {
    if tv_ptr == 0 {
        return NEG_EFAULT;
    }
    let (tv_sec, tv_usec) = tsc_now_us();
    // struct timeval: tv_sec (i64) + tv_usec (i64) = 16 bytes
    let mut buf = [0u8; 16];
    buf[0..8].copy_from_slice(&(tv_sec as i64).to_ne_bytes());
    buf[8..16].copy_from_slice(&(tv_usec as i64).to_ne_bytes());
    if UserSliceWo::new(tv_ptr, buf.len())
        .and_then(|s| s.copy_from_kernel(&buf))
        .is_err()
    {
        return NEG_EFAULT;
    }
    0
}

// ---------------------------------------------------------------------------
// clock_gettime(clk_id, tp) — syscall 228
// ---------------------------------------------------------------------------

/// Clock IDs (Linux ABI).
const CLOCK_REALTIME: u64 = 0;
const CLOCK_MONOTONIC: u64 = 1;
const CLOCK_MONOTONIC_RAW: u64 = 4;
const CLOCK_REALTIME_COARSE: u64 = 5;
const CLOCK_MONOTONIC_COARSE: u64 = 6;

/// Return time as struct timespec, dispatching on clock ID.
pub(super) fn sys_clock_gettime(clk_id: u64, tp_ptr: u64) -> u64 {
    if tp_ptr == 0 {
        return NEG_EFAULT;
    }
    let (secs, nsecs) = match clk_id {
        CLOCK_REALTIME | CLOCK_REALTIME_COARSE => {
            let (s, us) = tsc_now_us();
            (s, us * 1_000)
        }
        CLOCK_MONOTONIC | CLOCK_MONOTONIC_RAW | CLOCK_MONOTONIC_COARSE => {
            // Monotonic: elapsed since boot (no wall-clock epoch).
            let tsc_per_ms = crate::arch::x86_64::apic::tsc_per_ms();
            if tsc_per_ms == 0 {
                let ticks = crate::arch::x86_64::interrupts::tick_count();
                let s = ticks / TICKS_PER_SEC;
                let ns = (ticks % TICKS_PER_SEC) * (1_000_000_000 / TICKS_PER_SEC);
                (s, ns)
            } else {
                let boot_tsc = crate::arch::x86_64::apic::boot_tsc();
                let now_tsc = unsafe { core::arch::x86_64::_rdtsc() };
                let elapsed_tsc = now_tsc.wrapping_sub(boot_tsc);
                // Use checked_div to satisfy clippy.
                let elapsed_ms = elapsed_tsc.checked_div(tsc_per_ms).unwrap_or(0);
                let frac_ns = elapsed_tsc
                    .checked_rem(tsc_per_ms)
                    .and_then(|r| r.checked_mul(1_000_000))
                    .and_then(|v| v.checked_div(tsc_per_ms))
                    .unwrap_or(0);
                let s = elapsed_ms / 1_000;
                let ns = (elapsed_ms % 1_000) * 1_000_000 + frac_ns;
                (s, ns)
            }
        }
        _ => return NEG_EINVAL,
    };
    // struct timespec: tv_sec (i64) + tv_nsec (i64) = 16 bytes
    let mut buf = [0u8; 16];
    buf[0..8].copy_from_slice(&(secs as i64).to_ne_bytes());
    buf[8..16].copy_from_slice(&(nsecs as i64).to_ne_bytes());
    if UserSliceWo::new(tp_ptr, buf.len())
        .and_then(|s| s.copy_from_kernel(&buf))
        .is_err()
    {
        return NEG_EFAULT;
    }
    0
}

// ---------------------------------------------------------------------------
// futex(uaddr, op, val, ...) — syscall 202
// ---------------------------------------------------------------------------

/// Futex wait/wake implementation for thread synchronization.
/// Supports WAIT, WAKE, WAIT_BITSET, WAKE_BITSET, REQUEUE, CMP_REQUEUE with real
/// blocking queues.
///
/// Supports `FUTEX_WAIT`, `FUTEX_WAKE`, `FUTEX_WAIT_BITSET`, `FUTEX_WAKE_BITSET`,
/// `FUTEX_REQUEUE`, and `FUTEX_CMP_REQUEUE` operations with the
/// `FUTEX_PRIVATE_FLAG`. (REQUEUE/CMP_REQUEUE are what musl's `pthread_cond`
/// uses to hand cond-waiters to the associated mutex — required for libuv's
/// threadpool condvar, Phase 89.)
pub(super) fn sys_futex(uaddr: u64, op: u64, val: u64, val3: u64) -> u64 {
    const FUTEX_WAIT: u64 = 0;
    const FUTEX_WAKE: u64 = 1;
    const FUTEX_REQUEUE: u64 = 3;
    const FUTEX_CMP_REQUEUE: u64 = 4;
    const FUTEX_WAIT_BITSET: u64 = 9;
    const FUTEX_WAKE_BITSET: u64 = 10;
    const FUTEX_PRIVATE_FLAG: u64 = 128;

    use crate::process::futex::{FUTEX_BITSET_MATCH_ANY, FUTEX_TABLE, FutexWaiter};

    let is_private = (op & FUTEX_PRIVATE_FLAG) != 0;
    let cmd = op & !(FUTEX_PRIVATE_FLAG);

    // Build the futex key, scoped to the owning ADDRESS SPACE.
    //
    // 2026-06-16 fix: private futexes were keyed `(0, uaddr)` — a single global
    // root shared by EVERY process. That aliased every process's private futex
    // at the same `uaddr` into one wait queue. Claude Code spawns several
    // identical-layout `node` subprocesses whose musl/libuv pthread threadpool
    // condvars sit at the SAME virtual address; with the fixed-0 key, one node
    // process's `FUTEX_WAKE` woke (or absorbed the single `val=1` wake meant
    // for) ANOTHER process's threadpool waiter — so the intended worker was
    // never woken, the threadpool stalled (`BlockedOnFutex`, "no waker
    // registered"), and the whole `claude -p` run hung before reaching the API.
    // (node-smoke runs ONE node process, so it never collided — which is why it
    // passed while claude hung.)
    //
    // Key both private and shared futexes by the active page-table root (CR3 ==
    // the caller's pml4; no KPTI is active, so at syscall time CR3 is the user
    // mm root). CLONE_THREAD siblings share CR3 (they rendezvous); distinct
    // processes have distinct CR3 (no cross-process aliasing). `is_private` is
    // folded into bit 0 — the pml4 root is page-aligned so bit 0 is always free —
    // so a private and a shared futex at the same address never alias each other.
    let pml4 = x86_64::registers::control::Cr3::read()
        .0
        .start_address()
        .as_u64();
    let futex_root = if is_private { pml4 | 1 } else { pml4 };
    let key = (futex_root, uaddr);

    match cmd {
        FUTEX_WAIT | FUTEX_WAIT_BITSET => {
            let bitset = if cmd == FUTEX_WAIT_BITSET {
                let bs = val3 as u32;
                if bs == 0 {
                    return NEG_EINVAL;
                }
                bs
            } else {
                FUTEX_BITSET_MATCH_ANY
            };

            // Atomically: check *uaddr == val and enqueue waiter under the
            // FUTEX_TABLE lock so no wake can be missed between the check
            // and the block.
            let tid = match crate::task::current_task_id() {
                Some(id) => id,
                None => return NEG_EAGAIN,
            };

            // Single-threaded fast path: if this process has no thread group,
            // blocking would deadlock because no other thread exists to wake
            // us. Clear the futex word to 0 (matching the pre-Phase 40 stub
            // behavior that musl's __lock relies on) and return immediately.
            let is_single_threaded = {
                let pid = crate::process::current_pid();
                let table = crate::process::PROCESS_TABLE.lock();
                table
                    .find(pid)
                    .map(|p| p.thread_group.is_none())
                    .unwrap_or(true)
            };
            if is_single_threaded {
                let mut cur = [0u8; 4];
                if UserSliceRo::new(uaddr, cur.len())
                    .and_then(|s| s.copy_to_kernel(&mut cur))
                    .is_err()
                {
                    return NEG_EFAULT;
                }
                if u32::from_ne_bytes(cur) as u64 != val {
                    return NEG_EAGAIN;
                }
                let _ = UserSliceWo::new(uaddr, 4)
                    .and_then(|s| s.copy_from_kernel(&0u32.to_ne_bytes()));
                return 0;
            }

            // Pre-fault the futex word with NO lock held. For a dynamic binary
            // the word can live in a cold MAP_LAZY_FILE page whose demand-fault
            // blocks on a vfs_server IPC; faulting it under FUTEX_TABLE (an
            // IrqSafeMutex held across the resulting context switch) strands the
            // lock and wedges every core that touches a futex — the Phase 95b
            // lazy-file-mmap regression that hung multithreaded dynamic rust-lld.
            // Touching it here makes the page present so the compare-read under
            // the lock below cannot block.
            {
                let mut probe = [0u8; 4];
                if UserSliceRo::new(uaddr, probe.len())
                    .and_then(|s| s.copy_to_kernel(&mut probe))
                    .is_err()
                {
                    return NEG_EFAULT;
                }
            }

            let woken_flag = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));

            {
                let mut table = FUTEX_TABLE.lock();

                // Read the futex word from userspace.
                let mut cur = [0u8; 4];
                if UserSliceRo::new(uaddr, cur.len())
                    .and_then(|s| s.copy_to_kernel(&mut cur))
                    .is_err()
                {
                    return NEG_EFAULT;
                }
                let current_val = u32::from_ne_bytes(cur) as u64;
                if current_val != val {
                    return NEG_EAGAIN;
                }

                // Value matches — enqueue this thread as a waiter.
                table.entry(key).or_default().push(FutexWaiter {
                    tid,
                    bitset,
                    woken: alloc::sync::Arc::clone(&woken_flag),
                });
            }

            // Atomically check the woken flag and block under the scheduler
            // lock to avoid a missed-wakeup race where a waker sets the flag
            // and calls wake_task() between our check and block.
            //
            // F.3: Under sched-v2 use block_current_until (v2 CAS primitive)
            // instead of block_current_on_futex_unless_woken (v1). The
            // woken_flag is shared with the wake side; the Arc clone above
            // ensures it lives until the waiter is removed from FUTEX_TABLE.
            {
                let _ = crate::task::scheduler::block_current_until(
                    crate::task::TaskState::BlockedOnFutex,
                    &woken_flag,
                    None,
                );
            }

            // Phase 77 Track A — dequeue our waiter on return.
            //
            // A matching FUTEX_WAKE / `do_clear_child_tid` removes our waiter
            // before waking us, but ANY OTHER wake source (a stray
            // `wake_task_v2`, a signal-driven unblock, a sibling clearing a
            // *shared* `clear_child_tid` address — musl gives every joinable
            // thread the same join word in some layouts) returns us here with
            // our entry STILL queued. `FUTEX_WAKE`/`do_clear_child_tid` only
            // wake `val` (typically 1) waiters, so a lingering stale entry ahead
            // of a future real waiter absorbs that single wake and starves the
            // real `pthread_join` — the intermittent multithread-join / SSH
            // teardown freeze. Linux dequeues the futex waiter on every return
            // path; mirror that. Idempotent: removes 0 entries on the common
            // wake-removed-us path.
            {
                let mut table = FUTEX_TABLE.lock();
                // Remove our waiter from WHEREVER it is. FUTEX_CMP_REQUEUE may
                // have moved it from `key` to a different queue (uaddr2) while we
                // were blocked, so retaining only on `key` would leave a stale
                // entry that absorbs a future wake meant for a real waiter. Scan
                // all queues (the table is small) and drop our tid everywhere.
                let mut empty_keys = alloc::vec::Vec::new();
                for (k, waiters) in table.iter_mut() {
                    waiters.retain(|w| w.tid != tid);
                    if waiters.is_empty() {
                        empty_keys.push(*k);
                    }
                }
                for k in empty_keys {
                    table.remove(&k);
                }
            }

            0
        }

        FUTEX_WAKE | FUTEX_WAKE_BITSET => {
            let bitset = if cmd == FUTEX_WAKE_BITSET {
                let bs = val3 as u32;
                if bs == 0 {
                    return NEG_EINVAL;
                }
                bs
            } else {
                FUTEX_BITSET_MATCH_ANY
            };

            let max_wake = val as usize;
            let mut woken_count = 0usize;

            let to_wake = {
                let mut table = FUTEX_TABLE.lock();
                let mut wake_list = alloc::vec::Vec::new();
                if let Some(waiters) = table.get_mut(&key) {
                    let mut i = 0;
                    while i < waiters.len() && woken_count < max_wake {
                        if (waiters[i].bitset & bitset) != 0 {
                            let w = waiters.remove(i);
                            // Set the woken flag *before* calling wake_task so the
                            // waiter can detect the wake even if it has not blocked yet.
                            w.woken.store(true, core::sync::atomic::Ordering::Release);
                            wake_list.push(w.tid);
                            woken_count += 1;
                            // Don't increment i — remove shifted elements down.
                        } else {
                            i += 1;
                        }
                    }
                    // Clean up empty entries.
                    if waiters.is_empty() {
                        table.remove(&key);
                    }
                }
                wake_list
            };

            // Wake the tasks outside the FUTEX_TABLE lock.
            // Only count tasks that were actually transitioned to Ready
            // (skip Dead or already-woken tasks).
            //
            // F.3: under sched-v2 use wake_task_v2 (CAS-based); under v1
            // use wake_task (deferred-enqueue path).
            let mut actual_woken = 0usize;
            for tid in to_wake {
                {
                    use crate::task::scheduler::WakeOutcome;
                    if matches!(
                        crate::task::scheduler::wake_task_v2(tid),
                        WakeOutcome::Woken
                    ) {
                        actual_woken += 1;
                    }
                }
            }

            actual_woken as u64
        }

        FUTEX_REQUEUE | FUTEX_CMP_REQUEUE => {
            // futex(uaddr, op, nr_wake, nr_requeue(r10), uaddr2(r8), val3(r9)).
            // Wake up to `nr_wake` waiters on uaddr, then MOVE up to `nr_requeue`
            // of the remaining waiters onto uaddr2's queue. musl's
            // `pthread_cond_signal`/`broadcast` requeues cond-waiters onto the
            // associated mutex this way; without it (the old silent no-op default)
            // libuv's threadpool condvar deadlocks — a worker parks on a futex no
            // one ever wakes, so Node's `http.get`/getaddrinfo hangs and the
            // main + `clone-thread` workers go `BlockedOnFutex "no waker registered"`.
            let nr_wake = val as usize;
            let nr_requeue = per_core_syscall_arg3() as usize;
            let uaddr2 = per_core_syscall_user_r8();
            let key2 = (futex_root, uaddr2);

            let mut woken_tids = alloc::vec::Vec::new();
            let mut requeued = 0usize;
            // Pre-fault uaddr with NO lock held before the CMP_REQUEUE compare
            // (see FUTEX_WAIT): the under-lock read below would otherwise
            // demand-fault a cold lazy-file page and wedge all cores. musl's
            // pthread_cond_signal/broadcast requeues onto a global mutex word,
            // which is exactly such a page for a dynamic binary.
            if cmd == FUTEX_CMP_REQUEUE {
                let mut probe = [0u8; 4];
                if UserSliceRo::new(uaddr, probe.len())
                    .and_then(|s| s.copy_to_kernel(&mut probe))
                    .is_err()
                {
                    return NEG_EFAULT;
                }
            }
            {
                let mut table = FUTEX_TABLE.lock();
                // CMP_REQUEUE re-checks `*uaddr == val3` under the table lock (so a
                // racing waker/writer can't slip between the check and the move)
                // before touching any queue; mismatch → EAGAIN, like Linux.
                if cmd == FUTEX_CMP_REQUEUE {
                    let mut cur = [0u8; 4];
                    if UserSliceRo::new(uaddr, cur.len())
                        .and_then(|s| s.copy_to_kernel(&mut cur))
                        .is_err()
                    {
                        return NEG_EFAULT;
                    }
                    if u32::from_ne_bytes(cur) as u64 != val3 {
                        return NEG_EAGAIN;
                    }
                }
                if let Some(mut waiters) = table.remove(&key) {
                    while woken_tids.len() < nr_wake && !waiters.is_empty() {
                        let w = waiters.remove(0);
                        w.woken.store(true, core::sync::atomic::Ordering::Release);
                        woken_tids.push(w.tid);
                    }
                    let mut to_requeue = alloc::vec::Vec::new();
                    while to_requeue.len() < nr_requeue && !waiters.is_empty() {
                        to_requeue.push(waiters.remove(0));
                    }
                    requeued = to_requeue.len();
                    if !to_requeue.is_empty() {
                        // Moved waiters keep their `woken` Arc + tid; a later
                        // FUTEX_WAKE on uaddr2 wakes them via the normal path, and
                        // the requeue-robust dequeue in FUTEX_WAIT removes them
                        // from whichever key they end up on.
                        table.entry(key2).or_default().extend(to_requeue);
                    }
                    if !waiters.is_empty() {
                        // `extend` into the entry, NOT `insert`: a self-requeue
                        // (uaddr == uaddr2 ⇒ key2 == key) has just placed the
                        // requeued waiters into `table[key]` above, so `insert`
                        // would clobber and permanently strand them (they would
                        // sit `BlockedOnFutex` with no waker). Appending the
                        // leftover after the requeued ones preserves FIFO; for the
                        // common key2 != key case `key` was `remove`d above so the
                        // entry starts empty and this is identical to `insert`.
                        table.entry(key).or_default().extend(waiters);
                    }
                }
            }
            let mut actual_woken = 0usize;
            for tid in woken_tids {
                use crate::task::scheduler::WakeOutcome;
                if matches!(
                    crate::task::scheduler::wake_task_v2(tid),
                    WakeOutcome::Woken
                ) {
                    actual_woken += 1;
                }
            }
            // Linux returns the total number woken + requeued.
            (actual_woken + requeued) as u64
        }

        _ => {
            // Futex ops we don't implement (FUTEX_WAKE_OP, FUTEX_LOCK_PI, …).
            // Returns 0 (most Linux callers tolerate a no-op), but surface it,
            // rate-limited, so a runtime deadlocking on a missing op is visible
            // instead of silently hanging.
            use core::sync::atomic::{AtomicU32, Ordering};
            static UNIMPL_N: AtomicU32 = AtomicU32::new(0);
            let n = UNIMPL_N.fetch_add(1, Ordering::Relaxed);
            if n < 8 || n.is_multiple_of(4096) {
                log::warn!(
                    "[futex] unimplemented op cmd={cmd} pid={}",
                    crate::process::current_pid()
                );
            }
            0
        }
    }
}

// ---------------------------------------------------------------------------
// Phase 23: Socket syscalls
// ---------------------------------------------------------------------------

/// Helper: read a SockaddrIn from userspace and return (ip, port).
fn sockaddr_from_user(addr_ptr: u64) -> Result<([u8; 4], u16), u64> {
    let mut buf = [0u8; 16]; // sizeof(sockaddr_in)
    if UserSliceRo::new(addr_ptr, buf.len())
        .and_then(|s| s.copy_to_kernel(&mut buf))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    let family = u16::from_ne_bytes([buf[0], buf[1]]);
    if family != 2 {
        // AF_INET
        return Err(NEG_EINVAL);
    }
    let port = u16::from_be_bytes([buf[2], buf[3]]);
    let ip = [buf[4], buf[5], buf[6], buf[7]];
    Ok((ip, port))
}

/// Helper: write a SockaddrIn to userspace.
fn sockaddr_to_user(addr_ptr: u64, ip: [u8; 4], port: u16) -> Result<(), u64> {
    if addr_ptr == 0 {
        return Ok(());
    }
    let mut buf = [0u8; 16];
    buf[0..2].copy_from_slice(&2u16.to_ne_bytes()); // AF_INET
    buf[2..4].copy_from_slice(&port.to_be_bytes());
    buf[4..8].copy_from_slice(&ip);
    if UserSliceWo::new(addr_ptr, buf.len())
        .and_then(|s| s.copy_from_kernel(&buf))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    Ok(())
}

/// Phase 91 — read a `sockaddr_in6` (28 bytes) from userspace → (addr, port).
/// Family must be AF_INET6 (10). Port is network-order; `sin6_addr` is the
/// 16 address octets at offset 8.
fn sockaddr_from_user6(addr_ptr: u64) -> Result<([u8; 16], u16), u64> {
    let mut buf = [0u8; 28]; // sizeof(sockaddr_in6)
    if UserSliceRo::new(addr_ptr, buf.len())
        .and_then(|s| s.copy_to_kernel(&mut buf))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    let family = u16::from_ne_bytes([buf[0], buf[1]]);
    if family != 10 {
        // AF_INET6
        return Err(NEG_EINVAL);
    }
    let port = u16::from_be_bytes([buf[2], buf[3]]);
    let mut addr = [0u8; 16];
    addr.copy_from_slice(&buf[8..24]);
    Ok((addr, port))
}

/// Phase 91 — write a `sockaddr_in6` to userspace, clamped to the caller's
/// declared buffer length (`cap`). Linux value-result semantics: write
/// `min(cap, 28)` bytes into the user buffer while the addrlen out-parameter
/// (written by the caller) still reports the full 28. `cap` must be the
/// caller's validated `addrlen` — passing a too-small `cap` truncates the
/// address rather than overrunning the buffer past its declared size.
fn sockaddr_to_user6(addr_ptr: u64, addr: [u8; 16], port: u16, cap: usize) -> Result<(), u64> {
    if addr_ptr == 0 {
        return Ok(());
    }
    let mut buf = [0u8; 28];
    buf[0..2].copy_from_slice(&10u16.to_ne_bytes()); // AF_INET6
    buf[2..4].copy_from_slice(&port.to_be_bytes()); // sin6_port (network order)
    // sin6_flowinfo (4) @ offset 4 stays zero.
    buf[8..24].copy_from_slice(&addr); // sin6_addr
    // sin6_scope_id (4) @ offset 24 stays zero.
    let n = cap.min(buf.len());
    if UserSliceWo::new(addr_ptr, n)
        .and_then(|s| s.copy_from_kernel(&buf[..n]))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    Ok(())
}

/// Helper: look up socket handle from fd. Returns (handle, socket_kind, protocol).
fn socket_handle_from_fd(
    fd: u64,
) -> Result<
    (
        crate::net::SocketHandle,
        crate::net::SocketKind,
        crate::net::SocketProtocol,
    ),
    u64,
> {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return Err(NEG_EBADF);
    }
    let entry = current_fd_entry(fd_idx).ok_or(NEG_EBADF)?;
    match &entry.backend {
        FdBackend::Socket { handle } => {
            let h = *handle;
            let info = crate::net::with_socket(h, |s| (s.kind, s.protocol));
            match info {
                Some((kind, proto)) => Ok((h, kind, proto)),
                None => Err(NEG_EBADF),
            }
        }
        _ => Err(NEG_ENOTSOCK),
    }
}

/// Stamp the calling process's `(pid, uid, gid)` onto the local-creds
/// fields of a freshly-allocated Unix socket so `getsockopt(SO_PEERCRED)`
/// on the eventual peer can return them.  Called from `sys_socket`,
/// `sys_socketpair`, `sys_accept` (server-side accepted socket), and
/// `sys_bind_unix` (in case a listener was bound by a different
/// process than the original creator — uncommon but defensive).
fn stamp_unix_socket_local_creds(handle: usize) {
    let pid = crate::process::current_pid();
    let (uid, gid) = {
        let table = crate::process::PROCESS_TABLE.lock();
        match table.find(pid) {
            Some(p) => (p.euid, p.egid),
            None => (0, 0),
        }
    };
    crate::net::unix::with_unix_socket_mut(handle, |s| {
        s.local_pid = pid;
        s.local_uid = uid;
        s.local_gid = gid;
    });
}

/// Copy the peer socket's `local_*` credentials into this socket's
/// `peer_*` slots.  Called from accept / connect / socketpair after
/// the two sockets are peered, so subsequent
/// `getsockopt(SO_PEERCRED)` calls return the other end's creator
/// triple.
fn link_unix_socket_peer_creds(handle: usize, peer_handle: usize) {
    let peer_creds = crate::net::unix::with_unix_socket(peer_handle, |s| {
        (s.local_pid, s.local_uid, s.local_gid)
    })
    .unwrap_or((0, u32::MAX, u32::MAX));
    crate::net::unix::with_unix_socket_mut(handle, |s| {
        s.peer_pid = peer_creds.0;
        s.peer_uid = peer_creds.1;
        s.peer_gid = peer_creds.2;
    });
}

const NEG_ENOTSOCK: u64 = (-88_i64) as u64;
const NEG_ENFILE: u64 = (-23_i64) as u64;
const NEG_EADDRINUSE: u64 = (-98_i64) as u64;
const NEG_ENOTCONN: u64 = (-107_i64) as u64;
const NEG_ECONNREFUSED: u64 = (-111_i64) as u64;
const NEG_ETIMEDOUT: u64 = (-110_i64) as u64;
const NEG_EOPNOTSUPP: u64 = (-95_i64) as u64;
const NEG_ENOPROTOOPT: u64 = (-92_i64) as u64;
const NEG_EAFNOSUPPORT: u64 = (-97_i64) as u64;
const NEG_EISCONN: u64 = (-106_i64) as u64;
const NEG_EALREADY: u64 = (-114_i64) as u64;
const NEG_EINPROGRESS: u64 = (-115_i64) as u64;

// ===========================================================================
// Phase 39: Unix domain socket syscall helpers
// ===========================================================================

/// Create an AF_UNIX socket.
fn sys_socket_unix(socktype: u64) -> u64 {
    const SOCK_NONBLOCK: u64 = 0x800;
    const SOCK_CLOEXEC: u64 = 0x80000;
    let flags = socktype & (SOCK_CLOEXEC | SOCK_NONBLOCK);
    let raw_type = socktype & !(SOCK_CLOEXEC | SOCK_NONBLOCK);
    let unix_type = match raw_type {
        1 | 5 => crate::net::unix::UnixSocketType::Stream, // SOCK_STREAM or SOCK_SEQPACKET
        2 => crate::net::unix::UnixSocketType::Datagram,
        _ => return NEG_EINVAL,
    };
    let handle = match crate::net::unix::alloc_unix_socket(unix_type) {
        Some(h) => h,
        None => return NEG_ENFILE,
    };
    // Phase 69d follow-up: stamp the creator's credentials so the peer
    // can read them via getsockopt(SO_PEERCRED) once connected.
    stamp_unix_socket_local_creds(handle);
    let entry = FdEntry {
        backend: FdBackend::UnixSocket { handle },
        offset: 0,
        readable: true,
        writable: true,
        cloexec: flags & SOCK_CLOEXEC != 0,
        nonblock: flags & SOCK_NONBLOCK != 0,
    };
    match alloc_fd(0, entry) {
        Some(fd) => fd as u64,
        None => {
            crate::net::unix::free_unix_socket(handle);
            NEG_EMFILE
        }
    }
}

/// socketpair(domain, type, protocol, sv) — syscall 53
pub(super) fn sys_socketpair(domain: u64, socktype: u64, _protocol: u64, sv_ptr: u64) -> u64 {
    const AF_UNIX: u64 = 1;
    const SOCK_NONBLOCK: u64 = 0x800;
    const SOCK_CLOEXEC: u64 = 0x80000;

    if domain != AF_UNIX {
        // Fall back to pipe-based socketpair for non-AF_UNIX.
        let cloexec = socktype & SOCK_CLOEXEC != 0;
        return sys_pipe_with_flags(sv_ptr, cloexec);
    }

    let flags = socktype & (SOCK_CLOEXEC | SOCK_NONBLOCK);
    let raw_type = socktype & !(SOCK_CLOEXEC | SOCK_NONBLOCK);
    let unix_type = match raw_type {
        1 | 5 => crate::net::unix::UnixSocketType::Stream, // SOCK_STREAM or SOCK_SEQPACKET
        2 => crate::net::unix::UnixSocketType::Datagram,
        _ => return NEG_EINVAL,
    };

    let h1 = match crate::net::unix::alloc_unix_socket(unix_type) {
        Some(h) => h,
        None => return NEG_ENFILE,
    };
    let h2 = match crate::net::unix::alloc_unix_socket(unix_type) {
        Some(h) => h,
        None => {
            crate::net::unix::free_unix_socket(h1);
            return NEG_ENFILE;
        }
    };

    // Peer them together and mark as connected.
    crate::net::unix::with_unix_socket_mut(h1, |s| {
        s.peer = Some(h2);
        s.state = crate::net::unix::UnixSocketState::Connected;
    });
    crate::net::unix::with_unix_socket_mut(h2, |s| {
        s.peer = Some(h1);
        s.state = crate::net::unix::UnixSocketState::Connected;
    });
    // Phase 69d follow-up: both ends of socketpair are created by the
    // same process, so both local and peer creds come from the caller.
    stamp_unix_socket_local_creds(h1);
    stamp_unix_socket_local_creds(h2);
    link_unix_socket_peer_creds(h1, h2);
    link_unix_socket_peer_creds(h2, h1);

    let cloexec = flags & SOCK_CLOEXEC != 0;
    let nonblock = flags & SOCK_NONBLOCK != 0;

    let fd1 = match alloc_fd(
        0,
        FdEntry {
            backend: FdBackend::UnixSocket { handle: h1 },
            offset: 0,
            readable: true,
            writable: true,
            cloexec,
            nonblock,
        },
    ) {
        Some(fd) => fd,
        None => {
            crate::net::unix::free_unix_socket(h1);
            crate::net::unix::free_unix_socket(h2);
            return NEG_EMFILE;
        }
    };
    let fd2 = match alloc_fd(
        0,
        FdEntry {
            backend: FdBackend::UnixSocket { handle: h2 },
            offset: 0,
            readable: true,
            writable: true,
            cloexec,
            nonblock,
        },
    ) {
        Some(fd) => fd,
        None => {
            // Close fd1
            with_current_fd_mut(fd1, |slot| *slot = None);
            crate::net::unix::free_unix_socket(h1);
            crate::net::unix::free_unix_socket(h2);
            return NEG_EMFILE;
        }
    };

    // Write [fd1, fd2] to userspace sv[2] array.
    let mut sv_bytes = [0u8; 8];
    sv_bytes[..4].copy_from_slice(&(fd1 as i32).to_ne_bytes());
    sv_bytes[4..].copy_from_slice(&(fd2 as i32).to_ne_bytes());
    if UserSliceWo::new(sv_ptr, sv_bytes.len())
        .and_then(|s| s.copy_from_kernel(&sv_bytes))
        .is_err()
    {
        // Clean up on fault.
        with_current_fd_mut(fd1, |slot| *slot = None);
        with_current_fd_mut(fd2, |slot| *slot = None);
        crate::net::unix::free_unix_socket(h1);
        crate::net::unix::free_unix_socket(h2);
        return NEG_EFAULT;
    }
    0
}

/// Parse a sockaddr_un from userspace. Returns the path string.
fn sockaddr_un_from_user(addr_ptr: u64, addr_len: u64) -> Result<alloc::string::String, u64> {
    if addr_len < 3 {
        return Err(NEG_EINVAL); // Must have at least family + 1 byte of path
    }
    let len = (addr_len as usize).min(110); // sun_family(2) + path(up to 108)
    let mut buf = [0u8; 110];
    if UserSliceRo::new(addr_ptr, buf[..len].len())
        .and_then(|s| s.copy_to_kernel(&mut buf[..len]))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    // Validate sun_family == AF_UNIX (1)
    let family = u16::from_ne_bytes([buf[0], buf[1]]);
    if family != 1 {
        return Err(NEG_EAFNOSUPPORT);
    }
    // Extract NUL-terminated path from bytes [2..len].
    let path_bytes = &buf[2..len];
    let path_len = path_bytes
        .iter()
        .position(|&b| b == 0)
        .unwrap_or(path_bytes.len());
    if path_len == 0 {
        return Err(NEG_EINVAL);
    }
    if path_len > 107 {
        return Err(NEG_EINVAL);
    }
    match core::str::from_utf8(&path_bytes[..path_len]) {
        Ok(s) => Ok(alloc::string::String::from(s)),
        Err(_) => Err(NEG_EINVAL),
    }
}

/// Helper: get Unix socket handle from FD, or ENOTSOCK.
fn unix_socket_handle_from_fd(fd: u64) -> Result<(usize, FdEntry), u64> {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return Err(NEG_EBADF);
    }
    let entry = current_fd_entry(fd_idx).ok_or(NEG_EBADF)?;
    match &entry.backend {
        FdBackend::UnixSocket { handle } => Ok((*handle, entry)),
        _ => Err(NEG_ENOTSOCK),
    }
}

/// bind() for Unix sockets.
fn sys_bind_unix(fd: u64, addr_ptr: u64, addr_len: u64) -> u64 {
    let (handle, _entry) = match unix_socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    let path = match sockaddr_un_from_user(addr_ptr, addr_len) {
        Ok(p) => p,
        Err(e) => return e,
    };

    // Check socket is unbound.
    let state = crate::net::unix::with_unix_socket(handle, |s| s.state);
    if state != Some(crate::net::unix::UnixSocketState::Unbound) {
        return NEG_EINVAL;
    }

    // Register the path in the path map.
    if crate::net::unix::bind_path(&path, handle).is_err() {
        return NEG_EADDRINUSE;
    }

    // Create a socket node in tmpfs if the path is under /tmp or /run.
    // The tmpfs API takes paths with the **leading "tmp/" prefix** —
    // mirroring the convention used by stat / read / write throughout
    // the syscall layer (`tmpfs_relative_path` returns "tmp/foo" not
    // "foo").  An earlier version of this code used a bare
    // `strip_prefix("/tmp/")`, which silently desynchronised the path
    // namespace between bind and the rest of the FS — `mkdir
    // /tmp/tmux-0` registered as "tmp/tmux-0" while bind looked up
    // "tmux-0", landing on `parent_and_name` -> NotFound and the
    // -EIO fall-through.  Use the same helper everyone else uses.
    if let Some(rel) = tmpfs_relative_path(&path) {
        let pid = crate::process::current_pid();
        let (uid, gid, umask) = {
            let table = crate::process::PROCESS_TABLE.lock();
            match table.find(pid) {
                Some(p) => (p.uid, p.gid, p.umask),
                None => (0, 0, 0o022),
            }
        };
        let mode = 0o777 & !umask;
        let mut tmpfs = crate::fs::tmpfs::TMPFS.lock();
        match tmpfs.create_file_with_meta(rel, uid, gid, mode) {
            Ok(_) => {}
            Err(crate::fs::tmpfs::TmpfsError::AlreadyExists) => {
                drop(tmpfs);
                crate::net::unix::unbind_path(&path);
                return NEG_EADDRINUSE;
            }
            Err(_) => {
                drop(tmpfs);
                crate::net::unix::unbind_path(&path);
                return NEG_EIO;
            }
        }
    }

    // Update socket state.
    crate::net::unix::with_unix_socket_mut(handle, |s| {
        s.path = Some(path);
        s.state = crate::net::unix::UnixSocketState::Bound;
    });
    0
}

/// connect() for Unix stream sockets.
fn sys_connect_unix(fd: u64, addr_ptr: u64, addr_len: u64) -> u64 {
    let (handle, entry) = match unix_socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    let path = match sockaddr_un_from_user(addr_ptr, addr_len) {
        Ok(p) => p,
        Err(e) => return e,
    };

    let sock_type = match crate::net::unix::with_unix_socket(handle, |s| s.socket_type) {
        Some(t) => t,
        None => return NEG_EBADF,
    };

    // Look up the target socket.
    let target_handle = match crate::net::unix::lookup_path(&path) {
        Some(h) => h,
        None => return NEG_ECONNREFUSED,
    };

    match sock_type {
        crate::net::unix::UnixSocketType::Stream => {
            // Guard: reject if already connected or already pending connect.
            let cur_state = crate::net::unix::with_unix_socket(handle, |s| s.state);
            match cur_state {
                Some(crate::net::unix::UnixSocketState::Connected) => return NEG_EISCONN,
                Some(crate::net::unix::UnixSocketState::Connecting) => return NEG_EALREADY,
                _ => {}
            }

            // Verify target is listening.
            let is_listening = crate::net::unix::with_unix_socket(target_handle, |s| {
                matches!(s.state, crate::net::unix::UnixSocketState::Listening)
            });
            if is_listening != Some(true) {
                return NEG_ECONNREFUSED;
            }

            // Check backlog space.
            let backlog_full = crate::net::unix::with_unix_socket(target_handle, |s| {
                s.backlog.len() >= s.backlog_limit
            });
            if backlog_full == Some(true) {
                return NEG_ECONNREFUSED;
            }

            // Increment refcount before enqueuing to prevent use-after-free
            // if the client FD is closed before accept() processes the entry.
            crate::net::unix::add_unix_socket_ref(handle);

            // Mark as Connecting to prevent duplicate backlog entries.
            crate::net::unix::with_unix_socket_mut(handle, |s| {
                s.state = crate::net::unix::UnixSocketState::Connecting;
            });

            // Add ourselves to the listener's backlog.
            crate::net::unix::with_unix_socket_mut(target_handle, |s| {
                s.backlog.push_back(handle);
            });
            // Wake the listener.
            crate::net::unix::wake_unix_socket(target_handle);

            // Block until accepted (state transitions to Connected) or return EAGAIN.
            let nonblock = entry.nonblock;
            loop {
                let state = crate::net::unix::with_unix_socket(handle, |s| s.state);
                if state == Some(crate::net::unix::UnixSocketState::Connected) {
                    return 0;
                }
                if nonblock || has_pending_signal() {
                    // Roll back: remove from backlog, reset state, release refcount.
                    crate::net::unix::with_unix_socket_mut(target_handle, |s| {
                        s.backlog.retain(|&h| h != handle);
                    });
                    crate::net::unix::with_unix_socket_mut(handle, |s| {
                        s.state = crate::net::unix::UnixSocketState::Unbound;
                    });
                    crate::net::unix::free_unix_socket(handle);
                    return if nonblock { NEG_EAGAIN } else { NEG_EINTR };
                }
                crate::net::unix::UNIX_SOCKET_WAITQUEUES[handle].sleep();
            }
        }
        crate::net::unix::UnixSocketType::Datagram => {
            // For datagram sockets, just set default destination.
            crate::net::unix::with_unix_socket_mut(handle, |s| {
                s.peer = Some(target_handle);
            });
            0
        }
    }
}

/// listen() for Unix stream sockets.
fn sys_listen_unix(handle: usize, backlog: u64) -> u64 {
    let info = crate::net::unix::with_unix_socket(handle, |s| (s.state, s.socket_type));
    match info {
        Some((
            crate::net::unix::UnixSocketState::Bound,
            crate::net::unix::UnixSocketType::Stream,
        )) => {}
        _ => return NEG_EINVAL,
    }
    let limit = (backlog as usize).clamp(1, 16);
    crate::net::unix::with_unix_socket_mut(handle, |s| {
        s.state = crate::net::unix::UnixSocketState::Listening;
        s.backlog_limit = limit;
    });
    0
}

/// accept() for Unix stream sockets.
fn sys_accept_unix(fd: u64, addr_ptr: u64, addr_len_ptr: u64, flags: u64) -> u64 {
    let (handle, entry) = match unix_socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };

    // Validate this is a listening stream socket.
    let info = crate::net::unix::with_unix_socket(handle, |s| (s.socket_type, s.state));
    match info {
        Some((
            crate::net::unix::UnixSocketType::Stream,
            crate::net::unix::UnixSocketState::Listening,
        )) => {}
        _ => return NEG_EINVAL,
    }

    let nonblock = entry.nonblock;

    const SOCK_NONBLOCK: u64 = 0x800;
    const SOCK_CLOEXEC: u64 = 0x80000;

    loop {
        // Try to dequeue a pending connection.
        let client_handle =
            crate::net::unix::with_unix_socket_mut(handle, |s| s.backlog.pop_front());
        if let Some(Some(ch)) = client_handle {
            // Allocate a new server-side socket.
            let server_handle =
                match crate::net::unix::alloc_unix_socket(crate::net::unix::UnixSocketType::Stream)
                {
                    Some(h) => h,
                    None => {
                        // Release backlog refcount on failure.
                        crate::net::unix::free_unix_socket(ch);
                        return NEG_ENFILE;
                    }
                };

            // Peer the server socket with the client.
            crate::net::unix::with_unix_socket_mut(server_handle, |s| {
                s.peer = Some(ch);
                s.state = crate::net::unix::UnixSocketState::Connected;
            });
            crate::net::unix::with_unix_socket_mut(ch, |s| {
                s.peer = Some(server_handle);
                s.state = crate::net::unix::UnixSocketState::Connected;
            });
            // Phase 69d follow-up: stamp the server-side accepted
            // socket with the accepting process's creds, then link
            // peer creds in both directions.  `ch` was stamped by
            // the connecting process during `sys_connect_unix`; its
            // local_* fields carry the client's uid.
            stamp_unix_socket_local_creds(server_handle);
            link_unix_socket_peer_creds(server_handle, ch);
            link_unix_socket_peer_creds(ch, server_handle);
            // Wake the client (blocked in connect).
            crate::net::unix::wake_unix_socket(ch);

            // Release the backlog refcount now that peering is complete.
            crate::net::unix::free_unix_socket(ch);

            // Create FD for the accepted socket.
            let new_entry = FdEntry {
                backend: FdBackend::UnixSocket {
                    handle: server_handle,
                },
                offset: 0,
                readable: true,
                writable: true,
                cloexec: flags & SOCK_CLOEXEC != 0,
                nonblock: flags & SOCK_NONBLOCK != 0,
            };
            let new_fd = match alloc_fd(0, new_entry) {
                Some(fd) => fd,
                None => {
                    crate::net::unix::free_unix_socket(server_handle);
                    return NEG_EMFILE;
                }
            };

            // Write peer address if requested.
            if addr_ptr != 0 && addr_len_ptr != 0 {
                let peer_path =
                    crate::net::unix::with_unix_socket(ch, |s| s.path.clone()).flatten();
                let _ = sockaddr_un_to_user(addr_ptr, addr_len_ptr, peer_path.as_deref());
            }

            return new_fd as u64;
        }

        if nonblock {
            return NEG_EAGAIN;
        }
        if has_pending_signal() {
            return NEG_EINTR;
        }
        crate::net::unix::UNIX_SOCKET_WAITQUEUES[handle].sleep();
    }
}

/// Helper: write a sockaddr_un to userspace.
fn sockaddr_un_to_user(addr_ptr: u64, addr_len_ptr: u64, path: Option<&str>) -> Result<(), u64> {
    // Read the caller-provided buffer size.
    let mut caller_len_bytes = [0u8; 4];
    if UserSliceRo::new(addr_len_ptr, caller_len_bytes.len())
        .and_then(|s| s.copy_to_kernel(&mut caller_len_bytes))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    let caller_len = u32::from_ne_bytes(caller_len_bytes) as usize;

    let mut buf = [0u8; 110];
    buf[0] = 1; // AF_UNIX
    buf[1] = 0;
    let total_len = if let Some(p) = path {
        let bytes = p.as_bytes();
        let copy_len = bytes.len().min(107);
        buf[2..2 + copy_len].copy_from_slice(&bytes[..copy_len]);
        2 + copy_len + 1 // family + path + NUL
    } else {
        2 // just the family
    };
    // Only write up to the caller's buffer size.
    let write_len = total_len.min(caller_len);
    if write_len > 0
        && UserSliceWo::new(addr_ptr, buf[..write_len].len())
            .and_then(|s| s.copy_from_kernel(&buf[..write_len]))
            .is_err()
    {
        return Err(NEG_EFAULT);
    }
    // Write back the actual address length.
    let len_val = (total_len as u32).to_ne_bytes();
    if UserSliceWo::new(addr_len_ptr, len_val.len())
        .and_then(|s| s.copy_from_kernel(&len_val))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    Ok(())
}

/// shutdown() for Unix sockets.
fn sys_shutdown_unix(handle: usize, how: u64) -> u64 {
    let peer = crate::net::unix::with_unix_socket_mut(handle, |s| {
        match how {
            0 => s.shut_rd = true, // SHUT_RD
            1 => s.shut_wr = true, // SHUT_WR
            2 => {
                s.shut_rd = true;
                s.shut_wr = true;
            } // SHUT_RDWR
            _ => return None,
        }
        s.peer
    });
    match peer {
        Some(Some(p)) => {
            crate::net::unix::wake_unix_socket(p);
            crate::net::unix::wake_unix_socket(handle);
            0
        }
        Some(None) => {
            crate::net::unix::wake_unix_socket(handle);
            0
        }
        None => NEG_EINVAL,
    }
}

/// sendto() for Unix datagram sockets.
fn sys_sendto_unix(
    handle: usize,
    buf_ptr: u64,
    len: u64,
    nonblock: bool,
    addr_ptr: u64,
    addr_len: u64,
) -> u64 {
    let capped = (len as usize).min(4096);
    let mut data = alloc::vec![0u8; capped];
    if UserSliceRo::new(buf_ptr, data.len())
        .and_then(|s| s.copy_to_kernel(&mut data))
        .is_err()
    {
        return NEG_EFAULT;
    }

    let sender_path = crate::net::unix::with_unix_socket(handle, |s| s.path.clone()).flatten();

    // Determine target: explicit addr or connected peer.
    let target = if addr_ptr != 0 && addr_len >= 3 {
        let path = match sockaddr_un_from_user(addr_ptr, addr_len) {
            Ok(p) => p,
            Err(e) => return e,
        };
        match crate::net::unix::lookup_path(&path) {
            Some(h) => h,
            None => return NEG_ECONNREFUSED,
        }
    } else {
        match crate::net::unix::with_unix_socket(handle, |s| s.peer).flatten() {
            Some(p) => p,
            None => return NEG_ENOTCONN,
        }
    };

    loop {
        match crate::net::unix::unix_dgram_send(sender_path.clone(), target, &data) {
            Ok(n) => {
                crate::net::unix::wake_unix_socket(target);
                return n as u64;
            }
            Err(-11) => {
                // EAGAIN — queue full, block or return.
                if nonblock {
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    return NEG_EINTR;
                }
                crate::net::unix::UNIX_SOCKET_WAITQUEUES[target].sleep();
            }
            Err(e) => return e as u64, // ECONNREFUSED, etc.
        }
    }
}

/// recvfrom() for Unix datagram sockets.
fn sys_recvfrom_unix(
    handle: usize,
    buf_ptr: u64,
    count: u64,
    nonblock: bool,
    addr_ptr: u64,
    addr_len_ptr: u64,
) -> u64 {
    let capped = (count as usize).min(4096);
    let mut tmp = alloc::vec![0u8; capped];
    loop {
        match crate::net::unix::unix_dgram_recv(handle, &mut tmp) {
            Ok((n, sender_path)) => {
                if UserSliceWo::new(buf_ptr, tmp[..n].len())
                    .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                    .is_err()
                {
                    return NEG_EFAULT;
                }
                if addr_ptr != 0 && addr_len_ptr != 0 {
                    let _ = sockaddr_un_to_user(addr_ptr, addr_len_ptr, sender_path.as_deref());
                }
                return n as u64;
            }
            Err(_) => {
                if nonblock {
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    return NEG_EINTR;
                }
                crate::net::unix::UNIX_SOCKET_WAITQUEUES[handle].sleep();
            }
        }
    }
}

/// socket(domain, type, protocol) — syscall 41
pub(super) fn sys_socket(domain: u64, socktype: u64, protocol: u64) -> u64 {
    use crate::net::{SocketKind, SocketProtocol};
    const AF_UNIX: u64 = 1;
    const AF_INET: u64 = 2;
    // Phase 91 — AF_INET6 slots in as a third family branch beside AF_UNIX/INET.
    const AF_INET6: u64 = 10;

    if domain == AF_UNIX {
        return sys_socket_unix(socktype);
    }
    if domain != AF_INET && domain != AF_INET6 {
        return NEG_EAFNOSUPPORT;
    }
    let is_v6 = domain == AF_INET6;
    const SOCK_NONBLOCK: u64 = 0x800;
    const SOCK_CLOEXEC: u64 = 0x80000;
    let sock_flags = socktype & (SOCK_CLOEXEC | SOCK_NONBLOCK);
    let socktype_raw = socktype & !(SOCK_CLOEXEC | SOCK_NONBLOCK);
    let (kind, proto) = match socktype_raw {
        1 => (SocketKind::Stream, SocketProtocol::Tcp), // SOCK_STREAM
        2 => {
            // SOCK_DGRAM — protocol determines UDP vs ICMP. IPPROTO_ICMP (1, v4)
            // and IPPROTO_ICMPV6 (58, v6) both map to the Icmp protocol; the
            // socket's `family` field distinguishes the wire format.
            if protocol == 1 || protocol == 58 {
                (SocketKind::Dgram, SocketProtocol::Icmp)
            } else {
                (SocketKind::Dgram, SocketProtocol::Udp) // default to UDP
            }
        }
        _ => return NEG_EINVAL,
    };
    let handle = match crate::net::alloc_socket(kind, proto) {
        Some(h) => h,
        None => return NEG_ENFILE,
    };
    if is_v6 {
        crate::net::with_socket_mut(handle, |s| s.family = 10);
    }
    // Phase 54 Track C: notify net_udp service about new UDP socket.
    if proto == SocketProtocol::Udp && net_udp_service_available() {
        let err = net_udp_service_create(handle);
        if err != 0 {
            crate::net::release_socket_pub(handle);
            return err;
        }
    }
    let entry = FdEntry {
        backend: FdBackend::Socket { handle },
        offset: 0,
        readable: true,
        writable: true,
        cloexec: sock_flags & SOCK_CLOEXEC != 0,
        nonblock: sock_flags & SOCK_NONBLOCK != 0,
    };
    match alloc_fd(0, entry) {
        Some(fd) => fd as u64,
        None => {
            crate::net::release_socket_pub(handle);
            NEG_EMFILE
        }
    }
}

/// bind(fd, addr, addrlen) — syscall 49
pub(super) fn sys_bind(fd: u64, addr_ptr: u64, addr_len: u64) -> u64 {
    // Check for Unix socket first.
    if let Ok((_, _)) = unix_socket_handle_from_fd(fd) {
        return sys_bind_unix(fd, addr_ptr, addr_len);
    }
    let (handle, kind, proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    let family = crate::net::with_socket(handle, |s| s.family).unwrap_or(2);
    if family == 10 {
        // Phase 91 — AF_INET6 bind: 28-byte sockaddr_in6, v6 UDP port table.
        if addr_len < 28 {
            return NEG_EINVAL;
        }
        let (addr6, port) = match sockaddr_from_user6(addr_ptr) {
            Ok(v) => v,
            Err(e) => return e,
        };
        if matches!(proto, crate::net::SocketProtocol::Udp) && !crate::net::udp::bind_v6(port) {
            return NEG_EADDRINUSE;
        }
        crate::net::with_socket_mut(handle, |s| {
            s.local_addr6 = addr6;
            s.local_port = port;
            if matches!(proto, crate::net::SocketProtocol::Udp) {
                s.udp_bound = true;
            }
            s.state = crate::net::SocketState::Bound;
        });
        let _ = kind;
        return 0;
    }
    if addr_len < 16 {
        return NEG_EINVAL;
    }
    let (ip, port) = match sockaddr_from_user(addr_ptr) {
        Ok(v) => v,
        Err(e) => return e,
    };
    let local_ip = if ip == [0, 0, 0, 0] {
        crate::net::config::our_ip()
    } else {
        ip
    };

    match proto {
        crate::net::SocketProtocol::Udp => {
            // Phase 54 Track C: delegate binding policy to net_udp service.
            if net_udp_service_available() {
                let err = net_udp_service_bind(handle, port, local_ip);
                if err != 0 {
                    return err;
                }
                // Service approved — register in kernel mechanism layer too
                // so ingress datagrams are queued for this port.  Ignore the
                // return value: the service is the policy authority.
                let _ = crate::net::udp::bind(port);
            } else {
                // Fallback: no service, kernel owns policy directly.
                if !crate::net::udp::bind(port) {
                    return NEG_EADDRINUSE;
                }
            }
            crate::net::with_socket_mut(handle, |s| {
                s.local_addr = local_ip;
                s.local_port = port;
                s.udp_bound = true;
                s.state = crate::net::SocketState::Bound;
            });
        }
        crate::net::SocketProtocol::Tcp => {
            crate::net::with_socket_mut(handle, |s| {
                s.local_addr = local_ip;
                s.local_port = port;
                s.state = crate::net::SocketState::Bound;
            });
        }
        crate::net::SocketProtocol::Icmp => {
            crate::net::with_socket_mut(handle, |s| {
                s.local_addr = local_ip;
                s.state = crate::net::SocketState::Bound;
            });
        }
    }
    let _ = kind;
    0
}

/// connect(fd, addr, addrlen) — syscall 42
pub(super) fn sys_connect(fd: u64, addr_ptr: u64, addr_len: u64) -> u64 {
    if let Ok((_, _)) = unix_socket_handle_from_fd(fd) {
        return sys_connect_unix(fd, addr_ptr, addr_len);
    }
    let (handle, _kind, proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    let family = crate::net::with_socket(handle, |s| s.family).unwrap_or(2);
    if family == 10 {
        // Phase 91 — AF_INET6 connect: full dual-stack TCP active open, or peer
        // record for UDP/ICMPv6.
        if addr_len < 28 {
            return NEG_EINVAL;
        }
        let (addr6, port) = match sockaddr_from_user6(addr_ptr) {
            Ok(v) => v,
            Err(e) => return e,
        };
        if matches!(proto, crate::net::SocketProtocol::Tcp) {
            // Mirror of the v4 TCP connect path (non-blocking re-issue guard,
            // slot alloc, SYN, blocking/non-blocking handshake completion).
            crate::net::reconcile_connecting(handle);
            match crate::net::with_socket(handle, |s| s.state) {
                Some(crate::net::SocketState::Connected) => return NEG_EISCONN,
                Some(crate::net::SocketState::Connecting) => return NEG_EALREADY,
                _ => {}
            }
            let local_port = crate::net::with_socket(handle, |s| {
                if s.local_port == 0 {
                    crate::arch::x86_64::interrupts::tick_count() as u16 | 0x8000
                } else {
                    s.local_port
                }
            })
            .unwrap_or(0x8000);
            let tcp_idx = match crate::net::tcp::create_v6(local_port) {
                Some(idx) => idx,
                None => return NEG_EAGAIN, // no v6 source configured or no slots
            };
            crate::net::tcp::connect_v6(tcp_idx, addr6, port);
            crate::net::with_socket_mut(handle, |s| {
                s.tcp_slot = Some(tcp_idx);
                s.remote_addr6 = addr6;
                s.remote_port = port;
                s.local_port = local_port;
            });
            let nonblock = current_fd_entry(fd as usize)
                .map(|e| e.nonblock)
                .unwrap_or(false);
            if nonblock {
                crate::net::with_socket_mut(handle, |s| {
                    s.state = crate::net::SocketState::Connecting;
                });
                return NEG_EINPROGRESS;
            }
            let start_tick = crate::arch::x86_64::interrupts::tick_count();
            loop {
                match crate::net::tcp::state(tcp_idx) {
                    crate::net::tcp::TcpState::Established => {
                        crate::net::with_socket_mut(handle, |s| {
                            s.state = crate::net::SocketState::Connected;
                        });
                        return 0;
                    }
                    crate::net::tcp::TcpState::Closed => {
                        crate::net::tcp::destroy(tcp_idx);
                        crate::net::with_socket_mut(handle, |s| {
                            s.tcp_slot = None;
                            s.state = crate::net::SocketState::Closed;
                        });
                        return NEG_ECONNREFUSED;
                    }
                    _ => {
                        if crate::arch::x86_64::interrupts::tick_count().wrapping_sub(start_tick)
                            > 3000
                        {
                            crate::net::tcp::destroy(tcp_idx);
                            crate::net::with_socket_mut(handle, |s| {
                                s.tcp_slot = None;
                                s.state = crate::net::SocketState::Closed;
                            });
                            return NEG_ETIMEDOUT;
                        }
                        if has_pending_signal() {
                            crate::net::tcp::destroy(tcp_idx);
                            crate::net::with_socket_mut(handle, |s| {
                                s.tcp_slot = None;
                                s.state = crate::net::SocketState::Closed;
                            });
                            return NEG_EINTR;
                        }
                        crate::task::yield_now();
                    }
                }
            }
        }
        crate::net::with_socket_mut(handle, |s| {
            s.remote_addr6 = addr6;
            s.remote_port = port;
            s.state = crate::net::SocketState::Connected;
        });
        return 0;
    }
    if addr_len < 16 {
        return NEG_EINVAL;
    }
    let (ip, port) = match sockaddr_from_user(addr_ptr) {
        Ok(v) => v,
        Err(e) => return e,
    };

    match proto {
        crate::net::SocketProtocol::Tcp => {
            // Phase 86b — non-blocking connect re-issue guard. A poll-driven
            // client (e.g. dropbear) calls connect() again after the first call
            // returned EINPROGRESS; reject the re-issue BEFORE allocating a fresh
            // TCP slot so retries cannot leak slots from the 64-entry table.
            // Reconcile first so a connect that has since completed reports
            // EISCONN rather than EALREADY.
            crate::net::reconcile_connecting(handle);
            match crate::net::with_socket(handle, |s| s.state) {
                Some(crate::net::SocketState::Connected) => return NEG_EISCONN,
                Some(crate::net::SocketState::Connecting) => return NEG_EALREADY,
                _ => {}
            }

            // Allocate a TCP connection slot
            let local_port = crate::net::with_socket(handle, |s| {
                if s.local_port == 0 {
                    // Auto-assign ephemeral port
                    crate::arch::x86_64::interrupts::tick_count() as u16 | 0x8000
                } else {
                    s.local_port
                }
            })
            .unwrap_or(0x8000);

            let tcp_idx = match crate::net::tcp::create(local_port) {
                Some(idx) => idx,
                None => return NEG_EAGAIN, // no TCP slots
            };
            crate::net::tcp::connect(tcp_idx, ip, port);
            crate::net::with_socket_mut(handle, |s| {
                s.tcp_slot = Some(tcp_idx);
                s.remote_addr = ip;
                s.remote_port = port;
                s.local_port = local_port;
                s.local_addr = crate::net::config::our_ip();
            });

            // Phase 86b — non-blocking connect: the SYN is now in flight and the
            // standing net_task drives the handshake to completion. Return
            // EINPROGRESS immediately instead of busy-waiting; the caller detects
            // completion via poll(POLLOUT) → getsockopt(SO_ERROR). Mark the socket
            // Connecting so the poll/getsockopt paths can promote it (Established
            // → Connected) or surface failure (Closed slot → POLLOUT|POLLERR,
            // SO_ERROR=ECONNREFUSED). The TCP slot is intentionally NOT destroyed
            // here — it must outlive this syscall and is reaped at close().
            let nonblock = current_fd_entry(fd as usize)
                .map(|e| e.nonblock)
                .unwrap_or(false);
            if nonblock {
                crate::net::with_socket_mut(handle, |s| {
                    s.state = crate::net::SocketState::Connecting;
                });
                return NEG_EINPROGRESS;
            }

            // Block until connected or error
            let start_tick = crate::arch::x86_64::interrupts::tick_count();
            loop {
                let state = crate::net::tcp::state(tcp_idx);
                match state {
                    crate::net::tcp::TcpState::Established => {
                        crate::net::with_socket_mut(handle, |s| {
                            s.state = crate::net::SocketState::Connected;
                        });
                        return 0;
                    }
                    crate::net::tcp::TcpState::Closed => {
                        crate::net::tcp::destroy(tcp_idx);
                        crate::net::with_socket_mut(handle, |s| {
                            s.tcp_slot = None;
                            s.state = crate::net::SocketState::Closed;
                        });
                        return NEG_ECONNREFUSED;
                    }
                    _ => {
                        if crate::arch::x86_64::interrupts::tick_count().wrapping_sub(start_tick)
                            > 3000
                        {
                            // ~30 seconds timeout
                            crate::net::tcp::destroy(tcp_idx);
                            crate::net::with_socket_mut(handle, |s| {
                                s.tcp_slot = None;
                                s.state = crate::net::SocketState::Closed;
                            });
                            return NEG_ETIMEDOUT;
                        }
                        if has_pending_signal() {
                            // Phase 86b — reap the in-flight TCP slot before
                            // returning EINTR, mirroring the timeout/refused arms
                            // above. Without this the SYN-SENT slot is orphaned:
                            // a re-issued blocking connect() (state is still
                            // Bound/Unbound, so the Connecting re-issue guard does
                            // not catch it) calls tcp::create() again and
                            // overwrites s.tcp_slot, leaking one of 64 slots until
                            // reboot. (Pre-existing; surfaced by the 86b audit.)
                            crate::net::tcp::destroy(tcp_idx);
                            crate::net::with_socket_mut(handle, |s| {
                                s.tcp_slot = None;
                                s.state = crate::net::SocketState::Closed;
                            });
                            return NEG_EINTR;
                        }
                        crate::task::yield_now();
                    }
                }
            }
        }
        crate::net::SocketProtocol::Udp => {
            // Phase 54 Track C: delegate connect policy to net_udp service.
            if net_udp_service_available() {
                let (err, ephemeral_port) = net_udp_service_connect(handle, ip, port);
                if err != 0 {
                    return err;
                }
                // If the service auto-bound an ephemeral port, register in
                // kernel mechanism layer and update socket state.
                if ephemeral_port != 0 {
                    let _ = crate::net::udp::bind(ephemeral_port);
                    crate::net::with_socket_mut(handle, |s| {
                        s.local_port = ephemeral_port;
                        s.local_addr = crate::net::config::our_ip();
                        s.udp_bound = true;
                    });
                }
            } else {
                // Fallback: kernel owns policy directly.
                let needs_bind = crate::net::with_socket(handle, |s| !s.udp_bound).unwrap_or(true);
                if needs_bind {
                    let ephemeral = crate::arch::x86_64::interrupts::tick_count() as u16 | 0xC000;
                    if crate::net::udp::bind(ephemeral) {
                        crate::net::with_socket_mut(handle, |s| {
                            s.local_port = ephemeral;
                            s.local_addr = crate::net::config::our_ip();
                            s.udp_bound = true;
                        });
                    }
                }
            }
            crate::net::with_socket_mut(handle, |s| {
                s.remote_addr = ip;
                s.remote_port = port;
                s.state = crate::net::SocketState::Connected;
            });
            0
        }
        crate::net::SocketProtocol::Icmp => {
            crate::net::with_socket_mut(handle, |s| {
                s.remote_addr = ip;
                s.state = crate::net::SocketState::Connected;
            });
            0
        }
    }
}

/// listen(fd, backlog) — syscall 50
pub(super) fn sys_listen(fd: u64, backlog: u64) -> u64 {
    if let Ok((handle, _)) = unix_socket_handle_from_fd(fd) {
        return sys_listen_unix(handle, backlog);
    }
    let (handle, _kind, proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    if !matches!(proto, crate::net::SocketProtocol::Tcp) {
        return NEG_EOPNOTSUPP;
    }
    let local_port = crate::net::with_socket(handle, |s| s.local_port).unwrap_or(0);
    if local_port == 0 {
        return NEG_EINVAL; // must bind first
    }
    // Allocate a TCP slot for listening — a v6 slot for an AF_INET6 socket so
    // inbound v6 SYNs (which only match family==10 connections) reach it.
    let family = crate::net::with_socket(handle, |s| s.family).unwrap_or(2);
    let tcp_idx = match if family == 10 {
        crate::net::tcp::create_v6(local_port)
    } else {
        crate::net::tcp::create(local_port)
    } {
        Some(idx) => idx,
        None => return NEG_EAGAIN,
    };
    crate::net::tcp::listen(tcp_idx);
    crate::net::with_socket_mut(handle, |s| {
        s.tcp_slot = Some(tcp_idx);
        s.state = crate::net::SocketState::Listening;
    });
    0
}

/// accept(fd, addr, addrlen) — syscall 43
pub(super) fn sys_accept(fd: u64, addr_ptr: u64, addr_len_ptr: u64) -> u64 {
    if let Ok((_, _)) = unix_socket_handle_from_fd(fd) {
        return sys_accept_unix(fd, addr_ptr, addr_len_ptr, 0);
    }
    let (handle, _kind, _proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    let tcp_idx = match crate::net::with_socket(handle, |s| s.tcp_slot) {
        Some(Some(idx)) => idx,
        _ => return NEG_EINVAL,
    };

    // Block until an incoming connection is established
    loop {
        let state = crate::net::tcp::state(tcp_idx);
        match state {
            crate::net::tcp::TcpState::Established | crate::net::tcp::TcpState::CloseWait => {
                // Connection accepted — the listen slot has been consumed.
                // Transfer it to a new socket.
                let new_handle = match crate::net::alloc_socket(
                    crate::net::SocketKind::Stream,
                    crate::net::SocketProtocol::Tcp,
                ) {
                    Some(h) => h,
                    None => return NEG_ENFILE,
                };

                // Phase 91 — the accepted socket inherits the listener's address
                // family so getpeername/recvfrom report the correct sockaddr and
                // the re-armed listen slot is the right family (a v6 listener must
                // re-arm a v6 slot, since inbound v6 SYNs only match family==10
                // connections in `handle_tcp_v6`).
                let listener_family = crate::net::with_socket(handle, |s| s.family).unwrap_or(2);

                // Peer info, family-tagged: the v6 4-tuple for AF_INET6, else the
                // legacy [u8;4] path.
                let (remote_ip, remote_port, local_port, remote_ip6) = if listener_family == 10 {
                    let (ip6, rport, lport) =
                        crate::net::tcp::peer_info6(tcp_idx).unwrap_or(([0; 16], 0, 0));
                    ([0u8; 4], rport, lport, ip6)
                } else {
                    let (ip, rport, lport) =
                        crate::net::tcp::peer_info(tcp_idx).unwrap_or(([0; 4], 0, 0));
                    (ip, rport, lport, [0u8; 16])
                };

                crate::net::with_socket_mut(new_handle, |s| {
                    s.tcp_slot = Some(tcp_idx);
                    s.family = listener_family;
                    s.remote_port = remote_port;
                    s.local_port = local_port;
                    if listener_family == 10 {
                        s.remote_addr6 = remote_ip6;
                        s.local_addr6 = crate::net::config::our_ip_v6().unwrap_or([0; 16]);
                    } else {
                        s.remote_addr = remote_ip;
                        s.local_addr = crate::net::config::our_ip();
                    }
                    s.state = crate::net::SocketState::Connected;
                });

                // Transfer ownership: clear old socket's tcp_slot first
                crate::net::with_socket_mut(handle, |s| {
                    s.tcp_slot = None;
                });

                // Create a new listen slot on the original socket — family-aware.
                let listen_port = crate::net::with_socket(handle, |s| s.local_port).unwrap_or(0);
                let relisten = if listener_family == 10 {
                    crate::net::tcp::create_v6(listen_port)
                } else {
                    crate::net::tcp::create(listen_port)
                };
                if let Some(new_tcp) = relisten {
                    crate::net::tcp::listen(new_tcp);
                    crate::net::with_socket_mut(handle, |s| {
                        s.tcp_slot = Some(new_tcp);
                    });
                } else {
                    log::warn!(
                        "[socket] accept: no TCP slots for new listener on port {listen_port}"
                    );
                }

                // Write peer address to userspace (family-tagged: 28-byte
                // sockaddr_in6 for v6, 16-byte sockaddr_in for v4).
                if addr_ptr != 0 {
                    if addr_len_ptr == 0 {
                        // Linux requires addrlen when addr is non-null
                        crate::net::release_socket_pub(new_handle);
                        return NEG_EINVAL;
                    }
                    let mut len_buf = [0u8; 4];
                    if UserSliceRo::new(addr_len_ptr, len_buf.len())
                        .and_then(|s| s.copy_to_kernel(&mut len_buf))
                        .is_err()
                    {
                        crate::net::release_socket_pub(new_handle);
                        return NEG_EFAULT;
                    }
                    let cap = u32::from_ne_bytes(len_buf) as usize;
                    if cap < 16 {
                        crate::net::release_socket_pub(new_handle);
                        return NEG_EINVAL;
                    }
                    let r = if listener_family == 10 {
                        sockaddr_to_user6(addr_ptr, remote_ip6, remote_port, cap)
                    } else {
                        sockaddr_to_user(addr_ptr, remote_ip, remote_port)
                    };
                    if let Err(e) = r {
                        crate::net::release_socket_pub(new_handle);
                        return e;
                    }
                }

                if addr_len_ptr != 0 {
                    let reported = if listener_family == 10 { 28u32 } else { 16u32 };
                    let len_buf = reported.to_ne_bytes();
                    if UserSliceWo::new(addr_len_ptr, len_buf.len())
                        .and_then(|s| s.copy_from_kernel(&len_buf))
                        .is_err()
                    {
                        crate::net::release_socket_pub(new_handle);
                        return NEG_EFAULT;
                    }
                }

                // Allocate fd for the new socket
                let entry = FdEntry {
                    backend: FdBackend::Socket { handle: new_handle },
                    offset: 0,
                    readable: true,
                    writable: true,
                    cloexec: false,
                    nonblock: false,
                };
                match alloc_fd(0, entry) {
                    Some(new_fd) => return new_fd as u64,
                    None => {
                        crate::net::release_socket_pub(new_handle);
                        return NEG_EMFILE;
                    }
                }
            }
            _ => {
                if has_pending_signal() {
                    return NEG_EINTR;
                }
                crate::task::yield_now();
            }
        }
    }
}

/// accept4(fd, addr, addrlen, flags) — syscall 288
///
/// Like accept() but applies SOCK_NONBLOCK and SOCK_CLOEXEC flags
/// to the newly accepted socket FD.
pub(super) fn sys_accept4(fd: u64, addr_ptr: u64, addr_len_ptr: u64, flags: u64) -> u64 {
    const SOCK_NONBLOCK: u64 = 0x800;
    const SOCK_CLOEXEC: u64 = 0x80000;
    if flags & !(SOCK_NONBLOCK | SOCK_CLOEXEC) != 0 {
        return NEG_EINVAL;
    }
    let result = sys_accept(fd, addr_ptr, addr_len_ptr);
    // If accept failed (negative), return the error.
    if result as i64 >= 0 {
        let new_fd = result as usize;
        if flags & (SOCK_NONBLOCK | SOCK_CLOEXEC) != 0 {
            with_current_fd_mut(new_fd, |slot| {
                if let Some(e) = slot {
                    if flags & SOCK_NONBLOCK != 0 {
                        e.nonblock = true;
                    }
                    if flags & SOCK_CLOEXEC != 0 {
                        e.cloexec = true;
                    }
                }
            });
        }
    }
    result
}

/// Phase 91 — AF_INET6 datagram send path (ICMPv6 echo + UDP over IPv6).
/// TCP-over-IPv6 is fully implemented but flows over the connected `write()`
/// path (`tcp::send` → family-aware `build_seg` → `ipv6::send_from`), not via
/// `sendto`; a payload `sendto` on a v6 TCP socket is therefore rejected below.
fn sys_sendto_v6(
    handle: crate::net::SocketHandle,
    proto: crate::net::SocketProtocol,
    data: &[u8],
    addr_ptr: u64,
    addr_len: u64,
) -> u64 {
    use crate::net::SocketProtocol;
    // ENETUNREACH (101) — no usable IPv6 source address is configured yet.
    const NEG_ENETUNREACH: u64 = (-101_i64) as u64;
    // Destination: explicit sockaddr_in6, else the connected peer.
    let (dst_addr, dst_port) = if addr_ptr != 0 {
        if addr_len < 28 {
            return NEG_EINVAL;
        }
        match sockaddr_from_user6(addr_ptr) {
            Ok(v) => v,
            Err(e) => return e,
        }
    } else {
        match crate::net::with_socket(handle, |s| (s.remote_addr6, s.remote_port)) {
            Some(v) => v,
            None => return NEG_EBADF,
        }
    };

    match proto {
        SocketProtocol::Icmp => {
            // Build an ICMPv6 Echo Request; id/seq are the first 4 payload bytes.
            let (id, seq) = if data.len() >= 4 {
                (
                    u16::from_be_bytes([data[0], data[1]]),
                    u16::from_be_bytes([data[2], data[3]]),
                )
            } else {
                (1u16, 0u16)
            };
            let rest = [(id >> 8) as u8, id as u8, (seq >> 8) as u8, seq as u8];
            let body: &[u8] = if data.len() > 4 {
                &data[4..]
            } else {
                &[0xAB; 32]
            };
            crate::net::icmpv6::arm_ping6(id, seq);

            // Source: for a self/`::1` destination use the destination itself so
            // the checksum + internal loopback round-trips; otherwise our address.
            let src = if kernel_core::types::ipv6_is_loopback(&dst_addr) {
                dst_addr
            } else {
                match crate::net::config::our_ip_v6() {
                    Some(s) => s,
                    None => return NEG_ENETUNREACH,
                }
            };
            let msg = kernel_core::net::icmpv6::build(
                kernel_core::net::icmpv6::ICMPV6_ECHO_REQUEST,
                0,
                rest,
                body,
                src,
                dst_addr,
            );
            crate::net::ipv6::send_from(src, dst_addr, kernel_core::net::ipv6::PROTO_ICMPV6, &msg);
            data.len() as u64
        }
        SocketProtocol::Udp => {
            let src = match crate::net::config::our_ip_v6() {
                Some(s) => s,
                None => return NEG_ENETUNREACH,
            };
            // Source port: the bound local port, or an ephemeral autobind.
            let mut sport = crate::net::with_socket(handle, |s| s.local_port).unwrap_or(0);
            if sport == 0 {
                for _ in 0..1024u16 {
                    let cand =
                        0xC000u16 | (crate::arch::x86_64::interrupts::tick_count() as u16 & 0x3FFF);
                    if crate::net::udp::bind_v6(cand) {
                        sport = cand;
                        break;
                    }
                }
                if sport == 0 {
                    return NEG_EAGAIN;
                }
                crate::net::with_socket_mut(handle, |s| {
                    s.local_port = sport;
                    s.udp_bound = true;
                });
            }
            crate::net::udp::send_v6(src, dst_addr, dst_port, sport, data);
            data.len() as u64
        }
        // TCP data uses the connected write() path, not sendto-with-payload.
        SocketProtocol::Tcp => NEG_EOPNOTSUPP,
    }
}

/// sendto(fd, buf, len, flags, addr, addrlen) — syscall 44
pub(super) fn sys_sendto(
    fd: u64,
    buf_ptr: u64,
    len: u64,
    _flags: u64,
    addr_ptr: u64,
    addr_len: u64,
) -> u64 {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };

    match &entry.backend {
        FdBackend::Socket { handle } => {
            let handle = *handle;
            let info = match crate::net::with_socket(handle, |s| {
                (
                    s.protocol,
                    s.tcp_slot,
                    s.remote_addr,
                    s.remote_port,
                    s.local_port,
                    s.shut_wr,
                )
            }) {
                Some(v) => v,
                None => return NEG_EBADF,
            };
            let (proto, tcp_slot, remote_addr, remote_port, local_port, shut_wr) = info;
            if shut_wr {
                const NEG_EPIPE: u64 = (-32_i64) as u64;
                return NEG_EPIPE;
            }

            let capped = (len as usize).min(4096);
            let mut tmp = [0u8; 4096];
            if UserSliceRo::new(buf_ptr, tmp[..capped].len())
                .and_then(|s| s.copy_to_kernel(&mut tmp[..capped]))
                .is_err()
            {
                return NEG_EFAULT;
            }

            // Phase 91 — AF_INET6 datagram sockets take the v6 send path. TCP
            // sends are family-agnostic (they operate on the connection's
            // tcp_slot), so a v6 TCP socket falls through to the shared TCP arm.
            let family = crate::net::with_socket(handle, |s| s.family).unwrap_or(2);
            if family == 10 && !matches!(proto, crate::net::SocketProtocol::Tcp) {
                return sys_sendto_v6(handle, proto, &tmp[..capped], addr_ptr, addr_len);
            }

            match proto {
                crate::net::SocketProtocol::Tcp => {
                    if let Some(tcp_idx) = tcp_slot {
                        // Flow-control-aware send. `tcp::send` accepts as many
                        // bytes as the connection's send window allows (always
                        // >= one segment when nothing is outstanding); a 0
                        // return means the window is currently full. Mirror the
                        // recv path: block (yield) until space frees, unless the
                        // socket is non-blocking, a signal is pending, or the
                        // connection drops. A dead peer cannot wedge us — its
                        // unacked data hits MAX_RETRANSMITS and the connection
                        // resets to Closed, surfaced here as EPIPE.
                        const NEG_EPIPE: u64 = (-32_i64) as u64;
                        let nonblock = entry.nonblock;
                        loop {
                            match crate::net::tcp::state(tcp_idx) {
                                crate::net::tcp::TcpState::Established => {
                                    let n = crate::net::tcp::send(tcp_idx, &tmp[..capped]);
                                    if n > 0 {
                                        break n as u64;
                                    }
                                    // Send window full — wait for an ACK.
                                }
                                // Still completing the handshake — wait for it.
                                crate::net::tcp::TcpState::SynSent
                                | crate::net::tcp::TcpState::SynReceived => {}
                                // Any half-closed / closed state: broken pipe.
                                _ => break NEG_EPIPE,
                            }
                            if nonblock {
                                break NEG_EAGAIN;
                            }
                            if has_pending_signal() {
                                break NEG_EINTR;
                            }
                            crate::task::yield_now();
                        }
                    } else {
                        NEG_ENOTCONN
                    }
                }
                crate::net::SocketProtocol::Udp => {
                    // Use provided addr or connected peer
                    let (dst_ip, dst_port) = if addr_ptr != 0 {
                        if addr_len < 16 {
                            return NEG_EINVAL;
                        }
                        match sockaddr_from_user(addr_ptr) {
                            Ok(v) => v,
                            Err(e) => return e,
                        }
                    } else {
                        (remote_addr, remote_port)
                    };
                    if dst_port == 0 {
                        return NEG_ENOTCONN;
                    }
                    // Phase 54 Track C: service validates, then kernel transmits.
                    let src_port = if net_udp_service_available() {
                        let (err, sp) =
                            net_udp_service_sendto_params(handle, dst_ip, dst_port, capped);
                        if err != 0 {
                            return err;
                        }
                        sp
                    } else if local_port != 0 {
                        local_port
                    } else {
                        // Phase 77 Track D.1 — kernel-direct unbound-UDP send:
                        // assign an ephemeral source port (Linux behaviour) so
                        // the reply can be routed back. Range 0xC000..=0xFFFF
                        // (16384 ports) matches the connect/net_udp ephemeral
                        // range.
                        //
                        // Probe a persistent ROTATING counter rather than a
                        // tick-derived window: the old 8-candidate loop derived
                        // every candidate from the same near-constant
                        // `tick_count`, so a cluster of ~8 contiguous bound ports
                        // falsely returned EAGAIN with thousands of ports free.
                        // The rotating counter spreads candidates across the
                        // whole range; only a port that actually binds is used,
                        // and exhausting the probe budget returns EAGAIN rather
                        // than falsely marking the socket bound. The `if` block
                        // below re-binds this same port (a no-op here, since it
                        // is already bound) so the shared service path is also
                        // registered.
                        static EPHEMERAL_UDP_NEXT: core::sync::atomic::AtomicU16 =
                            core::sync::atomic::AtomicU16::new(0);
                        let mut found_port = 0u16;
                        for _ in 0..1024u16 {
                            let n = EPHEMERAL_UDP_NEXT
                                .fetch_add(1, core::sync::atomic::Ordering::Relaxed);
                            // 0xC000 | (n & 0x3FFF) -> 0xC000..=0xFFFF, never 0.
                            let cand = 0xC000u16 | (n & 0x3FFF);
                            if crate::net::udp::bind(cand) {
                                found_port = cand;
                                break;
                            }
                        }
                        if found_port == 0 {
                            return NEG_EAGAIN;
                        }
                        found_port
                    };
                    // Phase 77 Track D.1 — register a freshly-assigned ephemeral
                    // source port so inbound datagrams (e.g. the DNS reply) are
                    // enqueued for it and `recvfrom` can dequeue them. musl's
                    // resolver `sendto`s from an unbound socket; without this the
                    // reply's dst_port matches no binding and is dropped.
                    //
                    // Bind `src_port` in the kernel `UDP_BINDINGS` table here —
                    // inbound delivery is kernel-owned even with the userspace
                    // net_udp service present (`recvfrom` dequeues via
                    // `crate::net::udp::recv`, and `handle_udp` drops datagrams
                    // for any unbound port). On the kernel-direct path the retry
                    // loop above already bound this exact port, so `bind` returns
                    // false (a harmless no-op); on the net_udp-service path the
                    // service-allocated port is not otherwise registered in the
                    // kernel table, so this is the binding that lets the reply
                    // arrive (mirrors the kernel-side bind in sys_bind/sys_connect).
                    if local_port == 0 && src_port != 0 {
                        let _ = crate::net::udp::bind(src_port);
                        let associated = crate::net::with_socket_mut(handle, |s| {
                            s.local_port = src_port;
                            s.udp_bound = true;
                        });
                        if associated.is_none() {
                            // The socket was closed concurrently (another thread
                            // sharing the fd table) between the snapshot above and
                            // here, so no `SocketEntry` will carry this port and
                            // the close path can never reclaim it. Release the
                            // just-bound port now to avoid stranding one of the
                            // 32 UDP binding slots until reboot.
                            crate::net::udp::unbind(src_port);
                        }
                    }
                    // Phase 55c Track G R1: surface EAGAIN when the ring-3 NIC
                    // driver is in a restart window.  Socket fd is already
                    // validated by the FdBackend::Socket check above.
                    if let Some(err) = crate::net::remote::RemoteNic::sendto_restart_ret() {
                        return err as u64;
                    }
                    crate::net::udp::send(dst_ip, dst_port, src_port, &tmp[..capped]);
                    capped as u64
                }
                crate::net::SocketProtocol::Icmp => {
                    // Build and send ICMP echo request
                    let dst_ip = if addr_ptr != 0 {
                        if addr_len < 16 {
                            return NEG_EINVAL;
                        }
                        match sockaddr_from_user(addr_ptr) {
                            Ok((ip, _)) => ip,
                            Err(e) => return e,
                        }
                    } else {
                        remote_addr
                    };
                    // The payload IS the ICMP packet body (type/code/checksum/rest + data
                    // are built by the caller for raw ICMP, but for DGRAM ICMP sockets
                    // we build the echo request).
                    // Extract id and seq from the first 4 bytes if present
                    let (id, seq) = if capped >= 4 {
                        let id = u16::from_be_bytes([tmp[0], tmp[1]]);
                        let seq = u16::from_be_bytes([tmp[2], tmp[3]]);
                        (id, seq)
                    } else {
                        (1u16, 0u16)
                    };
                    let rest = [(id >> 8) as u8, id as u8, (seq >> 8) as u8, seq as u8];
                    let payload = if capped > 4 {
                        &tmp[4..capped]
                    } else {
                        &[0xABu8; 32] as &[u8]
                    };
                    use crate::net::icmp::{
                        ICMP_ECHO_REQUEST, PING_EXPECTED_ID, PING_EXPECTED_SEQ, PING_REPLY_RECEIVED,
                    };
                    use core::sync::atomic::Ordering;
                    PING_REPLY_RECEIVED.store(false, Ordering::Release);
                    PING_EXPECTED_ID.store(id, Ordering::Release);
                    PING_EXPECTED_SEQ.store(seq, Ordering::Release);
                    let icmp_pkt =
                        kernel_core::net::icmp::build(ICMP_ECHO_REQUEST, 0, rest, payload);
                    // Phase 55c Track G R1: same restart gate as the UDP path.
                    if let Some(err) = crate::net::remote::RemoteNic::sendto_restart_ret() {
                        return err as u64;
                    }
                    crate::net::ipv4::send(dst_ip, crate::net::ipv4::PROTO_ICMP, &icmp_pkt);
                    capped as u64
                }
            }
        }
        FdBackend::UnixSocket { handle } => {
            let handle = *handle;
            let sock_type = crate::net::unix::with_unix_socket(handle, |s| s.socket_type);
            match sock_type {
                Some(crate::net::unix::UnixSocketType::Datagram) => {
                    sys_sendto_unix(handle, buf_ptr, len, entry.nonblock, addr_ptr, addr_len)
                }
                Some(crate::net::unix::UnixSocketType::Stream) => {
                    // Stream sockets use write() semantics.
                    sys_linux_write(fd, buf_ptr, len)
                }
                None => NEG_EBADF,
            }
        }
        FdBackend::PipeWrite { .. } => {
            // sendto on pipe-based socketpair — delegate to write
            sys_linux_write(fd, buf_ptr, len)
        }
        _ => sys_linux_write(fd, buf_ptr, len),
    }
}

/// recvfrom(fd, buf, len, flags, addr, addrlen) — syscall 45
pub(super) fn sys_recvfrom_socket(
    fd: u64,
    buf_ptr: u64,
    count: u64,
    flags: u64,
    addr_ptr: u64,
    addr_len_ptr: u64,
) -> u64 {
    const MSG_DONTWAIT: u64 = 0x40;

    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };
    let nonblock = entry.nonblock || flags & MSG_DONTWAIT != 0;

    match &entry.backend {
        FdBackend::Socket { handle } => {
            let handle = *handle;
            let info = match crate::net::with_socket(handle, |s| {
                (
                    s.protocol,
                    s.tcp_slot,
                    s.local_port,
                    s.remote_addr,
                    s.remote_port,
                    s.shut_rd,
                )
            }) {
                Some(v) => v,
                None => return NEG_EBADF,
            };
            let (proto, tcp_slot, local_port, remote_addr, remote_port, shut_rd) = info;
            if shut_rd {
                return 0; // EOF
            }
            // Phase 91 — AF_INET6 sockets recv from the v6 path.
            let family = crate::net::with_socket(handle, |s| s.family).unwrap_or(2);
            let remote_addr6 =
                crate::net::with_socket(handle, |s| s.remote_addr6).unwrap_or([0; 16]);

            // Validate addr_len if addr_ptr is provided, capturing the caller's
            // declared buffer size so a v6 sockaddr write clamps to it (a v6
            // peer is 28 bytes but the gate only requires >= 16; without the
            // clamp a 16..27-byte buffer would be overrun — see
            // `sockaddr_to_user6`).
            let mut addr_cap = 0usize;
            if addr_ptr != 0 {
                if addr_len_ptr == 0 {
                    return NEG_EINVAL;
                }
                let mut len_buf = [0u8; 4];
                if UserSliceRo::new(addr_len_ptr, len_buf.len())
                    .and_then(|s| s.copy_to_kernel(&mut len_buf))
                    .is_err()
                {
                    return NEG_EFAULT;
                }
                let cap = u32::from_ne_bytes(len_buf) as usize;
                if cap < 16 {
                    return NEG_EINVAL;
                }
                addr_cap = cap;
            }

            let capped = (count as usize).min(4096);

            match proto {
                crate::net::SocketProtocol::Tcp => {
                    let tcp_idx = match tcp_slot {
                        Some(idx) => idx,
                        None => return NEG_ENOTCONN,
                    };
                    loop {
                        let mut tmp = [0u8; 4096];
                        let n = crate::net::tcp::recv(tcp_idx, &mut tmp[..capped]);
                        if n > 0 {
                            if UserSliceWo::new(buf_ptr, tmp[..n].len())
                                .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                                .is_err()
                            {
                                return NEG_EFAULT;
                            }
                            if addr_ptr != 0 {
                                // Phase 91 — fill the v6 peer for AF_INET6 TCP.
                                let r = if family == 10 {
                                    sockaddr_to_user6(addr_ptr, remote_addr6, remote_port, addr_cap)
                                } else {
                                    sockaddr_to_user(addr_ptr, remote_addr, remote_port)
                                };
                                if let Err(e) = r {
                                    return e;
                                }
                                if addr_len_ptr != 0 {
                                    let reported = if family == 10 { 28u32 } else { 16u32 };
                                    let len_buf = reported.to_ne_bytes();
                                    if UserSliceWo::new(addr_len_ptr, len_buf.len())
                                        .and_then(|s| s.copy_from_kernel(&len_buf))
                                        .is_err()
                                    {
                                        return NEG_EFAULT;
                                    }
                                }
                            }
                            return n as u64;
                        }
                        // Check if connection is closed
                        let state = crate::net::tcp::state(tcp_idx);
                        if matches!(
                            state,
                            crate::net::tcp::TcpState::CloseWait
                                | crate::net::tcp::TcpState::Closed
                                | crate::net::tcp::TcpState::TimeWait
                        ) {
                            return 0; // EOF
                        }
                        if nonblock {
                            return NEG_EAGAIN;
                        }
                        if has_pending_signal() {
                            return NEG_EINTR;
                        }
                        crate::task::yield_now();
                    }
                }
                crate::net::SocketProtocol::Udp if family == 10 => {
                    // Phase 91 — AF_INET6 UDP recv from the v6 datagram queue.
                    loop {
                        if let Some(dgram) = crate::net::udp::recv_v6(local_port) {
                            let n = dgram.data.len().min(capped);
                            if UserSliceWo::new(buf_ptr, dgram.data[..n].len())
                                .and_then(|s| s.copy_from_kernel(&dgram.data[..n]))
                                .is_err()
                            {
                                return NEG_EFAULT;
                            }
                            if addr_ptr != 0 {
                                if let Err(e) = sockaddr_to_user6(
                                    addr_ptr,
                                    dgram.src_ip,
                                    dgram.src_port,
                                    addr_cap,
                                ) {
                                    return e;
                                }
                                if addr_len_ptr != 0 {
                                    let len_buf = 28u32.to_ne_bytes();
                                    if UserSliceWo::new(addr_len_ptr, len_buf.len())
                                        .and_then(|s| s.copy_from_kernel(&len_buf))
                                        .is_err()
                                    {
                                        return NEG_EFAULT;
                                    }
                                }
                            }
                            return n as u64;
                        }
                        if nonblock {
                            return NEG_EAGAIN;
                        }
                        if has_pending_signal() {
                            return NEG_EINTR;
                        }
                        crate::task::yield_now();
                    }
                }
                crate::net::SocketProtocol::Udp => {
                    // Phase 54 Track C: service validates which port to recv from.
                    let recv_port = if net_udp_service_available() {
                        let (err, port) = net_udp_service_recvfrom_port(handle);
                        if err != 0 {
                            return err;
                        }
                        port
                    } else {
                        local_port
                    };
                    loop {
                        if let Some(dgram) = crate::net::udp::recv(recv_port) {
                            let n = dgram.data.len().min(capped);
                            if UserSliceWo::new(buf_ptr, dgram.data[..n].len())
                                .and_then(|s| s.copy_from_kernel(&dgram.data[..n]))
                                .is_err()
                            {
                                return NEG_EFAULT;
                            }
                            if addr_ptr != 0 {
                                if let Err(e) =
                                    sockaddr_to_user(addr_ptr, dgram.src_ip, dgram.src_port)
                                {
                                    return e;
                                }
                                if addr_len_ptr != 0 {
                                    let len_buf = 16u32.to_ne_bytes();
                                    if UserSliceWo::new(addr_len_ptr, len_buf.len())
                                        .and_then(|s| s.copy_from_kernel(&len_buf))
                                        .is_err()
                                    {
                                        return NEG_EFAULT;
                                    }
                                }
                            }
                            return n as u64;
                        }
                        if nonblock {
                            return NEG_EAGAIN;
                        }
                        if has_pending_signal() {
                            return NEG_EINTR;
                        }
                        crate::task::yield_now();
                    }
                }
                crate::net::SocketProtocol::Icmp => {
                    // Wait for an ICMP(v6) echo reply. The v6 path tracks the
                    // reply via the PING6_* atomics (set by `icmpv6` on a wire
                    // reply or the internal loopback for `::1`/self).
                    use core::sync::atomic::Ordering;
                    let is_v6 = family == 10;
                    loop {
                        let got = if is_v6 {
                            crate::net::icmpv6::PING6_REPLY_RECEIVED.load(Ordering::Acquire)
                        } else {
                            crate::net::icmp::PING_REPLY_RECEIVED.load(Ordering::Acquire)
                        };
                        if got {
                            let tick = if is_v6 {
                                crate::net::icmpv6::PING6_REPLY_RECEIVED
                                    .store(false, Ordering::Release);
                                crate::net::icmpv6::PING6_REPLY_TICK.load(Ordering::Acquire)
                            } else {
                                crate::net::icmp::PING_REPLY_RECEIVED
                                    .store(false, Ordering::Release);
                                crate::net::icmp::PING_REPLY_TICK.load(Ordering::Acquire)
                            };
                            // Write tick as 8-byte LE to userspace as reply data
                            let tick_bytes = tick.to_le_bytes();
                            let n = tick_bytes.len().min(capped);
                            if UserSliceWo::new(buf_ptr, tick_bytes[..n].len())
                                .and_then(|s| s.copy_from_kernel(&tick_bytes[..n]))
                                .is_err()
                            {
                                return NEG_EFAULT;
                            }
                            if addr_ptr != 0 {
                                let r = if is_v6 {
                                    sockaddr_to_user6(addr_ptr, remote_addr6, 0, addr_cap)
                                } else {
                                    sockaddr_to_user(addr_ptr, remote_addr, 0)
                                };
                                if let Err(e) = r {
                                    return e;
                                }
                                if addr_len_ptr != 0 {
                                    let reported = if is_v6 { 28u32 } else { 16u32 };
                                    let len_buf = reported.to_ne_bytes();
                                    if UserSliceWo::new(addr_len_ptr, len_buf.len())
                                        .and_then(|s| s.copy_from_kernel(&len_buf))
                                        .is_err()
                                    {
                                        return NEG_EFAULT;
                                    }
                                }
                            }
                            return n as u64;
                        }
                        if nonblock {
                            return NEG_EAGAIN;
                        }
                        if has_pending_signal() {
                            return NEG_EINTR;
                        }
                        crate::task::yield_now();
                    }
                }
            }
        }
        FdBackend::PipeRead { pipe_id } => {
            let pipe_id = *pipe_id;
            let len = (count as usize).min(4096);

            if nonblock {
                let mut tmp = [0u8; 4096];
                match crate::pipe::pipe_read(pipe_id, &mut tmp[..len]) {
                    Ok(n) if n > 0 => {
                        if UserSliceWo::new(buf_ptr, tmp[..n].len())
                            .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                            .is_err()
                        {
                            return NEG_EFAULT;
                        }
                        n as u64
                    }
                    Ok(_) => 0,
                    Err(_) => NEG_EAGAIN,
                }
            } else {
                loop {
                    let mut tmp = [0u8; 4096];
                    match crate::pipe::pipe_read(pipe_id, &mut tmp[..len]) {
                        Ok(0) => return 0,
                        Ok(n) => {
                            if UserSliceWo::new(buf_ptr, tmp[..n].len())
                                .and_then(|s| s.copy_from_kernel(&tmp[..n]))
                                .is_err()
                            {
                                return NEG_EFAULT;
                            }
                            return n as u64;
                        }
                        Err(_) => {
                            if has_pending_signal() {
                                return NEG_EINTR;
                            }
                            crate::task::yield_now();
                        }
                    }
                }
            }
        }
        FdBackend::UnixSocket { handle } => {
            let handle = *handle;
            let sock_type = crate::net::unix::with_unix_socket(handle, |s| s.socket_type);
            match sock_type {
                Some(crate::net::unix::UnixSocketType::Datagram) => {
                    sys_recvfrom_unix(handle, buf_ptr, count, nonblock, addr_ptr, addr_len_ptr)
                }
                Some(crate::net::unix::UnixSocketType::Stream) => {
                    sys_linux_read(fd, buf_ptr, count)
                }
                None => NEG_EBADF,
            }
        }
        _ => sys_linux_read(fd, buf_ptr, count),
    }
}

/// shutdown(fd, how) — syscall 48
pub(super) fn sys_shutdown_sock(fd: u64, how: u64) -> u64 {
    if let Ok((handle, _)) = unix_socket_handle_from_fd(fd) {
        return sys_shutdown_unix(handle, how);
    }
    let (handle, _kind, _proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    let tcp_slot = crate::net::with_socket(handle, |s| s.tcp_slot).flatten();
    match how {
        0 => {
            // SHUT_RD
            crate::net::with_socket_mut(handle, |s| s.shut_rd = true);
        }
        1 => {
            // SHUT_WR
            if let Some(tcp_idx) = tcp_slot {
                crate::net::tcp::close(tcp_idx); // send FIN
            }
            crate::net::with_socket_mut(handle, |s| s.shut_wr = true);
        }
        2 => {
            // SHUT_RDWR
            if let Some(tcp_idx) = tcp_slot {
                crate::net::tcp::close(tcp_idx);
            }
            crate::net::with_socket_mut(handle, |s| {
                s.shut_rd = true;
                s.shut_wr = true;
                s.state = crate::net::SocketState::Closed;
            });
        }
        _ => return NEG_EINVAL,
    }
    0
}

/// getsockname(fd, addr, addrlen) — syscall 51
pub(super) fn sys_getsockname(fd: u64, addr_ptr: u64, addr_len_ptr: u64) -> u64 {
    let (handle, _kind, _proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    // Phase 91 — family-aware: a v6 socket reports its sockaddr_in6 (28 bytes).
    let (family, ip, ip6, port) = match crate::net::with_socket(handle, |s| {
        (s.family, s.local_addr, s.local_addr6, s.local_port)
    }) {
        Some(v) => v,
        None => return NEG_EBADF,
    };
    let mut cap = if family == 10 { 28usize } else { 16usize };
    if addr_len_ptr != 0 {
        let mut len_buf = [0u8; 4];
        if UserSliceRo::new(addr_len_ptr, len_buf.len())
            .and_then(|s| s.copy_to_kernel(&mut len_buf))
            .is_err()
        {
            return NEG_EFAULT;
        }
        let provided = u32::from_ne_bytes(len_buf) as usize;
        if provided < 16 {
            return NEG_EINVAL;
        }
        cap = provided;
    }
    let r = if family == 10 {
        sockaddr_to_user6(addr_ptr, ip6, port, cap)
    } else {
        sockaddr_to_user(addr_ptr, ip, port)
    };
    if let Err(e) = r {
        return e;
    }
    if addr_len_ptr != 0 {
        let reported = if family == 10 { 28u32 } else { 16u32 };
        let len_buf = reported.to_ne_bytes();
        if UserSliceWo::new(addr_len_ptr, len_buf.len())
            .and_then(|s| s.copy_from_kernel(&len_buf))
            .is_err()
        {
            return NEG_EFAULT;
        }
    }
    0
}

/// getpeername(fd, addr, addrlen) — syscall 52
pub(super) fn sys_getpeername(fd: u64, addr_ptr: u64, addr_len_ptr: u64) -> u64 {
    let (handle, _kind, _proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    // Phase 86b — promote a completed non-blocking connect before reading
    // s.state, so a client that lets connect() reach Established without ever
    // poll()ing does not get a spurious ENOTCONN here. Keeps getpeername
    // consistent with the other SocketState readers (connect/getsockopt/poll).
    crate::net::reconcile_connecting(handle);
    // Phase 91 — family-aware: a v6 socket reports its sockaddr_in6 (28 bytes).
    let info = match crate::net::with_socket(handle, |s| {
        (
            s.family,
            s.remote_addr,
            s.remote_addr6,
            s.remote_port,
            s.state,
        )
    }) {
        Some(v) => v,
        None => return NEG_EBADF,
    };
    let (family, ip, ip6, port, state) = info;
    if !matches!(state, crate::net::SocketState::Connected) {
        return NEG_ENOTCONN;
    }
    let mut cap = if family == 10 { 28usize } else { 16usize };
    if addr_len_ptr != 0 {
        let mut len_buf = [0u8; 4];
        if UserSliceRo::new(addr_len_ptr, len_buf.len())
            .and_then(|s| s.copy_to_kernel(&mut len_buf))
            .is_err()
        {
            return NEG_EFAULT;
        }
        let provided = u32::from_ne_bytes(len_buf) as usize;
        if provided < 16 {
            return NEG_EINVAL;
        }
        cap = provided;
    }
    let r = if family == 10 {
        sockaddr_to_user6(addr_ptr, ip6, port, cap)
    } else {
        sockaddr_to_user(addr_ptr, ip, port)
    };
    if let Err(e) = r {
        return e;
    }
    if addr_len_ptr != 0 {
        let reported = if family == 10 { 28u32 } else { 16u32 };
        let len_buf = reported.to_ne_bytes();
        if UserSliceWo::new(addr_len_ptr, len_buf.len())
            .and_then(|s| s.copy_from_kernel(&len_buf))
            .is_err()
        {
            return NEG_EFAULT;
        }
    }
    0
}

/// setsockopt(fd, level, optname, optval, optlen) — syscall 54
pub(super) fn sys_setsockopt(
    fd: u64,
    level: u64,
    optname: u64,
    optval_ptr: u64,
    optlen: u64,
) -> u64 {
    let (handle, _kind, _proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };
    // Read the option value (up to 4 bytes for int options)
    if optlen < 4 {
        return NEG_EINVAL;
    }
    let val = if optval_ptr != 0 {
        let mut buf = [0u8; 4];
        if UserSliceRo::new(optval_ptr, buf.len())
            .and_then(|s| s.copy_to_kernel(&mut buf))
            .is_err()
        {
            return NEG_EFAULT;
        }
        i32::from_ne_bytes(buf)
    } else {
        return NEG_EFAULT;
    };

    const SOL_SOCKET: u64 = 1;
    const SO_REUSEADDR: u64 = 2;
    const SO_KEEPALIVE: u64 = 9;
    const SO_RCVBUF: u64 = 8;
    const SO_SNDBUF: u64 = 7;
    const IPPROTO_TCP: u64 = 6;
    const TCP_NODELAY: u64 = 1;
    // TCP keepalive tuning (IPPROTO_TCP level). Accepted + stored for the
    // future keepalive prober; the probe timer itself is deferred (see
    // `crate::net::SocketOptions` and docs/roadmap/90b-claude-code.md).
    const TCP_KEEPIDLE: u64 = 4;
    const TCP_KEEPINTVL: u64 = 5;
    const TCP_KEEPCNT: u64 = 6;

    match (level, optname) {
        (SOL_SOCKET, SO_REUSEADDR) => {
            crate::net::with_socket_mut(handle, |s| s.options.reuse_addr = val != 0);
        }
        (SOL_SOCKET, SO_KEEPALIVE) => {
            crate::net::with_socket_mut(handle, |s| s.options.keep_alive = val != 0);
        }
        (SOL_SOCKET, SO_RCVBUF) => {
            crate::net::with_socket_mut(handle, |s| s.options.recv_buf_size = val as u32);
        }
        (SOL_SOCKET, SO_SNDBUF) => {
            crate::net::with_socket_mut(handle, |s| s.options.send_buf_size = val as u32);
        }
        (IPPROTO_TCP, TCP_NODELAY) => {
            crate::net::with_socket_mut(handle, |s| s.options.tcp_nodelay = val != 0);
        }
        (IPPROTO_TCP, TCP_KEEPIDLE) => {
            crate::net::with_socket_mut(handle, |s| s.options.keep_idle_secs = val.max(0) as u32);
        }
        (IPPROTO_TCP, TCP_KEEPINTVL) => {
            crate::net::with_socket_mut(handle, |s| s.options.keep_intvl_secs = val.max(0) as u32);
        }
        (IPPROTO_TCP, TCP_KEEPCNT) => {
            crate::net::with_socket_mut(handle, |s| s.options.keep_cnt = val.max(0) as u32);
        }
        // Phase 90b: accept-and-log unimplemented best-effort options instead
        // of returning ENOPROTOOPT. m3OS presents a Linux ABI and runs
        // unmodified Linux binaries (libuv/undici/curl) that treat *any*
        // setsockopt failure as fatal — a hard ENOPROTOOPT on an optional knob
        // (e.g. SO_LINGER, SO_REUSEPORT) aborts the connection. Ignoring the
        // hint is safe; the value is simply not honored. The first such call
        // per boot is logged so the deferred work is visible (see
        // docs/roadmap/90b-claude-code.md). Reads stay honest: an
        // unimplemented `getsockopt` still returns ENOPROTOOPT rather than
        // fabricating a value.
        _ => log_setsockopt_noop(level, optname),
    }
    0
}

/// One-shot, per-boot log of the first `setsockopt` that hit the accept-and-log
/// path (Phase 90b). Single line per boot to stay clear of the SMP serial-RX
/// starvation guard — a tight retry loop would otherwise flood COM1.
fn log_setsockopt_noop(level: u64, optname: u64) {
    use core::sync::atomic::{AtomicBool, Ordering};
    static WARNED: AtomicBool = AtomicBool::new(false);
    if !WARNED.swap(true, Ordering::Relaxed) {
        log::info!(
            "[net] setsockopt: accepting unimplemented option as no-op \
             (first: level={level} optname={optname}); socket-option behaviors \
             (incl. the TCP keepalive prober) are tracked as deferred — see \
             docs/roadmap/90b-claude-code.md"
        );
    }
}

/// getsockopt(fd, level, optname, optval, optlen) — syscall 55
pub(super) fn sys_getsockopt(
    fd: u64,
    level: u64,
    optname: u64,
    optval_ptr: u64,
    optlen_ptr: u64,
) -> u64 {
    const SOL_SOCKET: u64 = 1;
    const SO_REUSEADDR: u64 = 2;
    const SO_KEEPALIVE: u64 = 9;
    const SO_RCVBUF: u64 = 8;
    const SO_SNDBUF: u64 = 7;
    const SO_ERROR: u64 = 4;
    const SO_PEERCRED: u64 = 17;
    const IPPROTO_TCP: u64 = 6;
    const TCP_NODELAY: u64 = 1;
    const TCP_KEEPIDLE: u64 = 4;
    const TCP_KEEPINTVL: u64 = 5;
    const TCP_KEEPCNT: u64 = 6;

    // Phase 69d follow-up: SO_PEERCRED on a Unix-domain socket
    // returns the connected peer's `struct ucred { pid, uid, gid }`.
    // tmux's `server_acl_join` requires this to identify the
    // connecting client's uid; rejecting the call with ENOTSOCK
    // makes tmux refuse the connection with "access not allowed".
    let fd_idx = fd as usize;
    if fd_idx < MAX_FDS
        && level == SOL_SOCKET
        && optname == SO_PEERCRED
        && let Some(entry) = current_fd_entry(fd_idx)
        && let FdBackend::UnixSocket { handle } = entry.backend
    {
        let creds =
            crate::net::unix::with_unix_socket(handle, |s| (s.peer_pid, s.peer_uid, s.peer_gid));
        let (pid, uid, gid) = creds.unwrap_or((0, u32::MAX, u32::MAX));
        // struct ucred is 12 bytes: pid(4) uid(4) gid(4).
        const UCRED_SIZE: usize = 12;
        if optlen_ptr != 0 {
            let mut len_buf = [0u8; 4];
            if UserSliceRo::new(optlen_ptr, len_buf.len())
                .and_then(|s| s.copy_to_kernel(&mut len_buf))
                .is_err()
            {
                return NEG_EFAULT;
            }
            let caller_len = u32::from_ne_bytes(len_buf) as usize;
            if caller_len < UCRED_SIZE {
                return NEG_EINVAL;
            }
        }
        if optval_ptr == 0 {
            return NEG_EFAULT;
        }
        let mut buf = [0u8; UCRED_SIZE];
        buf[0..4].copy_from_slice(&(pid as i32).to_ne_bytes());
        buf[4..8].copy_from_slice(&uid.to_ne_bytes());
        buf[8..12].copy_from_slice(&gid.to_ne_bytes());
        if UserSliceWo::new(optval_ptr, buf.len())
            .and_then(|s| s.copy_from_kernel(&buf))
            .is_err()
        {
            return NEG_EFAULT;
        }
        if optlen_ptr != 0 {
            let written = (UCRED_SIZE as u32).to_ne_bytes();
            if UserSliceWo::new(optlen_ptr, written.len())
                .and_then(|s| s.copy_from_kernel(&written))
                .is_err()
            {
                return NEG_EFAULT;
            }
        }
        return 0;
    }

    let (handle, _kind, _proto) = match socket_handle_from_fd(fd) {
        Ok(v) => v,
        Err(e) => return e,
    };

    let val: i32 = match (level, optname) {
        (SOL_SOCKET, SO_REUSEADDR) => {
            crate::net::with_socket(handle, |s| s.options.reuse_addr as i32).unwrap_or(0)
        }
        (SOL_SOCKET, SO_KEEPALIVE) => {
            crate::net::with_socket(handle, |s| s.options.keep_alive as i32).unwrap_or(0)
        }
        (SOL_SOCKET, SO_RCVBUF) => {
            crate::net::with_socket(handle, |s| s.options.recv_buf_size as i32).unwrap_or(0)
        }
        (SOL_SOCKET, SO_SNDBUF) => {
            crate::net::with_socket(handle, |s| s.options.send_buf_size as i32).unwrap_or(0)
        }
        (IPPROTO_TCP, TCP_NODELAY) => {
            crate::net::with_socket(handle, |s| s.options.tcp_nodelay as i32).unwrap_or(0)
        }
        // Keepalive tuning round-trips the value stored by setsockopt (the
        // probe timer is deferred; see SocketOptions / 90b-claude-code.md).
        (IPPROTO_TCP, TCP_KEEPIDLE) => {
            crate::net::with_socket(handle, |s| s.options.keep_idle_secs as i32).unwrap_or(7200)
        }
        (IPPROTO_TCP, TCP_KEEPINTVL) => {
            crate::net::with_socket(handle, |s| s.options.keep_intvl_secs as i32).unwrap_or(75)
        }
        (IPPROTO_TCP, TCP_KEEPCNT) => {
            crate::net::with_socket(handle, |s| s.options.keep_cnt as i32).unwrap_or(9)
        }
        (SOL_SOCKET, SO_ERROR) => {
            // Phase 86b — pending socket error, read once by clients after a
            // non-blocking connect completes (poll POLLOUT → getsockopt SO_ERROR).
            // Derived on demand and bounded to the connecting window: a connect
            // that reached Established (now promoted to Connected) or is still in
            // flight reports 0; a Connecting socket whose slot has gone Closed
            // reports the POSITIVE errno ECONNREFUSED(111). A normally
            // established/closed data socket reports 0 (no spurious error). The
            // value written is the positive errno, not the kernel NEG_ encoding.
            crate::net::reconcile_connecting(handle);
            crate::net::with_socket(handle, |s| {
                if matches!(s.state, crate::net::SocketState::Connecting) {
                    match s.tcp_slot {
                        Some(idx)
                            if matches!(
                                crate::net::tcp::state(idx),
                                crate::net::tcp::TcpState::Closed
                            ) =>
                        {
                            111
                        }
                        _ => 0,
                    }
                } else {
                    0
                }
            })
            .unwrap_or(0)
        }
        _ => return NEG_ENOPROTOOPT,
    };

    // Validate caller's buffer size
    if optlen_ptr != 0 {
        let mut len_buf = [0u8; 4];
        if UserSliceRo::new(optlen_ptr, len_buf.len())
            .and_then(|s| s.copy_to_kernel(&mut len_buf))
            .is_err()
        {
            return NEG_EFAULT;
        }
        let caller_len = u32::from_ne_bytes(len_buf);
        if caller_len < 4 {
            return NEG_EINVAL;
        }
    }

    if optval_ptr == 0 {
        return NEG_EFAULT;
    }
    let buf = val.to_ne_bytes();
    if UserSliceWo::new(optval_ptr, buf.len())
        .and_then(|s| s.copy_from_kernel(&buf))
        .is_err()
    {
        return NEG_EFAULT;
    }
    if optlen_ptr != 0 {
        let len_buf = 4u32.to_ne_bytes();
        if UserSliceWo::new(optlen_ptr, len_buf.len())
            .and_then(|s| s.copy_from_kernel(&len_buf))
            .is_err()
        {
            return NEG_EFAULT;
        }
    }
    0
}

// ---------------------------------------------------------------------------
// Phase 69d follow-up: sendmsg / recvmsg with SCM_RIGHTS support
// ---------------------------------------------------------------------------
//
// Both syscalls follow the same shape:
//   1. Copy the user-space `struct msghdr` (56 bytes on x86_64) into a
//      kernel `MsgHdr`.
//   2. Copy the `iovec` array and run the scatter / gather copy.
//   3. For `sendmsg`, parse each cmsg in `msg_control` and — for
//      `SOL_SOCKET / SCM_RIGHTS` cmsgs — clone the sender's `FdBackend`
//      and park it on the peer's ancillary queue tagged with the byte
//      position of the first byte that rides with it.
//   4. For `recvmsg`, after the data copy completes, drain ancillary
//      fds whose `deliver_at_stream_pos` is now <= the receiver's
//      consumed-bytes cursor, install them in the receiver's fd table,
//      and encode an outgoing `SCM_RIGHTS` cmsg into `msg_control`.

/// Acquire a refcount on the underlying kernel object referenced by a
/// `FdBackend` so a parallel handle can be parked on a peer's anc queue.
/// Mirrors `crate::process::add_fd_refs` for a single entry.
fn acquire_inflight_anc_backend(backend: &FdBackend) {
    match backend {
        FdBackend::PipeRead { pipe_id } => crate::pipe::pipe_add_reader(*pipe_id),
        FdBackend::PipeWrite { pipe_id } => crate::pipe::pipe_add_writer(*pipe_id),
        FdBackend::EventFd { id } => crate::eventfd::eventfd_add_ref(*id),
        FdBackend::Socket { handle } => crate::net::add_socket_ref(*handle),
        FdBackend::UnixSocket { handle } => crate::net::unix::add_unix_socket_ref(*handle),
        FdBackend::PtyMaster { pty_id } => crate::pty::add_master_ref(*pty_id),
        FdBackend::PtySlave { pty_id } => crate::pty::add_slave_ref(*pty_id),
        FdBackend::Epoll { instance_id } => epoll_add_ref_pub(*instance_id),
        _ => {}
    }
}

/// True iff `acquire_inflight_anc_backend` has refcount semantics for
/// this backend kind.  `sys_sendmsg` rejects fds whose backend would
/// sit on the anc queue without a pin, because the sender's close path
/// (and for VfsService / Ext2Disk the fd-table alias scan) is invisible
/// to the in-flight copy and would tear the underlying object down
/// before the receiver's `recvmsg` materializes it.
fn anc_backend_is_refcounted(backend: &FdBackend) -> bool {
    // Phase 69d follow-up (PR #177 third-pass review fix): `UnixSocket`
    // was previously included but allowing it leaks sockets in
    // self/cyclic SCM_RIGHTS transfers — an in-flight fd increments
    // the socket's refcount, but `free_unix_socket` drains
    // `anc_queue` only when the refcount reaches zero, so a socket
    // queued on itself (or a cycle of sockets queued on each other)
    // keeps the last reference forever.  Full garbage collection of
    // such cycles is a substantial future patch (mirroring Linux's
    // unix_gc); for now reject UnixSocket fds in SCM_RIGHTS with
    // `EOPNOTSUPP` from the sendmsg path so the cycle cannot form.
    // tmux and other current SCM_RIGHTS users on m3OS pass pipe /
    // PTY fds, not Unix sockets, so the rejection does not regress
    // any in-tree caller.
    matches!(
        backend,
        FdBackend::PipeRead { .. }
            | FdBackend::PipeWrite { .. }
            // Phase 86d Track D — eventfd is cycle-safe (no anc_queue like
            // UnixSocket), refcounted, and Linux permits passing it via
            // SCM_RIGHTS; keep it symmetric with the acquire/release helpers.
            | FdBackend::EventFd { .. }
            | FdBackend::Socket { .. }
            | FdBackend::PtyMaster { .. }
            | FdBackend::PtySlave { .. }
            | FdBackend::Epoll { .. }
    )
}

/// Drop a refcount previously acquired by [`acquire_inflight_anc_backend`].
/// Called from sendmsg/recvmsg rollback paths and from the receiver's
/// SCM_RIGHTS install path when an fd slot couldn't be allocated.  Kept
/// next to the acquire helper so additions to the backend list stay
/// symmetric.
fn release_inflight_anc_backend(backend: &FdBackend) {
    match backend {
        FdBackend::PipeRead { pipe_id } => crate::pipe::pipe_close_reader(*pipe_id),
        FdBackend::PipeWrite { pipe_id } => crate::pipe::pipe_close_writer(*pipe_id),
        FdBackend::EventFd { id } => crate::eventfd::eventfd_close(*id),
        FdBackend::Socket { handle } => crate::net::release_socket_pub(*handle),
        FdBackend::UnixSocket { handle } => crate::net::unix::free_unix_socket(*handle),
        FdBackend::PtyMaster { pty_id } => crate::pty::close_master(*pty_id),
        FdBackend::PtySlave { pty_id } => crate::pty::close_slave(*pty_id),
        FdBackend::Epoll { instance_id } => crate::epoll::epoll_free_pub(*instance_id),
        _ => {}
    }
}

/// Whether an in-flight ancillary fd is ready to be drained given the
/// receiver's current `stream_pos_consumed`.  For data-carrying sends
/// the receiver must have consumed PAST the first byte; for
/// ancillary-only sends the fd is deliverable as soon as the consumed
/// cursor REACHES `deliver_at_stream_pos`.  Centralised so the four
/// recvmsg / read sites agree (PR #177 third-pass review fix).
fn inflight_is_deliverable(inf: &crate::net::unix::InflightFd, consumed: u64) -> bool {
    if inf.has_data {
        consumed > inf.deliver_at_stream_pos
    } else {
        consumed >= inf.deliver_at_stream_pos
    }
}

/// Maximum bytes per scatter/gather copy.  Mirrors the limit used by
/// `sys_sendto` / `sys_recvfrom_socket`.
const SENDMSG_MAX_BYTES: usize = 4096;
/// Maximum bytes per ancillary-data buffer.  Generous enough for ~64
/// fds per cmsg.
const SENDMSG_MAX_CONTROL: usize = 1024;

pub(super) fn sys_sendmsg(fd: u64, msghdr_ptr: u64, flags: u64) -> u64 {
    use kernel_core::net::msghdr::{
        CmsgView, CmsgWalkError, IOVEC_SIZE, IoVec, MSG_DONTWAIT, MSGHDR_SIZE, MsgHdr, SCM_MAX_FD,
        SENDMSG_SUPPORTED_FLAGS, try_for_each_cmsg,
    };

    // Reject any flag bit the kernel doesn't honour so callers don't
    // silently get different semantics than they asked for.
    let flags_i32 = flags as i32;
    if flags_i32 & !SENDMSG_SUPPORTED_FLAGS != 0 {
        return NEG_EOPNOTSUPP;
    }
    let force_nonblock = flags_i32 & MSG_DONTWAIT != 0;

    // 1. Copy msghdr.
    let mut header_bytes = [0u8; MSGHDR_SIZE];
    if UserSliceRo::new(msghdr_ptr, header_bytes.len())
        .and_then(|s| s.copy_to_kernel(&mut header_bytes))
        .is_err()
    {
        return NEG_EFAULT;
    }
    let header = match MsgHdr::decode(&header_bytes) {
        Some(h) => h,
        None => return NEG_EINVAL,
    };
    // Linux's `UIO_MAXIOV` cap.
    if header.msg_iovlen > 1024 {
        return NEG_EINVAL;
    }

    // 2. Resolve the fd.  We only support AF_UNIX stream for now —
    // datagram and AF_INET sendmsg fall through to `-EOPNOTSUPP` rather
    // than silently shimming on top of `sys_sendto`.
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };
    if !entry.writable {
        return NEG_EBADF;
    }
    let nonblock = entry.nonblock || force_nonblock;
    let unix_handle = match &entry.backend {
        FdBackend::UnixSocket { handle } => *handle,
        _ => return NEG_EOPNOTSUPP,
    };
    // Reject datagram Unix sockets — they have message-boundary
    // semantics that the stream-buffer write path does not preserve.
    // Supporting them is a future patch; for now refuse explicitly so
    // callers don't get silently corrupted into the stream path.
    let socket_type = match crate::net::unix::with_unix_socket(unix_handle, |s| s.socket_type) {
        Some(t) => t,
        None => return NEG_EBADF,
    };
    if !matches!(socket_type, crate::net::unix::UnixSocketType::Stream) {
        return NEG_EOPNOTSUPP;
    }

    // 3. Decode iov array and concatenate.
    let iov_count = header.msg_iovlen as usize;
    let mut iov_buf = alloc::vec![0u8; iov_count.checked_mul(IOVEC_SIZE).unwrap_or(0)];
    if iov_count > 0
        && UserSliceRo::new(header.msg_iov, iov_buf.len())
            .and_then(|s| s.copy_to_kernel(&mut iov_buf))
            .is_err()
    {
        return NEG_EFAULT;
    }
    let iovs = match IoVec::decode_array(&iov_buf, iov_count) {
        Some(v) => v,
        None => return NEG_EINVAL,
    };

    let total_len = IoVec::total_len(&iovs).min(SENDMSG_MAX_BYTES as u64) as usize;
    let mut payload = alloc::vec![0u8; total_len];
    {
        let mut cursor = 0usize;
        for iov in &iovs {
            if cursor >= total_len {
                break;
            }
            let chunk = ((total_len - cursor) as u64).min(iov.iov_len) as usize;
            if chunk == 0 {
                continue;
            }
            if UserSliceRo::new(iov.iov_base, chunk)
                .and_then(|s| s.copy_to_kernel(&mut payload[cursor..cursor + chunk]))
                .is_err()
            {
                return NEG_EFAULT;
            }
            cursor += chunk;
        }
    }

    // 4. Parse ancillary buffer and build InflightFd list.
    //
    // Phase 69d follow-up (PR #177 third-pass review fix): reject
    // `msg_controllen > 0 && msg_control == 0` as `EFAULT` instead of
    // silently dropping the caller's ancillary data — Linux's
    // sendmsg(2) reports EFAULT for this combination and applications
    // (notably tmux) rely on the error path to surface a malformed
    // header.
    if header.msg_controllen > 0 && header.msg_control == 0 {
        return NEG_EFAULT;
    }
    let mut inflight: alloc::vec::Vec<crate::net::unix::InflightFd> = alloc::vec::Vec::new();
    if header.msg_control != 0 && header.msg_controllen > 0 {
        if header.msg_controllen as usize > SENDMSG_MAX_CONTROL {
            return NEG_EINVAL;
        }
        let mut control = alloc::vec![0u8; header.msg_controllen as usize];
        if UserSliceRo::new(header.msg_control, control.len())
            .and_then(|s| s.copy_to_kernel(&mut control))
            .is_err()
        {
            return NEG_EFAULT;
        }

        let mut error: u64 = 0;
        let walk = try_for_each_cmsg(&control, |view: CmsgView<'_>| {
            if error != 0 {
                return;
            }
            if !view.is_scm_rights() {
                // Unknown ancillary kind — Linux silently ignores
                // unrecognized cmsgs on send.  Match that behaviour.
                return;
            }
            let Some(fds) = view.scm_rights_fds() else {
                error = NEG_EINVAL;
                return;
            };
            if fds.len() > SCM_MAX_FD {
                error = NEG_EINVAL;
                return;
            }
            for sender_fd in fds {
                if sender_fd < 0 || (sender_fd as usize) >= MAX_FDS {
                    error = NEG_EBADF;
                    return;
                }
                let Some(sender_entry) = current_fd_entry(sender_fd as usize) else {
                    error = NEG_EBADF;
                    return;
                };
                // Reject backends without inflight refcount support
                // (VfsService, Ext2Disk, Fat32Disk, Ramdisk, Tmpfs,
                // Dir, Proc, DeviceTTY, Dev{Null,Zero,Urandom,Full},
                // Stdin, Stdout).  Those have no per-handle refcount
                // for the anc-queue path to pin: the sender's close
                // path or fd-table alias scan would tear the underlying
                // object down before the receiver materializes it,
                // leaving the receiver to install a stale backend.
                if !anc_backend_is_refcounted(&sender_entry.backend) {
                    error = NEG_EOPNOTSUPP;
                    return;
                }
                acquire_inflight_anc_backend(&sender_entry.backend);
                inflight.push(crate::net::unix::InflightFd {
                    backend: sender_entry.backend.clone(),
                    cloexec: sender_entry.cloexec,
                    offset: sender_entry.offset,
                    nonblock: sender_entry.nonblock,
                    readable: sender_entry.readable,
                    writable: sender_entry.writable,
                    // Updated below once we know the post-write peer offset.
                    deliver_at_stream_pos: 0,
                    // Updated below by `unix_stream_write_with_anc` once
                    // it knows whether bytes followed in this sendmsg.
                    has_data: false,
                });
            }
        });
        // Malformed control buffer (header truncated or cmsg_len lies)
        // is a hard EINVAL — silently ignoring it would drop fds the
        // caller intended to pass.
        if let Err(walk_err) = walk
            && error == 0
        {
            error = match walk_err {
                CmsgWalkError::TruncatedHeader | CmsgWalkError::InvalidLength => NEG_EINVAL,
            };
        }
        if error != 0 {
            for inf in &inflight {
                release_inflight_anc_backend(&inf.backend);
            }
            return error;
        }
    }

    // 5. Atomic delivery: stamp inflight cmsgs with the peer's current
    //    stream offset and append them to the anc queue under the same
    //    lock that extends `recv_buf`.  For blocking stream sockets the
    //    peer buffer can be full; park on our own wait queue and retry
    //    on every wake — matches `sys_linux_write`'s blocking contract
    //    for the same UnixSocket backend so a full-buffer sendmsg
    //    sleeps efficiently instead of burning scheduler turns on
    //    `yield_now()`.  The reader's `unix_stream_read` wakes
    //    `self.peer = unix_handle` after draining bytes.
    let mut inflight_mut = inflight;
    let written = loop {
        match crate::net::unix::unix_stream_write_with_anc(unix_handle, &payload, &mut inflight_mut)
        {
            Ok(n) => break n,
            // -EAGAIN: peer buffer full.  Honour the same blocking
            // contract as `write(2)` on the same backend — only return
            // EAGAIN when the fd or call is non-blocking.
            Err(-11) => {
                if nonblock {
                    for inf in &inflight_mut {
                        release_inflight_anc_backend(&inf.backend);
                    }
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    for inf in &inflight_mut {
                        release_inflight_anc_backend(&inf.backend);
                    }
                    return NEG_EINTR;
                }
                // Phase 69d follow-up (PR #177 third-pass review fix):
                // genuine register-before-block pattern with a recheck
                // *after* registering.  If the peer drains between the
                // initial EAGAIN and `register`, the wake_unix_socket
                // call fires against an empty queue; the recheck below
                // then sees the freed space and breaks immediately.
                // If the recheck still sees EAGAIN, we are safely
                // parked and the next `wake_unix_socket` either lands
                // on our queued entry (woken=true) or has already
                // landed (block_current_until's TOCTOU recheck
                // observes woken=true and returns AlreadyTrue).
                let task_id = match crate::task::scheduler::current_task_id() {
                    Some(id) => id,
                    None => {
                        for inf in &inflight_mut {
                            release_inflight_anc_backend(&inf.backend);
                        }
                        return NEG_EINTR;
                    }
                };
                let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
                let wq = &crate::net::unix::UNIX_SOCKET_WAITQUEUES[unix_handle];
                wq.register(task_id, &woken);
                match crate::net::unix::unix_stream_write_with_anc(
                    unix_handle,
                    &payload,
                    &mut inflight_mut,
                ) {
                    Ok(n) => {
                        wq.deregister(task_id);
                        break n;
                    }
                    Err(-11) => {
                        let _ = crate::task::scheduler::block_current_until(
                            crate::task::TaskState::BlockedOnRecv,
                            &woken,
                            None,
                        );
                        wq.deregister(task_id);
                        // Loop body retries the write.
                    }
                    Err(e) => {
                        wq.deregister(task_id);
                        for inf in &inflight_mut {
                            release_inflight_anc_backend(&inf.backend);
                        }
                        return e as u64;
                    }
                }
            }
            Err(e) => {
                for inf in &inflight_mut {
                    release_inflight_anc_backend(&inf.backend);
                }
                return e as u64;
            }
        }
    };

    written as u64
}

/// `recvmsg()` for AF_INET sockets (UDP / TCP).
///
/// musl's stub resolver (`__res_msend`) drains DNS replies with `recvmsg`,
/// **not** `recvfrom`, and then byte-compares the reply's source address —
/// which it reads from `msg_name` — against its configured nameserver list
/// (`memcmp(ns+j, &sa, sl)`). A reply whose source sockaddr is missing or
/// wrong is silently discarded, so the kernel MUST both deliver the payload
/// and fill `msg_name` with the sender's `sockaddr_in`. Before this path
/// existed, `recvmsg` on an INET socket returned `EOPNOTSUPP`, so the
/// resolver busy-looped `poll → recvmsg(fail) → poll` until its timeout and
/// `getaddrinfo` returned `EAI_AGAIN` even though the reply sat ready in the
/// kernel's UDP queue. Mirrors `sys_recvfrom_socket`'s recv logic.
fn sys_recvmsg_inet(
    handle: crate::net::SocketHandle,
    mut header: kernel_core::net::msghdr::MsgHdr,
    msghdr_ptr: u64,
    nonblock: bool,
) -> u64 {
    use kernel_core::net::msghdr::{IOVEC_SIZE, IoVec, MSG_TRUNC, MSGHDR_SIZE};

    // Decode the scatter list.
    let iov_count = header.msg_iovlen as usize;
    if iov_count > 1024 {
        return NEG_EINVAL;
    }
    let mut iov_buf = alloc::vec![0u8; iov_count.checked_mul(IOVEC_SIZE).unwrap_or(0)];
    if iov_count > 0
        && UserSliceRo::new(header.msg_iov, iov_buf.len())
            .and_then(|s| s.copy_to_kernel(&mut iov_buf))
            .is_err()
    {
        return NEG_EFAULT;
    }
    let iovs = match IoVec::decode_array(&iov_buf, iov_count) {
        Some(v) => v,
        None => return NEG_EINVAL,
    };
    let cap = IoVec::total_len(&iovs).min(SENDMSG_MAX_BYTES as u64) as usize;

    // Validate the writable destination prefix BEFORE consuming a datagram,
    // so an EFAULT cannot drop an already-dequeued reply (same discipline as
    // the Unix recvmsg path).
    let mut remaining_validate = cap as u64;
    for iov in &iovs {
        if remaining_validate == 0 {
            break;
        }
        let chunk = iov.iov_len.min(remaining_validate);
        if chunk == 0 {
            continue;
        }
        if UserSliceWo::new(iov.iov_base, chunk as usize).is_err() {
            return NEG_EFAULT;
        }
        remaining_validate -= chunk;
    }
    if UserSliceWo::new(msghdr_ptr, MSGHDR_SIZE).is_err() {
        return NEG_EFAULT;
    }
    // Phase 91 — AF_INET6 sockets report a 28-byte `sockaddr_in6` source;
    // AF_INET reports a 16-byte `sockaddr_in`.
    let family = crate::net::with_socket(handle, |s| s.family).unwrap_or(2);
    let name_cap = if family == 10 { 28usize } else { 16 };
    // Pre-validate the `msg_name` buffer up front too. The source-address
    // write happens in `finish` AFTER a datagram is dequeued, so without this
    // a faulting `msg_name` pointer would consume-and-drop the reply — the
    // same loss the iov/msghdr pre-validation above guards against.
    if header.msg_name != 0 {
        let name_len = (header.msg_namelen as usize).min(name_cap);
        if name_len > 0 && UserSliceWo::new(header.msg_name, name_len).is_err() {
            return NEG_EFAULT;
        }
    }

    let info = match crate::net::with_socket(handle, |s| {
        (
            s.protocol,
            s.tcp_slot,
            s.local_port,
            s.remote_addr,
            s.remote_port,
            s.shut_rd,
        )
    }) {
        Some(v) => v,
        None => return NEG_EBADF,
    };
    // remote_addr/remote_port are intentionally unused: datagram sockets fill
    // msg_name from the per-datagram source, and connection-mode (TCP) reports
    // msg_namelen = 0 like Linux.
    let (proto, tcp_slot, local_port, _remote_addr, _remote_port, shut_rd) = info;

    // Helper: write the sender's `sockaddr_in` into `msg_name` for datagram
    // sockets (`src = Some(..)`) and commit the updated msghdr
    // (namelen/controllen/flags). Connection-mode (TCP) and EOF pass
    // `src = None`, which reports `msg_namelen = 0` like Linux. `msg_name` is
    // pre-validated above, so the copy here only faults under a concurrent
    // unmap (same window the iov writes accept). Returns `Err(errno)` on a
    // faulting copy. On return `msg_namelen` carries the real address size
    // (16) even if the caller's buffer was smaller — the recvmsg(2) contract,
    // matching `sys_recvfrom_socket`.
    // Family-tagged datagram source for `finish`. `None` = connection-mode
    // (TCP) / EOF (reports `msg_namelen = 0`, like Linux).
    enum RecvSrc {
        None,
        V4([u8; 4], u16),
        V6([u8; 16], u16),
    }
    let finish = |header: &mut kernel_core::net::msghdr::MsgHdr,
                  src: RecvSrc,
                  truncated: bool|
     -> Result<(), u64> {
        // recvmsg(2) is value-result: copy at most the caller's buffer size, but
        // always report the *real* address length (16 v4 / 28 v6) on return —
        // even when the buffer is too small or empty — so a caller probing the
        // length or truncating sees the true size.
        match src {
            RecvSrc::V4(src_ip, src_port) if header.msg_name != 0 => {
                let name_len = (header.msg_namelen as usize).min(16);
                if name_len > 0 {
                    let mut sa = [0u8; 16];
                    sa[0..2].copy_from_slice(&2u16.to_ne_bytes()); // AF_INET
                    sa[2..4].copy_from_slice(&src_port.to_be_bytes());
                    sa[4..8].copy_from_slice(&src_ip);
                    if UserSliceWo::new(header.msg_name, name_len)
                        .and_then(|s| s.copy_from_kernel(&sa[..name_len]))
                        .is_err()
                    {
                        return Err(NEG_EFAULT);
                    }
                }
                header.msg_namelen = 16;
            }
            RecvSrc::V6(src_ip, src_port) if header.msg_name != 0 => {
                let name_len = (header.msg_namelen as usize).min(28);
                if name_len > 0 {
                    let mut sa = [0u8; 28];
                    sa[0..2].copy_from_slice(&10u16.to_ne_bytes()); // AF_INET6
                    sa[2..4].copy_from_slice(&src_port.to_be_bytes()); // sin6_port
                    // sin6_flowinfo @4..8 stays zero.
                    sa[8..24].copy_from_slice(&src_ip); // sin6_addr
                    // sin6_scope_id @24..28 stays zero.
                    if UserSliceWo::new(header.msg_name, name_len)
                        .and_then(|s| s.copy_from_kernel(&sa[..name_len]))
                        .is_err()
                    {
                        return Err(NEG_EFAULT);
                    }
                }
                header.msg_namelen = 28;
            }
            _ => header.msg_namelen = 0,
        }
        header.msg_controllen = 0;
        header.msg_flags = if truncated { MSG_TRUNC } else { 0 };
        let encoded = header.encode();
        if UserSliceWo::new(msghdr_ptr, encoded.len())
            .and_then(|s| s.copy_from_kernel(&encoded))
            .is_err()
        {
            return Err(NEG_EFAULT);
        }
        Ok(())
    };

    if shut_rd {
        // EOF: deliver a zero-length message with a clean header.
        return match finish(&mut header, RecvSrc::None, false) {
            Ok(()) => 0,
            Err(e) => e,
        };
    }

    match proto {
        crate::net::SocketProtocol::Udp => {
            // Resolve the recv port. AF_INET6 UDP uses the v6 datagram queue
            // keyed by the bound local port (the v4-only net_udp service is not
            // in that path); AF_INET keeps the existing service-resolved port.
            let recv_port = if family == 10 {
                local_port
            } else if net_udp_service_available() {
                let (err, port) = net_udp_service_recvfrom_port(handle);
                if err != 0 {
                    return err;
                }
                port
            } else {
                local_port
            };
            loop {
                // Dequeue a datagram of the socket's family, tagging the source.
                let dg: Option<(alloc::vec::Vec<u8>, RecvSrc)> = if family == 10 {
                    crate::net::udp::recv_v6(recv_port)
                        .map(|d| (d.data, RecvSrc::V6(d.src_ip, d.src_port)))
                } else {
                    crate::net::udp::recv(recv_port)
                        .map(|d| (d.data, RecvSrc::V4(d.src_ip, d.src_port)))
                };
                if let Some((data, src)) = dg {
                    let n = data.len().min(cap);
                    let mut cursor = 0usize;
                    for iov in &iovs {
                        if cursor >= n {
                            break;
                        }
                        let chunk = ((n - cursor) as u64).min(iov.iov_len) as usize;
                        if chunk == 0 {
                            continue;
                        }
                        if UserSliceWo::new(iov.iov_base, chunk)
                            .and_then(|s| s.copy_from_kernel(&data[cursor..cursor + chunk]))
                            .is_err()
                        {
                            return NEG_EFAULT;
                        }
                        cursor += chunk;
                    }
                    let truncated = data.len() > n;
                    if let Err(e) = finish(&mut header, src, truncated) {
                        return e;
                    }
                    return n as u64;
                }
                if nonblock {
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    return NEG_EINTR;
                }
                crate::task::yield_now();
            }
        }
        crate::net::SocketProtocol::Tcp => {
            let tcp_idx = match tcp_slot {
                Some(idx) => idx,
                None => return NEG_ENOTCONN,
            };
            // A zero-length read returns 0 immediately (Linux recv semantics);
            // entering the loop with cap == 0 would otherwise spin a blocking
            // socket forever, since tcp::recv always yields 0 for an empty buf.
            if cap == 0 {
                return match finish(&mut header, RecvSrc::None, false) {
                    Ok(()) => 0,
                    Err(e) => e,
                };
            }
            let mut tmp = alloc::vec![0u8; cap];
            loop {
                let n = crate::net::tcp::recv(tcp_idx, &mut tmp[..cap]);
                if n > 0 {
                    let mut cursor = 0usize;
                    for iov in &iovs {
                        if cursor >= n {
                            break;
                        }
                        let chunk = ((n - cursor) as u64).min(iov.iov_len) as usize;
                        if chunk == 0 {
                            continue;
                        }
                        if UserSliceWo::new(iov.iov_base, chunk)
                            .and_then(|s| s.copy_from_kernel(&tmp[cursor..cursor + chunk]))
                            .is_err()
                        {
                            return NEG_EFAULT;
                        }
                        cursor += chunk;
                    }
                    // Connection-mode socket: Linux reports msg_namelen = 0.
                    if let Err(e) = finish(&mut header, RecvSrc::None, false) {
                        return e;
                    }
                    return n as u64;
                }
                let state = crate::net::tcp::state(tcp_idx);
                if matches!(
                    state,
                    crate::net::tcp::TcpState::CloseWait
                        | crate::net::tcp::TcpState::Closed
                        | crate::net::tcp::TcpState::TimeWait
                ) {
                    return match finish(&mut header, RecvSrc::None, false) {
                        Ok(()) => 0,
                        Err(e) => e,
                    };
                }
                if nonblock {
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    return NEG_EINTR;
                }
                crate::task::yield_now();
            }
        }
        crate::net::SocketProtocol::Icmp => NEG_EOPNOTSUPP,
    }
}

pub(super) fn sys_recvmsg(fd: u64, msghdr_ptr: u64, flags: u64) -> u64 {
    use kernel_core::net::msghdr::{
        IOVEC_SIZE, IoVec, MSG_CMSG_CLOEXEC, MSG_CTRUNC, MSG_DONTWAIT, MSGHDR_SIZE, MsgHdr,
        RECVMSG_SUPPORTED_FLAGS, SCM_MAX_FD, cmsg_space, encode_scm_rights,
    };

    // Reject unrecognized flag bits.  MSG_PEEK would require splitting
    // the read path so as not to consume bytes; it is a future patch.
    let flags_i32 = flags as i32;
    if flags_i32 & !RECVMSG_SUPPORTED_FLAGS != 0 {
        return NEG_EOPNOTSUPP;
    }
    let force_nonblock = flags_i32 & MSG_DONTWAIT != 0;
    let cmsg_cloexec = flags_i32 & MSG_CMSG_CLOEXEC != 0;

    // 1. Copy msghdr.
    let mut header_bytes = [0u8; MSGHDR_SIZE];
    if UserSliceRo::new(msghdr_ptr, header_bytes.len())
        .and_then(|s| s.copy_to_kernel(&mut header_bytes))
        .is_err()
    {
        return NEG_EFAULT;
    }
    let mut header = match MsgHdr::decode(&header_bytes) {
        Some(h) => h,
        None => return NEG_EINVAL,
    };
    if header.msg_iovlen > 1024 {
        return NEG_EINVAL;
    }

    // 2. Resolve fd → UnixSocket handle.
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let entry = match current_fd_entry(fd_idx) {
        Some(e) => e,
        None => return NEG_EBADF,
    };
    if !entry.readable {
        return NEG_EBADF;
    }
    let nonblock = entry.nonblock || force_nonblock;
    // AF_INET / AF_INET6 sockets (UDP/TCP) take a dedicated path: the DNS
    // resolver drains UDP replies with recvmsg and validates the source address
    // from msg_name. `sys_recvmsg_inet` is family-aware (Phase 91) — it fills a
    // 16-byte sockaddr_in or a 28-byte sockaddr_in6 per the socket's family. The
    // Unix-socket SCM_RIGHTS machinery below does not apply.
    if let FdBackend::Socket { handle } = &entry.backend {
        return sys_recvmsg_inet(*handle, header, msghdr_ptr, nonblock);
    }
    let unix_handle = match &entry.backend {
        FdBackend::UnixSocket { handle } => *handle,
        _ => return NEG_EOPNOTSUPP,
    };
    let socket_type = match crate::net::unix::with_unix_socket(unix_handle, |s| s.socket_type) {
        Some(t) => t,
        None => return NEG_EBADF,
    };
    if !matches!(socket_type, crate::net::unix::UnixSocketType::Stream) {
        return NEG_EOPNOTSUPP;
    }

    // 3. Decode iov array.
    let iov_count = header.msg_iovlen as usize;
    let mut iov_buf = alloc::vec![0u8; iov_count.checked_mul(IOVEC_SIZE).unwrap_or(0)];
    if iov_count > 0
        && UserSliceRo::new(header.msg_iov, iov_buf.len())
            .and_then(|s| s.copy_to_kernel(&mut iov_buf))
            .is_err()
    {
        return NEG_EFAULT;
    }
    let iovs = match IoVec::decode_array(&iov_buf, iov_count) {
        Some(v) => v,
        None => return NEG_EINVAL,
    };
    let cap = IoVec::total_len(&iovs).min(SENDMSG_MAX_BYTES as u64) as usize;

    // Phase 69d follow-up (PR #177 third-pass review fix): pre-validate
    // the writable range of every output iov BEFORE consuming bytes
    // from the socket, but only up to the bytes we may ACTUALLY write
    // (capped at `SENDMSG_MAX_BYTES`).  An earlier version validated
    // the FULL advertised iovec length, which rejected legitimate
    // large receive buffers because `UserSliceWo::new` enforces a
    // 96 KiB MAX_COPY_LEN cap.  The recv path only ever writes
    // `min(total_iov_len, SENDMSG_MAX_BYTES)`, so only that prefix
    // needs to be writable for the read to land safely.
    //
    // Without the pre-validation: the first invalid destination would
    // be discovered AFTER `unix_stream_read` had advanced
    // `stream_pos_consumed`, and the drained bytes (plus any
    // ancillary fd whose `deliver_at_stream_pos` the read crossed)
    // would be lost — the caller would see EFAULT while the data was
    // gone.
    //
    // Also reject `msg_controllen > 0 && msg_control == 0` as EFAULT
    // before consuming bytes (Linux's recvmsg(2) reports EFAULT for
    // a null buffer with non-zero length).
    if header.msg_controllen > 0 && header.msg_control == 0 {
        return NEG_EFAULT;
    }
    let mut remaining_validate = cap as u64;
    for iov in &iovs {
        if remaining_validate == 0 {
            break;
        }
        let chunk = iov.iov_len.min(remaining_validate);
        if chunk == 0 {
            continue;
        }
        if UserSliceWo::new(iov.iov_base, chunk as usize).is_err() {
            return NEG_EFAULT;
        }
        remaining_validate -= chunk;
    }
    if header.msg_controllen > 0
        && header.msg_control != 0
        && UserSliceWo::new(header.msg_control, header.msg_controllen as usize).is_err()
    {
        return NEG_EFAULT;
    }
    if UserSliceWo::new(msghdr_ptr, MSGHDR_SIZE).is_err() {
        return NEG_EFAULT;
    }

    // Phase 69d follow-up (PR #177 third-pass review fix): a
    // zero-capacity recvmsg with no pending ancillary data should
    // complete immediately with 0 instead of parking on the socket
    // wait queue forever — Linux returns 0 for `recvmsg` with a
    // zero-length iov when no ancillary is queued.
    if cap == 0 {
        let anc_already_ready = crate::net::unix::with_unix_socket(unix_handle, |s| {
            s.anc_queue
                .front()
                .map(|inf| inflight_is_deliverable(inf, s.stream_pos_consumed))
                .unwrap_or(false)
        })
        .unwrap_or(false);
        if !anc_already_ready {
            // Write back zeroed control/flags so caller sees a clean header.
            header.msg_controllen = 0;
            header.msg_flags = 0;
            let encoded = header.encode();
            if UserSliceWo::new(msghdr_ptr, encoded.len())
                .and_then(|s| s.copy_from_kernel(&encoded))
                .is_err()
            {
                return NEG_EFAULT;
            }
            return 0;
        }
    }

    // 4. Read data — wait until at least one byte arrives, an
    //    ancillary-only message arrives, EOF, or signal.  Register on
    //    the socket wait queue every iteration so wake_all's consume-
    //    on-wake semantics cannot lose a wake (same fix that closed
    //    the tmux-control-client hang in `sys_poll`).
    let mut tmp = alloc::vec![0u8; cap.max(1)];
    let n = loop {
        // Zero-payload SCM_RIGHTS message: the sender wrote 0 bytes
        // with a non-empty cmsg, so `unix_stream_read` will keep
        // returning EAGAIN forever while the inflight fd sits on the
        // anc queue waiting for a byte cursor that never advances.
        // Detect this case before the read attempt and break out so
        // step 6 below can drain the queue.
        let anc_ready_no_bytes = crate::net::unix::with_unix_socket(unix_handle, |s| {
            s.recv_buf.is_empty()
                && s.anc_queue
                    .front()
                    .map(|inf| inflight_is_deliverable(inf, s.stream_pos_consumed))
                    .unwrap_or(false)
        })
        .unwrap_or(false);
        if anc_ready_no_bytes {
            break 0usize;
        }
        match crate::net::unix::unix_stream_read(unix_handle, &mut tmp[..cap]) {
            Ok(n) => break n,
            Err(-11) => {
                if nonblock {
                    return NEG_EAGAIN;
                }
                if has_pending_signal() {
                    return NEG_EINTR;
                }
                // Phase 69d follow-up (PR #177 third-pass review fix):
                // register-before-block with a recheck after register.
                // The earlier inline fix omitted the recheck — if data
                // (or an ancillary fd) arrived between the initial
                // EAGAIN and `register`, the wake fired against an
                // empty queue and the task could park indefinitely
                // while the socket was readable.  The post-register
                // re-read closes that window: either it succeeds (we
                // deregister and break with the data) or it returns
                // EAGAIN under registration, in which case any future
                // wake either lands on our queued entry or has already
                // set `woken=true` so `block_current_until` returns
                // immediately.
                let task_id = match crate::task::scheduler::current_task_id() {
                    Some(id) => id,
                    None => return NEG_EINTR,
                };
                let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
                let wq = &crate::net::unix::UNIX_SOCKET_WAITQUEUES[unix_handle];
                wq.register(task_id, &woken);
                // Recheck the zero-payload SCM_RIGHTS edge case (an
                // ancillary fd became ready between the previous check
                // and registration) before the byte read.
                let anc_ready_now = crate::net::unix::with_unix_socket(unix_handle, |s| {
                    s.recv_buf.is_empty()
                        && s.anc_queue
                            .front()
                            .map(|inf| inflight_is_deliverable(inf, s.stream_pos_consumed))
                            .unwrap_or(false)
                })
                .unwrap_or(false);
                if anc_ready_now {
                    wq.deregister(task_id);
                    break 0usize;
                }
                match crate::net::unix::unix_stream_read(unix_handle, &mut tmp[..cap]) {
                    Ok(n) => {
                        wq.deregister(task_id);
                        break n;
                    }
                    Err(-11) => {
                        let _ = crate::task::scheduler::block_current_until(
                            crate::task::TaskState::BlockedOnRecv,
                            &woken,
                            None,
                        );
                        wq.deregister(task_id);
                        continue;
                    }
                    Err(e) => {
                        wq.deregister(task_id);
                        return e as u64;
                    }
                }
            }
            Err(e) => return e as u64,
        }
    };

    // 5. Scatter the bytes into user iov entries.
    {
        let mut cursor = 0usize;
        for iov in &iovs {
            if cursor >= n {
                break;
            }
            let chunk = ((n - cursor) as u64).min(iov.iov_len) as usize;
            if chunk == 0 {
                continue;
            }
            if UserSliceWo::new(iov.iov_base, chunk)
                .and_then(|s| s.copy_from_kernel(&tmp[cursor..cursor + chunk]))
                .is_err()
            {
                return NEG_EFAULT;
            }
            cursor += chunk;
        }
    }

    // 6. Drain ready ancillary fds and install them in the receiver's
    // fd table.  We grant at most SCM_MAX_FD per call to keep the
    // outgoing cmsg payload bounded.
    let ready = crate::net::unix::unix_stream_drain_ready_anc(unix_handle, SCM_MAX_FD);
    let mut new_fds: alloc::vec::Vec<i32> = alloc::vec::Vec::with_capacity(ready.len());
    let mut control_bytes_written: usize = 0;
    let mut ctrunc = false;
    if !ready.is_empty() {
        // Compute outgoing cmsg size and decide whether the receiver's
        // control buffer is large enough; if not, set MSG_CTRUNC and
        // drop the extra entries from the tail.
        let mut keep_n = ready.len();
        let control_budget = header.msg_controllen as usize;
        while keep_n > 0 && cmsg_space(keep_n * 4) > control_budget {
            keep_n -= 1;
            ctrunc = true;
        }

        // Install up to `keep_n` of the ready fds into the receiver's
        // fd table; release refcounts on the truncated tail.
        //
        // Phase 69d follow-up (PR #177 review): preserve the sender's
        // FdEntry metadata (offset / readable / writable / nonblock)
        // so a fd-passing operation behaves like `dup(2)` of the
        // sender's view — a write-only fd stays write-only, a
        // nonzero-offset regular file lands at the same offset.
        // FD_CLOEXEC is decided by the receiver's MSG_CMSG_CLOEXEC
        // flag (cleared by default) regardless of the sender's bit,
        // matching Linux's `recvmsg(2)` semantics.
        for inf in ready.iter().take(keep_n) {
            let new_entry = FdEntry {
                backend: inf.backend.clone(),
                offset: inf.offset,
                readable: inf.readable,
                writable: inf.writable,
                cloexec: cmsg_cloexec,
                nonblock: inf.nonblock,
            };
            match alloc_fd(0, new_entry) {
                Some(fd) => new_fds.push(fd as i32),
                None => {
                    // Out of fds — release this inflight; keep_n
                    // effectively shrinks for the trailing release loop.
                    release_inflight_anc_backend(&inf.backend);
                    ctrunc = true;
                }
            }
        }

        // Drop refcounts on the truncated tail.
        for inf in ready.iter().skip(keep_n) {
            release_inflight_anc_backend(&inf.backend);
        }

        // Encode the outgoing cmsg into a kernel buffer first.  Only
        // commit it to the user control buffer once we have proof we
        // can write back the updated msghdr too — otherwise an EFAULT
        // on copy-back leaves the receiver with installed fds it
        // never learned about.
        if !new_fds.is_empty() {
            let space = cmsg_space(new_fds.len() * 4);
            let mut cmsg_buf = alloc::vec![0u8; space];
            let n_enc = encode_scm_rights(&mut cmsg_buf, &new_fds).unwrap_or(0);
            if n_enc > 0 {
                let user_control_ok = UserSliceWo::new(header.msg_control, n_enc)
                    .and_then(|s| s.copy_from_kernel(&cmsg_buf[..n_enc]))
                    .is_ok();
                if !user_control_ok {
                    // Roll back: close every installed fd and surface
                    // EFAULT, leaving no orphan fds in the receiver.
                    for fd in &new_fds {
                        let _ = sys_linux_close(*fd as u64);
                    }
                    return NEG_EFAULT;
                }
                control_bytes_written = n_enc;
            }
        }
    }

    // 7. Write back the updated msghdr (controllen + flags).
    //
    // Phase 69d follow-up (PR #177 third-pass review fix): `msg_flags`
    // is an OUTPUT field on recvmsg.  Linux's man page is explicit:
    // "msg_flags is set on return".  Previously we preserved whatever
    // bits the caller had set in the input header and only toggled
    // MSG_CTRUNC, so a caller that reused a non-zero input header
    // would observe phantom flags (e.g. a stale MSG_OOB bit).  Reset
    // to 0 first and OR in only the conditions this recv actually
    // produced.
    header.msg_controllen = control_bytes_written as u64;
    header.msg_flags = 0;
    if ctrunc {
        header.msg_flags |= MSG_CTRUNC;
    }
    let encoded = header.encode();
    if UserSliceWo::new(msghdr_ptr, encoded.len())
        .and_then(|s| s.copy_from_kernel(&encoded))
        .is_err()
    {
        // Same rollback as the cmsg copy-back failure path so the
        // receiver doesn't end up with installed fds it can't see.
        for fd in &new_fds {
            let _ = sys_linux_close(*fd as u64);
        }
        return NEG_EFAULT;
    }

    n as u64
}

// ---------------------------------------------------------------------------
// Phase 37: I/O multiplexing helpers
// ---------------------------------------------------------------------------

const POLLIN: i16 = 0x001;
const POLLOUT: i16 = 0x004;
const POLLERR: i16 = 0x008;
const POLLHUP: i16 = 0x010;
const POLLNVAL: i16 = 0x020;
// Phase 86d Track B — peer half-close (read side hung up). Value matches Linux
// POLLRDHUP/EPOLLRDHUP (0x2000) so the bit survives the `as u16 as u32`
// widening in epoll_wait and maps straight onto EPOLLRDHUP.
const POLLRDHUP: i16 = 0x2000;

/// Query current readiness events for a file descriptor.
///
/// Returns a bitmask of POLLIN/POLLOUT/POLLHUP/POLLERR/POLLNVAL.
fn fd_poll_events(entry: &FdEntry) -> i16 {
    match &entry.backend {
        FdBackend::PipeRead { pipe_id } => {
            // Side-effect-free readiness check.
            let mut revents: i16 = 0;
            // POLLHUP when writer has closed (even if data remains in buffer).
            if crate::pipe::pipe_writer_closed(*pipe_id) {
                revents |= POLLHUP;
            }
            match crate::pipe::pipe_read_ready(*pipe_id) {
                Some(true) => revents |= POLLIN,
                Some(false) => {}
                None => revents |= POLLHUP,
            }
            revents
        }
        FdBackend::PipeWrite { pipe_id } => {
            // Side-effect-free writability check.
            match crate::pipe::pipe_write_ready(*pipe_id) {
                Some(true) => POLLOUT,     // writable
                Some(false) => 0,          // full but reader alive
                None => POLLERR | POLLHUP, // reader closed (EPIPE)
            }
        }
        FdBackend::EventFd { id } => {
            // Phase 86d Track D — eventfd readiness: POLLIN when the counter is
            // non-zero, POLLOUT when it is below the cap (effectively always).
            // This drives Go's netpoll epoll wakeup on `netpollBreak` writes.
            if !crate::eventfd::eventfd_exists(*id) {
                // The object was freed out from under us (last fd closed while a
                // peer was blocked here). Report a terminal "readable + hung up
                // + error" so every waiter type gets a ready event and exits
                // instead of spinning:
                //   - POLLIN  — a freed eventfd is at EOF (a `read` returns 0),
                //     so it is "readable"; this is what `select`'s readfds arm
                //     keys on (it only sets the read bit on POLLIN), mirroring
                //     the PipeRead closed-writer path where `pipe_read_ready`
                //     reports EOF as readable.
                //   - POLLHUP — drives `poll`/`epoll_wait`, which pass HUP/ERR
                //     through unconditionally regardless of the interest mask
                //     (POLLNVAL would be masked out by poll's filter).
                //   - POLLERR — drives `select`'s exceptfds arm.
                return POLLIN | POLLHUP | POLLERR;
            }
            let mut revents: i16 = 0;
            if crate::eventfd::eventfd_readable(*id) {
                revents |= POLLIN;
            }
            if crate::eventfd::eventfd_writable(*id) {
                revents |= POLLOUT;
            }
            revents
        }
        FdBackend::TimerFd { id } => {
            // Phase 89 Track A.1 — timerfd readiness: POLLIN once the timer has
            // fired (level-triggered while expirations remain; the epoll ET
            // watermark handles edge mode). Never writable. A freed object
            // reports a terminal event so blocked waiters exit (mirrors eventfd).
            if !crate::timerfd::timerfd_exists(*id) {
                return POLLIN | POLLHUP | POLLERR;
            }
            if crate::timerfd::timerfd_readable(*id) {
                POLLIN
            } else {
                0
            }
        }
        FdBackend::DeviceTTY { .. } | FdBackend::Stdin => {
            let mut revents: i16 = 0;
            if entry.readable && crate::stdin::has_data() {
                revents |= POLLIN;
            }
            if entry.writable {
                revents |= POLLOUT;
            }
            revents
        }
        FdBackend::Socket { handle } => {
            let h = *handle;
            // Phase 86b — promote a completed non-blocking connect
            // (Connecting → Connected) before computing readiness, so the
            // writable check below reports POLLOUT on connect success. A failed
            // connect stays Connecting with a Closed slot and is surfaced as
            // POLLOUT|POLLERR (see the writable + RST branches below).
            crate::net::reconcile_connecting(h);
            crate::net::with_socket(h, |s| {
                let mut revents: i16 = 0;
                let readable = match s.protocol {
                    crate::net::SocketProtocol::Tcp => {
                        if let Some(tcp_idx) = s.tcp_slot {
                            if matches!(s.state, crate::net::SocketState::Listening) {
                                matches!(
                                    crate::net::tcp::state(tcp_idx),
                                    crate::net::tcp::TcpState::Established
                                        | crate::net::tcp::TcpState::CloseWait
                                )
                            } else {
                                crate::net::tcp::has_recv_data(tcp_idx)
                                    || matches!(
                                        crate::net::tcp::state(tcp_idx),
                                        crate::net::tcp::TcpState::CloseWait
                                            | crate::net::tcp::TcpState::Closed
                                            | crate::net::tcp::TcpState::TimeWait
                                    )
                            }
                        } else {
                            false
                        }
                    }
                    crate::net::SocketProtocol::Udp => crate::net::udp::has_data(s.local_port),
                    crate::net::SocketProtocol::Icmp => crate::net::icmp::PING_REPLY_RECEIVED
                        .load(core::sync::atomic::Ordering::Acquire),
                };
                let writable = match s.protocol {
                    crate::net::SocketProtocol::Tcp => match s.tcp_slot {
                        // Connected (incl. a just-promoted non-blocking connect)
                        // is writable. A socket still Connecting whose slot has
                        // gone Closed is a *failed* connect — POSIX makes it
                        // writable so the caller's select(writefds) wakes and
                        // reads SO_ERROR. A slot still in SynSent is not writable.
                        Some(idx) => {
                            matches!(s.state, crate::net::SocketState::Connected)
                                || (matches!(s.state, crate::net::SocketState::Connecting)
                                    && matches!(
                                        crate::net::tcp::state(idx),
                                        crate::net::tcp::TcpState::Closed
                                    ))
                        }
                        None => false,
                    },
                    _ => true,
                };
                if readable {
                    revents |= POLLIN;
                }
                if writable {
                    revents |= POLLOUT;
                }
                if matches!(s.state, crate::net::SocketState::Closed) {
                    revents |= POLLHUP;
                }
                // Phase 86d Track B — EPOLLRDHUP: the peer has shut down its
                // writing half (we received a FIN), so the read side is done.
                // Go's netpoll registers EPOLLRDHUP to learn of remote close.
                // Derived from the connection's half-close state; only surfaced
                // to callers that requested POLLRDHUP (poll masks by `events`,
                // select ignores it, epoll matches it against the interest).
                if let Some(tcp_idx) = s.tcp_slot
                    && !matches!(s.state, crate::net::SocketState::Listening)
                    && matches!(
                        crate::net::tcp::state(tcp_idx),
                        crate::net::tcp::TcpState::CloseWait
                            | crate::net::tcp::TcpState::LastAck
                            | crate::net::tcp::TcpState::TimeWait
                            | crate::net::tcp::TcpState::Closed
                    )
                {
                    revents |= POLLRDHUP;
                }
                // TCP RST → POLLERR
                if let Some(tcp_idx) = s.tcp_slot
                    && matches!(
                        crate::net::tcp::state(tcp_idx),
                        crate::net::tcp::TcpState::Closed
                    )
                    && !matches!(
                        s.state,
                        crate::net::SocketState::Closed | crate::net::SocketState::Listening
                    )
                {
                    revents |= POLLERR;
                }
                revents
            })
            .unwrap_or(POLLNVAL)
        }
        FdBackend::PtyMaster { pty_id } => {
            let id = *pty_id;
            let table = crate::pty::PTY_TABLE.lock();
            if let Some(Some(pair)) = table.get(id as usize) {
                let mut revents: i16 = 0;
                if !pair.s2m.is_empty() {
                    revents |= POLLIN;
                }
                if pair.slave_refcount == 0 && pair.slave_opened {
                    revents |= POLLHUP | POLLIN;
                }
                if !pair.m2s.is_full() {
                    revents |= POLLOUT;
                }
                revents
            } else {
                POLLHUP
            }
        }
        FdBackend::PtySlave { pty_id } => {
            let id = *pty_id;
            let table = crate::pty::PTY_TABLE.lock();
            if let Some(Some(pair)) = table.get(id as usize) {
                let mut revents: i16 = 0;
                if pair.termios.is_canonical() {
                    if pair.edit_buf.as_slice().contains(&b'\n') || pair.eof_pending {
                        revents |= POLLIN;
                    }
                } else if !pair.m2s.is_empty() {
                    revents |= POLLIN;
                }
                if pair.master_refcount == 0 {
                    revents |= POLLHUP | POLLIN;
                }
                if !pair.s2m.is_full() {
                    revents |= POLLOUT;
                }
                revents
            } else {
                POLLHUP
            }
        }
        FdBackend::Stdout => POLLOUT,
        FdBackend::DevNull => POLLIN | POLLOUT,
        FdBackend::Proc { path } => {
            // `/proc/kmsg` is a live stream: readable only while this fd's
            // cursor is behind the dmesg write position. Reporting always-ready
            // here (as the old snapshot model did) made poll() loops spin at
            // 100% CPU once the stream was drained. Proc fds are read-only, so
            // no POLLOUT. Other procfs files regenerate on read and stay
            // effectively always-ready.
            if path == "/proc/kmsg" {
                if (entry.offset as u64) < crate::serial::dmesg_total_written() {
                    POLLIN
                } else {
                    0
                }
            } else {
                POLLIN | POLLOUT
            }
        }
        FdBackend::DevZero
        | FdBackend::DevUrandom
        | FdBackend::DevFull
        | FdBackend::Ramdisk { .. }
        | FdBackend::Tmpfs { .. }
        | FdBackend::Fat32Disk { .. }
        | FdBackend::Ext2Disk { .. }
        | FdBackend::Dir { .. } => POLLIN | POLLOUT,
        FdBackend::UnixSocket { handle } => {
            let h = *handle;
            // Extract socket info under the lock, then check peer separately
            // to avoid nested lock acquisition (deadlock).
            //
            // `anc_ready` covers zero-byte SCM_RIGHTS messages: the
            // sender wrote 0 bytes plus a non-empty cmsg, the wake
            // fired once, and an event loop that polls before
            // calling `recvmsg` would otherwise see `recv_buf` empty,
            // report no POLLIN, and miss the only wake.
            let info = crate::net::unix::with_unix_socket(h, |s| {
                let anc_ready = s
                    .anc_queue
                    .front()
                    .map(|inf| inflight_is_deliverable(inf, s.stream_pos_consumed))
                    .unwrap_or(false);
                (
                    s.socket_type,
                    s.state,
                    s.peer,
                    !s.recv_buf.is_empty(),
                    !s.backlog.is_empty(),
                    !s.dgram_queue.is_empty(),
                    s.shut_rd,
                    anc_ready,
                )
            });
            match info {
                Some((
                    sock_type,
                    state,
                    peer,
                    has_data,
                    has_backlog,
                    has_dgram,
                    shut_rd,
                    anc_ready,
                )) => {
                    let mut revents: i16 = 0;
                    match sock_type {
                        crate::net::unix::UnixSocketType::Stream => {
                            if has_data || anc_ready {
                                revents |= POLLIN;
                            }
                            if matches!(state, crate::net::unix::UnixSocketState::Listening)
                                && has_backlog
                            {
                                revents |= POLLIN;
                            }
                            if let Some(peer_h) = peer {
                                let peer_has_space =
                                    crate::net::unix::with_unix_socket(peer_h, |ps| {
                                        ps.recv_buf.len() < crate::net::unix::UNIX_STREAM_BUF_SIZE
                                    });
                                if peer_has_space.unwrap_or(false) {
                                    revents |= POLLOUT;
                                }
                                if peer_has_space.is_none() {
                                    revents |= POLLHUP; // peer freed
                                }
                            } else if matches!(state, crate::net::unix::UnixSocketState::Connected)
                            {
                                revents |= POLLHUP;
                            }
                        }
                        crate::net::unix::UnixSocketType::Datagram => {
                            if has_dgram {
                                revents |= POLLIN;
                            }
                            // Datagram writability is not determined by the local
                            // receive queue — always report writable.
                            revents |= POLLOUT;
                        }
                    }
                    if shut_rd {
                        revents |= POLLIN;
                    }
                    if matches!(state, crate::net::unix::UnixSocketState::Closed) {
                        revents |= POLLHUP;
                    }
                    revents
                }
                None => POLLNVAL,
            }
        }
        FdBackend::Epoll { .. } => 0, // epoll FDs not themselves pollable
        FdBackend::VfsService { .. } => POLLIN, // always readable
    }
}

/// Register the current task on the wait queue(s) of a file descriptor.
///
/// Uses `WaitQueue::register()` to add the task without blocking, allowing
/// registration on multiple queues before a single block call.
/// Returns `true` if a wait queue was registered, `false` for non-pollable types.
fn fd_register_waiter(
    entry: &FdEntry,
    task_id: crate::task::TaskId,
    woken: &alloc::sync::Arc<core::sync::atomic::AtomicBool>,
) -> bool {
    match &entry.backend {
        FdBackend::PipeRead { pipe_id } | FdBackend::PipeWrite { pipe_id } => {
            let wqs = crate::pipe::PIPE_WAITQUEUES.lock();
            if let Some(Some(wq)) = wqs.get(*pipe_id) {
                wq.register(task_id, woken);
                return true;
            }
            false
        }
        FdBackend::EventFd { id } => crate::eventfd::eventfd_register_waiter(*id, task_id, woken),
        FdBackend::TimerFd { id } => crate::timerfd::timerfd_register_waiter(*id, task_id, woken),
        FdBackend::DeviceTTY { .. } | FdBackend::Stdin => {
            crate::stdin::STDIN_WAITQUEUE.register(task_id, woken);
            true
        }
        FdBackend::Socket { handle } => {
            crate::net::SOCKET_WAITQUEUES[*handle as usize].register(task_id, woken);
            true
        }
        FdBackend::UnixSocket { handle } => {
            crate::net::unix::UNIX_SOCKET_WAITQUEUES[*handle].register(task_id, woken);
            true
        }
        FdBackend::PtyMaster { pty_id } => {
            crate::pty::PTY_MASTER_WQ[*pty_id as usize].register(task_id, woken);
            true
        }
        FdBackend::PtySlave { pty_id } => {
            crate::pty::PTY_SLAVE_WQ[*pty_id as usize].register(task_id, woken);
            true
        }
        _ => false, // non-pollable types (ramdisk, tmpfs, etc.)
    }
}

/// Deregister the current task from all wait queues it was registered on.
fn fd_deregister_waiter(entry: &FdEntry, task_id: crate::task::TaskId) {
    match &entry.backend {
        FdBackend::PipeRead { pipe_id } | FdBackend::PipeWrite { pipe_id } => {
            let wqs = crate::pipe::PIPE_WAITQUEUES.lock();
            if let Some(Some(wq)) = wqs.get(*pipe_id) {
                wq.deregister(task_id);
            }
        }
        FdBackend::DeviceTTY { .. } | FdBackend::Stdin => {
            crate::stdin::STDIN_WAITQUEUE.deregister(task_id);
        }
        FdBackend::Socket { handle } => {
            crate::net::SOCKET_WAITQUEUES[*handle as usize].deregister(task_id);
        }
        FdBackend::UnixSocket { handle } => {
            crate::net::unix::UNIX_SOCKET_WAITQUEUES[*handle].deregister(task_id);
        }
        FdBackend::PtyMaster { pty_id } => {
            crate::pty::PTY_MASTER_WQ[*pty_id as usize].deregister(task_id);
        }
        FdBackend::PtySlave { pty_id } => {
            crate::pty::PTY_SLAVE_WQ[*pty_id as usize].deregister(task_id);
        }
        FdBackend::EventFd { id } => crate::eventfd::eventfd_deregister_waiter(*id, task_id),
        FdBackend::TimerFd { id } => crate::timerfd::timerfd_deregister_waiter(*id, task_id),
        _ => {}
    }
}

/// Nearest armed-timerfd next-expiry tick among `entries[..nfds]`, for clamping a
/// `poll`/`select` block deadline (Phase 89 Track A.1). `None` when none is
/// armed-and-pending — an already-expired timerfd is readable, so the poll
/// returns without blocking and needs no clamp.
fn nearest_timerfd_deadline_entries(entries: &[Option<FdEntry>], nfds: usize) -> Option<u64> {
    let mut nearest: Option<u64> = None;
    for entry in entries.iter().take(nfds).flatten() {
        if let FdBackend::TimerFd { id } = &entry.backend
            && let Some(d) = crate::timerfd::timerfd_next_expiry_tick(*id)
        {
            nearest = Some(nearest.map_or(d, |m| m.min(d)));
        }
    }
    nearest
}

/// Nearest armed-timerfd next-expiry tick among the given fds — `epoll_wait`
/// tracks interest fds rather than `FdEntry`s, so it resolves each fd fresh.
fn nearest_timerfd_deadline_fds(fds: impl Iterator<Item = usize>) -> Option<u64> {
    let mut nearest: Option<u64> = None;
    for fd in fds {
        if let Some(entry) = current_fd_entry(fd)
            && let FdBackend::TimerFd { id } = &entry.backend
            && let Some(d) = crate::timerfd::timerfd_next_expiry_tick(*id)
        {
            nearest = Some(nearest.map_or(d, |m| m.min(d)));
        }
    }
    nearest
}

/// Clamp a `poll`/`epoll_wait` user block deadline to the nearest armed-timerfd
/// expiry — whichever is first. This is what lets a blocked (including
/// indefinite, `timeout == -1`) waiter wake when a timerfd fires: the scheduler's
/// IRQ-safe `wake_deadline` scanner fires at the clamped deadline, the waiter
/// re-scans, and finds the timerfd readable. A timerfd cannot signal its wait
/// queue from the timer ISR (`WaitQueue::wake_all` is task-context only).
fn clamp_block_deadline(user: Option<u64>, timerfd: Option<u64>) -> Option<u64> {
    match (user, timerfd) {
        (Some(a), Some(b)) => Some(a.min(b)),
        (Some(a), None) => Some(a),
        (None, t) => t,
    }
}

// ---------------------------------------------------------------------------
// Phase 37: poll(fds, nfds, timeout) — syscall 7
// ---------------------------------------------------------------------------

/// poll(fds, nfds, timeout) — wait-queue-driven I/O readiness notification.
///
/// Phase 37 rewrite: uses per-FD wait queues instead of busy-wait yield loop.
/// The task blocks via WaitQueue until an FD becomes ready or timeout expires.
#[allow(clippy::needless_range_loop)]
pub(super) fn sys_poll(fds_ptr: u64, nfds: u64, timeout: u64) -> u64 {
    let nfds = nfds as usize;
    if nfds > 256 {
        return NEG_EINVAL;
    }
    let timeout_i = timeout as i64;
    // Convert ms timeout to tick deadline.
    // TICKS_PER_SEC = 1000, so 1 tick = 1 ms: deadline = start + timeout_ms (no ÷10).
    // The old `(timeout_i as u64).div_ceil(10)` assumed a 100 Hz timer — G.3 fix.
    let start_tick = crate::arch::x86_64::interrupts::tick_count();
    let deadline_tick = if timeout_i > 0 {
        Some(start_tick + (timeout_i as u64)) // 1 tick = 1 ms; no divisor needed
    } else {
        None // 0 = non-blocking, -1 = indefinite
    };

    // Read all pollfd structs from userspace once.
    let mut pfds = [[0u8; 8]; 256];
    for i in 0..nfds {
        let base = match fds_ptr.checked_add((i * 8) as u64) {
            Some(a) => a,
            None => return NEG_EFAULT,
        };
        if UserSliceRo::new(base, pfds[i].len())
            .and_then(|s| s.copy_to_kernel(&mut pfds[i]))
            .is_err()
        {
            return NEG_EFAULT;
        }
    }

    // Collect FD entries for wait queue registration.
    let mut entries: [Option<FdEntry>; 256] = [const { None }; 256];
    for i in 0..nfds {
        let fd = i32::from_ne_bytes([pfds[i][0], pfds[i][1], pfds[i][2], pfds[i][3]]);
        if fd >= 0 && (fd as usize) < MAX_FDS {
            entries[i] = current_fd_entry(fd as usize);
        }
    }

    // Phase 69d follow-up: re-register on EVERY loop iteration.
    //
    // The "H8 fix" comment that used to live here claimed wait queues
    // kept registrations across `wake_all`, but they don't:
    // `WaitQueue::wake_all` does `core::mem::take(&mut *q)` and so
    // empties the queue.  When poll waits in a loop and gets
    // multiple spurious wakes (e.g. a Unix socket POLLOUT wake while
    // we're really waiting for a POLLIN), the first wake consumes
    // our entry; subsequent wakes hit an empty queue and the task
    // is silently lost.  Re-registering on every iteration matches
    // the pattern used by pipe_read / unix_stream_read / stdin and
    // is the safe default; the lost-wake-window the old comment
    // worried about is closed by clearing `woken` BEFORE register
    // and scanning AFTER, so a wake firing between register and
    // block sets `woken=true` and `block_current_until` returns
    // immediately.
    let task_id = match crate::task::scheduler::current_task_id() {
        Some(id) => id,
        None => return NEG_EINTR,
    };
    let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));

    // `registered_any` is recomputed each iteration below.
    let mut registered_any;

    let deregister_all = |entries: &[Option<FdEntry>; 256]| {
        for i in 0..nfds {
            if let Some(entry) = &entries[i] {
                fd_deregister_waiter(entry, task_id);
            }
        }
    };

    let result = loop {
        // Phase 69d follow-up (PR #177 review fix): deregister any
        // stale entries left on queues that did NOT wake us before
        // re-registering.  `WaitQueue::wake_all` drains only the
        // queue it fires from; queues we registered on in a previous
        // iteration but that didn't wake still carry our entry, and
        // re-registering would accumulate duplicate waiters on those
        // queues until the syscall finally exits.  The post-register
        // readiness scan still catches a release that fires in the
        // deregister-then-register window.
        deregister_all(&entries);

        // Clear `woken` BEFORE registering so any wake that fires
        // after register sets it to true.
        woken.store(false, core::sync::atomic::Ordering::Release);

        // Re-register on every iteration: `wake_all` consumed any
        // previous registration on queues that woke us; the explicit
        // `deregister_all` above cleared the rest.
        registered_any = false;
        if timeout_i != 0 {
            for i in 0..nfds {
                if let Some(entry) = &entries[i]
                    && fd_register_waiter(entry, task_id, &woken)
                {
                    registered_any = true;
                }
            }
        }

        let mut ready_count = 0u64;

        for i in 0..nfds {
            let events = i16::from_ne_bytes([pfds[i][4], pfds[i][5]]);
            let fd = i32::from_ne_bytes([pfds[i][0], pfds[i][1], pfds[i][2], pfds[i][3]]);
            let mut revents: i16 = 0;

            if fd >= 0 {
                if let Some(entry) = &entries[i] {
                    let ready = fd_poll_events(entry);
                    // Report only events the caller asked for, plus unconditional ones.
                    revents = (ready & events) | (ready & (POLLHUP | POLLERR));
                } else {
                    revents = POLLNVAL;
                }
            }

            if revents != 0 {
                ready_count += 1;
            }
            pfds[i][6..8].copy_from_slice(&revents.to_ne_bytes());
        }

        // Fast path: something ready, non-blocking poll, or timeout expired.
        let timed_out =
            deadline_tick.is_some_and(|d| crate::arch::x86_64::interrupts::tick_count() >= d);
        if ready_count > 0 || timeout_i == 0 || timed_out {
            break ready_count;
        }

        if has_pending_signal() {
            break NEG_EINTR;
        }

        // Block until woken by an FD event or timeout.  If a wake
        // fired between register and now, `woken` is already true and
        // `block_current_until` returns immediately. The deadline is clamped to
        // the nearest armed timerfd expiry (Phase 89 A.1) so a blocked poller
        // wakes when a timerfd fires even on an indefinite (-1) poll — the timer
        // ISR can't signal the timerfd's wait queue.
        let block_deadline = clamp_block_deadline(
            deadline_tick,
            nearest_timerfd_deadline_entries(&entries, nfds),
        );
        if registered_any || block_deadline.is_some() {
            let _ = crate::task::scheduler::block_current_until(
                crate::task::TaskState::BlockedOnRecv,
                &woken,
                block_deadline,
            );
        } else {
            crate::task::yield_now();
        }
    };

    deregister_all(&entries);

    // Write results back to userspace.
    if result != NEG_EINTR {
        for i in 0..nfds {
            let base = match fds_ptr.checked_add((i * 8) as u64) {
                Some(a) => a,
                None => return NEG_EFAULT,
            };
            if UserSliceWo::new(base, pfds[i].len())
                .and_then(|s| s.copy_from_kernel(&pfds[i]))
                .is_err()
            {
                return NEG_EFAULT;
            }
        }
    }

    result
}

// ---------------------------------------------------------------------------
// Phase 37: select(nfds, readfds, writefds, exceptfds, timeout) — syscall 23
// ---------------------------------------------------------------------------

/// Read an fd_set bitmap from userspace. Returns a 32-bit mask (one bit per FD).
fn read_fd_set(ptr: u64, nfds: usize) -> Result<u32, u64> {
    if ptr == 0 {
        return Ok(0);
    }
    // fd_set is 128 bytes (1024 bits). We only need the first 4 bytes (32 FDs).
    let mut buf = [0u8; 4];
    if UserSliceRo::new(ptr, buf.len())
        .and_then(|s| s.copy_to_kernel(&mut buf))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    let mask = u32::from_ne_bytes(buf);
    // Clear bits beyond nfds. Handle nfds >= 32 without shift overflow.
    let keep = if nfds >= 32 {
        u32::MAX
    } else {
        (1u32 << nfds) - 1
    };
    Ok(mask & keep)
}

/// Write an fd_set bitmap back to userspace.
fn write_fd_set(ptr: u64, mask: u32) -> Result<(), u64> {
    if ptr == 0 {
        return Ok(());
    }
    // Zero the entire 128-byte fd_set, then write our 4 bytes.
    let zero = [0u8; 128];
    if UserSliceWo::new(ptr, zero.len())
        .and_then(|s| s.copy_from_kernel(&zero))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    let buf = mask.to_ne_bytes();
    if UserSliceWo::new(ptr, buf.len())
        .and_then(|s| s.copy_from_kernel(&buf))
        .is_err()
    {
        return Err(NEG_EFAULT);
    }
    Ok(())
}

/// select(nfds, readfds, writefds, exceptfds, timeout) — syscall 23
pub(super) fn sys_select(
    nfds: u64,
    readfds_ptr: u64,
    writefds_ptr: u64,
    exceptfds_ptr: u64,
    timeout_ptr: u64,
) -> u64 {
    // Parse timeval timeout: NULL = block indefinitely, {0,0} = non-blocking.
    let timeout_ms: Option<u64> = if timeout_ptr == 0 {
        None
    } else {
        let mut tv = [0u8; 16]; // struct timeval: tv_sec (8) + tv_usec (8)
        if UserSliceRo::new(timeout_ptr, tv.len())
            .and_then(|s| s.copy_to_kernel(&mut tv))
            .is_err()
        {
            return NEG_EFAULT;
        }
        let sec = i64::from_ne_bytes(tv[0..8].try_into().unwrap());
        let usec = i64::from_ne_bytes(tv[8..16].try_into().unwrap());
        if sec < 0 || !(0..1_000_000).contains(&usec) {
            return NEG_EINVAL;
        }
        Some(sec as u64 * 1000 + usec as u64 / 1000)
    };
    select_inner(nfds, readfds_ptr, writefds_ptr, exceptfds_ptr, timeout_ms)
}

/// Shared select implementation used by both select() and pselect6().
#[allow(clippy::needless_range_loop)]
fn select_inner(
    nfds: u64,
    readfds_ptr: u64,
    writefds_ptr: u64,
    exceptfds_ptr: u64,
    timeout_ms: Option<u64>,
) -> u64 {
    let nfds = (nfds as usize).min(MAX_FDS);

    // Read fd_set bitmaps.
    let read_mask = match read_fd_set(readfds_ptr, nfds) {
        Ok(m) => m,
        Err(e) => return e,
    };
    let write_mask = match read_fd_set(writefds_ptr, nfds) {
        Ok(m) => m,
        Err(e) => return e,
    };
    let except_mask = match read_fd_set(exceptfds_ptr, nfds) {
        Ok(m) => m,
        Err(e) => return e,
    };
    let start_tick = crate::arch::x86_64::interrupts::tick_count();
    // TICKS_PER_SEC = 1000, so 1 tick = 1 ms: deadline = start + timeout_ms (no ÷10).
    // The old `ms.div_ceil(10)` assumed a 100 Hz timer — G.3 fix.
    let deadline_tick = timeout_ms.filter(|&ms| ms > 0).map(|ms| start_tick + ms); // 1 tick = 1 ms; no divisor needed
    let nonblocking = timeout_ms == Some(0);

    let combined = read_mask | write_mask | except_mask;
    if combined == 0 && nonblocking {
        // No FDs and non-blocking → return immediately.
        return 0;
    }

    // Collect FD entries.
    let mut entries: [Option<FdEntry>; 32] = [const { None }; 32];
    for fd in 0..nfds {
        if combined & (1 << fd) != 0 {
            entries[fd] = current_fd_entry(fd);
        }
    }

    loop {
        let mut r_out: u32 = 0;
        let mut w_out: u32 = 0;
        let mut e_out: u32 = 0;

        for fd in 0..nfds {
            let bit = 1u32 << fd;
            if combined & bit == 0 {
                continue;
            }
            if let Some(entry) = &entries[fd] {
                let ready = fd_poll_events(entry);
                if read_mask & bit != 0 && ready & POLLIN != 0 {
                    r_out |= bit;
                }
                if write_mask & bit != 0 && ready & POLLOUT != 0 {
                    w_out |= bit;
                }
                if except_mask & bit != 0 && ready & POLLERR != 0 {
                    e_out |= bit;
                }
            } else {
                return NEG_EBADF;
            }
        }

        let total = (r_out.count_ones() + w_out.count_ones() + e_out.count_ones()) as u64;

        let timed_out =
            deadline_tick.is_some_and(|d| crate::arch::x86_64::interrupts::tick_count() >= d);
        if total > 0 || nonblocking || timed_out {
            // Write results back.
            if let Err(e) = write_fd_set(readfds_ptr, r_out) {
                return e;
            }
            if let Err(e) = write_fd_set(writefds_ptr, w_out) {
                return e;
            }
            if let Err(e) = write_fd_set(exceptfds_ptr, e_out) {
                return e;
            }
            return total;
        }

        if has_pending_signal() {
            return NEG_EINTR;
        }

        // Block on wait queues.
        let task_id = match crate::task::scheduler::current_task_id() {
            Some(id) => id,
            None => return NEG_EINTR,
        };
        let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
        let mut registered_any = false;
        for fd in 0..nfds {
            if let Some(entry) = &entries[fd]
                && combined & (1 << fd) != 0
                && fd_register_waiter(entry, task_id, &woken)
            {
                registered_any = true;
            }
        }

        if !registered_any {
            crate::task::yield_now();
            continue;
        }

        // Re-check readiness after registration to close the TOCTOU window.
        let mut any_ready = false;
        for fd in 0..nfds {
            if let Some(entry) = &entries[fd]
                && combined & (1 << fd) != 0
            {
                let ready = fd_poll_events(entry);
                if (ready & POLLIN) != 0
                    || (ready & POLLOUT) != 0
                    || (ready & (POLLHUP | POLLERR)) != 0
                {
                    any_ready = true;
                    break;
                }
            }
        }
        if any_ready {
            for fd in 0..nfds {
                if let Some(entry) = &entries[fd]
                    && combined & (1 << fd) != 0
                {
                    fd_deregister_waiter(entry, task_id);
                }
            }
            continue;
        }

        // F.4: Under sched-v2, use block_current_until for both timeout branches:
        // positive timeout passes deadline_tick; indefinite passes None.
        // Under v1, retain yield_now() for positive timeout and
        // block_current_unless_woken for indefinite timeout.
        {
            let _ = crate::task::scheduler::block_current_until(
                crate::task::TaskState::BlockedOnRecv,
                &woken,
                deadline_tick,
            );
            for fd in 0..nfds {
                if let Some(entry) = &entries[fd]
                    && combined & (1 << fd) != 0
                {
                    fd_deregister_waiter(entry, task_id);
                }
            }
        }
    }
}

/// pselect6(nfds, readfds, writefds, exceptfds, timeout, sigmask_ptr) — syscall 270
///
/// Modern variant of select with timespec timeout and signal mask.
/// Signal mask is accepted but not applied (no signal masking yet).
pub(super) fn sys_pselect6(
    nfds: u64,
    readfds_ptr: u64,
    writefds_ptr: u64,
    exceptfds_ptr: u64,
    timeout_ptr: u64,
) -> u64 {
    // pselect6 uses timespec {tv_sec, tv_nsec}. Parse to timeout_ms without
    // mutating user memory. The 6th arg (sigmask) is ignored.
    let timeout_ms: Option<u64> = if timeout_ptr != 0 {
        let mut ts = [0u8; 16];
        if UserSliceRo::new(timeout_ptr, ts.len())
            .and_then(|s| s.copy_to_kernel(&mut ts))
            .is_err()
        {
            return NEG_EFAULT;
        }
        let sec = i64::from_ne_bytes(ts[0..8].try_into().unwrap());
        let nsec = i64::from_ne_bytes(ts[8..16].try_into().unwrap());
        if sec < 0 || !(0..1_000_000_000).contains(&nsec) {
            return NEG_EINVAL;
        }
        Some(sec as u64 * 1000 + nsec as u64 / 1_000_000)
    } else {
        None // block indefinitely
    };
    select_inner(nfds, readfds_ptr, writefds_ptr, exceptfds_ptr, timeout_ms)
}

// ---------------------------------------------------------------------------
// Phase 37: epoll interface — syscalls 291, 233, 232
// ---------------------------------------------------------------------------

const MAX_EPOLL_INSTANCES: usize = 16;
const MAX_EPOLL_INTEREST: usize = 32;

#[allow(dead_code)]
const EPOLLIN: u32 = 0x001;
#[allow(dead_code)]
const EPOLLOUT: u32 = 0x004;
const EPOLLERR: u32 = 0x008;
const EPOLLHUP: u32 = 0x010;
// Phase 86d Track B — peer half-close + edge-triggered / one-shot control bits.
// EPOLLRDHUP mirrors POLLRDHUP (0x2000). EPOLLET (1<<31) and EPOLLONESHOT
// (1<<30) are carried in the events word but are NOT readiness bits, so they
// are stripped before matching against fd readiness.
const EPOLLRDHUP: u32 = 0x2000;
// The RDHUP bit flows from `fd_poll_events` (an `i16` POLLRDHUP) through the
// `as u16 as u32` widening in `sys_epoll_wait` and must land exactly on
// EPOLLRDHUP. Assert that numeric coincidence at compile time so the two
// constants can never silently drift apart (and so EPOLLRDHUP is not dead).
const _: () = assert!(EPOLLRDHUP == POLLRDHUP as u16 as u32);
const EPOLLONESHOT: u32 = 0x4000_0000;
const EPOLLET: u32 = 0x8000_0000;
const EPOLL_CONTROL_BITS: u32 = EPOLLET | EPOLLONESHOT;
// Always-reported bits: surfaced even if the interest did not request them.
const EPOLL_UNCONDITIONAL: u32 = EPOLLHUP | EPOLLERR;

const EPOLL_CTL_ADD: u64 = 1;
const EPOLL_CTL_DEL: u64 = 2;
const EPOLL_CTL_MOD: u64 = 3;

const EPOLL_CLOEXEC: u64 = 0x80000;

/// An entry in the epoll interest list: which FD to monitor and for what events.
#[derive(Clone)]
struct EpollInterest {
    fd: usize,
    events: u32,
    data: u64,
    /// Phase 86d Track B — for edge-triggered (`EPOLLET`) interests, the
    /// readiness set last reported to userspace. An edge event fires only when
    /// the current readiness rises above this watermark (not-ready→ready). The
    /// watermark is refreshed every `epoll_wait` scan so a drain lowers it and
    /// a refill re-triggers. Unused for level-triggered interests. Per-interest
    /// (not per-fd): the same fd in two epoll instances tracks edges
    /// independently.
    last_ready: u32,
}

/// An epoll instance — tracks the interest set (which FDs to monitor).
/// Blocking in epoll_wait is done by registering on monitored FDs' wait queues.
struct EpollInstance {
    interests: alloc::vec::Vec<EpollInterest>,
    refcount: u32,
    owner_pid: crate::process::Pid,
}

impl EpollInstance {
    fn new(pid: crate::process::Pid) -> Self {
        Self {
            interests: alloc::vec::Vec::new(),
            refcount: 1,
            owner_pid: pid,
        }
    }
}

/// Phase 57b G.6 — `IrqSafeMutex` inherits Track F.1's preempt-discipline.
/// Acquired only from task context (epoll_create/ctl/wait + close-on-exec).
static EPOLL_TABLE: crate::task::scheduler::IrqSafeMutex<
    [Option<EpollInstance>; MAX_EPOLL_INSTANCES],
> = {
    const NONE: Option<EpollInstance> = None;
    crate::task::scheduler::IrqSafeMutex::new([NONE; MAX_EPOLL_INSTANCES])
};

// Phase 66 Track D.2 — `epoll_free_pub` body has moved to
// `kernel/src/epoll.rs`. The decrement helper is exposed as
// `epoll_free_internal` so the new module can forward to it without
// duplicating the table-locking dance below.

/// Public entry point for epoll_add_ref (called from add_fd_refs on fork/dup).
pub fn epoll_add_ref_pub(instance_id: usize) {
    epoll_add_ref(instance_id);
}

/// Internal: decrement epoll instance refcount; free when it reaches
/// zero. Re-exposed at `pub(crate)` so `kernel/src/epoll.rs` can call it
/// without duplicating the lock dance.
pub(crate) fn epoll_free_internal(instance_id: usize) {
    epoll_free(instance_id);
}

/// Decrement epoll instance refcount; free when it reaches zero.
fn epoll_free(instance_id: usize) {
    let mut table = EPOLL_TABLE.lock();
    if let Some(inst) = table.get_mut(instance_id).and_then(|slot| slot.as_mut()) {
        inst.refcount = inst.refcount.saturating_sub(1);
        if inst.refcount == 0 {
            table[instance_id] = None;
        }
    }
}

/// Increment epoll instance refcount (called on dup/fork).
fn epoll_add_ref(instance_id: usize) {
    let mut table = EPOLL_TABLE.lock();
    if let Some(inst) = table.get_mut(instance_id).and_then(|slot| slot.as_mut()) {
        inst.refcount += 1;
    }
}

/// Remove an FD from epoll interest lists owned by the current process.
fn epoll_remove_fd(fd: usize) {
    let pid = crate::process::current_pid();
    let mut table = EPOLL_TABLE.lock();
    for inst in table.iter_mut().flatten() {
        if inst.owner_pid == pid {
            inst.interests.retain(|i| i.fd != fd);
        }
    }
}

/// epoll_create1(flags) — syscall 291
pub(super) fn sys_epoll_create1(flags: u64) -> u64 {
    // Reject unknown flags.
    if flags & !EPOLL_CLOEXEC != 0 {
        return NEG_EINVAL;
    }
    let cloexec = flags & EPOLL_CLOEXEC != 0;

    // Allocate an instance.
    let pid = crate::process::current_pid();
    let instance_id = {
        let mut table = EPOLL_TABLE.lock();
        let mut found = None;
        for (i, slot) in table.iter_mut().enumerate() {
            if slot.is_none() {
                *slot = Some(EpollInstance::new(pid));
                found = Some(i);
                break;
            }
        }
        match found {
            Some(id) => id,
            None => return NEG_ENOMEM,
        }
    };

    let entry = FdEntry {
        backend: FdBackend::Epoll { instance_id },
        offset: 0,
        readable: true,
        writable: false,
        cloexec,
        nonblock: false,
    };
    match alloc_fd(0, entry) {
        Some(fd) => fd as u64,
        None => {
            epoll_free(instance_id);
            NEG_EMFILE
        }
    }
}

/// eventfd2(initval, flags) — syscall 290. Phase 86d Track D.
///
/// Go 1.21+'s runtime creates an eventfd (`EFD_CLOEXEC | EFD_NONBLOCK`) as its
/// cross-thread M-wakeup primitive. Returns a single fd that is both readable
/// and writable, backed by `crate::eventfd`.
pub(super) fn sys_eventfd2(initval: u64, flags: u64) -> u64 {
    use crate::eventfd::{EFD_CLOEXEC, EFD_KNOWN_FLAGS, EFD_NONBLOCK, EFD_SEMAPHORE};
    if flags & !EFD_KNOWN_FLAGS != 0 {
        return NEG_EINVAL;
    }
    let semaphore = flags & EFD_SEMAPHORE != 0;
    let cloexec = flags & EFD_CLOEXEC != 0;
    let nonblock = flags & EFD_NONBLOCK != 0;

    let id = match crate::eventfd::eventfd_create(initval, semaphore) {
        Some(id) => id,
        None => return NEG_ENOMEM,
    };
    let entry = FdEntry {
        backend: FdBackend::EventFd { id },
        offset: 0,
        readable: true,
        writable: true,
        cloexec,
        nonblock,
    };
    match alloc_fd(0, entry) {
        Some(fd) => fd as u64,
        None => {
            crate::eventfd::eventfd_close(id);
            NEG_EMFILE
        }
    }
}

// ---------------------------------------------------------------------------
// Phase 89 Track A.1 — timerfd_create / timerfd_settime / timerfd_gettime
// ---------------------------------------------------------------------------

/// Current time of `clockid` in nanoseconds, for `TFD_TIMER_ABSTIME`
/// resolution. Monotonic uses the same TSC/tick source as `clock_gettime`.
fn clock_now_nanos(clockid: u32) -> u64 {
    if clockid == crate::timerfd::CLOCK_REALTIME {
        let (s, us) = tsc_now_us();
        s.saturating_mul(1_000_000_000)
            .saturating_add(us.saturating_mul(1_000))
    } else {
        // CLOCK_MONOTONIC / CLOCK_BOOTTIME — elapsed since boot in ns, mirroring
        // the CLOCK_MONOTONIC branch of `sys_clock_gettime`.
        let tsc_per_ms = crate::arch::x86_64::apic::tsc_per_ms();
        if tsc_per_ms == 0 {
            let ticks = crate::arch::x86_64::interrupts::tick_count();
            ticks.saturating_mul(1_000_000_000 / TICKS_PER_SEC)
        } else {
            let boot_tsc = crate::arch::x86_64::apic::boot_tsc();
            let now_tsc = unsafe { core::arch::x86_64::_rdtsc() };
            let elapsed_tsc = now_tsc.wrapping_sub(boot_tsc);
            let elapsed_ms = elapsed_tsc.checked_div(tsc_per_ms).unwrap_or(0);
            let frac_ns = elapsed_tsc
                .checked_rem(tsc_per_ms)
                .and_then(|r| r.checked_mul(1_000_000))
                .and_then(|v| v.checked_div(tsc_per_ms))
                .unwrap_or(0);
            elapsed_ms.saturating_mul(1_000_000).saturating_add(frac_ns)
        }
    }
}

/// timerfd_create(clockid, flags) — syscall 283.
pub(super) fn sys_timerfd_create(clockid: u64, flags: u64) -> u64 {
    use crate::timerfd::{TFD_CLOEXEC, TFD_CREATE_KNOWN_FLAGS, TFD_NONBLOCK};
    let clockid = clockid as u32;
    match clockid {
        crate::timerfd::CLOCK_REALTIME
        | crate::timerfd::CLOCK_MONOTONIC
        | crate::timerfd::CLOCK_BOOTTIME => {}
        _ => return NEG_EINVAL, // CPU-time and other clocks are unsupported
    }
    if flags & !TFD_CREATE_KNOWN_FLAGS != 0 {
        return NEG_EINVAL;
    }
    let cloexec = flags & TFD_CLOEXEC != 0;
    let nonblock = flags & TFD_NONBLOCK != 0;
    let id = match crate::timerfd::timerfd_create(clockid) {
        Some(id) => id,
        None => return NEG_ENOMEM,
    };
    let entry = FdEntry {
        backend: FdBackend::TimerFd { id },
        offset: 0,
        readable: true,
        writable: false,
        cloexec,
        nonblock,
    };
    match alloc_fd(0, entry) {
        Some(fd) => fd as u64,
        None => {
            crate::timerfd::timerfd_close(id);
            NEG_EMFILE
        }
    }
}

/// timerfd_settime(fd, flags, new_value, old_value) — syscall 286.
pub(super) fn sys_timerfd_settime(
    fd: u64,
    flags: u64,
    new_value_ptr: u64,
    old_value_ptr: u64,
) -> u64 {
    use crate::timerfd::{TFD_SETTIME_KNOWN_FLAGS, TFD_TIMER_ABSTIME};
    if flags & !TFD_SETTIME_KNOWN_FLAGS != 0 {
        return NEG_EINVAL;
    }
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let id = match current_fd_entry(fd_idx) {
        Some(e) => match e.backend {
            FdBackend::TimerFd { id } => id,
            _ => return NEG_EINVAL,
        },
        None => return NEG_EBADF,
    };
    if new_value_ptr == 0 {
        return NEG_EFAULT;
    }
    // struct itimerspec: it_interval{sec,nsec} then it_value{sec,nsec} = 32 bytes.
    let mut buf = [0u8; 32];
    if UserSliceRo::new(new_value_ptr, buf.len())
        .and_then(|s| s.copy_to_kernel(&mut buf))
        .is_err()
    {
        return NEG_EFAULT;
    }
    let rd = |o: usize| -> i64 { i64::from_ne_bytes(buf[o..o + 8].try_into().unwrap()) };
    let it_interval_sec = rd(0);
    let it_interval_nsec = rd(8);
    let it_value_sec = rd(16);
    let it_value_nsec = rd(24);
    // Linux rejects out-of-range nanoseconds and negative components with EINVAL.
    if !(0..1_000_000_000).contains(&it_interval_nsec)
        || !(0..1_000_000_000).contains(&it_value_nsec)
        || it_interval_sec < 0
        || it_value_sec < 0
    {
        return NEG_EINVAL;
    }
    let interval_ns = (it_interval_sec as u64)
        .saturating_mul(1_000_000_000)
        .saturating_add(it_interval_nsec as u64);
    let value_ns = (it_value_sec as u64)
        .saturating_mul(1_000_000_000)
        .saturating_add(it_value_nsec as u64);
    let interval_tick = kernel_core::timerfd::ns_to_ticks_ceil(interval_ns);

    let now_tick = crate::arch::x86_64::interrupts::tick_count();
    let (armed, expiry_tick) = if it_value_sec == 0 && it_value_nsec == 0 {
        (false, 0) // it_value == 0 disarms the timer
    } else if flags & TFD_TIMER_ABSTIME != 0 {
        // Absolute deadline on the timer's clock → relative duration → tick
        // deadline. A past deadline yields a 0-duration (fires immediately).
        let clockid =
            crate::timerfd::timerfd_clockid(id).unwrap_or(crate::timerfd::CLOCK_MONOTONIC);
        let dur_ns = value_ns.saturating_sub(clock_now_nanos(clockid));
        (
            true,
            now_tick.saturating_add(kernel_core::timerfd::ns_to_ticks_ceil(dur_ns)),
        )
    } else {
        (
            true,
            now_tick.saturating_add(kernel_core::timerfd::ns_to_ticks_ceil(value_ns)),
        )
    };

    let (old_remaining_tick, old_interval_tick) =
        match crate::timerfd::timerfd_settime(id, armed, expiry_tick, interval_tick) {
            Some(o) => o,
            None => return NEG_EBADF,
        };

    if old_value_ptr != 0 {
        let old_value_ns = kernel_core::timerfd::ticks_to_ns(old_remaining_tick);
        let old_interval_ns = kernel_core::timerfd::ticks_to_ns(old_interval_tick);
        let mut out = [0u8; 32];
        out[0..8].copy_from_slice(&((old_interval_ns / 1_000_000_000) as i64).to_ne_bytes());
        out[8..16].copy_from_slice(&((old_interval_ns % 1_000_000_000) as i64).to_ne_bytes());
        out[16..24].copy_from_slice(&((old_value_ns / 1_000_000_000) as i64).to_ne_bytes());
        out[24..32].copy_from_slice(&((old_value_ns % 1_000_000_000) as i64).to_ne_bytes());
        if UserSliceWo::new(old_value_ptr, out.len())
            .and_then(|s| s.copy_from_kernel(&out))
            .is_err()
        {
            return NEG_EFAULT;
        }
    }
    0
}

/// timerfd_gettime(fd, curr_value) — syscall 287.
pub(super) fn sys_timerfd_gettime(fd: u64, curr_value_ptr: u64) -> u64 {
    let fd_idx = fd as usize;
    if fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let id = match current_fd_entry(fd_idx) {
        Some(e) => match e.backend {
            FdBackend::TimerFd { id } => id,
            _ => return NEG_EINVAL,
        },
        None => return NEG_EBADF,
    };
    if curr_value_ptr == 0 {
        return NEG_EFAULT;
    }
    let (remaining_tick, interval_tick) = match crate::timerfd::timerfd_gettime(id) {
        Some(v) => v,
        None => return NEG_EBADF,
    };
    let value_ns = kernel_core::timerfd::ticks_to_ns(remaining_tick);
    let interval_ns = kernel_core::timerfd::ticks_to_ns(interval_tick);
    let mut out = [0u8; 32];
    out[0..8].copy_from_slice(&((interval_ns / 1_000_000_000) as i64).to_ne_bytes());
    out[8..16].copy_from_slice(&((interval_ns % 1_000_000_000) as i64).to_ne_bytes());
    out[16..24].copy_from_slice(&((value_ns / 1_000_000_000) as i64).to_ne_bytes());
    out[24..32].copy_from_slice(&((value_ns % 1_000_000_000) as i64).to_ne_bytes());
    if UserSliceWo::new(curr_value_ptr, out.len())
        .and_then(|s| s.copy_from_kernel(&out))
        .is_err()
    {
        return NEG_EFAULT;
    }
    0
}

/// epoll_ctl(epfd, op, fd, event_ptr) — syscall 233
pub(super) fn sys_epoll_ctl(epfd: u64, op: u64, fd: u64, event_ptr: u64) -> u64 {
    let epfd_idx = epfd as usize;
    let fd_idx = fd as usize;
    if epfd_idx >= MAX_FDS || fd_idx >= MAX_FDS {
        return NEG_EBADF;
    }

    // Reject adding an epoll FD to itself (Linux returns EINVAL for this).
    if epfd_idx == fd_idx {
        return NEG_EINVAL;
    }

    // Get the epoll instance ID from the FD.
    let instance_id = match current_fd_entry(epfd_idx) {
        Some(e) => match e.backend {
            FdBackend::Epoll { instance_id } => instance_id,
            _ => return NEG_EINVAL,
        },
        None => return NEG_EBADF,
    };

    // Verify target FD exists and is not an epoll FD.
    match current_fd_entry(fd_idx) {
        Some(e) => {
            if matches!(e.backend, FdBackend::Epoll { .. }) {
                return NEG_EINVAL; // epoll FDs cannot be monitored
            }
        }
        None => return NEG_EBADF,
    }

    // Read epoll_event from userspace: packed { events: u32, data: u64 } = 12 bytes
    let (events, data) = if op != EPOLL_CTL_DEL {
        if event_ptr == 0 {
            return NEG_EFAULT;
        }
        let mut ev = [0u8; 12];
        if UserSliceRo::new(event_ptr, ev.len())
            .and_then(|s| s.copy_to_kernel(&mut ev))
            .is_err()
        {
            return NEG_EFAULT;
        }
        let events = u32::from_ne_bytes([ev[0], ev[1], ev[2], ev[3]]);
        let data = u64::from_ne_bytes([ev[4], ev[5], ev[6], ev[7], ev[8], ev[9], ev[10], ev[11]]);
        (events, data)
    } else {
        (0, 0)
    };

    let mut table = EPOLL_TABLE.lock();
    let inst = match table.get_mut(instance_id).and_then(|s| s.as_mut()) {
        Some(i) => i,
        None => return NEG_EBADF,
    };

    match op {
        EPOLL_CTL_ADD => {
            // Check for duplicate.
            if inst.interests.iter().any(|i| i.fd == fd_idx) {
                return NEG_EEXIST;
            }
            if inst.interests.len() >= MAX_EPOLL_INTEREST {
                return NEG_ENOMEM;
            }
            inst.interests.push(EpollInterest {
                fd: fd_idx,
                events,
                data,
                // Fresh interest: empty watermark so an already-ready ET fd
                // fires its first edge immediately.
                last_ready: 0,
            });
            0
        }
        EPOLL_CTL_MOD => {
            if let Some(entry) = inst.interests.iter_mut().find(|i| i.fd == fd_idx) {
                entry.events = events;
                entry.data = data;
                // Re-arm the edge state: EPOLL_CTL_MOD resets the ET watermark
                // so the modified interest re-reports current readiness.
                entry.last_ready = 0;
                0
            } else {
                const NEG_ENOENT: u64 = (-2_i64) as u64;
                NEG_ENOENT
            }
        }
        EPOLL_CTL_DEL => {
            let before = inst.interests.len();
            inst.interests.retain(|i| i.fd != fd_idx);
            if inst.interests.len() == before {
                const NEG_ENOENT: u64 = (-2_i64) as u64;
                NEG_ENOENT
            } else {
                0
            }
        }
        _ => NEG_EINVAL,
    }
}

/// epoll_wait(epfd, events, maxevents, timeout) — syscall 232
pub(super) fn sys_epoll_wait(epfd: u64, events_ptr: u64, maxevents: u64, timeout: u64) -> u64 {
    let maxevents = (maxevents as usize).min(MAX_EPOLL_INTEREST);
    if maxevents == 0 {
        return NEG_EINVAL;
    }
    let timeout_i = timeout as i64;
    let start_tick = crate::arch::x86_64::interrupts::tick_count();
    // TICKS_PER_SEC = 1000, so 1 tick = 1 ms: deadline = start + timeout_ms (no ÷10).
    // The old `(timeout_i as u64).div_ceil(10)` assumed a 100 Hz timer — G.3 fix.
    let deadline_tick = if timeout_i > 0 {
        Some(start_tick + (timeout_i as u64)) // 1 tick = 1 ms; no divisor needed
    } else {
        None
    };

    let epfd_idx = epfd as usize;
    if epfd_idx >= MAX_FDS {
        return NEG_EBADF;
    }
    let instance_id = match current_fd_entry(epfd_idx) {
        Some(e) => match e.backend {
            FdBackend::Epoll { instance_id } => instance_id,
            _ => return NEG_EINVAL,
        },
        None => return NEG_EBADF,
    };

    loop {
        // Scan interest list for ready FDs.
        let mut out_count = 0usize;
        let interests = {
            let table = EPOLL_TABLE.lock();
            match table.get(instance_id).and_then(|s| s.as_ref()) {
                Some(inst) => inst.interests.clone(),
                None => return NEG_EBADF,
            }
        };

        // Edge-aware scan: a level-triggered interest emits whenever a
        // requested/unconditional bit is ready; an edge-triggered (EPOLLET)
        // interest emits only on a not-ready→ready transition relative to its
        // per-interest watermark. The decision is the pure, host-tested
        // `kernel_core::epoll::evaluate_interest`. The scan runs on a clone (no
        // table lock held across `fd_poll_events`), so the refreshed ET
        // watermarks are persisted back to the table afterwards.
        let mut et_updates: alloc::vec::Vec<(usize, u32)> = alloc::vec::Vec::new();
        for interest in &interests {
            if out_count >= maxevents {
                break;
            }
            if let Some(entry) = current_fd_entry(interest.fd) {
                let ready_u32 = fd_poll_events(&entry) as u16 as u32;
                let event_mask = interest.events & !EPOLL_CONTROL_BITS;
                let is_et = interest.events & EPOLLET != 0;
                let eval = kernel_core::epoll::evaluate_interest(
                    ready_u32,
                    event_mask,
                    EPOLL_UNCONDITIONAL,
                    interest.last_ready,
                    is_et,
                );
                if is_et {
                    et_updates.push((interest.fd, eval.new_last_ready));
                }
                if eval.emit {
                    // Write epoll_event to userspace: packed { events: u32, data: u64 } = 12 bytes
                    let base = match events_ptr.checked_add((out_count * 12) as u64) {
                        Some(a) => a,
                        None => return NEG_EFAULT,
                    };
                    let ev_out = eval.revents.to_ne_bytes();
                    let data_out = interest.data.to_ne_bytes();
                    let mut buf = [0u8; 12];
                    buf[0..4].copy_from_slice(&ev_out);
                    buf[4..12].copy_from_slice(&data_out);
                    if UserSliceWo::new(base, buf.len())
                        .and_then(|s| s.copy_from_kernel(&buf))
                        .is_err()
                    {
                        return NEG_EFAULT;
                    }
                    out_count += 1;
                }
            }
        }

        // Persist refreshed ET watermarks onto the live interests (matched by
        // fd; a concurrently removed/modified interest is simply skipped).
        //
        // Known benign race (Phase 86d Track B): the readiness scan above runs
        // on a *clone* of the interest list with the table lock dropped (so
        // `fd_poll_events` can descend into the net/pipe layers). If another
        // thread issues `EPOLL_CTL_MOD` for the same fd in that window — which
        // resets `last_ready` to 0 to re-arm the edge — this write-back can
        // overwrite that fresh 0 with the stale watermark computed before the
        // MOD, costing one spurious or missed edge. It is never memory-unsafe
        // (the fd match just lands on the re-armed interest). The robust fix is
        // a per-interest epoch captured in the clone and compared here; it is a
        // tracked follow-up — no in-tree consumer MODs an fd concurrently with
        // a sibling thread's `epoll_wait`, and Go (the 86d driver) does not MOD
        // in its netpoll hot path. The gate also pins `-smp 1`.
        if !et_updates.is_empty() {
            let mut table = EPOLL_TABLE.lock();
            if let Some(inst) = table.get_mut(instance_id).and_then(|s| s.as_mut()) {
                for (fd, new_last) in et_updates {
                    if let Some(it) = inst.interests.iter_mut().find(|i| i.fd == fd) {
                        it.last_ready = new_last;
                    }
                }
            }
        }

        let timed_out =
            deadline_tick.is_some_and(|d| crate::arch::x86_64::interrupts::tick_count() >= d);
        if out_count > 0 || timeout_i == 0 || timed_out {
            return out_count as u64;
        }

        if has_pending_signal() {
            return NEG_EINTR;
        }

        // If the interest list is empty, there's nothing to wait on.
        // Return 0 immediately rather than blocking forever.
        if interests.is_empty() {
            return 0;
        }

        // Block on each monitored FD's wait queue so we wake on events.
        let task_id = match crate::task::scheduler::current_task_id() {
            Some(id) => id,
            None => return NEG_EINTR,
        };
        let woken = alloc::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
        let mut registered_any = false;
        for interest in &interests {
            if let Some(entry) = current_fd_entry(interest.fd)
                && fd_register_waiter(&entry, task_id, &woken)
            {
                registered_any = true;
            }
        }

        // If no pollable FDs were registered, yield once to avoid infinite blocking.
        if !registered_any {
            crate::task::yield_now();
            continue;
        }

        // Re-check readiness after registration (TOCTOU). Re-read fresh
        // interests so the ET watermarks updated above are honored: an
        // already-reported, still-ready ET fd is NOT a fresh edge and must not
        // wake us — otherwise a persistently-readable ET fd would busy-loop.
        let recheck = {
            let table = EPOLL_TABLE.lock();
            match table.get(instance_id).and_then(|s| s.as_ref()) {
                Some(inst) => inst.interests.clone(),
                None => alloc::vec::Vec::new(),
            }
        };
        let mut any_ready = false;
        for interest in &recheck {
            if let Some(entry) = current_fd_entry(interest.fd) {
                let ready_u32 = fd_poll_events(&entry) as u16 as u32;
                let event_mask = interest.events & !EPOLL_CONTROL_BITS;
                let is_et = interest.events & EPOLLET != 0;
                let eval = kernel_core::epoll::evaluate_interest(
                    ready_u32,
                    event_mask,
                    EPOLL_UNCONDITIONAL,
                    interest.last_ready,
                    is_et,
                );
                if eval.emit {
                    any_ready = true;
                    break;
                }
            }
        }
        if any_ready {
            for interest in &interests {
                if let Some(entry) = current_fd_entry(interest.fd) {
                    fd_deregister_waiter(&entry, task_id);
                }
            }
            continue;
        }

        // F.4: Under sched-v2, use block_current_until for both timeout branches:
        // positive timeout passes deadline_tick; indefinite passes None.
        // Under v1, retain yield_now() for positive timeout and
        // block_current_unless_woken for indefinite timeout.
        {
            // Clamp to the nearest armed timerfd expiry so a timerfd in the
            // interest set wakes a blocked (incl. indefinite) epoll_wait — the
            // libuv event-loop due-timer path (Phase 89 A.1).
            let block_deadline = clamp_block_deadline(
                deadline_tick,
                nearest_timerfd_deadline_fds(interests.iter().map(|i| i.fd)),
            );
            let _ = crate::task::scheduler::block_current_until(
                crate::task::TaskState::BlockedOnRecv,
                &woken,
                block_deadline,
            );
            for interest in &interests {
                if let Some(entry) = current_fd_entry(interest.fd) {
                    fd_deregister_waiter(&entry, task_id);
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// sys_ktrace — Phase 43b Track G
// ---------------------------------------------------------------------------

// ktrace command codes (passed in arg0). Keep in sync with `syscall_lib`.
const KTRACE_READ_CORE: u64 = 0;
const KTRACE_ARM: u64 = 1;
const KTRACE_DISARM: u64 = 2;
const KTRACE_READ_FOCUS: u64 = 3;
const KTRACE_FOCUS_LEN: u64 = 4;
const KTRACE_TASKS: u64 = 5;
const KTRACE_DUMP_SERIAL: u64 = 6;
const KTRACE_DUMP_CORES: u64 = 7;
const KTRACE_DUMP_TASKS_SERIAL: u64 = 8;

/// Largest kernel staging buffer for a single text dump call (focus / tasks).
#[cfg(feature = "trace")]
const KTRACE_TEXT_CAP: usize = 16 * 1024;
/// Focus entries formatted per `READ_FOCUS` call (callers page with `offset`).
#[cfg(feature = "trace")]
const KTRACE_FOCUS_BATCH: usize = 256;

#[cfg(feature = "trace")]
/// Kernel trace control + readout. Command (`cmd`, arg0) selects the operation:
///
/// - `0 READ_CORE`: a=core_id, b=buf_ptr, c=buf_len — copy raw `TraceEntry`
///   records from a per-core ring (legacy/compat path).
/// - `1 ARM`: a=pids_ptr (u32 array), b=count — arm the deep focus ring on
///   those pids. Returns resolved target idx count.
/// - `2 DISARM`: disarm the focus ring.
/// - `3 READ_FOCUS`: a=offset, b=buf_ptr, c=buf_len — write annotated text
///   lines for focus entries `[offset..]`. Returns entries written.
/// - `4 FOCUS_LEN`: return the focus ring's current entry count.
/// - `5 TASKS`: b=buf_ptr, c=buf_len — write the live task table as text
///   (idx pid state prio core name). Returns rows.
/// - `6 DUMP_SERIAL`: dump the whole focus ring to the serial console (the
///   always-available path for reading the trace while userspace I/O is wedged
///   by the hang under study). Returns entries dumped.
/// - `7 DUMP_CORES`: dump per-core dispatch state (current task + run queue per
///   core, and every Ready/Running task) to serial. Names the ring-0 hog.
///
/// Returns `u64::MAX` on error.
pub(super) fn sys_ktrace(cmd: u64, a: u64, b: u64, c: u64) -> u64 {
    // ktrace exposes kernel-internal diagnostics — the full task table
    // (KTRACE_TASKS), per-core dispatch state, and the focus-ring contents — and
    // expensive serial-flood / heap-churn dumps (DUMP_SERIAL/DUMP_CORES/
    // DUMP_TASKS_SERIAL). None of it is appropriate for an unprivileged caller,
    // so gate the whole surface on root (PR #201 audit): no scheduler-internals
    // disclosure and no UART/heap self-DoS from ring 3.
    {
        let pid = crate::process::current_pid();
        let uid = {
            let table = crate::process::PROCESS_TABLE.lock();
            table.find(pid).map(|p| p.uid).unwrap_or(u32::MAX)
        };
        if uid != 0 {
            return NEG_EPERM;
        }
    }
    match cmd {
        KTRACE_READ_CORE => sys_ktrace_read_core(a, b, c),
        KTRACE_ARM => sys_ktrace_arm(a, b),
        KTRACE_DISARM => {
            crate::trace::focus::disarm();
            0
        }
        KTRACE_DUMP_SERIAL => sys_ktrace_dump_serial(),
        KTRACE_DUMP_CORES => {
            crate::task::scheduler::ktrace_dump_dispatch_state();
            0
        }
        KTRACE_DUMP_TASKS_SERIAL => sys_ktrace_dump_tasks_serial(),
        KTRACE_FOCUS_LEN => crate::trace::focus::len() as u64,
        KTRACE_READ_FOCUS => sys_ktrace_read_focus(a, b, c),
        KTRACE_TASKS => sys_ktrace_tasks(b, c),
        _ => u64::MAX,
    }
}

#[cfg(feature = "trace")]
fn sys_ktrace_read_core(core_id: u64, buf_ptr: u64, buf_len: u64) -> u64 {
    let core_id = core_id as u8;
    if core_id >= crate::smp::core_count() || buf_ptr == 0 {
        return u64::MAX;
    }
    if buf_len == 0 {
        return 0;
    }
    let data = match crate::smp::get_core_data(core_id) {
        Some(d) => d,
        None => return u64::MAX,
    };
    // Safety: trace_ring is UnsafeCell; we only read. The owning core may
    // concurrently write (at most one torn entry — acceptable for diagnostics).
    let ring_ptr = data.trace_ring.get();
    let entry_size = core::mem::size_of::<kernel_core::trace_ring::TraceEntry>();
    let max_entries = (buf_len as usize) / entry_size;
    if max_entries == 0 {
        return 0;
    }
    const MAX_BATCH: usize = 64;
    let batch = max_entries.min(MAX_BATCH);
    let mut tmp = [kernel_core::trace_ring::TraceEntry::EMPTY; MAX_BATCH];
    let write_count = unsafe { (*ring_ptr).copy_into(&mut tmp[..batch]) };
    if write_count == 0 {
        return 0;
    }
    // TraceEntry is #[repr(C)] with zeroed padding, so byte reinterpretation
    // leaks no uninit bytes.
    let src_bytes =
        unsafe { core::slice::from_raw_parts(tmp.as_ptr() as *const u8, write_count * entry_size) };
    if UserSliceWo::new(buf_ptr, src_bytes.len())
        .and_then(|s| s.copy_from_kernel(src_bytes))
        .is_err()
    {
        return u64::MAX;
    }
    write_count as u64
}

#[cfg(feature = "trace")]
fn sys_ktrace_arm(pids_ptr: u64, count: u64) -> u64 {
    use crate::trace::focus::MAX_TARGETS;
    if pids_ptr == 0 {
        return u64::MAX;
    }
    let count = (count as usize).min(MAX_TARGETS);
    if count == 0 {
        return u64::MAX;
    }
    // Read the requested pids from userspace.
    let mut pid_bytes = [0u8; MAX_TARGETS * 4];
    let want = count * 4;
    if UserSliceRo::new(pids_ptr, want)
        .and_then(|s| s.copy_to_kernel(&mut pid_bytes[..want]))
        .is_err()
    {
        return u64::MAX;
    }
    let mut pids = [0u32; MAX_TARGETS];
    for i in 0..count {
        pids[i] = u32::from_ne_bytes(pid_bytes[i * 4..i * 4 + 4].try_into().unwrap());
    }
    // Resolve pids -> task indices.
    let mut target_idxs = [0u32; MAX_TARGETS];
    let n_targets = crate::task::scheduler::ktrace_resolve_pids(&pids[..count], &mut target_idxs);
    // Snapshot the idx -> (pid, name) table now (targets alive) for annotation.
    let mut names: alloc::vec::Vec<(u32, u32, &'static str)> = alloc::vec::Vec::with_capacity(96);
    crate::task::scheduler::ktrace_for_each_task(|idx, pid, _st, _prio, _core, name| {
        if names.len() < names.capacity() {
            names.push((idx, pid, name));
        }
    });
    crate::trace::focus::arm(&target_idxs[..n_targets], names);
    n_targets as u64
}

#[cfg(feature = "trace")]
fn sys_ktrace_read_focus(offset: u64, buf_ptr: u64, buf_len: u64) -> u64 {
    if buf_ptr == 0 || buf_len == 0 {
        return u64::MAX;
    }
    // Annotation uses the arm-time name snapshot stored in the focus ring.
    let cap = (buf_len as usize).min(KTRACE_TEXT_CAP);
    let mut out = alloc::vec![0u8; cap];
    let entries = crate::trace::focus::dump_text(offset as usize, KTRACE_FOCUS_BATCH, &mut out);

    // Copy the formatted text (through the NUL terminator) to userspace.
    let text_len = out
        .iter()
        .position(|&x| x == 0)
        .map(|p| p + 1)
        .unwrap_or(cap);
    let copy_len = text_len.min(cap);
    if UserSliceWo::new(buf_ptr, copy_len)
        .and_then(|s| s.copy_from_kernel(&out[..copy_len]))
        .is_err()
    {
        return u64::MAX;
    }
    entries as u64
}

#[cfg(feature = "trace")]
fn sys_ktrace_tasks(buf_ptr: u64, buf_len: u64) -> u64 {
    use core::fmt::Write;
    if buf_ptr == 0 || buf_len == 0 {
        return u64::MAX;
    }
    // Snapshot rows under the scheduler lock (pre-reserved: no alloc while held).
    let mut rows: alloc::vec::Vec<(u32, u32, u8, u8, u8, &'static str)> =
        alloc::vec::Vec::with_capacity(96);
    crate::task::scheduler::ktrace_for_each_task(|idx, pid, st, prio, core, name| {
        if rows.len() < rows.capacity() {
            rows.push((idx, pid, st, prio, core, name));
        }
    });

    let mut s = alloc::string::String::with_capacity((buf_len as usize).min(KTRACE_TEXT_CAP));
    let _ = writeln!(s, "idx pid state prio core name");
    for (idx, pid, st, prio, core, name) in &rows {
        let _ = writeln!(
            s,
            "{idx} {pid} {} {prio} {core} {name}",
            ktrace_state_name(*st)
        );
    }

    let bytes = s.as_bytes();
    let cap = (buf_len as usize).saturating_sub(1).min(bytes.len());
    let mut tmp = alloc::vec![0u8; cap + 1];
    tmp[..cap].copy_from_slice(&bytes[..cap]);
    tmp[cap] = 0; // NUL-terminate
    if UserSliceWo::new(buf_ptr, tmp.len())
        .and_then(|sl| sl.copy_from_kernel(&tmp))
        .is_err()
    {
        return u64::MAX;
    }
    rows.len() as u64
}

#[cfg(feature = "trace")]
fn sys_ktrace_dump_serial() -> u64 {
    // Annotation uses the arm-time name snapshot stored in the focus ring.
    crate::trace::focus::dump_serial() as u64
}

/// Dump every live task's state to serial (idx/pid/state/prio/core/name),
/// INCLUDING Blocked tasks. Lightweight (~one line per task, no preempt-trace
/// flood) so it does not perturb the hang it samples. Distinguishes a lost
/// wake (`ion` stuck `Blk*`) from dispatch starvation (`ion` stuck `Ready`).
#[cfg(feature = "trace")]
fn sys_ktrace_dump_tasks_serial() -> u64 {
    // Pre-reserve before the scheduler-locked walk so it never allocates while
    // the lock is held; format to serial afterwards (lock released).
    let mut rows: alloc::vec::Vec<(u32, u32, u8, u8, u8, &'static str)> =
        alloc::vec::Vec::with_capacity(160);
    crate::task::scheduler::ktrace_for_each_task(|idx, pid, st, prio, core, name| {
        if rows.len() < rows.capacity() {
            rows.push((idx, pid, st, prio, core, name));
        }
    });
    crate::serial_println!("=== KTRACE TASK STATES ({} tasks) ===", rows.len());
    for (idx, pid, st, prio, core, name) in &rows {
        crate::serial_println!(
            "idx={} pid={} state={} prio={} core={} {}",
            idx,
            pid,
            ktrace_state_name(*st),
            prio,
            core,
            name
        );
    }
    crate::serial_println!("=== END KTRACE TASK STATES ===");
    rows.len() as u64
}

/// Map a `TaskState` u8 discriminant to a short name (see `SchedTrace` docs).
#[cfg(feature = "trace")]
fn ktrace_state_name(st: u8) -> &'static str {
    match st {
        0 => "Ready",
        1 => "Running",
        2 => "BlkRecv",
        3 => "BlkSend",
        4 => "BlkReply",
        5 => "BlkNotif",
        6 => "BlkFutex",
        7 => "Dead",
        _ => "?",
    }
}

// ===========================================================================
// Phase 54 Track C: UDP network service facade
// ===========================================================================

/// Returns `true` when the ring-3 `net_udp` service is registered and the
/// current caller is *not* the service itself (prevents recursion).
pub(crate) fn net_udp_service_available() -> bool {
    !is_current_exec_path("/bin/net_server") && crate::ipc::registry::is_registered("net_udp")
}

/// Tell the service about a newly-allocated kernel socket handle.
fn net_udp_service_create(kernel_handle: u32) -> u64 {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::net::udp_protocol::NET_UDP_CREATE;

    let ep = match registry::lookup_endpoint_id("net_udp") {
        Some(ep) => ep,
        None => return NEG_EIO,
    };
    let task = match scheduler::current_task_id() {
        Some(id) => id,
        None => return NEG_EINVAL,
    };

    let mut msg = Message::new(NET_UDP_CREATE);
    msg.data[0] = kernel_handle as u64;
    let reply = endpoint::call_msg(task, ep, msg);
    reply.label // 0 on success
}

/// Forward bind to the service (port binding policy decision).
fn net_udp_service_bind(kernel_handle: u32, port: u16, ip: [u8; 4]) -> u64 {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::net::udp_protocol::NET_UDP_BIND;

    let ep = match registry::lookup_endpoint_id("net_udp") {
        Some(ep) => ep,
        None => return NEG_EIO,
    };
    let task = match scheduler::current_task_id() {
        Some(id) => id,
        None => return NEG_EINVAL,
    };

    let ip_u32 =
        ((ip[0] as u64) << 24) | ((ip[1] as u64) << 16) | ((ip[2] as u64) << 8) | (ip[3] as u64);

    let mut msg = Message::new(NET_UDP_BIND);
    msg.data[0] = kernel_handle as u64;
    msg.data[1] = port as u64;
    msg.data[2] = ip_u32;
    let reply = endpoint::call_msg(task, ep, msg);
    reply.label
}

/// Forward connect to the service. Returns (errno, ephemeral_port).
fn net_udp_service_connect(kernel_handle: u32, ip: [u8; 4], port: u16) -> (u64, u16) {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::net::udp_protocol::{NET_UDP_CONNECT, pack_ip_port};

    let ep = match registry::lookup_endpoint_id("net_udp") {
        Some(ep) => ep,
        None => return (NEG_EIO, 0),
    };
    let task = match scheduler::current_task_id() {
        Some(id) => id,
        None => return (NEG_EINVAL, 0),
    };

    let mut msg = Message::new(NET_UDP_CONNECT);
    msg.data[0] = kernel_handle as u64;
    msg.data[1] = pack_ip_port(ip, port);
    let reply = endpoint::call_msg(task, ep, msg);
    (reply.label, reply.data[0] as u16)
}

/// Validate a sendto — returns (errno, src_port) from the service.
fn net_udp_service_sendto_params(
    kernel_handle: u32,
    dst_ip: [u8; 4],
    dst_port: u16,
    len: usize,
) -> (u64, u16) {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::net::udp_protocol::{NET_UDP_SENDTO, pack_ip_port};

    let ep = match registry::lookup_endpoint_id("net_udp") {
        Some(ep) => ep,
        None => return (NEG_EIO, 0),
    };
    let task = match scheduler::current_task_id() {
        Some(id) => id,
        None => return (NEG_EINVAL, 0),
    };

    let mut msg = Message::new(NET_UDP_SENDTO);
    msg.data[0] = kernel_handle as u64;
    msg.data[1] = pack_ip_port(dst_ip, dst_port);
    msg.data[2] = len as u64;
    let reply = endpoint::call_msg(task, ep, msg);
    (reply.label, reply.data[0] as u16)
}

/// Validate a recvfrom — returns (errno, local_port) from the service.
fn net_udp_service_recvfrom_port(kernel_handle: u32) -> (u64, u16) {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::net::udp_protocol::NET_UDP_RECVFROM;

    let ep = match registry::lookup_endpoint_id("net_udp") {
        Some(ep) => ep,
        None => return (NEG_EIO, 0),
    };
    let task = match scheduler::current_task_id() {
        Some(id) => id,
        None => return (NEG_EINVAL, 0),
    };

    let mut msg = Message::new(NET_UDP_RECVFROM);
    msg.data[0] = kernel_handle as u64;
    let reply = endpoint::call_msg(task, ep, msg);
    (reply.label, reply.data[0] as u16)
}

/// Tell the service a socket was closed. Returns the port that was unbound.
pub(crate) fn net_udp_service_close(kernel_handle: u32) -> u16 {
    use crate::ipc::{endpoint, message::Message, registry};
    use crate::task::scheduler;
    use kernel_core::net::udp_protocol::NET_UDP_CLOSE;

    let ep = match registry::lookup_endpoint_id("net_udp") {
        Some(ep) => ep,
        None => return 0,
    };
    let task = match scheduler::current_task_id() {
        Some(id) => id,
        None => return 0,
    };

    let mut msg = Message::new(NET_UDP_CLOSE);
    msg.data[0] = kernel_handle as u64;
    let reply = endpoint::call_msg(task, ep, msg);
    reply.data[0] as u16
}

// Phase 66 Track D.1 — `release_socket_pub` body has moved to
// `kernel/src/net/mod.rs`. The internal call sites here now go through
// `crate::net::release_socket_pub` directly.
